# ---------- 运行日志（内存，最近200条） ----------
LOG = []
def log(msg):
    now = time.time()
    # 相邻 8 秒内完全相同的消息只保留一条（旧版“卸载模型”等会重复刷屏）
    if LOG and LOG[-1]["m"] == msg and now - LOG[-1]["ts"] < 8:
        LOG[-1]["ts"] = now
        return
    LOG.append({"t": time.strftime("%H:%M:%S"), "m": msg, "ts": now})
    if len(LOG) > 200:
        del LOG[:len(LOG) - 200]

# ---------- 当前活动状态（给前端判断“正在做什么 / 是否卡住”） ----------
ACTIVITY = {"active": False, "op": "", "detail": "", "start": 0, "last": 0, "eta": ""}
def set_activity(op, detail="", eta=""):
    """开始（或切换）一个耗时的后台步骤。"""
    now = time.time()
    ACTIVITY.update({
        "active": True, "op": op, "detail": detail,
        "start": now, "last": now, "eta": eta,
    })

def touch_activity(detail=None, eta=""):
    """长步骤进行中定期更新“最后活跃时间”，前端据此判断没有卡死。"""
    now = time.time()
    if detail is not None:
        ACTIVITY["detail"] = detail
    if eta:
        ACTIVITY["eta"] = eta
    ACTIVITY["last"] = now

def clear_activity():
    ACTIVITY.update({"active": False, "op": "", "detail": "", "start": 0, "last": 0, "eta": ""})

# ---------- 统一进度中心（所有长任务共享，网页进度条统一读取） ----------
OP_LOCK = threading.Lock()
OPS = {}

def op_ensure(op_id, label, total=0, detail="", kind=None):
    """登记一个后台任务；同一个任务已运行时不重复重置进度。"""
    with OP_LOCK:
        op = OPS.get(op_id)
        if op and op.get("active"):
            return dict(op)
        OPS[op_id] = {
            "id": op_id, "label": str(label), "active": True,
            "total": max(0, int(total or 0)), "done": 0,
            "percent": 0.0, "detail": str(detail or ""),
            "kind": str(kind) if kind else "",
            "status": "running", "startedAt": time.time(),
            "lastAt": time.time(), "endedAt": 0,
        }
        return dict(OPS[op_id])

def op_update(op_id, done=None, total=None, detail=None, status=None, percent=None, kind=None, label=None):
    with OP_LOCK:
        op = OPS.get(op_id)
        if not op:
            return None
        if total is not None:
            op["total"] = max(0, int(total or 0))
        if done is not None:
            op["done"] = max(0, int(done or 0))
        if detail is not None:
            op["detail"] = str(detail or "")
        if status is not None:
            op["status"] = str(status)
        if kind is not None:
            op["kind"] = str(kind)
        if label is not None:
            op["label"] = str(label)
        if percent is not None:
            op["percent"] = max(0.0, min(1.0, float(percent)))
        elif op["total"] > 0:
            op["percent"] = min(1.0, op["done"] / op["total"])
        else:
            op["percent"] = 0.0
        op["lastAt"] = time.time()
        return dict(op)

def op_heartbeat(op_id, detail=None):
    """长步骤进行中定期心跳，前端据此判断是否卡住。"""
    with OP_LOCK:
        op = OPS.get(op_id)
        if not op:
            return None
        if detail is not None:
            op["detail"] = str(detail or "")
        op["lastAt"] = time.time()
        return dict(op)

def op_end(op_id, status="complete", detail=""):
    with OP_LOCK:
        op = OPS.get(op_id)
        if not op:
            return None
        op["status"] = str(status)
        op["active"] = status in ("running", "stopping")
        if detail:
            op["detail"] = str(detail)
        if status == "complete":
            op["percent"] = 1.0
        op["lastAt"] = time.time()
        op["endedAt"] = time.time()
        return dict(op)

def op_snapshot():
    with OP_LOCK:
        return {k: dict(v) for k, v in OPS.items()}

# ---------- 实际速度校准（记住每类操作的真实耗时，用于更准的剩余时间估算） ----------
CALIB_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "progress_calibration.json")
CALIB_LOCK = threading.Lock()
CALIB = {}

def _calib_load():
    global CALIB
    try:
        if os.path.exists(CALIB_FILE):
            with open(CALIB_FILE, encoding="utf-8") as f:
                d = json.load(f)
                if isinstance(d, dict):
                    CALIB = d
    except Exception:
        pass

_calib_load()

def calib_record(key, seconds):
    """记录一次真实耗时；同类操作会做平滑平均，避免单次异常带偏。"""
    if not key or seconds is None or float(seconds) <= 0:
        return
    seconds = float(seconds)
    with CALIB_LOCK:
        old = CALIB.get(key) or {}
        avg = float(old.get("avg") or 0)
        count = int(old.get("count") or 0)
        if count <= 0:
            avg = seconds
        else:
            avg = avg * 0.8 + seconds * 0.2
        CALIB[key] = {"avg": round(avg, 2), "count": count + 1}
        data = dict(CALIB)
    try:
        tmp = CALIB_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        os.replace(tmp, CALIB_FILE)
    except Exception:
        pass

def calib_avg(key, default=None):
    with CALIB_LOCK:
        d = CALIB.get(key)
        if isinstance(d, dict) and d.get("avg"):
            return float(d["avg"])
    return default

def calib_speeds():
    with CALIB_LOCK:
        return {k: (float(v.get("avg")) if isinstance(v, dict) and v.get("avg") else None)
                for k, v in CALIB.items()}

def _calib_key_for_wh(wh):
    if wh:
        return "krea2_%dx%d" % (int(wh[0]), int(wh[1]))
    return "krea2_default"

