def _chat_id(value=""):
    cid = "".join(c for c in str(value or "") if c.isalnum() or c in "-_")
    return cid or ("chat_" + time.strftime("%Y%m%d_%H%M%S") + "_%03d" % int(time.time_ns() % 1000))

def _chat_path(cid):
    return os.path.join(CHAT_DIR, _chat_id(cid) + ".json")

def _clean_chat_messages(messages):
    cleaned = []
    for item in messages if isinstance(messages, list) else []:
        if not isinstance(item, dict):
            continue
        role = item.get("role")
        text = str(item.get("content") or "").strip()
        if role in ("user", "assistant", "system") and text:
            cleaned.append({"role": role, "content": text})
    return cleaned

def estimate_text_tokens(text):
    """离线近似 token 数：中文约1字/token，英文约4字符/token。"""
    text = str(text or "")
    cjk = sum(1 for ch in text if "\u3400" <= ch <= "\u9fff")
    other = len(text) - cjk
    return max(0, int(cjk * 1.05 + other / 4 + 0.5))

def estimate_message_tokens(messages):
    return sum(estimate_text_tokens(m.get("content", "")) + 4
               for m in _clean_chat_messages(messages))

def load_chat_record(cid):
    cid = _chat_id(cid)
    p = os.path.join(CHAT_DIR, cid + ".json")
    if os.path.exists(p):
        try:
            rec = json.load(open(p, encoding="utf-8"))
        except Exception:
            rec = {}
    else:
        rec = {}
    messages = _clean_chat_messages(rec.get("messages", []))
    created = float(rec.get("created") or (os.path.getctime(p) if os.path.exists(p) else time.time()))
    updated = float(rec.get("updated") or (os.path.getmtime(p) if os.path.exists(p) else created))
    compacted = max(0, min(int(rec.get("compactedUntil") or 0), len(messages)))
    return {
        "id": cid,
        "title": str(rec.get("title") or "新对话")[:60],
        "messages": messages,
        "memory": str(rec.get("memory") or "").strip(),
        "compactedUntil": compacted,
        "created": created,
        "updated": updated,
    }

def save_chat_record(data):
    cid = _chat_id(data.get("id"))
    old = load_chat_record(cid)
    messages = _clean_chat_messages(data.get("messages", old["messages"]))
    compacted = max(0, min(int(data.get("compactedUntil", old["compactedUntil"]) or 0), len(messages)))
    rec = {
        "id": cid,
        "title": str(data.get("title") or old["title"] or "新对话")[:60],
        "messages": messages,
        "memory": str(data.get("memory", old["memory"]) or "").strip(),
        "compactedUntil": compacted,
        "created": old["created"],
        "updated": time.time(),
    }
    with open(os.path.join(CHAT_DIR, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    return rec

# ================== 与模型对话 ==================
OLLAMA_EXE = os.environ.get("OLLAMA_EXE") or shutil.which("ollama") or ""
OLLAMA_MODELS_DIR = os.environ.get("OLLAMA_MODELS", "")
GEN_STOP = threading.Event()

def ollama_model_names(timeout=3):
    """返回当前 Ollama 服务实际可见的模型名。服务未启动时抛出连接异常。"""
    data = json.load(urllib.request.urlopen("http://localhost:11434/api/tags", timeout=timeout))
    return [str(m.get("name") or m.get("model") or "") for m in data.get("models", [])]

def ollama_has_writer(names=None):
    names = names if names is not None else ollama_model_names()
    wanted = MODEL.split(":", 1)[0].lower()
    return any(str(n).split(":", 1)[0].lower() == wanted for n in names)

def ollama_ensure():
    """确保 Ollama 服务在线，并且确实能看到本工作台需要的写作模型。"""
    _local_model_guard()
    import time as _t
    try:
        names = ollama_model_names()
        if ollama_has_writer(names):
            return True
        raise RuntimeError(
            "Ollama 已启动，但看不到 Qwen3.6模型 qwen-writer。"
            "请检查 Ollama 中已安装的模型与 OLLAMA_MODELS 配置。"
        )
    except RuntimeError:
        raise
    except Exception:
        pass
    if not os.path.exists(OLLAMA_EXE):
        raise RuntimeError("找不到 Ollama 程序，请确认 Ollama 已安装。")
    log("⚙ Ollama 未运行，正在自动启动…")
    import subprocess
    env = dict(os.environ)
    if OLLAMA_MODELS_DIR:
        env["OLLAMA_MODELS"] = OLLAMA_MODELS_DIR
    try:
        subprocess.Popen([OLLAMA_EXE, "serve"], env=env, creationflags=0x08000000)
    except Exception as e:
        raise RuntimeError("Ollama 启动失败：" + str(e))
    for _ in range(20):
        _t.sleep(1)
        try:
            names = ollama_model_names()
            if ollama_has_writer(names):
                log("✅ Ollama 与 qwen-writer 已就绪")
                return True
        except Exception:
            pass
    raise RuntimeError(
        "Ollama 已启动，但 20 秒内没有发现 qwen-writer。"
        "请确认 Ollama 模型目录和模型名称正确。"
    )

# ===== Qwen3.6-35B-A3B 本地视觉（无审核，llama-server :8080）=====
Q36_VISION_URL = "http://127.0.0.1:8080/v1/chat/completions"
Q36_VISION_MODEL = "qwen3.6-35b-a3b"
Q36_SERVER_EXE = _package_paths.get("llama_server_exe")
Q36_MODEL_GGUF = _package_paths.get("model_gguf")
Q36_MMPROJ_GGUF = _package_paths.get("mmproj_gguf")
Q36_LOG = _package_paths.get("llama_log") or os.path.join(_PACKAGE_LOGS, "writer.log")
Q36_ERR_LOG = _package_paths.get("llama_err_log") or os.path.join(_PACKAGE_LOGS, "writer.err.log")
Q36_PROC = None


def qwen36_up():
    try:
        urllib.request.urlopen("http://127.0.0.1:8080/v1/models", timeout=10).close()
        return True
    except Exception:
        return False


Q36_START_LOCK = threading.Lock()


def qwen36_start():
    _local_model_guard()
    with Q36_START_LOCK:
        return _qwen36_start_locked()


def _qwen36_start_locked():
    global Q36_PROC
    if qwen36_up():
        return True
    if not all(os.path.isfile(p) for p in (Q36_SERVER_EXE, Q36_MODEL_GGUF, Q36_MMPROJ_GGUF)):
        raise RuntimeError("请在 config.json 配置 llama_server_exe、model_gguf 和 mmproj_gguf，或先启动兼容服务（8080）。")
    # 现有实例可能正忙于上一个长请求，短暂健康检查会误判为“未启动”。
    # 先等待它恢复响应，避免在已有实例占用显存时重复启动导致“显存不足”。
    for _ in range(10):
        if qwen36_up():
            return True
        time.sleep(2)
        touch_activity("等待 Qwen3.6 模型就绪…")
    # 统一显存互斥：写作/视觉模型启动前先结束 H3，避免两个大模型同时占 24G 显存。
    try:
        if video_gen_core:
            video_gen_core.service_stop(kill=True)
    except Exception:
        pass
    try:
        ollama_unload()
    except Exception:
        pass
    try:
        comfy_free()   # 启动前先释放 ComfyUI 显存，否则视觉模型会被挤到 CPU
    except Exception:
        pass
    free_gb = -1.0
    try:
        import subprocess as _sp
        for _ in range(10):
            out = _sp.check_output(
                ["nvidia-smi", "--query-gpu=memory.free",
                 "--format=csv,noheader,nounits"], timeout=5).decode("utf-8", "replace").strip()
            free_gb = float(out.splitlines()[0].strip()) / 1024.0
            if free_gb >= 21:
                break
            time.sleep(2)
        if free_gb < 21:
            log("⚠ 显存不足，自动停止 ComfyUI 给写作模型腾显存…")
            comfy_kill()
            time.sleep(3)
            for _ in range(8):
                try:
                    out = _sp.check_output(
                        ["nvidia-smi", "--query-gpu=memory.free",
                         "--format=csv,noheader,nounits"], timeout=5).decode(
                        "utf-8", "replace").strip()
                    free_gb = float(out.splitlines()[0].strip()) / 1024.0
                    if free_gb >= 21:
                        break
                except Exception:
                    pass
                time.sleep(2)
            if free_gb < 21:
                raise RuntimeError(
                    "显存不足（空闲 %.1fGB，需要约21GB）。已自动停止ComfyUI，"
                    "仍有其他程序占用显存，请关闭后重试。" % free_gb)
    except RuntimeError:
        raise
    except Exception:
        pass
    log("⏳ 视觉服务启动中，首次加载约需 30-60 秒…")
    if not (os.path.exists(Q36_SERVER_EXE) and os.path.exists(Q36_MODEL_GGUF)
            and os.path.exists(Q36_MMPROJ_GGUF)):
        raise RuntimeError(
            "找不到模型或 llama-server，请检查 config.json 中的模型路径。")
    log("🧠 启动本地 Qwen3.6 视觉服务（llama-server）…")
    import subprocess
    args = [Q36_SERVER_EXE, "-m", Q36_MODEL_GGUF, "--mmproj", Q36_MMPROJ_GGUF,
            "-ngl", "999", "-c", "16384", "-n", "8192", "-np", "1",
            "-fa", "on",
            "--host", "127.0.0.1", "--port", "8080", "--jinja"]
    try:
        out_log = open(Q36_LOG, "a", encoding="utf-8", errors="ignore")
        err_log = open(Q36_ERR_LOG, "a", encoding="utf-8", errors="ignore")
        # ⚠⚠ 遵守项目约定：creationflags 必须是 0x08000000（CREATE_NO_WINDOW）
        Q36_PROC = subprocess.Popen(args, creationflags=0x08000000,
                                    stdout=out_log, stderr=err_log)
    except Exception as e:
        raise RuntimeError("Qwen3.6 视觉服务启动失败：" + str(e))
    load_t0 = time.time()
    for _ in range(45):
        time.sleep(2)
        if qwen36_up():
            log("✅ 本地 Qwen3.6 视觉服务就绪")
            calib_record("model_load", time.time() - load_t0)
            return True
        touch_activity("正在加载 Qwen3.6 模型…")
    raise RuntimeError("Qwen3.6 视觉服务 120 秒内未就绪，请查看 " + Q36_ERR_LOG)


def qwen36_free():
    """停止本地视觉服务，释放显存给写作/出图。"""
    global Q36_PROC
    if Q36_PROC is not None:
        try:
            Q36_PROC.terminate()
        except Exception:
            pass
        Q36_PROC = None
    try:
        import subprocess as _sp
        out = _sp.check_output(["netstat", "-ano"], timeout=5).decode("latin1", "replace")
        for line in out.splitlines():
            if ("127.0.0.1:8080" in line or "127.0.0.1:8081" in line) and "LISTENING" in line:
                parts = line.strip().split()
                if parts:
                    pid = parts[-1]
                    try:
                        _sp.run(["taskkill", "/PID", pid, "/F"], timeout=5,
                                capture_output=True)
                    except Exception:
                        pass
                break
    except Exception:
        pass


def _qwen36_compress_image(image_url, max_side=1280, quality=88):
    """统一图片压缩为 data:image/jpeg;base64。
    支持 data URL、本地PNG/JPEG路径、bytes 输入。
    禁止把本地路径直接放进 image_url.url。"""
    from PIL import Image
    import io as _io
    import base64 as _b64
    if isinstance(image_url, (bytes, bytearray)):
        img = Image.open(_io.BytesIO(bytes(image_url)))
    elif isinstance(image_url, str) and image_url.startswith("data:image/"):
        head, _, b64 = image_url.partition(",")
        if not b64:
            raise RuntimeError("data URL 缺少base64内容")
        img = Image.open(_io.BytesIO(_b64.b64decode(b64)))
    elif isinstance(image_url, str) and os.path.isfile(image_url):
        img = Image.open(image_url)
    else:
        raise RuntimeError("不支持的图片输入类型")
    img = img.convert("RGB")
    img.thumbnail((max_side, max_side), Image.LANCZOS)
    buf = _io.BytesIO()
    img.save(buf, "JPEG", quality=quality)
    return "data:image/jpeg;base64," + _b64.b64encode(buf.getvalue()).decode("ascii")


def parse_local_model_json(raw, schema=None):
    """解析本地模型的JSON输出：剥```json围栏/think标签、提取首个JSON对象、
    json.loads；schema为可选字段名集合。返回 {"ok":True,"data":...,"raw":...}；
    失败时抛 RuntimeError（不静默伪造数据）。"""
    t = str(raw or "")
    t = re.sub(r"</?think>", "", t, flags=re.I)
    t = re.sub(r"```(?:json)?", "", t)
    i, j = t.find("{"), t.rfind("}")
    if i < 0 or j <= i:
        raise RuntimeError("未找到JSON对象")
    candidate = t[i:j + 1]
    try:
        data = json.loads(candidate)
    except Exception as e:
        raise RuntimeError("JSON解析失败：%s" % str(e)[:120])
    if not isinstance(data, dict):
        raise RuntimeError("JSON顶层不是对象")
    if schema:
        missing = [k for k in schema if k not in data]
        if missing:
            raise RuntimeError("JSON缺少字段：%s" % "、".join(missing))
    return {"ok": True, "data": data, "raw": t.strip()}


Q36_BUSY = False


def qwen36_vision(image_url, prompt, system=None, max_tokens=1200,
                  temperature=0.1, return_json=False):
    global Q36_BUSY
    if Q36_BUSY:
        raise RuntimeError("已有视觉识别任务正在进行，请稍候再试")
    Q36_BUSY = True
    set_activity("🧠 视觉识别", "正在识别图片…")
    log("🧠 视觉识别开始…")
    try:
        return _qwen36_vision_impl(
            image_url, prompt, system=system,
            max_tokens=max_tokens, temperature=temperature,
            return_json=return_json)
    finally:
        Q36_BUSY = False
        clear_activity()


def _qwen36_vision_impl(image_url, prompt, system=None, max_tokens=1200,
                        temperature=0.1, return_json=False):
    # 图片先压缩成小体积 JPEG，避免超大图/不常见格式拖垮识别
    image_url = _qwen36_compress_image(image_url)
    # ComfyUI 正在出图时不要抢显存，直接给出明确提示
    try:
        q = json.load(urllib.request.urlopen(COMFY + "/queue", timeout=3))
        if q.get("queue_running") or q.get("queue_pending"):
            raise RuntimeError("ComfyUI 正在出图，请等出图完成后再使用视觉识别")
    except RuntimeError:
        raise
    except Exception:
        pass
    if not qwen36_up():
        try:
            ollama_unload()
        except Exception:
            pass
        qwen36_start()
    content = [{"type": "text", "text": prompt},
               {"type": "image_url", "image_url": {"url": image_url}}]
    messages = []
    if system:
        messages.append({"role": "system", "content": system})
    messages.append({"role": "user", "content": content})
    body = json.dumps({
        "model": Q36_VISION_MODEL,
        "messages": messages,
        "max_tokens": int(max_tokens),
        "temperature": float(temperature),
        "chat_template_kwargs": {"enable_thinking": False},
    }).encode("utf-8")
    req = urllib.request.Request(Q36_VISION_URL, data=body,
                                 headers={"Content-Type": "application/json"},
                                 method="POST")
    _vision_t0 = time.time()
    with urllib.request.urlopen(req, timeout=600) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    calib_record("vision_call", time.time() - _vision_t0)
    reply = ""
    try:
        reply = str(data["choices"][0]["message"]["content"] or "")
    except Exception:
        pass
    if not reply:
        try:
            msg = data["choices"][0]["message"]
            reply = str(msg.get("reasoning_content") or "").strip()
        except Exception:
            pass
    if not reply:
        raise RuntimeError("Qwen3.6 视觉服务没有返回内容")
    if return_json:
        parsed = parse_local_model_json(reply)
        return parsed["data"]
    # 非JSON模式：至少剥离围栏，保持可读
    try:
        parsed = parse_local_model_json(reply)
        return parsed["data"]
    except Exception:
        return reply


# ===== Qwen2.5-VL 快速轻量视觉（llama-server :8081）=====
Q25_VISION_URL = "http://127.0.0.1:8081/v1/chat/completions"
Q25_VISION_MODEL = "qwen2.5-vl"
Q25_MODEL_GGUF = _package_paths.get("q25_model_gguf")
Q25_MMPROJ_GGUF = _package_paths.get("q25_mmproj_gguf")
Q25_LOG = os.path.join(_PACKAGE_LOGS, "q25vl.log")
Q25_ERR_LOG = os.path.join(_PACKAGE_LOGS, "q25vl.err.log")
Q25_PROC = None
Q25_BUSY = False
VISION_ENGINE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vision_engine.txt")


def load_vision_engine():
    try:
        with open(VISION_ENGINE_FILE, encoding="utf-8") as f:
            v = str(f.read() or "").strip().lower()
        if v in ("q25", "qwen2.5-vl", "qwen25"):
            return "q25"
    except Exception:
        pass
    return "q36"


def save_vision_engine(v):
    engine = "q25" if str(v).lower() in ("q25", "qwen2.5-vl", "qwen25") else "q36"
    with open(VISION_ENGINE_FILE, "w", encoding="utf-8") as f:
        f.write(engine)
    return engine


def qwen25_up():
    try:
        urllib.request.urlopen("http://127.0.0.1:8081/v1/models", timeout=2).close()
        return True
    except Exception:
        return False


def qwen25_start():
    global Q25_PROC
    _local_model_guard()
    if qwen25_up():
        return True
    if not all(os.path.isfile(p) for p in (Q36_SERVER_EXE, Q25_MODEL_GGUF, Q25_MMPROJ_GGUF)):
        raise RuntimeError("快速视觉为可选功能，请配置 q25_model_gguf、q25_mmproj_gguf 和 llama_server_exe，或先启动兼容服务（8081）。")
    try:
        if video_gen_core:
            video_gen_core.service_stop(kill=True)
    except Exception:
        pass
    try:
        ollama_unload()
    except Exception:
        pass
    try:
        comfy_free()
    except Exception:
        pass
    try:
        import subprocess as _sp
        out = _sp.check_output(
            ["nvidia-smi", "--query-gpu=memory.free",
             "--format=csv,noheader,nounits"], timeout=5).decode("utf-8", "replace").strip()
        free_gb = float(out.splitlines()[0].strip()) / 1024.0
        if free_gb < 5:
            raise RuntimeError(
                "显存不足（空闲 %.1fGB）。请先停止 ComfyUI 出图或等待释放后再试。" % free_gb)
    except RuntimeError:
        raise
    except Exception:
        pass
    log("⚡ 启动 Qwen2.5-VL 快速视觉服务…")
    import subprocess
    args = [Q36_SERVER_EXE, "-m", Q25_MODEL_GGUF, "--mmproj", Q25_MMPROJ_GGUF,
            "-ngl", "999", "-c", "4096", "-n", "4096", "-np", "1",
            "-fa", "on",
            "--host", "127.0.0.1", "--port", "8081", "--jinja"]
    try:
        out_log = open(Q25_LOG, "a", encoding="utf-8", errors="ignore")
        err_log = open(Q25_ERR_LOG, "a", encoding="utf-8", errors="ignore")
        Q25_PROC = subprocess.Popen(args, creationflags=0x08000000,
                                    stdout=out_log, stderr=err_log)
    except Exception as e:
        raise RuntimeError("Qwen2.5-VL 视觉服务启动失败：" + str(e))
    for _ in range(30):
        time.sleep(2)
        if qwen25_up():
            log("✅ Qwen2.5-VL 快速视觉服务就绪")
            return True
    raise RuntimeError("Qwen2.5-VL 视觉服务 60 秒内未就绪，请查看 " + Q25_ERR_LOG)


def qwen25_free():
    global Q25_PROC
    if Q25_PROC is not None:
        try:
            Q25_PROC.terminate()
        except Exception:
            pass
        Q25_PROC = None
    try:
        import subprocess as _sp
        out = _sp.check_output(["netstat", "-ano"], timeout=5).decode("latin1", "replace")
        for line in out.splitlines():
            if "127.0.0.1:8081" in line and "LISTENING" in line:
                parts = line.strip().split()
                if parts:
                    try:
                        _sp.run(["taskkill", "/PID", parts[-1], "/F"], timeout=5,
                                capture_output=True)
                    except Exception:
                        pass
                break
    except Exception:
        pass


def qwen25_vision(image_url, prompt, system=None, max_tokens=1200,
                  temperature=0.1, return_json=False):
    global Q25_BUSY
    if Q25_BUSY:
        raise RuntimeError("已有视觉识别任务正在进行，请稍候再试")
    Q25_BUSY = True
    set_activity("⚡ 快速视觉识别", "正在识别图片…")
    log("⚡ Qwen2.5-VL 视觉识别开始…")
    try:
        if not qwen25_up():
            qwen25_start()
        content = [{"type": "text", "text": prompt},
                   {"type": "image_url", "image_url": {"url": image_url}}]
        messages = []
        if system:
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": content})
        body = json.dumps({
            "model": Q25_VISION_MODEL,
            "messages": messages,
            "max_tokens": int(max_tokens),
            "temperature": float(temperature),
        }).encode("utf-8")
        req = urllib.request.Request(Q25_VISION_URL, data=body,
                                     headers={"Content-Type": "application/json"},
                                     method="POST")
        with urllib.request.urlopen(req, timeout=300) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        reply = ""
        try:
            reply = str(data["choices"][0]["message"]["content"] or "")
        except Exception:
            pass
        reply = reply.replace("</think>", "").strip()
        if not reply:
            raise RuntimeError("Qwen2.5-VL 视觉服务没有返回内容")
        if return_json:
            parsed = parse_local_model_json(reply)
            return parsed["data"]
        try:
            parsed = parse_local_model_json(reply)
            return parsed["data"]
        except Exception:
            return reply
    finally:
        Q25_BUSY = False
        clear_activity()


def vision_engine_vision(image_url, prompt, system=None, max_tokens=1200,
                         return_json=False):
    engine = load_vision_engine()
    image_url = _qwen36_compress_image(image_url)
    if engine == "q25":
        qwen36_free()   # 两个模型不能同时占显存，切轻量时先停高质量
        return qwen25_vision(image_url, prompt, system=system,
                             max_tokens=max_tokens,
                             return_json=return_json)
    qwen25_free()
    return qwen36_vision(image_url, prompt, system=system,
                         max_tokens=max_tokens, return_json=return_json)


Q36_CHAT_URL = "http://127.0.0.1:8080/v1/chat/completions"


def llama_chat_stream(messages, temperature=0.8, on_delta=None, num_predict=None):
    """写作/对话统一走本地 Qwen3.6：同一个模型同时负责写作与识图，不再来回切换。"""
    from cores.age_policy import assert_model_request, assert_model_response
    request_text = "\n".join(str(m.get("content") or "") for m in messages if m.get("role") != "system")
    assert_model_request(request_text)
    if os.environ.get("V41_NO_MODEL"):
        raise RuntimeError("V41_NO_MODEL=1：零模型测试不许调模型（内嵌文字入口）")
    full = []
    last_piece_ts = [time.time()]
    last_heartbeat_ts = [0.0]
    set_activity("✍ Qwen3.6模型写作/对话", "正在生成文字…")
    try:
        qwen36_start()   # 确保共用的本地服务在线（内部会自动腾出显存）
        payload = {
            "model": Q36_VISION_MODEL,
            "messages": messages,
            "temperature": float(temperature),
            "stream": True,
            "chat_template_kwargs": {"enable_thinking": False},
        }
        if num_predict:
            payload["max_tokens"] = int(num_predict)
        body = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(Q36_CHAT_URL, data=body,
                                     headers={"Content-Type": "application/json"})
        try:
            resp = urllib.request.urlopen(req, timeout=600)
        except urllib.error.HTTPError as e:
            detail = e.read().decode("utf-8", "replace").strip()
            raise RuntimeError(
                "Qwen3.6模型请求失败（HTTP %s）：%s" % (e.code, detail or e.reason))
        with resp:
            for raw in resp:
                if GEN_STOP.is_set():
                    log("⛔ 已中断 Qwen3.6模型生成")
                    break
                line = raw.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    break
                try:
                    obj = json.loads(data)
                except Exception:
                    continue
                try:
                    piece = obj["choices"][0]["delta"].get("content") or ""
                except Exception:
                    piece = ""
                if piece:
                    full.append(piece)
                    assert_model_response(request_text, "".join(full))
                    last_piece_ts[0] = time.time()
                    touch_activity("正在生成文字…")
                    op_heartbeat("auto_job")
                    if on_delta:
                        on_delta(piece)
                else:
                    now = time.time()
                    if now - last_piece_ts[0] >= 60 and now - last_heartbeat_ts[0] >= 60:
                        last_heartbeat_ts[0] = now
                        log("⏳ Qwen3.6模型仍在生成，已 %d 秒没有新文字…" % int(now - last_piece_ts[0]))
    finally:
        clear_activity()
    return "".join(full)


def chat_stream(messages, temperature=0.8, on_delta=None, num_predict=None):
    GEN_STOP.clear()
    return llama_chat_stream(messages, temperature=temperature,
                             on_delta=on_delta, num_predict=num_predict)

def compact_chat_context(messages, memory="", compacted_until=0, keep_recent=6):
    """把尚未压缩的旧消息合并进长期记忆，最近若干轮仍保留原文。"""
    messages = _clean_chat_messages(messages)
    start = max(0, min(int(compacted_until or 0), len(messages)))
    keep_recent = max(2, min(int(keep_recent or 6), 20))
    cutoff = max(start, len(messages) - keep_recent)
    pending = messages[start:cutoff]
    before = estimate_text_tokens(memory) + estimate_message_tokens(messages[start:])
    if not pending:
        return {
            "memory": str(memory or "").strip(),
            "compactedUntil": start,
            "beforeTokens": before,
            "afterTokens": before,
            "mergedMessages": 0,
        }

    # 长历史分批压缩，避免一次超过本地模型的 16K 上下文。
    chunks, current, current_tokens = [], [], 0
    for msg in pending:
        cost = estimate_text_tokens(msg.get("content", "")) + 8
        if current and current_tokens + cost > 9000:
            chunks.append(current); current, current_tokens = [], 0
        current.append(msg); current_tokens += cost
    if current:
        chunks.append(current)

    merged_memory = str(memory or "").strip()
    for chunk in chunks:
        transcript = "\n\n".join(
            ("用户" if m["role"] == "user" else "AI") + "：" + m["content"]
            for m in chunk if m["role"] != "system"
        )
        system = (
            "你是对话上下文压缩器。请把旧对话整理成可供后续AI继续交流的长期记忆。"
            "必须保留：用户身份与长期偏好、已经确认的事实、目标、约束、决定、重要名称和数字、"
            "尚未完成的问题；删除寒暄、重复和已经失效的临时措辞。"
            "使用简洁中文分点输出，不要回答用户，也不要解释压缩过程。"
        )
        user = "【已有长期记忆】\n%s\n\n【本次新增旧对话】\n%s" % (
            merged_memory or "无", transcript or "无")
        merged_memory = chat_stream(
            [{"role": "system", "content": system}, {"role": "user", "content": user}],
            0.2, None, 1800).strip()
        if not merged_memory:
            raise RuntimeError("模型没有返回上下文摘要")

    after = estimate_text_tokens(merged_memory) + estimate_message_tokens(messages[cutoff:])
    return {
        "memory": merged_memory,
        "compactedUntil": cutoff,
        "beforeTokens": before,
        "afterTokens": after,
        "mergedMessages": len(pending),
    }

