def build_messages(proj, mode, instruction, current_text, length="medium", rules=None):
    """
    mode: 'new' 写新章节 / 'continue' 续写当前正文
    只发送【设定 + 大纲 + 已完成章节的摘要 + 当前正文(续写时) + 指令】，
    长度恒定，永远不会超出上下文。
    """
    world   = (proj.get("world", "") or proj.get("setting", "")).strip()
    chars   = proj.get("chars", "").strip()
    char_sheet = (proj.get("charSheet") or "").strip()
    outline = proj.get("outline", "").strip()
    style   = proj.get("style", "").strip()
    zishu, num_predict = LENGTH_MAP.get(length, LENGTH_MAP["medium"])

    # 最近章节保留完整摘要；较早章节只保留短节点，避免长篇越写上下文越重。
    summaries = []
    completed = [(i, ch) for i, ch in enumerate(proj.get("chapters", []), 1)
                 if (ch.get("summary") or "").strip()]
    recent_start = max(0, len(completed) - 8)
    for pos, (i, ch) in enumerate(completed):
        s = (ch.get("summary") or "").strip()
        if pos < recent_start and len(s) > 55:
            s = s[:55].rstrip("，,；;。 ") + "…"
        summaries.append(f"第{i}章《{ch.get('title','')}》：{s}")
    prev = "\n".join(summaries) if summaries else "（暂无，这是开篇）"

    custom_rules = rules.strip() if rules and rules.strip() else ""
    if custom_rules:
        sys_parts = [NOVEL_COMIC_CORE_RULES, "【用户可编辑写作规则】\n" + custom_rules]
    else:
        sys_parts = [DEFAULT_NOVEL_RULES]
    bible = (proj.get("bible") or "").strip()
    if style:   sys_parts.append("【文风要求】\n" + style)
    if world:   sys_parts.append("【世界观设定】\n" + world)
    if chars:   sys_parts.append("【人物设定】\n" + chars)
    if char_sheet:
        sys_parts.append(
            "【人物固定视觉资产（年龄、发型、服装与固定标志必须遵守）】\n"
            + char_sheet[:6000])
    if outline: sys_parts.append("【全书大纲】\n" + outline)
    if bible:
        sys_parts.append("【剧情连续性档案（务必延续：伤势、位置、持有物、关系变化都要和这里对得上，不许前后矛盾）】\n" + bible)
        if "===伏笔账本===" in bible or "伏笔" in bible:
            sys_parts.append(
                "【伏笔纪律（重要）】上面档案里标“未回收/推进中”的伏笔是欠着读者的账。"
                "本章至少要推进或回收其中一条，并在正文里写清楚；"
                "不要凭空冒出与档案冲突的设定，也不要把已回收的伏笔当新的再抛一次。"
                "本章如果新埋钩子，要埋得具体（有名字、有物件、有时间），别写含糊的暗示。")
    sys_parts.append("【前情摘要】\n" + prev)
    system = "\n\n".join(sys_parts)

    if mode == "continue" and current_text.strip():
        user = ("这是本章已经写好的部分：\n\n" + current_text.strip() +
                "\n\n请紧接着上文自然地继续往下写，保持人物、情节、文风完全一致，不要重复已写内容。")
        if instruction.strip():
            user += "\n接下来这一段要发生：" + instruction.strip()
        user += f"\n本次续写篇幅：{zishu}。"
    else:
        user = "请开始写这一章的正文。"
        if instruction.strip():
            user += "\n【本章必须写到的情节】" + instruction.strip() + "（务必围绕这个来写，不要跑题）"
        else:
            user += "根据大纲和前情，自然地推进下一段剧情。"
        user += f"\n篇幅：{zishu}，情节自然推进、有始有终。"

    return [{"role": "system", "content": system}, {"role": "user", "content": user}], num_predict

