def _profile_value(value, source="world_derived", locked=False):
    return {"value": value, "source": source, "locked": bool(locked)}

def _profile_node_value(node, default=""):
    if isinstance(node, dict) and "value" in node:
        return node.get("value")
    return default if node is None else node

def _profile_text(profile):
    """把结构化世界视觉基准变成可读文本；不会输出内部权限布尔值。"""
    if not isinstance(profile, dict):
        return str(profile or "").strip()
    fields = profile.get("fields") if isinstance(profile.get("fields"), dict) else profile
    labels = {
        "genre": "题材", "era": "时代", "civilization": "文明与地域",
        "technology": "技术水平", "materials": "常见材料",
        "clothingSystem": "服装体系", "architectureSystem": "建筑体系",
        "toolSystem": "工具与武器体系", "supernaturalSystem": "超自然体系",
        "visualTone": "视觉气质", "allowedMixedElements": "允许混合元素",
    }
    lines = []
    for key in WORLD_VISUAL_FIELDS:
        value = _profile_node_value(fields.get(key), "")
        if isinstance(value, list):
            value = "、".join(str(x).strip() for x in value if str(x).strip())
        value = str(value or "").strip()
        if value:
            lines.append(labels[key] + "｜" + value)
    return "\n".join(lines)

def build_blueprint_messages(premise, style, chapter_count="complete",
                             locked_world_profile=None):
    raw_count = str(chapter_count or "complete").strip().lower()
