def _blueprint_pick(text, tag, following):
    import re as _re
    stop = "|".join(_re.escape("【" + x + "】") for x in following)
    pat = "【" + _re.escape(tag) + r"】([\s\S]*?)"
    pat += ("(?=" + stop + "|$)") if stop else "$"
    match = _re.search(pat, str(text or ""))
    return match.group(1).strip() if match else ""

def _blueprint_chapters(text):
    import re as _re
    result = []
    for raw in str(text or "").splitlines():
        match = _re.match(r'^\s*(\d+)\s*[\.、|｜:：]\s*(.+)$', raw)
        if not match:
            continue
        parts = _re.split(r'[|｜]', match.group(2))
        title = parts[0].strip()
        brief = "；".join(x.strip() for x in parts[1:] if x.strip())
        if title:
            result.append({"title": title[:40], "brief": brief or title[:60]})
    return result

def _split_profile_list(value):
    import re as _re
    return [
        x.strip() for x in _re.split(r'[、,，;；/]+', str(value or ""))
        if x.strip() and x.strip() not in ("无", "留空", "空")
    ]

def _value_is_user_explicit(value, premise):
    import re as _re
    value = str(value or "").strip()
    premise = str(premise or "").strip()
    if not value or not premise:
        return False
    if value in premise:
        return True
    numbers = _re.findall(r'\d+', value)
    if numbers and any(num in premise for num in numbers):
        return True
    tokens = _re.findall(r'[\u4e00-\u9fff]{2,8}', value)
    return any(token in premise for token in tokens[:4])

def parse_world_visual_profile(text, premise="", locked=False, version=1):
    import re as _re
    found = {}
    for raw in str(text or "").splitlines():
        parts = _re.split(r'[|｜:：]', raw.strip(), maxsplit=1)
        if len(parts) != 2:
            continue
        key = WORLD_VISUAL_LABELS.get(parts[0].strip())
        if key:
            found[key] = parts[1].strip()
    fields = {}
    list_fields = {
        "materials", "clothingSystem", "architectureSystem",
        "toolSystem", "visualTone", "allowedMixedElements",
    }
    for key in WORLD_VISUAL_FIELDS:
        value = found.get(key, "")
        if key in list_fields:
            value = _split_profile_list(value)
        explicit = _value_is_user_explicit(
            "、".join(value) if isinstance(value, list) else value, premise)
        fields[key] = _profile_value(
            value, "user_explicit" if explicit else "world_derived",
            bool(locked or explicit))
    tools_text = "、".join(found.get(key, "") for key in (
        "technology", "toolSystem", "allowedMixedElements"))
    modern_firearms = any(word in tools_text for word in (
        "现代枪械", "手枪", "步枪", "自动武器", "现代火器"))
    magic_firearms = any(word in tools_text for word in (
        "魔法枪", "魔导枪", "符文枪", "炼金火器"))
    industrial = any(word in tools_text for word in (
        "工业机械", "蒸汽机", "内燃机", "自动化", "流水线", "重工业"))
    return {
        "version": max(1, int(version or 1)),
        "locked": bool(locked),
        "fields": fields,
        "permissions": {
            "modernFirearmsAllowed": _profile_value(
                modern_firearms, "world_derived", bool(locked)),
            "industrialMachineryAllowed": _profile_value(
                industrial, "world_derived", bool(locked)),
            "magicFirearmsAllowed": _profile_value(
                magic_firearms, "world_derived", bool(locked)),
        },
    }

def _explicit_empty_prop_for(name, premise, character_count=1):
    import re as _re
    text = str(premise or "")
    empty = _re.search(
        r'(?:从不|不再|不|没有|无需|拒绝|空手).{0,8}(?:携带|使用|依靠)?'
        r'.{0,5}(?:武器|枪械|枪|刀剑|刀|剑|法杖|道具)', text)
    if not empty:
        return False
    if character_count == 1:
        return True
    start = max(0, empty.start() - 18)
    return bool(name and name in text[start:empty.end()])

def _clean_prop_description(value):
    import re as _re
    value = str(value or "").strip()
    if not value or _re.search(r'^(?:无|没有|无需|留空|空|unset|locked_empty)$', value, _re.I):
        return ""
    return value

