def _premise_character_constraints(premise):
    import re as _re
    text = str(premise or "").strip()
    age_match = _re.search(r'(?<!\d)(\d{1,3})\s*岁', text)
    chinese_age = _re.search(r'([零一二三四五六七八九十两]{1,3})岁', text)
    chinese_digits = {"零": 0, "一": 1, "二": 2, "两": 2, "三": 3, "四": 4,
                      "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    def _cn_number(raw):
        if raw == "十":
            return 10
        if "十" in raw:
            left, right = raw.split("十", 1)
            return (chinese_digits.get(left, 1) * 10
                    + chinese_digits.get(right, 0))
        value = 0
        for char in raw:
            value = value * 10 + chinese_digits.get(char, 0)
        return value
    if any(word in text for word in ("少女", "女孩", "女主", "公主", "皇女", "女王")):
        sex = "女性"
    elif any(word in text for word in ("少年", "男孩", "男主", "王子", "皇子", "国王")):
        sex = "男性"
    else:
        sex = ""
    stage = next((word for word in (
        "婴儿", "幼童", "儿童", "小孩", "少年", "少女", "青年", "中年", "老人")
                  if word in text), "")
    hair_length = next((word for word in PREMISE_HAIR_LENGTHS if word in text), "")
    hair_color = next((
        word for word in PREMISE_HAIR_COLORS
        if _re.search(_re.escape(word) + r'(?:及腰|披肩|中长|长|短)?(?:头)?发', text)
    ), "")
    role_candidates = [word for word in PREMISE_ROLE_TERMS if word in text]
    roles = [
        word for word in role_candidates
        if not any(word != other and word in other for other in role_candidates)
    ]
    moods = [word for word in PREMISE_MOOD_TERMS if word in text]
    outfit_tone = next((word for word in (
        "极尽华丽", "华丽", "繁复", "奢华", "朴素", "简朴", "破旧", "制服")
                        if word in text), "")
    return {
        "age": (int(age_match.group(1)) if age_match
                else (_cn_number(chinese_age.group(1)) if chinese_age else None)),
        "sex": sex, "stage": stage,
        "hairLength": hair_length, "hairColor": hair_color,
        "roles": roles, "moods": moods, "outfitTone": outfit_tone,
    }

def _replace_age_with_locked(text, age):
    import re as _re
    text = str(text or "")
    if age is None:
        return text
    replacement = "%d岁" % age
    if _re.search(r'\d{1,3}\s*岁', text):
        return _re.sub(r'\d{1,3}\s*岁', replacement, text)
    return replacement + "，" + text

def _apply_premise_facts_to_character_sections(story_text, visual_text, premise):
    """把原句中能确定的第一主角事实写回字段；模型只负责补充，不得覆盖。"""
    import re as _re
    locks = _premise_character_constraints(premise)
    story_lines = str(story_text or "").splitlines()
    visual_lines = str(visual_text or "").splitlines()
    story_index = next((i for i, line in enumerate(story_lines) if line.strip()), None)
    visual_index = next((i for i, line in enumerate(visual_lines) if line.strip()), None)
    if story_index is not None:
        parts = [x.strip() for x in _re.split(r'[|｜]', story_lines[story_index])]
        if len(parts) >= 3:
            parts[2] = _replace_age_with_locked(parts[2], locks["age"])
            for role in locks["roles"]:
                if role not in "｜".join(parts[:3]):
                    parts[1] = (parts[1] + "，" + role).strip("，")
            for mood in locks["moods"]:
                if mood not in "｜".join(parts):
                    target = 4 if len(parts) > 4 else 1
                    parts[target] = (parts[target] + "，" + mood).strip("，")
            story_lines[story_index] = "｜".join(parts)
    if visual_index is not None:
        prefix = ""
        raw = visual_lines[visual_index]
        numbered = _re.match(r'^(\s*\d+\s*[.、]\s*)', raw)
        if numbered:
            prefix = numbered.group(1)
            raw = raw[numbered.end():]
        parts = [x.strip() for x in _re.split(r'[|｜]', raw)]
        if len(parts) >= 4:
            parts[1] = _replace_age_with_locked(parts[1], locks["age"])
            if locks["sex"] and locks["sex"] not in parts[1]:
                parts[1] = locks["sex"] + "，" + parts[1]
            if locks["stage"] and locks["stage"] not in parts[1]:
                parts[1] += "，" + locks["stage"] + "感"
            for mood in locks["moods"]:
                if mood not in parts[2]:
                    parts[2] += "，带有" + mood + "神态"
            hair = parts[3]
            if locks["hairLength"]:
                hair = _re.sub(
                    r'及腰长发|披肩长发|中长发|长发|短发|寸头|光头',
                    locks["hairLength"], hair)
                if locks["hairLength"] not in hair:
                    hair = locks["hairLength"] + "，" + hair
            if locks["hairColor"] and locks["hairColor"] not in hair:
                hair = locks["hairColor"] + hair
            parts[3] = hair
            visual_lines[visual_index] = prefix + "｜".join(parts)
    return "\n".join(story_lines), "\n".join(visual_lines)

def _blueprint_explicit_fact_issues(text, premise):
    constraints = _premise_character_constraints(premise)
    story = _blueprint_pick(text, "主要人物", (
        "视觉人物卡", "全书大纲", "建议章节数", "章节规划"))
    visual = _blueprint_pick(text, "视觉人物卡", (
        "全书大纲", "建议章节数", "章节规划"))
    first_story = next((x for x in story.splitlines() if x.strip()), "")
    first_visual = next((x for x in visual.splitlines() if x.strip()), "")
    joined = first_story + "\n" + first_visual
    issues = []
    age = constraints["age"]
    if age is not None and ("%d岁" % age) not in joined.replace(" ", ""):
        issues.append("主角年龄必须严格保留为%d岁" % age)
    if constraints["hairLength"] and constraints["hairLength"] not in first_visual:
        issues.append("主角发型长度必须严格保留为" + constraints["hairLength"])
    for role in constraints["roles"]:
        if role not in first_story:
            issues.append("主角身份必须保留：" + role)
    for mood in constraints["moods"]:
        if mood not in joined:
            issues.append("主角气质必须保留：" + mood)
    return issues

def enforce_blueprint_premise_facts(text, premise):
    """重试仍漏事实时做确定性修正，不再让错误年龄和发型进入项目。"""
    import re as _re
    raw = str(text or "")
    tags = ("视觉人物卡", "全书大纲", "建议章节数", "章节规划")
    story = _blueprint_pick(raw, "主要人物", tags)
    visual = _blueprint_pick(raw, "视觉人物卡", tags[1:])
    fixed_story, fixed_visual = _apply_premise_facts_to_character_sections(
        story, visual, premise)
    raw = _re.sub(
        r'【主要人物】[\s\S]*?(?=【视觉人物卡】)',
        "【主要人物】\n" + fixed_story + "\n", raw, count=1)
    raw = _re.sub(
        r'【视觉人物卡】[\s\S]*?(?=【全书大纲】)',
        "【视觉人物卡】\n" + fixed_visual + "\n", raw, count=1)
    return raw

HERO_STYLE_DIRECTIONS = {
    "youthful_elegant": "清俊灵动的年轻主角，轮廓轻盈，眼神聪慧，带少年成长感",
    "hardline_handsome": "硬朗英俊的行动型主角，骨相清晰，神态坚定，轮廓利落",
    "mature_composed": "成熟沉稳的主角，气质克制，五官耐看，具有可靠的领导感",
    "powerful_heroic": "强健挺拔的英雄型主角，肩背有力量，比例修长，具有正面压场感",
    "agile_sharp": "敏捷锐利的主角，身形轻捷，线条干净，眼神警觉而有判断力",
    "noble_refined": "高贵精致的主角，仪态挺拔，剪裁考究，具有受过良好教养的从容",
    "dark_elegant": "冷峻优雅的暗色主角，苍白或冷调肤色，轮廓精致，危险感克制",
    "intellectual_cool": "理性清冷的智慧型主角，五官清晰，神态专注，气质简洁高级",
    "rugged_charismatic": "历练感鲜明的主角，轮廓粗粝但有吸引力，体态强韧，具有生存者气质",
}

BEAUTY_OVERRIDE_TERMS = (
    "长相普通", "不起眼", "路人脸", "不好看", "丑陋", "丑帅", "毁容",
    "病态", "畸形", "衰老", "极度肥胖", "极度瘦弱", "反传统主角外形",
)

def _character_id(name, premise="", index=0):
    raw = "%s|%s|%s" % (str(name or "").strip(), str(premise or "").strip(), index)
    return "character_" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]

def _extract_character_age(text):
    import re as _re
    match = _re.search(r'(\d{1,3})\s*岁', str(text or ""))
    return int(match.group(1)) if match else None

def resolve_hero_style(world_profile=None, story_text="", premise="", requested="auto"):
    requested = str(requested or "auto").strip()
    if requested in HERO_STYLE_DIRECTIONS:
        return requested
    text = " ".join((str(story_text or ""), str(premise or ""), _profile_text(world_profile)))
    age = _extract_character_age(text)
    if any(word in text for word in ("贵族", "王子", "公主", "皇室", "宫廷", "大法师", "皇家")):
        return "noble_refined"
    if age is not None and age <= 20 or any(word in text for word in ("少年", "少女", "学徒", "学生", "见习")):
        return "youthful_elegant"
    if any(word in text for word in ("黑暗", "暗影", "亡灵", "诅咒", "魔族", "吸血鬼", "禁咒")):
        return "dark_elegant"
    if any(word in text for word in ("刺客", "游侠", "特工", "盗贼", "斥候", "猎人")):
        return "agile_sharp"
    if any(word in text for word in ("科学家", "医生", "学者", "工程师", "研究员", "侦探")):
        return "intellectual_cool"
    if any(word in text for word in ("骑士", "勇者", "战士", "将军", "拳师", "武者", "重剑")):
        return "powerful_heroic"
    if any(word in text for word in ("刑警", "警察", "队长", "舰长", "负责人", "中年")):
        return "mature_composed"
    if any(word in text for word in ("废土", "佣兵", "流浪", "荒野", "幸存者")):
        return "rugged_charismatic"
    return "hardline_handsome"

def _default_visual_policy(index, world_profile=None, story_text="", premise=""):
    is_main = index == 0
    combined = str(story_text or "") + " " + str(premise or "")
    explicit_override = any(word in combined for word in BEAUTY_OVERRIDE_TERMS)
    outfit_override = _premise_character_constraints(premise).get("outfitTone") or None
    resolved = resolve_hero_style(world_profile, story_text, premise)
    if is_main:
        return {
            "roleVisualTier": "main_character",
            "beautyBaseline": "user_defined" if explicit_override else "high",
            "bodyQuality": "user_defined" if explicit_override else "excellent",
            "bodyProportion": "user_defined" if explicit_override else "slender_balanced",
            "protagonistAura": "user_defined" if explicit_override else "strong",
            "styleDirection": "auto",
            "styleDirectionResolved": resolved,
            "outfitDesignLevel": "legendary",
            "realismLevel": "cinematic_beautiful",
            "beautyOverride": next(
                (word for word in BEAUTY_OVERRIDE_TERMS if word in combined), None),
            "outfitOverride": outfit_override,
            "sourceMap": {
                "styleDirection": "world_derived",
                "beautyBaseline": "user_explicit" if explicit_override else "ai_optional",
                "bodyProportion": "user_explicit" if explicit_override else "ai_optional",
            },
            "lockedFields": ["beautyBaseline", "bodyProportion"] if explicit_override else [],
        }
    return {
        "roleVisualTier": "supporting_character",
        "beautyBaseline": "believable_attractive",
        "bodyQuality": "role_appropriate",
        "bodyProportion": "natural",
        "protagonistAura": "supporting",
        "styleDirection": "auto",
        "styleDirectionResolved": resolve_hero_style(
            world_profile, story_text, premise),
        "outfitDesignLevel": "refined",
        "realismLevel": "cinematic_believable",
        "beautyOverride": None,
        "outfitOverride": outfit_override,
        "sourceMap": {"styleDirection": "world_derived"},
        "lockedFields": [],
    }

def parse_character_profiles(story_text, visual_text, premise="", world_profile=None):
    import re as _re
    story_rows = {}
    for raw in str(story_text or "").splitlines():
        line = _re.sub(r'^\s*\d+\s*[.、]\s*', '', raw).strip()
        parts = [x.strip() for x in _re.split(r'[|｜]', line)]
        if len(parts) >= 2 and parts[0]:
            story_rows[parts[0]] = parts[1:]

    visual_rows = []
    for raw in str(visual_text or "").splitlines():
        line = _re.sub(r'^\s*\d+\s*[.、]\s*', '', raw).strip()
        parts = [x.strip() for x in _re.split(r'[|｜]', line)]
        if len(parts) >= 2 and parts[0]:
            visual_rows.append((parts[0], parts[1:]))

    result = []
    cards = []
    total = len(visual_rows)
    for index, (name, values) in enumerate(visual_rows):
        padded = values[:12] + [""] * max(0, 12 - len(values))
        visible_values = dict(zip(CHARACTER_VISUAL_LABELS[:9], padded[:9]))
        raw_state = padded[9].lower()
        prop = _clean_prop_description(padded[10])
        identifiers = padded[11]
        # 小模型偶尔把“配色/轮廓/站姿”等编号识别项挤进固定道具列。
        # 这些内容回收到识别特征，不能触发随机持枪或携带道具。
        if prop and (
                _re.match(r'^\d+\s*[.、]', prop)
                or any(word in prop for word in (
                    "配色", "站姿", "轮廓", "反差", "识别特征"))):
            if not any(word in prop for word in ACTUAL_PROP_WORDS):
                identifiers = "；".join(
                    x for x in (identifiers, prop) if str(x or "").strip())
                prop = ""
        explicit_empty = _explicit_empty_prop_for(name, premise, total)
        if explicit_empty or "locked_empty" in raw_state:
            prop_state = "locked_empty"
            prop = ""
            prop_source = "user_explicit" if explicit_empty else "world_derived"
            prop_locked = True
        elif prop or "present" in raw_state:
            prop_state = "present"
            prop_source = "user_explicit" if _value_is_user_explicit(prop, premise) else "world_derived"
            prop_locked = prop_source == "user_explicit"
        else:
            prop_state = "unset"
            prop = ""
            prop_source = "ai_optional"
            prop_locked = False

        field_nodes = {}
        card_parts = []
        for label in CHARACTER_VISUAL_LABELS[:9]:
            value = visible_values.get(label, "").strip()
            source = "user_explicit" if _value_is_user_explicit(value, premise) else "world_derived"
            field_nodes[label] = _profile_value(value, source, source == "user_explicit")
            if value:
                card_parts.append(label + "：" + value)
        field_nodes["固定道具"] = _profile_value(prop, prop_source, prop_locked)
        field_nodes["识别特征"] = _profile_value(
            identifiers,
            "user_explicit" if _value_is_user_explicit(identifiers, premise) else "world_derived",
            _value_is_user_explicit(identifiers, premise))
        if prop_state == "present" and prop:
            card_parts.append("固定道具：" + prop)
        if identifiers:
            card_parts.append("识别特征：" + identifiers)
        card = name + "—" + "；".join(card_parts)
        cards.append(card)
        story_raw = "｜".join(story_rows.get(name, []))
        visual_policy = _default_visual_policy(
            index, world_profile, story_raw, premise)
        result.append({
            "name": name,
            "character_id": _character_id(name, premise, index),
            "version": 1,
            "story_profile": {
                "raw": _profile_value(story_raw, "ai_optional", False),
                "explicitFacts": _profile_value(str(premise or "").strip(), "user_explicit", True),
            },
            "visual_profile": field_nodes,
            "visual_policy": visual_policy,
            "propState": _profile_value(prop_state, prop_source, prop_locked),
            "assembledCard": card,
            "generation_state": {
                "profileVersion": 1,
                "assetVersion": 0,
                "worldProfileVersion": int((world_profile or {}).get("version") or 1),
                "masterStatus": "pending",
            },
        })
    return result, "\n".join(cards)

def parse_blueprint_result(text, premise="", existing_world_profile=None):
    tags = [
        "书名", "题材与视觉基准", "世界观", "主要人物",
        "视觉人物卡", "全书大纲", "建议章节数", "章节规划",
    ]
    parts = {
        tag: _blueprint_pick(text, tag, tags[index + 1:])
        for index, tag in enumerate(tags)
    }
    parts["主要人物"], parts["视觉人物卡"] = _apply_premise_facts_to_character_sections(
        parts["主要人物"], parts["视觉人物卡"], premise)
    existing = existing_world_profile if isinstance(existing_world_profile, dict) else {}
    if existing.get("locked"):
        world_profile = existing
    else:
        world_profile = parse_world_visual_profile(
            parts["题材与视觉基准"], premise,
            False, int(existing.get("version") or 0) + 1)
    character_profiles, char_sheet = parse_character_profiles(
        parts["主要人物"], parts["视觉人物卡"], premise, world_profile)
    return {
        "title": parts["书名"].replace("《", "").replace("》", "").strip(),
        "worldVisualText": _profile_text(world_profile),
        "world_visual_profile": world_profile,
        "world": parts["世界观"],
        "chars": parts["主要人物"],
        "visualCards": parts["视觉人物卡"],
        "charSheet": char_sheet,
        "character_profiles": character_profiles,
        "outline": parts["全书大纲"],
        "chapters": _blueprint_chapters(parts["章节规划"]),
    }

def validate_blueprint_result(text, premise, chapter_count):
    parsed = parse_blueprint_result(text, premise)
    issues = []
    for key in ("title", "worldVisualText", "world", "chars", "charSheet", "outline"):
        if not str(parsed.get(key) or "").strip():
            issues.append("缺少" + key)
    actual = len(parsed.get("chapters") or [])
    raw_count = str(chapter_count or "complete").lower()
    if raw_count in ("1", "5", "15") and actual != int(raw_count):
        issues.append("章节数应为%s，实际为%s" % (raw_count, actual))
    if raw_count == "complete" and not 30 <= actual <= 60:
        issues.append("完整长篇章节数必须在30到60之间，实际为%s" % actual)
    if _premise_overlap(premise, text) < 0.16:
        issues.append("输出明显偏离用户原句")
    issues.extend(_blueprint_explicit_fact_issues(text, premise))
    if _explicit_empty_prop_for("", premise, 1):
        states = [
            _profile_node_value(x.get("propState"), "")
            for x in parsed.get("character_profiles") or []
        ]
        if states and "locked_empty" not in states:
            issues.append("用户明确空手，但道具状态没有锁定为locked_empty")
    return issues

def build_more_chapters_messages(setting, outline, existing_titles, count):
    system = (
        "你是网文策划。下面给出一部小说的设定、大纲和已经规划好的章节。"
        "请紧接着最后一章往后，再设计 %d 章，剧情自然承接、层层推进，不得与已有章节重复。"
        "只输出章节行，每行格式：序号|本章标题|这一章要写的内容（40-70字）。不要写别的。" % count
    )
    parts = []
    if setting.strip(): parts.append("【设定】\n" + setting.strip())
    if outline.strip(): parts.append("【大纲】\n" + outline.strip())
    parts.append("【已有章节标题】\n" + "；".join(existing_titles[-30:]))
    parts.append("请从第 %d 章开始，再设计 %d 章。" % (len(existing_titles) + 1, count))
    return [{"role": "system", "content": system}, {"role": "user", "content": "\n\n".join(parts)}], count * 90 + 500

def summarize(text):
    msgs = [
        {"role": "system", "content": "你是编辑助手。把用户给的小说章节浓缩成一句到三句话的剧情摘要，只保留关键情节、人物动向和伏笔，150字以内，不要评论。"},
        {"role": "user", "content": text.strip()[:4000]},
    ]
    return chat_stream(msgs, temperature=0.3)

def gen_charsheet(chars_text, art, world_visual_profile=None, premise=""):
    """把小说人物描述，转成画图用的角色外观卡（名字—外观），供漫画锁定人物。"""
    world_text = _profile_text(world_visual_profile)
    msgs = [
        {"role": "system", "content":
         "你是漫画角色设定师。把用户给的小说人物，转成【画图专用的角色外观卡】。"
         "人物外观必须从给定的题材、时代、文明、技术、材料、服装体系、阶层和职业推导，"
         "不能脱离世界观套用现代战术人员、古代侠客或其他常见模板。"
         "第一行人物按主角处理：用户没有明确要求普通、丑陋、病态或反传统外形时，"
         "自动采用电影主演级协调五官、修长匀称比例、挺拔体态和鲜明主角气质；"
         "服装在世界工艺与人物身份允许范围内采用华丽繁复的主角级设计：至少内中外三层轮廓，"
         "明确高级材质、领肩袖腰结构、精细滚边或刺绣、稳定主辅色和一处身份纹样。"
         "配角也采用精致好看的完整服装，但轮廓和装饰层级低于主角。"
         "用户明确要求朴素、贫穷、破旧或制服时才降低装饰程度。"
         "少年魔法师应清俊灵动并有法术学徒或施法者的服装语言，不能写成现代便装路人；"
         "战士、侦探、学者等则按身份自动换成相应的主角美术方向。"
         "每个主要角色独占一行，格式：名字—外观。外观只写画图需要、镜头能看见的固定特征，采用【" +
         (art or "写实真人") + "】画风的描述，依次包含：性别与年龄段、脸型与一个关键五官、发型发色、"
         "正常可信的肤色体型、完整上装、完整下装、鞋靴、必要外层服装、最多一处固定疤痕或配饰。"
         "每人只保留3—5个能在远景或剪影里一眼认出的视觉锚点；"
         "不同角色的轮廓、主色、体态和标志物要有明显区分。若原文有专属武器或道具，写清其形状、尺度、材质、颜色和固定携带位置。"
         "用户明确空手或不携带武器时，整行省略武器与道具字段，不写任何武器词。"
         "不要写性格、目标、剧情、心理、当前伤势、血污、破损衣服、临时变身、当前手持物或某章换装；"
         "每人一行，不要编号、不要多余的话。"},
        {"role": "user", "content":
         ("【题材与世界视觉基准】\n" + (world_text or "按人物原始设定采用统一、可信的时代与服装体系") +
          "\n\n【用户原句事实】\n" + str(premise or "").strip()[:800] +
          "\n\n【故事人物档案】\n" + (chars_text or "").strip()[:3000])},
    ]
    return chat_stream(msgs, temperature=0.5)

def update_bible(old_bible, chapter_text):
    """用一次轻量调用同时更新全局连续性，并作为该章结束时的人物状态快照。"""
    msgs = [
        {"role": "system", "content":
         "你是小说连续性管理员。根据最新章节覆盖更新一份紧凑备忘，只保留后文或漫画真正需要的事实。"
         "有姓名且参与剧情的人物每人一行，格式：姓名｜年龄阶段与明显年龄感｜当前位置｜"
         "本章结束时可见外观变化（衣着、伤势、血污、发型、身体变化；无则写无）｜关键物品/能力｜关系或已知信息。"
         "儿童、少年和老人必须写清年龄阶段及儿童比例、少年感、皱纹白发或佝偻等可见年龄特征；"
         "普通成年人只写年龄段，不反复堆精确数字。\n"
         "【必须保留的第二部分：伏笔账本】人物行之后，另起一行写“===伏笔账本===”，"
         "然后每条伏笔一行，格式：第N章埋｜伏笔内容｜当前状态(未回收/推进中/已回收)。"
         "本章新埋的钩子要加进来；本章回收或推进的要更新状态；"
         "已回收的伏笔保留一行并标“已回收”，不要删掉，方便后文不再重复使用。"
         "凡是原文出现过但没有交代结果的东西——神秘信件、突然出现的人、没解释的伤、许下的承诺、提到的地名或组织——都要记成伏笔。\n"
         "删除失效的临时状态，人物部分尽量控制在1000字内，伏笔账本不限但每条从简。"
         "只输出更新后的完整备忘，不解释、不复述正文。"},
        {"role": "user", "content": "【当前角色状态备忘】\n" + (old_bible or "（空）") +
         "\n\n【最新章节】\n" + chapter_text.strip()[:4500] + "\n\n请输出更新后的紧凑备忘。"},
    ]
    return chat_stream(msgs, temperature=0.3)

def _premise_overlap(premise, story):
    """用低成本字面二元组拦截完全换题；不要求模型逐字照抄。"""
    import re as _re
    source = "".join(_re.findall(r'[\u4e00-\u9fffA-Za-z0-9]', str(premise or ""))).lower()
    target = "".join(_re.findall(r'[\u4e00-\u9fffA-Za-z0-9]', str(story or ""))).lower()
    if len(source) < 4:
        return 1.0 if source and source in target else 0.0
    grams = {source[i:i + 2] for i in range(len(source) - 1)}
    return sum(1 for gram in grams if gram in target) / max(1, len(grams))

def _compact_quick_story(story, premise, max_chars=420):
    """模型偶尔超写时按可见节拍压到单页容量，不再调用模型。"""
    import re as _re
    story = str(story or "").strip()
    if len(story) <= max_chars:
        return story
    beats = [x.strip() for x in _re.findall(r'[^。！？!?\n]+[。！？!?]?', story) if x.strip()]
    if len(beats) <= 2:
        return story[:max_chars].rstrip("，,；; ") + "。"
    source = "".join(_re.findall(r'[\u4e00-\u9fffA-Za-z0-9]', str(premise or ""))).lower()
    grams = {source[i:i + 2] for i in range(max(0, len(source) - 1))}
    action_words = ("发现", "打开", "冲", "跑", "抓", "救", "打", "追", "逃", "落下",
                    "倒下", "醒来", "决定", "看见", "听见", "抱", "捡", "拔", "挥")
    chosen = {0, len(beats) - 1}
    if len(beats) > 3:
        chosen.update((1, len(beats) - 2))
    def score(index):
        compact = "".join(_re.findall(r'[\u4e00-\u9fffA-Za-z0-9]', beats[index])).lower()
        overlap = sum(1 for gram in grams if gram in compact)
        return overlap * 5 + sum(2 for word in action_words if word in beats[index])
    candidates = sorted(
        (i for i in range(2, len(beats) - 2) if i not in chosen),
        key=lambda i: (-score(i), i))
    for index in candidates:
        trial = "".join(beats[i] for i in sorted(chosen | {index}))
        if len(trial) <= max_chars:
            chosen.add(index)
    compacted = "".join(beats[i] for i in sorted(chosen))
    if len(compacted) > max_chars:
        end = beats[-1]
        room = max(80, max_chars - len(end))
        compacted = story[:room].rstrip("，,；; ") + "。" + end
    return compacted[:max_chars].rstrip("，,；; ") + ("" if compacted[:max_chars].endswith(tuple("。！？!?")) else "。")

def generate_quick_comic_story(premise, art):
    """把一句话扩成可直接走“小说整页单图”管线的极短正文和轻量角色卡。"""
    premise = str(premise or "").strip()
    system = (
        "你是短篇漫画编剧。把一句话扩写成180—320字、可用一张竖版多格漫画页讲完的中文小故事；正文不得超过360字。"
        "用户的一句话是不可替换的故事核心：其中明确的人物年龄、地点、关键物品、动作目标和结果都必须保留，"
        "禁止另写一个相似主题或完全不同的故事。"
        "只保留1—3名有姓名的人物，必须有迅速入戏的开头、一次清楚的冲突或意外、可见的结果；"
        "整篇控制为3—6个能被相机直接拍到的主要视觉节拍，每个节拍只突出一个动作或状态，"
        "不并列堆放多个场景、人物动作和变化。动作和对白都要能画出来，不写庞大背景、支线和长篇解释。"
        "人物外观只写3—5个生图必需的固定辨识特征；儿童、少年、老人必须同时写年龄阶段和可见年龄特征，"
        "普通成年人写年龄段即可。严格输出JSON："
        '{"title":"短标题","characters":[{"name":"姓名","look":"性别年龄段；脸和发型；体型；服装主色；标志物"}],'
        '"story":"连续正文"}。不要解释，不要Markdown。'
    )
    user = (
        "画风：" + _norm_art(art) +
        "\n【不可替换的原始故事核心】" + premise +
        "\n扩写只能补充过程，不得改变上述核心事实。"
    )
    data = None
    story = ""
    for attempt in range(2):
        attempt_user = user
        if attempt:
            attempt_user += (
                "\n上一次输出偏离原题。此次正文必须直接出现原题中的主要人物年龄/身份、"
                "关键地点、关键物品和行动结果，否则视为失败。"
            )
        raw = chat_stream(
            [{"role": "system", "content": system},
             {"role": "user", "content": attempt_user}],
            0.55 if attempt else 0.7, None, 1000)
        data = _extract_json(raw)
        story = str(data.get("story") or "").strip() if isinstance(data, dict) else ""
        if len(story) >= 80 and _premise_overlap(premise, story) >= 0.18:
            break
    if not isinstance(data, dict):
        raise RuntimeError("一句话短篇没有返回可解析内容")
    if len(story) < 80:
        raise RuntimeError("一句话短篇正文过短")
    if _premise_overlap(premise, story) < 0.18:
        raise RuntimeError("一句话短篇连续两次偏离原题，请把故事写得再具体一点")
    story = _compact_quick_story(story, premise)
    title = str(data.get("title") or premise or "一句话短篇").strip()[:30]
    rows = []
    for item in data.get("characters", []) if isinstance(data.get("characters"), list) else []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "").strip()
        look = str(item.get("look") or "").strip()
        if name and look and name in story and len(rows) < 3:
            rows.append("%s—%s" % (name, look))
    return {"title": title, "story": story, "charSheet": "\n".join(rows)}

def build_quick_visual_plan_messages(premise, art, extra=""):
    """一句话漫画直接产出画面计划，不经过小说正文。"""
    system = """你是一句话漫画导演。把用户的一句话直接设计成一张竖版漫画页的结构化可见画面计划，不写小说正文，不输出分析过程，不写生图长提示词。

【不可替换的核心】
用户原句里明确的人物年龄或身份、地点、关键物品、动作目标、动作结果和对白都是硬事实，必须保留，禁止另写一个相似题材。
可以补充完成画面所需的中性过渡动作，但不能增加新支线、庞大背景、新能力、新人物关系或改变结果。
战斗结果强度按用户输入与所选内容倾向直接表现，不回避血腥特写；不擅自添加用户没有写的支线情节。

【画面选择】
先在内部判断真正需要展示几个不同瞬间，再选择1—6格：一个画面用hero；两个用hero+strip；三个用hero+2；四个用hero+2+1；五个动作高潮用2+hero+2，其他五个用hero+2+2；六个才用1+2+2+1。
一句话只是一个姿态、地点或人物展示时，用整页单幅；不要为了像漫画而补重复镜头。
一句话包含完整事件时，优先保留开始状态、冲突、关键动作和明确结果；每格只有一个画面中心。
每格是一个静止时间点，不得把同一人物的动作前与动作后同时画在一格。写“倒地”时只写倒地后的唯一身体，不再写扑来或站立状态。
挥砍、划向、扑向、冲撞等连续动作必须改写成蓄势停顿、已经接触或动作完成后的落点，写清支点、重心、身体朝向、四肢和武器停留位置。
多人拥抱、搀扶、抓握、压制或推拉时，必须逐人写清左右前后、身体朝向、每只手属于谁以及接触对方哪个部位。

【可见信息减法】
每格只填相机真正能拍到的内容。背影只填发型、轮廓、背部服装和可见背负物；正脸、眼睛和心理为空。远景只填剪影、体态、服装色块和大型武器。物件特写不填完整人物。
特大武器、面具、机械肢体等标志物只要当前镜头能看见，就作为独立身份锚点保留，不得被普通五官描述挤掉。
people 必须逐项列出这一格真实入镜的人物，每人只列一次；不得把同一个流氓、敌人或主角画成两个。纯环境和物件特写填空数组。

【输出】
只输出一个JSON对象，不要Markdown或任何解释：
{
  "title":"不超过12字的短标题",
  "layout":"hero/hero+strip/hero+2/hero+2+1/hero+2+2/2+hero+2/1+2+2+1",
  "characters":[
    {"name":"姓名或临时称呼","anchors":"3—5个实际会入镜的固定视觉锚点，优先轮廓、服装主色和标志性武器"}
  ],
  "scene":"2—4个必要环境锚点",
  "light":"一种必要光线或色彩条件，没有则空",
  "panels":[
    {
      "source_fact":"该格承载的用户原句事实，简短填写",
      "shot":"景别和机位，尽量12字内",
      "subject":"一个当前可见主体，尽量12字内",
      "people":["本格实际入镜的人物名；纯环境或物件空数组"],
      "visible":"当前机位可见的身份特征，尽量24字内",
      "action":"一个主要动作或最终状态，尽量24字内",
      "environment":"最多一个必要环境关系，不需要留空",
      "interaction":"多人身体接触时逐人写清左右前后、每只手和具体接触部位；没有身体接触留空"
    }
  ]
}

默认生成无字画面，不自动编写对白；用户原句里已有明确引号对白时，也只保留在本地排字阶段，不写进画面字段。画风由程序统一追加，不在JSON里复述。"""
    user = [
        "【不可替换的原始故事核心】\n" + str(premise or "").strip(),
        "【选定画风（只影响镜头夸张尺度，不要复述）】\n" + _norm_art(art),
    ]
    if str(extra or "").strip():
        user.append("【成品控制要求】\n" + str(extra).strip())
    user.append("只输出结构化JSON画面计划，不写小说。")
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(user)}], 1500

def _quick_plan_escalation(premise, raw):
    """拦截把普通击倒擅自升级为斩首、断肢或死亡的画面计划。"""
    source = str(premise or "")
    output = str(raw or "")
    groups = [
        (("斩首", "断头", "头颅断裂", "脑袋飞", "身首异处"),
         ("斩首", "断头", "砍头", "头颅断裂", "脑袋飞", "身首异处", "首级")),
        (("断肢", "手臂断裂", "肢体分离"),
         ("断肢", "断臂", "断腿", "手臂断裂", "肢体分离")),
        (("死亡", "尸体", "死去", "毙命"),
         ("死亡", "尸体", "死去", "毙命", "杀死", "处决")),
    ]
    for output_terms, source_terms in groups:
        found = next((term for term in output_terms if term in output), "")
        if found and not any(term in source for term in source_terms):
            return found
    return ""

def generate_quick_visual_plan(premise, art, extra="", temperature=0.65):
    """一次模型调用直接得到单页画面计划，再由程序编译为短提示词。"""
    premise = str(premise or "").strip()
    if not premise:
        raise RuntimeError("请先写一句话故事")
    msgs, num_predict = build_quick_visual_plan_messages(premise, art, extra)
    raw = ""
    plan = None
    for attempt in range(2):
        attempt_msgs = list(msgs)
        if attempt:
            attempt_msgs.append({
                "role": "user",
                "content": (
                    "上一版不是有效画面计划或偏离原句。请重新输出有效JSON；"
                    "必须直接保留原句中的人物、地点、关键物品、主要动作和结果，不写小说。"
                ),
            })
        raw = chat_stream(
            attempt_msgs, temperature if not attempt else 0.35,
            None, num_predict).strip()
        candidate = _extract_json(raw)
        panels = candidate.get("panels") if isinstance(candidate, dict) else None
        overlap = _premise_overlap(premise, raw)
        escalation = _quick_plan_escalation(premise, raw)
        if isinstance(panels, list) and panels and overlap >= 0.18 and not escalation:
            plan = candidate
            break
    if not isinstance(plan, dict):
        raise RuntimeError("一句话画面计划生成失败，请把人物、地点和动作写得再具体一点")
    fallback = choose_onepage_direction(premise, "adaptive", 6)
    prompt_body, direction = _compile_onepage_plan(plan, fallback, False, quick_mode=True)
    if not prompt_body:
        raise RuntimeError("一句话画面计划里没有可生成的画面")
    title = _short_visual(plan.get("title") or premise, 20) or "一句话漫画"
    rows = []
    for item in (plan.get("characters") or [])[:4]:
        if not isinstance(item, dict):
            continue
        name = _short_visual(item.get("name"), 12)
        anchors = _short_visual(item.get("anchors"), 90)
        if name and anchors:
            rows.append("%s—%s" % (name, anchors))
    return {
        "title": title,
        "premise": premise,
        "plan": plan,
        "prompt": _style_locked_prompt(prompt_body, art),
        "panel_count": direction["panels"],
        "layout": direction["layout"],
        "direction": direction,
        "charSheet": "\n".join(rows),
    }

