def _creative_item_violation(mode, item):
    if mode not in CREATIVE_FORBIDDEN_FIELDS or not isinstance(item, dict):
        return ""
    text = " ".join(str(item.get(k) or "") for k in (
        "subject", "shot", "action", "environment", "lighting", "palette", "material"))
    return next((term for term in CREATIVE_FORBIDDEN_FIELDS[mode] if term in text), "")

def _creative_topic_anchors(premise):
    """提取用户主题中的短锚点，用于拦住本地模型偶发沿用旧主题。"""
    import re as _re
    primary = str(premise or "").split("【固定人物视觉档案】", 1)[0][:800]
    anchors = []
    stop = {
        "一个", "一种", "一组", "一些", "这个", "那个", "生成", "制作", "系列",
        "图片", "画面", "风格", "主题", "需要", "想要", "故事", "世界",
    }
    for seq in _re.findall(r"[\u3400-\u9fff]{2,}", primary):
        if 2 <= len(seq) <= 8 and seq not in stop:
            anchors.append(seq)
        for size in (4, 3, 2):
            for i in range(max(0, len(seq) - size + 1)):
                part = seq[i:i + size]
                if part not in stop:
                    anchors.append(part)
    anchors.extend(x.lower() for x in _re.findall(r"[A-Za-z0-9][A-Za-z0-9_-]{2,}", primary))
    seen = set()
    return [x for x in anchors if not (x in seen or seen.add(x))][:80]

def _creative_topic_violation(premise, candidate):
    anchors = _creative_topic_anchors(premise)
    if not anchors:
        return ""
    rendered = json.dumps(candidate, ensure_ascii=False).lower()
    if any(anchor.lower() in rendered for anchor in anchors):
        return ""
    return "、".join(anchors[:10])

def _creative_prompt(mode, plan, item, art, aspect):
    label = CREATIVE_MODE_LABELS.get(mode, "主题图集")
    series_lock = _creative_clean(plan.get("series_lock"), 520)
    subject = _creative_clean(item.get("subject") or item.get("name"), 160)
    shot = _creative_clean(item.get("shot"), 130)
    action = _creative_clean(item.get("action"), 140)
    environment = _creative_clean(item.get("environment"), 180)
    lighting = _creative_clean(item.get("lighting"), 120)
    palette = _creative_clean(item.get("palette"), 100)
    material = _creative_clean(item.get("material") or item.get("detail"), 150)
    pieces = [
        _norm_art(art),
        CREATIVE_POSITIVE_FINISH.get(mode, label + "成品"),
        series_lock,
        subject,
        action,
        shot,
        environment,
        lighting,
        palette,
        material,
    ]
    if mode in ("fixed_portrait", "character_design"):
        pieces.append("同一人物的年龄感、骨相、五官距离、身材比例、发型和永久标志精确统一")
    if mode == "fixed_portrait":
        pieces.append("单幅画面中一位真实人物主体，单一连续身体，人物轮廓与肢体关系完整清楚，镜面和玻璃呈现抽象环境反光")
    if mode == "character_design":
        pieces.append("白色或淡米白摄影棚背景，完整全身比例，清楚脸部角度和可辨认表情")
    if mode == "world_album":
        pieces.append("空旷静谧的建筑环境，前景引导、中景主体、远景轮廓形成深远空间层次")
    if mode == "creature_codex":
        pieces.append("非人类生物独占画面，完整轮廓，明确尺度，生态环境与身体结构相互匹配")
    if mode == "object_design":
        pieces.append("器物独立陈列，完整外轮廓，清晰连接结构，真实制造材料与功能性磨损")
    pieces.append(str(aspect or "16:9") + "画幅，纯净成品画面，当前景别内主体构图完整，视觉中心明确")
    return "。".join(x.rstrip("。") for x in pieces if x) + "。"

def build_creative_plan_messages(mode, premise, count, directive=""):
    if mode not in CREATIVE_MODE_LABELS:
        raise RuntimeError("不支持的快速创作类型")
    count = 3 if mode == "character_design" else max(2, min(int(count or 6), 12))
    system = f"""你是{CREATIVE_MODE_LABELS[mode]}的视觉策划。把用户主题规划为{count}张可以独立生成的图片。
先完整理解主题，再做减法：每张只保留一个主体、一个清楚姿态或状态、一个必要环境。每一项都要使用Krea2容易理解的具体可见描述。
最终生图词将按“媒介与画风→主体→动作→构图→环境→光线→色谱→材质”组合，所以字段之间不要重复同一句形容。

【本类型规则】
{CREATIVE_MODE_RULES[mode]}

只输出一个JSON对象，不要Markdown：
{{
  "title":"12字以内系列名",
  "series_lock":"整个系列真正需要统一的可见设定；固定人物类180—320字，其他类型100—220字",
  "items":[
    {{
      "name":"本张短标题",
      "subject":"本张唯一主体及准确可见特征，最多70字",
      "shot":"景别、机位、焦段、主体位置、前中后景或设定页排法，最多60字",
      "action":"一个姿态、动作落点或最终状态，最多55字",
      "environment":"一个必要环境及空间结构，最多70字",
      "lighting":"真实主光源、方向、明暗关系和空气状态，最多50字",
      "palette":"2—4种主色及冷暖关系，最多35字",
      "material":"3—5种关键材质、表面状态与真实细节，最多55字"
    }}
  ]
}}
items必须正好{count}项。规划时可以使用否定约束，但各字段只写最终画面里实际呈现的正向可见内容。"""
    user_parts = [
        "【用户主题】\n" + str(premise or "").strip(),
        "【可编辑优化指令】\n" + (
            str(directive or "").strip() or CREATIVE_DEFAULT_DIRECTIVES[mode]),
    ]
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(user_parts)}], min(3200, 700 + count * 220)

def generate_creative_plan(mode, premise, art, count=6, directive="", aspect="16:9"):
    premise = str(premise or "").strip()
    if not premise:
        raise RuntimeError("请先填写要创作的主题")
    count = 3 if mode == "character_design" else max(2, min(int(count or 6), 12))
    messages, num_predict = build_creative_plan_messages(mode, premise, count, directive)
    plan = None
    raw = ""
    validation_feedback = ""
    for attempt in range(3):
        attempt_messages = list(messages)
        if validation_feedback:
            attempt_messages.append({
                "role": "user",
                "content": validation_feedback,
            })
        elif attempt:
            attempt_messages.append({
                "role": "user",
                "content": "上一版不是有效JSON或数量不正确。请严格按字段重新输出，items正好%d项。" % count,
            })
        raw = chat_stream(attempt_messages, 0.55 if not attempt else 0.3,
                          None, num_predict).strip()
        candidate = _extract_json(raw)
        items = candidate.get("items") if isinstance(candidate, dict) else None
        if isinstance(items, list) and len(items) == count and all(isinstance(x, dict) for x in items):
            missing_topic = _creative_topic_violation(premise, candidate)
            if missing_topic:
                validation_feedback = (
                    "上一版偏离了用户主题。请重新阅读【用户主题】，并在series_lock和items中明确保留"
                    "这些原始主题锚点中的至少一个：%s。不得换成另一套故事或世界。" % missing_topic)
                continue
            violation = next((_creative_item_violation(mode, x) for x in items
                              if _creative_item_violation(mode, x)), "")
            if not violation:
                plan = candidate
                break
            validation_feedback = (
                "上一版画面规划混入了“%s”。请按本类型主体范围重新输出全部JSON，"
                "各字段只写最终应出现的正向视觉内容。" % violation)
        else:
            validation_feedback = (
                "上一版不是有效JSON或数量不正确。请严格按字段重新输出，items正好%d项。" % count)
    if not isinstance(plan, dict):
        raise RuntimeError("图集规划没有返回有效内容，请把主题写得更具体一些")
    title = _creative_clean(plan.get("title") or premise, 24) or CREATIVE_MODE_LABELS[mode]
    prompts = []
    for index, item in enumerate(plan["items"], 1):
        prompts.append({
            "index": index,
            "name": _creative_clean(item.get("name") or ("第%d张" % index), 32),
            "prompt": _creative_prompt(mode, plan, item, art, aspect),
            "plan": item,
        })
    return {
        "mode": mode, "modeLabel": CREATIVE_MODE_LABELS[mode],
        "title": title, "premise": premise, "aspect": aspect,
        "count": len(prompts), "seriesLock": _creative_clean(plan.get("series_lock"), 520),
        "directive": str(directive or "").strip() or CREATIVE_DEFAULT_DIRECTIVES[mode],
        "items": prompts, "plan": plan,
    }

DEFAULT_CINEMATIC_STILL_DIRECTIVE = """你是顶级电影剧照提示词生成器，专门为 Krea 2 生成高质量中文生图提示词。

你的任务是：当用户给出一句非常简短的画面描述、人物关系、场景想法或情绪主题时，直接将它扩写成一段可以用于 Krea 2 的高质量中文提示词，生成结果必须像真实电影中的定帧画面，具有极强的电影感、镜头语言、人物调度、空间纵深、真实光影和画面张力。

你的最高目标不是“描述清楚”，而是让画面看起来像一部真正的电影剧照：有导演感，有摄影感，有分镜意识，有叙事张力，有真实空间，有光影设计，有情绪压迫或氛围感染力，而不是普通摆拍、网红写真、插画海报或平淡的人像图。

【输出要求】
1. 只输出一整段最终中文提示词，不要解释，不要分析，不要加标题，不要加引号，不要分点，不要写参数，不要写负面提示词。
2. 输出内容必须自然流畅，像一段成熟的视觉提示词，而不是条目堆砌。
3. 当用户描述很简单时，你要主动补全镜头语言、人物动作、人物站位、场景细节、光线来源、色调、氛围和摄影感。
4. 默认按“电影剧照”方向处理，而不是海报、宣传照、写真照、棚拍照或插画，除非用户明确要求。
5. 优先生成有真实演员感、真实空间、真实布景和真实摄影逻辑的画面，不要生成明显 AI 感、摆拍感、廉价感或过度装饰感的画面。

【核心原则】

一、先建立“这是电影镜头，不是普通图片”
你生成的每一段提示词，都必须带有明确的镜头意识和分镜意识。画面要像电影中的一个决定性瞬间，而不是随便一张人像。要明确这个镜头是在交代环境、表现人物状态、制造悬念、强化对峙、放大情绪，还是展示动作爆发前后的瞬间。要让人感觉到这个画面来自一段完整的电影叙事。

二、人物必须像真实演员，不像模特
人物要有真实演员感，而不是摆拍模特感。写清人物的年龄感、气质、五官特征、身形、穿着、姿势、动作和表情，但不要写成死板的人设卡。人物要处于“正在发生事情”的状态里，而不是站着给镜头看。默认人物动作要自然，有内在情绪，有正在思考、观察、犹豫、隐忍、戒备、对峙、疲惫、崩溃或冷静压抑的感觉。

三、必须有清晰的镜头语言
要主动设计画面的景别、机位和观察角度，例如大全景、中景、中近景、近景、特写，平视、低机位、高机位、侧后方、过肩、远距离窥视、贴近式凝视等。镜头角度必须服务于人物和情绪，比如低机位强化压迫感，远景强化孤独感，中近景突出呼吸与表情，过肩镜头强化关系张力。不要空泛地写“电影感”，而要让提示词本身具备镜头语言。

四、人物站位和空间调度必须明确
要明确人物位于画面中的哪里，例如站在画面中央偏左、靠近前景、坐在窗边、站在走廊尽头、背对镜头站在门口、靠着墙缩在角落、从右侧入画等。多人画面时，要明确主次、前后关系和距离关系。画面中最好有前景、中景、背景层次，形成真实纵深和空间压迫。不要只写“一个人在房间里”，要写出他在房间里的具体位置，以及环境如何包围他。

五、场景必须真实具体，有电影布景感
要把场景写实、写具体，像真实电影里的空间，而不是空泛背景。写清环境的结构、材质和关键元素，例如老旧公寓的墙皮、冷清走廊的荧光灯、地下车库的混凝土柱、酒店房间的落地窗和窗帘、雨夜街头的积水与霓虹、码头的雾气和集装箱、厨房里的台面、水汽和吊灯。场景必须带有生活痕迹、使用痕迹、湿度、灰尘、反光或空气感，形成可信的真实空间。

六、光线必须真实，像电影摄影而不是人自带打光
一定要明确主光源来自哪里，例如窗外自然光、霓虹灯、路灯、吊灯、车灯、屏幕光、晨雾中的天光、傍晚余晖、走廊顶灯、酒吧环境光等。写清楚光线如何落在人物身上，哪些地方亮，哪些地方暗，是否有轮廓光、侧逆光、边缘光、反射光、局部高光、阴影压暗、雾气吃光、地面反光等。光线要符合环境逻辑，人物绝不能像棚拍一样自带完美打光。

七、色调和调色必须明确，且服务情绪
要主动赋予画面明确的电影调色方向，例如冷灰蓝、暗绿色、棕灰低饱和、潮湿的蓝黑色夜景、琥珀色暖光、霓虹紫红混合冷青色等。调色要服务画面情绪，比如孤独感用冷调和空旷阴影，危险感用高反差暗部，暧昧感用柔暖低照度，压抑感用低饱和和发闷色温。不要只写“高级感”或“电影感”，而要写出真正的色调关系。

八、强调 Krea 2 更擅长的“真实质感与审美”
输出时优先强调真实人物摄影质感、真实皮肤与骨相、自然褶皱、空气透视、景深层次、复杂但自然的物理光影、材质反射、边缘细节和细腻颗粒感。画面整体要精致、有审美判断，但不要油腻，不要为了“高级”而过度堆砌元素。让构图、人物、环境和光线一起形成张力。

九、画面必须有张力，不要平
每一张图都要尽量像一个“被捕捉到的关键瞬间”。可以是人物刚转头、正停住脚步、沉默对峙、靠窗发呆、手刚碰到门把手、准备开口、受伤后喘息、准备行动前的停顿、暴雨中站定、灯光下看向远处。不要写成没有动作支点的静态站桩图。张力可以来自人物动作、人物之间的距离、环境压迫、前景遮挡、透视线条、明暗冲突或镜头角度。

十、整体默认风格
在用户没有额外指定时，默认采用：真实电影剧照质感，真人演员感，电影级构图，成熟摄影调度，低饱和调色，强烈光影层次，真实空间纵深，浅景深，空气透视，细腻颗粒感，情绪压缩感，具有叙事张力和决定性瞬间的电影镜头。

【执行方式】
当用户输入一句简单描述时，不要重复用户原句，不要解释思路，直接将其扩写成一整段高质量中文提示词。提示词中应自然包含：人物状态、服装、动作、站位、镜头、场景结构、环境细节、光线来源、调色方向、情绪氛围、空间纵深、材质质感和电影摄影感。最终效果必须像一部真实电影中的定帧，而不是普通写真或概念图。"""

def _cinematic_identity_context(source_text, char_sheet):
    """只给剧照优化器稳定身份与常规服装，不把人物卡里的临时动作带进每一幕。"""
    import re as _re
    matched, _, _ = _page_char_context(source_text, char_sheet)
    lines = []
    for raw in str(matched or "").splitlines():
        line = raw.strip()
        if not line:
            continue
        line = _re.sub(
            r'[，,；;]?无实体武器但双手前方悬浮[^，,；;。]*',
            '', line)
        line = _re.sub(
            r'[，,；;]?双手前方悬浮[^，,；;。]*',
            '', line)
        line = line.replace("因魔力流动而泛起微光", "")
        line = line.replace("随着情绪变色", "固定颜色")
        line = line.replace("手持", "固定携带")
        line = _re.sub(r'[，,；;]{2,}', '，', line).strip("，,；; ")
        if line:
            lines.append(line)
    return "\n".join(lines)

def build_cinematic_scene_brief_messages(source_text, char_sheet, scene=""):
    system = """你是电影场景剪辑师。先完整理解小说片段，再把它浓缩为一句可以交给电影导演的精简场面描述。
只选择最值得定格的一个决定性瞬间；严格忠于原文的地点、人物、动作和状态，不添加原文此刻没有出现的武器、魔法、人物或结果。
场面描述只写相机能够看见的核心内容：谁在什么空间、处于什么位置、正在发生什么，以及最关键的环境反应。
场面第一句必须先写清原文此刻所在的地点或空间；连续剧情没有换地点时，沿用原文已经建立的地点。
人物外观只保留辨认身份必需的2—4个可见锚点。这是单张静止图片：动作前后存在变化时只选择一个明确时点，优先选择接触已经发生或动作已经落定的状态。
用静止姿势写清双脚或身体支点、重心、躯干朝向、手臂位置、武器停留位置和已经造成的环境反应；不用“正在挥砍、划向、扑向、冲向、飞向、旋转”等连续运动过程。
多人互动必须写清每个人在画面左中右和前后层次中的位置，并逐一写明哪只手接触对方哪个部位。拥抱、搀扶、抓握、压制等动作不能只写动作名称。
气味、声音、心理、抽象比喻和不可见设定只用于理解剧情，把它们转换为此刻真正可见的空间、动作或物理痕迹。
输出一整段60—120字的简体中文，不写镜头焦段、构图、光线、色调、画质、分析、标题或解释。"""
    user = ["【小说原文】\n" + str(source_text or "").strip()]
    if str(char_sheet or "").strip():
        user.append("【人物视觉档案，仅用于核对身份】\n" + str(char_sheet).strip()[:3000])
    if str(scene or "").strip():
        user.append("【固定场景资料】\n" + str(scene).strip()[:1200])
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(user)}], 420

def build_cinematic_prompt_optimizer_messages(scene_brief, art, aspect,
                                              directive="", extra="",
                                              source_text="", char_sheet=""):
    art_direction = _norm_art(art)
    art_parts = [
        part.strip() for part in art_direction.split("；")
        if part.strip() and "自然不对称的面部结构" not in part
    ]
    art_direction = "；".join(art_parts)
    # 默认写实画风里的固定 35mm / 浅景深会把所有镜头拉回人物写真。
    # 剧照册需要让焦段和景深服务当前叙事场面。
    if "35mm电影镜头" in art_direction:
        art_direction = art_direction.replace(
            "35mm电影镜头", "电影镜头焦段、景深与机位由当前叙事目的决定")
    art_direction = art_direction.replace(
        "浅景深，", "前中后景层次由当前叙事目的决定，")
    user = [
        "【精简场面】\n" + str(scene_brief or "").strip(),
        (
            "【小说原文，仅用于核对地点与事实】\n"
            + str(source_text or "").strip()[:1800]
        ),
        (
            "【剧情事实锁】\n"
            "精简场面中的人物、道具、动作状态、接触关系与时间点均为已锁定事实；"
            "原文中的地点与空间类型同样锁定。扩写只补充服务这一瞬间的镜头、"
            "站位、同一地点内的可信布景、真实光源、调色和材质反应。"
        ),
        (
            "【单张图片姿势锁】\n"
            "这是一张静止电影剧照，不是视频。把动作写成唯一时间点的稳定姿势："
            "明确人物的支点、重心、躯干朝向、四肢位置、武器停留位置，以及已经发生的接触点或结果。"
            "原文是挥砍、划向、扑击、冲撞等连续动作时，选择蓄势停顿、接触瞬间或动作完成后的落点之一，"
            "优先选择肢体结构和剧情结果最清楚的一帧。最终提示词使用静态位置和接触结果，不使用运动过程词、残影或动作轨迹。"
            "多人接触时逐人写清左右与前后位置、身体朝向、每只手的归属和接触部位；"
            "两人的头部、躯干和手臂保持各自连续可辨，接触点单一清楚。"
        ),
        "【统一画风】\n" + art_direction,
        "【目标画幅】\n" + (
            "2.35:1超宽银幕" if str(aspect) == "2.35:1" else "16:9宽银幕"),
        (
            "【镜头选择原则】\n"
            "先判断这张定帧承担的叙事任务。环境、世界规模或空间压迫主导时，"
            "采用18—28mm大全景或全景，让人物只占画面合理的小到中等比例并建立前中后景；"
            "人物关系主导时采用35—50mm中景、过肩或侧后方调度；"
            "只有面部反应本身就是决定性事件时，才采用65—100mm近景或特写。"
            "动作瞬间选择力量方向、接触点和环境反馈最清楚的机位。"
        ),
        "【成品密度】\n最终提示词控制在260—480字，画面信息具体且互不重复。",
    ]
    if str(char_sheet or "").strip():
        user.append(
            "【人物视觉档案，仅锁定本幕出场人物的固定外观与常规服装】\n"
            + str(char_sheet).strip()[:3000]
        )
    if str(extra or "").strip():
        user.append("【本次补充要求】\n" + str(extra).strip())
    return [
        {"role": "system", "content": str(directive or "").strip()
         or DEFAULT_CINEMATIC_STILL_DIRECTIVE},
        {"role": "user", "content": "\n\n".join(user)},
    ], 1100

def _clean_cinematic_paragraph(value):
    text = str(value or "").strip().replace("```", "")
    for lead in ("最终提示词：", "最终提示词:", "提示词：", "提示词:"):
        if text.startswith(lead):
            text = text[len(lead):].strip()
    text = " ".join(text.split()).strip("“”\"'")
    return text

def _cinematic_negative_fragment(text):
    """最终扩散提示词只保留正向可见画面，返回命中的否定片段。"""
    value = str(text or "").lower()
    markers = (
        "不要", "不能", "不得", "禁止", "避免", "没有出现", "不出现",
        "无文字", "无水印", "无气泡", "无边框", "无字幕", "而不是",
        "不是视频", "不使用", "不包含", "不含",
        "not ", "no text", "without ",
    )
    return next((marker for marker in markers if marker in value), "")

def _cinematic_motion_process_fragment(text):
    """剧照是单张图片；拦截仍在描述连续轨迹、容易破坏肢体结构的动作词。"""
    value = str(text or "")
    markers = (
        "正在挥", "挥砍向", "挥剑砍向", "挥刀砍向", "剑刃划向", "刀刃划向",
        "劈向", "斩向", "刺向", "扑向", "冲向", "飞向", "旋转着",
        "运动模糊", "动作轨迹", "多重残影",
    )
    return next((marker for marker in markers if marker in value), "")

def _cinematic_unlicensed_effect(reference, candidate):
    """拦住从人物卡或旧上下文串入、但本段原文没有发生的主动奇幻效果。"""
    source = str(reference or "")
    value = str(candidate or "")
    markers = (
        "光刃", "魔法阵", "符文光", "生物荧光", "发光黏液", "磷火",
        "能量束", "能量球", "闪电法术", "火焰法术", "空间裂缝",
    )
    return next((marker for marker in markers
                 if marker in value and marker not in source), "")

def _cinematic_location_violation(source_text, candidate):
    """要求原文明确建立的空间类型继续出现在最终提示词中。"""
    source = str(source_text or "")
    value = str(candidate or "")
    groups = (
        (("森林", "林地", "树冠", "灌木", "苔藓"),
         ("森林", "林地", "树林", "树冠", "灌木", "树干", "苔藓", "林间")),
        (("酒馆", "酒吧"),
         ("酒馆", "酒吧", "吧台")),
        (("街道", "街头", "巷口", "小巷"),
         ("街道", "街头", "巷口", "小巷", "路面")),
        (("宫殿", "王宫", "大殿"),
         ("宫殿", "王宫", "大殿", "王座厅")),
        (("飞船", "舰桥", "舱室"),
         ("飞船", "舰桥", "舱室", "舱内")),
    )
    for source_terms, visible_terms in groups:
        if any(term in source for term in source_terms):
            if not any(term in value for term in visible_terms):
                return source_terms[0]
    return ""

def generate_cinematic_still_package(source_text, char_sheet, art, scene="", extra="",
                                     aspect="16:9", temperature=0.5, directive=""):
    source_text = str(source_text or "").strip()
    if not source_text:
        raise RuntimeError("剧照没有对应的小说原文")
    identity_sheet = _cinematic_identity_context(source_text, char_sheet)
    brief_messages, brief_predict = build_cinematic_scene_brief_messages(
        source_text, identity_sheet, scene)
    scene_brief = ""
    for attempt in range(3):
        attempt_messages = list(brief_messages)
        if attempt:
            attempt_messages.append({
                "role": "user",
                "content": (
                    "上一版包含互相矛盾的动作状态、偏离原文或额外发挥。"
                    "请重新只保留原文中的一个决定性瞬间，输出60—120字的一段场面。"
                ),
            })
        raw = chat_stream(attempt_messages, 0.35 if not attempt else 0.2,
                          None, brief_predict).strip()
        candidate = _clean_cinematic_paragraph(raw)
        if (35 <= len(candidate) <= 180
                and not _cinematic_unlicensed_effect(source_text, candidate)
                and not _creative_topic_violation(source_text, candidate)):
            scene_brief = candidate
            break
    if not scene_brief:
        raise RuntimeError("电影场面没有成功浓缩")

    optimizer_messages, optimizer_predict = build_cinematic_prompt_optimizer_messages(
        scene_brief, art, aspect, directive, extra, source_text, identity_sheet)
    prompt = ""
    for attempt in range(3):
        attempt_messages = list(optimizer_messages)
        if attempt:
            attempt_messages.append({
                "role": "user",
                "content": (
                    "上一版偏离了精简场面、含否定约束、仍在描述连续运动过程，"
                    "或不是一整段可直接生图的中文电影剧照提示词。"
                    "请忠于精简场面，把动作固定在唯一静止落点，只用正向可见画面语言，严格输出一段最终提示词。"
                ),
            })
        raw = chat_stream(attempt_messages, temperature if not attempt else 0.35,
                          None, optimizer_predict)
        candidate = _clean_cinematic_paragraph(raw)
        if (120 <= len(candidate) <= 1200
                and not _cinematic_negative_fragment(candidate)
                and not _cinematic_motion_process_fragment(candidate)
                and not _cinematic_unlicensed_effect(
                    source_text + "\n" + scene_brief, candidate)
                and not _cinematic_location_violation(source_text, candidate)
                and not _creative_topic_violation(scene_brief, candidate)):
            prompt = candidate
            break
    if not prompt:
        raise RuntimeError("电影剧照提示词优化没有返回有效内容")
    return {
        "prompt": prompt,
        "source": source_text,
        "sceneBrief": scene_brief,
        "plan": {"sceneBrief": scene_brief},
        "aspect": aspect,
    }

# ================== 漫画分镜脚本 ==================
def build_comic_messages(setting, outline, art, panels):
    panels = max(2, min(int(panels or 8), 40))
    system = (
        "你是漫画分镜编剧，同时精通AI绘图提示词。根据用户给的设定和事情经过，"
        "把内容拆成能直接画出来的分镜。全程用普通人一眼能看懂的大白话，不写小说。严格遵守：\n"
        f"1. 一共 {panels} 格，按事情实际发生的先后顺序写。每格只写这一刻看得见的人物、地点、动作、表情和结果。\n"
        "2. 每一格必须严格按下面的格式输出，不要额外解释、不要总起或结语：\n"
        "【第N格】\n"
        "画面：先写地点和人物位置，再写一个明确动作、表情和动作造成的可见结果，一到两句。\n"
        "对白：角色名：台词（如果这一格没有对白就写：无）\n"
        "旁白：这一格的旁白或音效（没有就写：无）\n"
        "出图提示词：一段完整中文提示词，可直接粘贴到绘图软件生成这一格画面，"
        "必须包含画风、该角色固定外观、动作表情、具体场景、构图景别和实际光源。\n"
        f"3. 全部画面统一采用同一种画风：{_norm_art(art)}；每一格的出图提示词开头都要带上这个画风。\n"
        "4. 同一个角色在每一格的发型、发色、瞳色、服装和标志必须一致，不能变来变去。\n"
        "5. 不写‘仿佛、宛若、宿命、灵魂、气场、氛围感、压迫感、破碎感、视觉语言’等空话。"
        "性格要改写成眉眼、嘴角、站姿、手势或实际行为；宏大、华丽、阴森要改写成尺寸、数量、材料、建筑、物件和光源。"
    )
    up = []
    if setting.strip(): up.append("【人物与设定】\n" + setting.strip())
    if outline.strip(): up.append("【剧情大纲】\n" + outline.strip())
    if not (setting.strip() or outline.strip()):
        up.append("请自拟一个有趣、完整的短篇故事。")
    up.append(f"请创作 {panels} 格漫画分镜脚本。")
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(up)}], panels * 420

def build_storyboard_messages(chapter_text, char_sheet, bible, max_panels, rules=None):
    """先让模型定【角色表】【场景表】(固定外观/固定环境)，再产出【分镜】。
    格数由内容决定，不按字数切；max_panels 只是安全上限。"""
    cap = max(4, min(int(max_panels or 30), 40))
    rule_txt = rules.strip() if rules and rules.strip() else DEFAULT_SB_RULES
    fmt = (
        "\n\n【切格标准（重要）】\n"
        "格数由真正需要展示的视觉节拍决定，绝不按字数或句子数平均切。先在内部通读并筛选，不输出分析过程：\n"
        "· 地点改变、主要主体改变、动作进入新阶段、关键发现或明确结果出现时，才考虑换一格；\n"
        "· 同一地点、同一人物、同一状态的连续形容应合并，只选最有辨识度的一瞬，不逐句配图；\n"
        "· 小动作、表情和物件只有承担关键转折时才独占一格，否则作为当前主动作的必要辅助；\n"
        "· 连续对白如果画面状态不变就合成一格，对白放对白栏，不额外制造重复人物镜头；\n"
        "· 每格仍然只能有一个视觉焦点；宁可舍弃非关键细节，也不要把多个主体和动作压在一起。\n"
        f"这段戏该切几格就切几格，最多不超过 {cap} 格。\n"
        "\n【输出格式（必须严格遵守，不要多余解释）】\n"
        "第一部分，单独一行写：===角色表===\n"
        "然后每个出场角色一行：角色名｜固定外观（只选3—5个最能稳定识别此人的可见锚点：年龄阶段、轮廓体型、发型、服装主色、一个标志物）。\n"
        "【重要】角色表只写长期不变的长相与常规服装；姿势、表情、伤口、泥污、血迹、死亡/倒地状态、当下手里拿的东西、临时换的衣服，都不许写进角色表，只能写进真正出现它的那一格『画面』栏。\n"
        "第二部分，单独一行写：===场景表===\n"
        "然后这段戏用到的每个地点一行：地点名｜固定环境描述（只选2—4个建立空间所必需的长期可见锚点）。\n"
        "【重要】场景表里**只写这个地点长期就有的东西**，绝不能写剧情道具——尸体、血迹、弹壳、掉落物、伤口、"
        "以及任何『到某一格才出现/才被发现』的东西，都不许写进场景表；它们只能写在真正出现它的那一格的『画面』栏里。\n"
        "同一地点的描述只写一次，之后每格都用同一个地点名，保证背景完全一致。\n"
        "第三部分，单独一行写：===分镜===\n"
        "然后每格严格一行，用竖线分隔：\n"
        "序号｜地点:地点名｜"
        "出场:这一格画面里**所有看得见的人形**都要列出来，包括躺着的尸体、倒地的人、被拍到的旁人；"
        "多个用逗号分隔；只有当画面里完全没有人（纯物件或纯风景特写）时才写 无｜"
        "镜头:必须以景别词开头，从【大远景/全景/中景/近景/特写/大特写】里选一个，再加机位"
        "（俯拍/仰拍/平视/过肩/第一人称POV）和焦段；且景别要和尺寸对应——"
        "大格用大远景或全景或俯瞰全景，中格用中景或近景，小格用特写或大特写｜"
        "尺寸:大/中/小｜"
        "画面:**只写一个主要动作、一个视觉主体和动作完成时的可见状态**；辅助人物、背景和道具只在理解主动作不可缺少时写入，"
        "原文同一人物的连续小动作先选最有表现力的一瞬，不必每个动作都画；"
        "不要出现任何文字、招牌字、字幕；"
        "**绝对不要在这一栏写角色的名字**，直接写动作本身，例如写“竖起衣领遮住半张脸”而不是“陈野竖起衣领”——"
        "人物外观会另行提供，重复写名字会让绘图模型误画成两个人｜"
        "旁白:内心独白或说明(没有写 无)｜对白:台词(没有写 无)\n"
        "【尺寸怎么定】按这一格在版面上该占多大来定：\n"
        "· 大 = 开场大场景、全景/远景、需要看清环境的俯瞰、以及情绪最重的震撼画面（占半页）；\n"
        "· 中 = 常规的人物动作、对话镜头、过肩或第一人称视角；\n"
        "· 小 = 局部细节、小动作、表情特写（如眯眼、伤疤、手指、一件小物件）。\n"
        "\n【忠实原文与镜头自洽（最重要）】\n"
        "1. 每格的画面、旁白、对白只能来自原文写到的内容，或为成画面所必需的中性视觉补全（光线、材质、天气这类不改变剧情的东西）。\n"
        "2. 绝不许自己推断剧情结论：不许凭弹壳写“近距离补枪”、不许凭伤口写“薄刀片所刻”、不许添加原文没有的“鲜血未凝固/心脏收缩”等；线索只能作为人物明确的猜测，且要有原文依据。\n"
        "3. 原文关键信息不能漏：重要人物身份、人物关系、关键动作、关键物件、情绪转折，都至少要有一格画面或一句旁白/对白承载——尤其“死者是谁、他和主角什么关系”这类信息，宁可多切一格也不能漏。\n"
        "4. 镜头必须和画面物理自洽：写“背影”就不能同时要求看到脸（想露侧脸请写“侧后方三分之二角度”）；要拍地面上的东西（弹壳等）用“俯拍/越肩俯视/地面微距”，不要写“仰拍”。"
    )
    system = rule_txt + fmt
    up = []
    if char_sheet.strip():
        up.append("【角色设定卡（外观基准，请据此写角色表）】\n" + char_sheet.strip())
    if bible.strip():
        up.append("【角色当前状态（务必体现在角色表的外观里，如某人受伤）】\n" + bible.strip())
    up.append("【小说正文】\n" + chapter_text.strip()[:6000])
    up.append("请依次输出 ===角色表===、===场景表===、===分镜===。格数按画面变化来定，不要凑数。")
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(up)}], cap * 200 + 800

def _seg_kv(seg):
    for sep in ("：", ":"):
        if sep in seg:
            k, v = seg.split(sep, 1)
            return k.strip(), v.strip()
    return "", seg.strip()

def _match_char(name, chars):
    """出场名字与角色表 key 做宽松匹配，避免因‘伊莉雅’vs‘伊莉雅(金发少女)’对不上而漏注入外观。"""
    name = name.strip()
    if not name:
        return ""
    if name in chars:
        return chars[name]
    for k in chars:
        if k and (k in name or name in k):
            return chars[k]
    for k in chars:
        if k[:2] and k[:2] == name[:2]:
            return chars[k]
    return ""

def _clean_char_sheet_text(text):
    """移除旧版误接到人物卡末尾的场景与剧情段落。"""
    return re.split(
        r'(?m)^\s*【(?:主要场景设定|场景[：:]|第1话剧情大意|第1话分镜概要)',
        str(text or ""), 1)[0].strip()

def parse_char_sheet(text):
    """把角色设定卡解析成 {名字: 外观}。一个角色一段：名字—外观。
    外观内部允许用 ； 分隔多项属性（不会被误当成角色分隔）；角色之间用换行、或『；名字—』分隔。"""
    import re as _re
    d = {}
    source = _clean_char_sheet_text(text)
    # 旧草稿曾把场景卡误接到人物卡末尾。人物解析在任何场景/剧情标签前截断，
    # 同时拒绝场景字段名，避免把“空间类型”之类当成角色名继续出图。
    reserved = {
        "空间类型", "空间与景观", "建筑结构", "材质与陈设",
        "装饰与识别物", "光线与配色", "地点与时间", "画面事件", "关键对白",
    }
    # 新格式固定一人一行；兼容旧版把多个人物写在同一行并用“；名字—”分隔。
    # 只把破折号视为同一行内的新人物边界，避免“上装：…；下装：…”被误拆成人名。
    chunks = _re.split(
        r'\n+|[；;](?=[^\s；;，,。—\-:：\n]{1,16}\s*[—\-])',
        source)
    for chunk in chunks:
        m = _re.match(
            r'^\s*([^\s；;，,。—\-:：\n]{1,24})\s*[—\-：:]\s*(.+?)\s*$',
            chunk, _re.S)
        if not m:
            continue
        name = m.group(1).strip()
        look = m.group(2).strip().strip("；;。 \n")
        if name and name not in reserved and look:
            d[name] = look
    return d

_FACE_KW = ("脸", "眉", "眼", "鼻", "唇", "发", "须", "疤", "痣", "肤", "岁", "男", "女", "雀斑", "颧")
_BODY_KW = ("身材", "体型", "服装", "穿", "衣", "裤", "鞋", "脚踝", "手腕", "颈后", "后背", "腰", "靴")

_CLOTH_KW = (
    "服装", "穿", "衣", "裙", "袍", "裤", "鞋", "靴", "袖", "甲",
    "手套", "风衣", "衬衫", "夹克", "外套",
)
_PROP_KW = (
    "剑", "刀", "枪", "弓", "斧", "锤", "盾", "法杖", "武器", "道具",
    "背负", "背着", "机械臂", "义肢", "面具",
)

def _filter_look(ap, mode):
    """按镜头只保留看得见的外观：特写只留脸；远景只留身形服装；
    背影去掉一切脸部特征只留发型/身形/服装；第一人称只留入画的衣袖/手套。"""
    import re as _r
    parts = [x.strip() for x in _r.split(r'[；;，,]', ap or "") if x.strip()]
    if not parts:
        return ap
    def keep_visible_prop(items, cap):
        prop = next((p for p in parts if any(k in p for k in _PROP_KW)), "")
        items = list(items[:cap])
        if prop and prop not in items:
            if len(items) >= cap:
                items[-1] = prop
            else:
                items.append(prop)
        return items
    if mode == "face":
        keep = [p for p in parts
                if any(k in p for k in _FACE_KW) and not any(k in p for k in _BODY_KW)]
        keep = keep[:6]
    elif mode == "far":
        keep = [p for p in parts if any(k in p for k in (
            "身材", "体型", "服装", "穿", "衣", "裤", "鞋", "发",
            "疤", "痣", "纹身",
        ))]
        keep = keep_visible_prop(keep, 6)
    elif mode == "back":
        # 背影：绝不能出现脸部五官（会诱导模型强行转头/生成半张脸/扭脖子）
        keep = [p for p in parts
                if (("发" in p) or any(k in p for k in ("身材", "体型")) or any(k in p for k in _CLOTH_KW))
                and not any(k in p for k in ("脸", "眉", "眼", "鼻", "唇", "须", "疤", "痣", "颧", "下颌", "五官"))]
        keep = keep_visible_prop(keep, 5)
    elif mode == "pov":
        # 第一人称：只保留能入画的衣袖/手套，其余一律不注入
        keep = [p for p in parts if any(k in p for k in ("袖", "手套", "风衣", "衬衫", "夹克", "外套", "手环", "腕"))]
        keep = keep_visible_prop(keep, 3)
    else:
        # 中近景：优先抓"一眼能分辨"的东西——身材、颜色、服装、标志物、发型。
        # 五官骨相不进这里（生图模型本来锁不住脸，写了只会挤掉真正有辨识度的锚点），
        # 只有脸部特写（mode == "face"）才用五官。痣/疤/纹身算标志物，保留。
        _FACE_ONLY = ("脸", "眉", "眼", "鼻", "唇", "颧", "下颌", "五官", "骨相",
                      "雀斑", "酒窝", "瞳", "睫")
        ident = [p for p in parts
                 if not (any(k in p for k in _FACE_ONLY)
                         and not any(k in p for k in ("疤", "痣", "纹身")))]
        keep = keep_visible_prop(ident or parts, 7)
    # 背影、POV、远景和特写绝不因“没筛到”而回退到整张人物卡；
    # 否则一个背影镜头仍会把正脸、首饰和全套服装全部塞给生图模型。
    return "；".join(keep) if keep else (ap if mode == "full" else "")

def _short_visual(text, limit):
    """截取一个简短、完整的可见描述，避免最终生图提示词重新膨胀。"""
    import re as _re
    if isinstance(text, (list, tuple)):
        text = "；".join(str(x) for x in text if str(x).strip())
    elif isinstance(text, dict):
        text = "；".join(str(x) for x in text.values() if str(x).strip())
    value = " ".join(str(text or "").split()).replace(",", "，").strip("，；;。 ")
    # 设定图调用固定传 150，但现在的定妆卡是 220—350 字；如果仍在 150 字处截断，
    # 往往只留下身材和五官，恰好把后面的完整服装全部丢掉。仅对明确含服装结构的
    # 定妆描述放宽上限，普通分格、镜头和场景短句仍严格使用调用方原限额。
    if limit == 150 and any(k in value for k in (
            "内搭", "外罩", "主体", "上装", "下装", "腰间", "腰封",
            "长衫", "外套", "披风", "裙", "裤", "鞋", "靴")):
        limit = 520
    if len(value) <= limit:
        return value
    cut = value[:limit]
    stops = [cut.rfind(mark) for mark in ("；", "，", "、", "。")]
    stop = max(stops)
    if stop >= max(12, limit // 2):
        cut = cut[:stop]
    return _re.sub(r'[，,；;。 ]+$', '', cut)

def assemble_storyboard(raw, art, user_chars=None):
    """把模型产出的 角色表+分镜 解析并逐格拼成最终图片提示词。
    user_chars（用户角色设定卡解析出的外观）拥有最高优先级，逐字用于每一格。"""
    art = _norm_art(art)
    def _table(txt):
        t = {}
        for line in (txt or "").splitlines():
            line = line.strip()
            if "｜" in line or "|" in line:
                nm, _, v = line.replace("|", "｜").partition("｜")
                nm = nm.strip().lstrip("-·* ").strip()
                if nm and v.strip():
                    t[nm] = v.strip()
        return t
    chars, scenes = {}, {}
    body = raw
    if "===分镜===" in raw:
        head, body = raw.split("===分镜===", 1)
        # 角色表 / 场景表 分段
        if "===场景表===" in head:
            ch_txt, sc_txt = head.split("===场景表===", 1)
        else:
            ch_txt, sc_txt = head, ""
        chars = _table(ch_txt.replace("===角色表===", ""))
        scenes = _table(sc_txt)
    # 用户设定卡覆盖模型的角色表（设定卡说了算）
    if user_chars:
        chars.update(user_chars)
    panels = []
    for line in body.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = [p for p in line.replace("|", "｜").split("｜") if p.strip()]
        if len(parts) < 2 or not parts[0][:1].isdigit():
            continue
        d = {}
        who = []
        for seg in parts[1:]:
            k, v = _seg_kv(seg)
            if not k:
                # 无标签字段：模型常把地点名直接写在第二格，这里认出来
                if v and (v in scenes or _match_char(v, scenes)):
                    d["loc"] = v
                continue
            if k.startswith("出场"):
                who = [w.strip() for w in v.replace("，", ",").replace("、", ",").split(",") if w.strip()]
            elif "地点" in k or "场景" in k: d["loc"] = v
            elif "镜头" in k: d["cam"] = v
            elif "背景" in k: d["bg"] = v
            elif "画面" in k or "动作" in k: d["act"] = v
            elif "尺寸" in k or "格子" in k: d["size"] = v
            elif "旁白" in k: d["nar"] = v
            elif "对白" in k: d["dlg"] = v
        # 出场名字去掉括号注解：老鬼(胸部特写) → 老鬼
        import re as _r2
        who = [_r2.sub(r'[（(].*?[）)]', '', w).strip() for w in who]
        who = [w for w in who if w and w not in ("无", "（无）", "none", "None", "-")]
        act_txt = d.get("act", ""); cam_txt = d.get("cam", "")
        closeup = any(k in cam_txt for k in ("大特写", "微距", "局部特写", "特写"))
        pov = any(k in (cam_txt + act_txt) for k in ("POV", "第一人称", "主观视角"))
        # 只注入“这一格画面里真的点到名”的角色；物件特写/主观镜头没点名则一个都不注入
        named = [w for w in who if w and w in act_txt]
        if named:
            use = named[:2]
        elif closeup or pov:
            use = []
        else:
            use = who[:2]
        looks = []
        for w in use:
            ap = _match_char(w, chars)
            if ap and ap not in looks:
                looks.append(ap)
        look = "；".join(looks)
        # 场景锁定：同一地点每格用同一段环境描述，保证背景一致
        scene = ""
        if d.get("loc"):
            scene = _match_char(d["loc"], scenes) or scenes.get(d["loc"], "")
        if not scene:
            scene = d.get("bg", "")
        shot = d.get("cam", "") + d.get("act", "")
        back = any(k in shot for k in ("背影", "背对", "背后", "身后", "后脑", "背面"))
        far = any(k in shot for k in ("远景", "大远景", "俯瞰"))
        pov = any(k in shot for k in ("POV", "第一人称", "主观视角"))
        # 提示词=纯正向画面描述。扩散模型会把“不要/没有…”当成要画的内容，故全程只用正向词。
        # ① 人数 + 景别 放最前（模型最吃开头的词）。尸体单独算一个人形，否则模型会脑补活人。
        _BODY = ("尸体", "遗体", "倒地", "躺着", "躺在", "死者", "仰面", "无脉")
        act_all = (d.get("act") or "")
        alive = [w for w in use if not any(k in (_match_char(w, chars) or "") for k in _BODY)]
        body_here = (any(k in act_all for k in _BODY)
                     or any(any(k in (_match_char(w, chars) or "") for k in _BODY) for w in use))
        n_alive = len(alive)
        if pov:
            head = "第一人称主观视角，画面只拍到主角自己的一只手与衣袖局部"
        elif n_alive == 0 and not body_here:
            head = "空镜头，画面里只有物件与环境"
        elif body_here and n_alive >= 1:
            head = "画面里一名男子蹲在一具躺在地上的男性尸体旁边，共两人"
        elif body_here and n_alive == 0:
            head = "画面里只有一具躺在地上的男性尸体，孤零零一人"
        elif n_alive == 1:
            head = "单人画面，全画面只有一个人物"
        else:
            head = "%d个人物同框" % max(1, n_alive)
        bits = [art, head]
        cam_txt2 = (d.get("cam") or "").strip()
        if cam_txt2:
            bits.append(_short_visual(cam_txt2, 42))
        if scene:
            scene = _filter_scene(scene, "far" if far else ("close" if closeup else "mid"))
            if scene:
                bits.append("场景：" + _short_visual(scene, 72 if far else 45))
        # ② 外观按镜头过滤：特写只留脸，远景只留身形服装（活人优先）
        show = alive[:2] if alive else use[:2]
        looks2 = []
        for w in show:
            ap = _match_char(w, chars)
            if ap and ap not in looks2:
                looks2.append(ap)
        if looks2:
            if pov: mode = "pov"
            elif back: mode = "back"
            elif closeup and not far: mode = "face"
            elif far: mode = "far"
            else: mode = "full"
            look3 = "；".join(x for x in (_filter_look(w, mode) for w in looks2) if x).strip("；")
            if pov:
                if look3: bits.append("入画的手部与衣袖：" + look3)
            elif back:
                bits.append("背影，只见后脑与身形轮廓" +
                            ("：" + _short_visual(look3, 70) if look3 else ""))
            elif far:
                bits.append("人物在画面中占比很小，以环境为主" +
                            ("：" + _short_visual(look3, 60) if look3 else ""))
            elif look3:
                bits.append("人物：" + _short_visual(look3, 90))
        if d.get("act"):
            bits.append(_short_visual(d["act"], 80))
        prompt = "，".join(bits) + "。"
        dlg = (d.get("dlg") or "").strip()
        nar = (d.get("nar") or "").strip()
        NONE = ("无", "（无）", "none", "None", "-")
        if dlg in NONE: dlg = ""
        if nar in NONE: nar = ""
        cap = dlg if dlg else (("（" + nar + "）") if nar else "")
        sz = (d.get("size") or "").strip()
        sz = "大" if "大" in sz else ("小" if "小" in sz else "中")
        # dialog=给旧版整页书用的字幕(会回退到旁白)；speech=真正的台词(分页版用，避免和旁白重复)
        panels.append({"prompt": prompt, "dialog": cap, "speech": dlg, "narration": nar, "size": sz,
                       "desc": ("｜".join(parts[1:]))[:160]})
    return panels, chars

# ============ JSON 结构化分镜管线（第二版，人数/尸体/物件由模型结构化输出，程序不再猜） ============
def _norm_art(art):
    """保留完整的可见画风配方，只清理空白并设置宽松安全上限。

    Krea2 对材质、线条、光线、色谱等具体提示比单个风格标签更稳定，
    因此前端预设会比旧版的“写实真人风”长得多，不能再截成第一句。
    """
    art = (art or DEFAULT_COMIC_STYLE_PRESETS[DEFAULT_COMIC_STYLE_NAME]).strip()
    legacy_builtin_default = (
        "极致写实的真人电影剧照，真实相机拍摄质感；自然不对称的面部结构，"
        "清晰可见的皮肤毛孔、细小绒毛与真实发丝，准确人体比例和手部结构；"
        "35mm电影镜头，主体动作清晰，背景具有自然景深，由场景内真实光源塑造立体明暗，"
        "布料、旧木、湿地、金属与皮革呈现可信材质，克制的电影调色，细腻胶片颗粒，"
        "真实环境中的轻微瑕疵，具有高预算真人电影的摄影真实感。")
    if art == legacy_builtin_default:
        art = DEFAULT_COMIC_STYLE_PRESETS[DEFAULT_COMIC_STYLE_NAME]
    # 画风栏偶尔会被误贴成“提示词生成器”的系统说明。这种元指令不是视觉画风，
    # 原样送进 Krea2 会稀释人物服装与构图要求，自动回退到已验证的默认画风。
    meta_hits = sum(x in art for x in (
        "你是顶级", "你的任务是", "【输出要求】", "只输出一整段",
        "不要解释，不要分析", "核心原则"))
    if meta_hits >= 2:
        art = DEFAULT_COMIC_STYLE_PRESETS[DEFAULT_COMIC_STYLE_NAME]
    simple = art.lower().replace(" ", "")
    aliases = {
        "写实": "Krea2·极致写实电影",
        "真人写实": "Krea2·极致写实电影",
        "电影写实": "Krea2·极致写实电影",
        "纪实": "Krea2·纪实摄影",
        "摄影": "Krea2·纪实摄影",
        "油画": "Krea2·古典叙事油画",
        "厚涂": "Krea2·厚涂表现油画",
        "动漫": "Krea2·日系动画电影",
        "动画": "Krea2·日系动画电影",
        "日漫": "Krea2·日系动画电影",
        "二次元": "Krea2·日系动画电影",
        "黑白漫画": "Krea2·黑白日漫",
        "水彩": "Krea2·水彩手绘",
        "手绘": "Krea2·水彩手绘",
        "马克笔": "Krea2·马克笔速写",
        "铅笔": "Krea2·铅笔炭笔",
        "炭笔": "Krea2·铅笔炭笔",
    }
    if simple in aliases:
        art = DEFAULT_COMIC_STYLE_PRESETS[aliases[simple]]
    art = " ".join(art.split())
    return art[:800]

def _style_character_adapter(art):
    """根据画风原文给人物一句正向适配写法，确保人物与背景同一种画风。"""
    art = str(art or "")
    rules = (
        (("水墨", "写意"),
         "人物以书法线条勾勒轮廓，面部用淡墨与留白，衣纹飘逸，不做写实渲染，"
         "与水墨背景完全统一"),
        (("赛博", "霓虹", "蒸汽波"),
         "人物以赛博霓虹风格表现，轮廓带发光线条，配色高饱和霓虹紫粉青"),
        (("像素",),
         "人物以像素块构成，风格复古游戏，不用写实皮肤纹理"),
        (("黑白漫画", "黑白日式"),
         "人物以黑白漫画线条与网点阴影表现，无彩色"),
        (("3D游戏模型",),
         "人物按3D游戏模型渲染，皮肤、服装与材质清晰统一"),
        (("厚涂",),
         "人物按厚涂插画表现，体积感强、笔触扎实"),
        (("水彩", "油画"),
         "人物以水彩油画笔触表现，色彩浓郁、边缘柔和"),
        (("日式动画", "日本动画", "赛璐璐", "动漫"),
         "人物按日式动画作画，线条干净、色彩鲜明"),
        (("电影级剧照", "电影剧照"),
         "人物按电影剧照写实渲染，真实皮肤质感与电影光效"),
        (("超仿真", "生活照"),
         "人物按真实生活照写实呈现，保留真实皮肤与自然光影"),
    )
    for keys, rule in rules:
        if any(k in art for k in keys):
            return "人物画风：%s。" % rule
    return "人物画风：人物与背景统一采用当前画风，禁止混用其他画风。"

def _content_bias_prompt(bias, custom=""):
    """根据“内容倾向/夸张度”选项生成注入编剧与设定的引导块。"""
    bias = str(bias or "").strip()
    custom = str(custom or "").strip()
    map_bias = {
        "dark": ("黑暗（剧情向）：故事气氛压抑、绝望，事情总是往坏的方向走；"
                 "重要代价、失败和损失真实发生，不强行圆满收场，可以给出沉重或"
                 "绝望的结局。"),
        "gore": ("血腥（画面向）：允许断肢、穿膛、内脏外露、大出血、残缺尸体、"
                 "血泊等极端血腥画面；战斗和伤害结果按剧情需要直接特写表现，"
                 "不回避、不弱化、不用遮挡替代。"),
        "adult": ("成人向：性行为与身体接触必须用大白话直接写明动作和性器官"
                  "（例如“苏婉张嘴含住李承泽的阴茎，舌头舔弄并前后吞吐”），"
                  "不回避、不淡化、不用“侍奉/亲昵/亲密”等含蓄词代替；"
                  "不写比喻、心理独白等小说腔。"),
        "exaggerated": ("夸张：允许非常规体型（巨人、巨物）、变异、半兽人、"
                        "超现实尺度；人物特征按用户要求放大，不强制高颜值匀称。"),
    }
    keys = []
    for key in bias.replace("，", "+").split("+"):
        key = key.strip()
        if key == "dark_adult":
            keys += ["dark", "adult"]
        elif key:
            keys.append(key)
    parts = [map_bias[k] for k in keys if k in map_bias]
    if custom:
        parts.append("自定义：" + custom)
    if not parts:
        return ""
    return ("本作内容倾向（最高优先级，按此引导）：\n"
            + "\n".join(parts) + "\n")

def _style_locked_prompt(prompt, art, single_frame=False):
    """把项目画风原文固定放在 Krea2 提示词最前面，避免语言模型改写或遗漏画风。"""
    style = _norm_art(art).rstrip("。；;，, ")
    body = str(prompt or "").strip()
    if single_frame:
        # 单格整页不是漫画分格页：画风锁不再带“分格/画格/分隔线”语言。
        lock = (
            style
            + "。整张画面保持上述媒介、材质、线条、光线、色谱与渲染方式，"
            "画面边缘完整，主体与环境纹理铺满整幅画布。"
        )
    else:
        lock = (
            style
            + "。全页所有分格统一保持上述媒介、材质、线条、光线、色谱与渲染方式。"
            "整张成品采用纯视觉连续叙事，所有画格从边缘到边缘铺满人物、物件与带有环境色彩的真实场景纹理，"
            "画格之间只使用窄而整齐的分隔线。"
        )
    return lock + (" " + body if body else "")

def _norm_size(s):
    s = str(s or "").strip()
    return "大" if "大" in s else ("小" if "小" in s else "中")

_CN_NUM = {1: "一", 2: "两", 3: "三", 4: "四", 5: "五", 6: "六", 7: "七", 8: "八"}
def _cn(n):
    return _CN_NUM.get(int(n), str(n))

def _extract_json(raw):
    """从模型输出里稳健抠出 JSON 对象；Q4 模型常带围栏/前后废话/尾逗号，都容错。"""
    import json as _j, re as _re
    if not raw:
        return None
    t = raw.strip()
    m = _re.search(r'```(?:json)?\s*(.+?)```', t, _re.S)
    if m:
        t = m.group(1).strip()
    i, jx = t.find("{"), t.rfind("}")
    if i >= 0 and jx > i:
        t = t[i:jx + 1]
    try:
        return _j.loads(t)
    except Exception:
        pass
    try:
        return _j.loads(_re.sub(r',\s*([}\]])', r'\1', t))  # 去尾逗号再试
    except Exception:
        return None

_SCENE_CLOSE_KW = ("光", "雾", "雨", "水", "尘", "烟", "影", "血", "皮", "布", "木", "石",
                   "泥", "雪", "火", "焰", "云", "风", "material", "材质", "纹理", "苔")
def _filter_scene(scene, mode):
    """场景按镜头过滤：远景给全环境，中景给前半，特写只留光线/材质/天气类，避免特写里硬塞整片背景。"""
    import re as _r
    parts = [x.strip() for x in _r.split(r'[；;]', scene or "") if x.strip()]
    if not parts:
        return ""
    if mode == "far":
        return "；".join(parts[:4])
    if mode == "mid":
        return "；".join(parts[:2])
    keep = [p for p in parts if any(k in p for k in _SCENE_CLOSE_KW)]
    return "；".join(keep[:2])

def build_storyboard_messages_json(chapter_text, char_sheet, bible, max_panels, rules=None):
    """让模型直接输出结构化 JSON：living/corpses/object_only/pov 都是明确字段，程序不再靠关键词猜。"""
    cap = max(4, min(int(max_panels or 30), 40))
    rule_txt = rules.strip() if rules and rules.strip() else DEFAULT_SB_RULES
    schema = (
        "\n\n【本次输出必须是一个 JSON 对象（不要任何解释文字，可用```json 包裹）】\n"
        "结构如下：\n"
        "{\n"
        '  "characters": [{"name":"角色名","look":"只写3—5个长期不变且最能辨认此人的可见锚点：年龄阶段、轮廓体型、发型、服装主色、一个标志物"}],\n'
        '  "scenes": [{"name":"地点名","desc":"只写2—4个建立空间所必需的长期可见锚点，绝不写尸体血迹弹壳等剧情道具"}],\n'
        '  "panels": [{\n'
        '     "id": 1,\n'
        '     "anchor": "这一格对应的原文短句（必填）",\n'
        '     "location": "地点名（要和 scenes 里的 name 一致）",\n'
        '     "living": ["画面里看得见的、还活着/站立/动作中的人物名，逐个列出"],\n'
        '     "corpses": ["画面里倒地不动的尸体或昏迷者，没有就空数组 []"],\n'
        '     "object_only": false,   // 纯风景/纯物件特写、画面里没有任何人时为 true\n'
        '     "pov": false,           // 第一人称主观镜头时为 true\n'
        '     "size": "大 或 中 或 小",\n'
        '     "shot": "景别+机位，如 大远景/俯拍/广角 或 特写/平视",\n'
        '     "composition": "一句构图关系：主体在画面什么位置(左/中/右)、占画面多大、视觉焦点在哪、前景中景背景各是什么；打斗多人时务必写清谁在左谁在右。可留空",\n'
        '     "body_part": "若这一格是人体局部/伤口的微距特写，填该部位如“胸口伤口”“一只手”；否则空字符串",\n'
        '     "action": "只写一个动作、一个主体，绝不出现人物名字，只描述最终可见状态、不描述如何造成",\n'
        '     "narration": "旁白（没有就空字符串）",\n'
        '     "dialogue": "台词（没有就空字符串）"\n'
        "  }]\n"
        "}\n"
        "【living / corpses 必须精确】画面里有几个活人就列几个，有几具尸体就列几具；"
        "动物/灵兽/坐骑不是人形，绝不列进 living 或 corpses；"
        "纯风景或纯物件特写时 object_only=true 且 living、corpses 都为空数组；"
        "第一人称主观镜头 pov=true 且 living、corpses 留空（只拍到主角自己的手与衣袖）。\n"
        "【切格】先在内部通读原文并筛选真正推动阅读的视觉节拍，不输出分析过程；格数不按字数切。"
        "地点、主要主体、动作阶段、关键发现或结果确实改变时才换格；同一状态的连续形容合并，"
        "小动作和物件只有承担转折时才独占一格。每格只保留一个主要动作/一个视觉主体，最多 %d 格。\n"
        "【忠实原文（最重要）】\n"
        "1. 每格的 action/narration/dialogue 只能来自 anchor 指向的原文，或成画面所必需的中性视觉补全（光线/材质/天气这类不改剧情的）。\n"
        "2. 绝不自行推断剧情结论：不许凭线索写出原文没有的结论或添加原文没有的细节；推测只能作为人物明确的猜测且有原文依据。\n"
        "3. 原文关键信息（重要人物身份、人物关系、关键动作、关键物件、情绪转折）不能漏，至少各有一格画面或一句旁白/对白承载。\n"
        "4. 镜头与画面要物理自洽：写“背影”就不能同时要看到脸；拍地面上的东西用俯拍，不要写仰拍。\n"
        "【固定与状态分离】characters.look 只写长期不变的；姿势、伤口、泥污、死亡状态、临时手持物、临时换的衣服只写进对应 panel 的 action。"
    ) % cap
    system = rule_txt + schema
    up = []
    if char_sheet.strip():
        up.append("【角色设定卡（外观基准，请据此写 characters.look）】\n" + char_sheet.strip())
    if bible.strip():
        up.append("【角色当前状态】\n" + bible.strip())
    up.append("【小说正文】\n" + chapter_text.strip()[:6000])
    up.append("只输出上面规定结构的 JSON。格数按画面变化定，不要凑数。")
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(up)}], cap * 300 + 1500

def assemble_storyboard_json(raw, art, user_chars=None):
    """解析结构化 JSON，逐格拼最终提示词。人数、尸体、物件、POV 全部读字段，不再从文本猜。"""
    art = _norm_art(art)
    obj = _extract_json(raw)
    if not obj or not isinstance(obj, dict):
        return [], {}
    chars = {}
    for c in (obj.get("characters") or []):
        nm = str(c.get("name", "")).strip()
        lk = str(c.get("look", "")).strip()
        if nm and lk:
            chars[nm] = lk
    if user_chars:
        chars.update(user_chars)
    scenes = {}
    for s in (obj.get("scenes") or []):
        nm = str(s.get("name", "")).strip()
        dc = str(s.get("desc", "")).strip()
        if nm and dc:
            scenes[nm] = dc
    panels = []
    for p in (obj.get("panels") or []):
        if not isinstance(p, dict):
            continue
        living = [str(x).strip() for x in (p.get("living") or []) if str(x).strip()]
        corpses = [str(x).strip() for x in (p.get("corpses") or []) if str(x).strip()]
        object_only = bool(p.get("object_only"))
        pov = bool(p.get("pov"))
        size = _norm_size(p.get("size"))
        shot = str(p.get("shot") or "").strip()
        comp = str(p.get("composition") or "").strip()
        body_part = str(p.get("body_part") or "").strip()
        action = str(p.get("action") or "").strip()
        nar = str(p.get("narration") or "").strip()
        dlg = str(p.get("dialogue") or "").strip()
        loc = str(p.get("location") or "").strip()
        n_alive, n_corpse = len(living), len(corpses)
        closeup = any(k in (shot + size) for k in ("大特写", "微距", "特写")) or size == "小"
        far = any(k in shot for k in ("远景", "大远景", "全景", "俯瞰"))
        # 背影只看镜头字段，不看画面内容——否则“身后一名弟子”里的“身后”会误判成拍背影
        back = any(k in shot for k in ("背影", "背对", "背面", "后脑", "从背后", "身后"))
        # —— head 完全由结构化字段决定 ——
        if body_part:
            # 人体局部/伤口微距——它不是“空镜”，要点明是人体的一部分，否则模型会画成脱离人体的肉块
            head = "人体局部特写，主体固定为" + body_part
        elif pov:
            head = "第一人称主观视角，主体固定为一只手与衣袖局部"
        elif object_only or (n_alive == 0 and n_corpse == 0):
            head = "纯环境或静物空镜"
        elif n_alive >= 1 and n_corpse >= 1:
            head = "人数固定：%s名活动人物和%s具倒地身体，共%s个人形" % (
                _cn(n_alive), _cn(n_corpse), _cn(n_alive + n_corpse))
        elif n_corpse >= 1:
            head = "人数固定：%s具倒地身体" % _cn(n_corpse)
        elif n_alive == 1:
            head = "单人画面"
        else:
            head = "人数固定：%s人同框" % _cn(n_alive)
        bits = [art, head]
        if shot:
            bits.append(_short_visual(shot, 42))
        if comp:                       # 构图关系：主体位置/占比/焦点/前中背景（评审重点）
            bits.append(_short_visual(comp, 48))
        scene = scenes.get(loc, "") or _match_char(loc, scenes)
        if scene:
            sc = _filter_scene(scene, "far" if far else ("close" if (closeup and not far) else "mid"))
            if sc:
                # 中景把背景虚化，避免整片码头/环境跟主体抢焦点
                if (not far) and (not closeup) and (not body_part):
                    bits.append("背景虚化：" + _short_visual(sc, 45))
                else:
                    bits.append("场景：" + _short_visual(sc, 72 if far else 40))
        # 外观：只注入 living（活人），按镜头可见性过滤；人体局部微距不注入整体外观
        show = living[:2]
        looks = []
        for w in show:
            ap = _match_char(w, chars)
            if ap and ap not in looks:
                looks.append(ap)
        if looks and not pov and not object_only and not body_part:
            if back:
                mode = "back"
            elif closeup and not far:
                mode = "face"
            elif far:
                mode = "far"
            else:
                mode = "full"
            look3 = "；".join(x for x in (_filter_look(w, mode) for w in looks) if x).strip("；")
            if back:
                bits.append("背影，只见后脑与身形轮廓" +
                            ("：" + _short_visual(look3, 70) if look3 else ""))
            elif far:
                bits.append("人物在画面中占比很小，以环境为主" +
                            ("：" + _short_visual(look3, 60) if look3 else ""))
            elif look3:
                bits.append("人物：" + _short_visual(look3, 90))
        # 尸体外观（若设定卡里有）
        if corpses and not object_only:
            for w in corpses[:1]:
                ap = _match_char(w, chars)
                if ap:
                    corpse_look = _filter_look(ap, "far")
                    if corpse_look:
                        bits.append("倒地者：" + _short_visual(corpse_look, 55))
        if action:
            bits.append(_short_visual(action, 80))
        prompt = "，".join(bits).rstrip("。，, ") + "。"
        NONE = ("无", "（无）", "none", "None", "-")
        if dlg in NONE:
            dlg = ""
        if nar in NONE:
            nar = ""
        cap_txt = dlg if dlg else (("（" + nar + "）") if nar else "")
        panels.append({"prompt": prompt, "dialog": cap_txt, "speech": dlg, "narration": nar,
                       "size": size, "anchor": str(p.get("anchor", "")), "desc": (action or "")[:160]})
    return panels, chars

# ============ 整页直出：让写作模型把一段小说编排成“一整张多格漫画页”的大提示词 ============
def _char_sheet_entries(char_sheet):
    """把“姓名—外观”角色卡拆成条目，供每页按原文实际人物过滤。"""
    import re as _re
    entries = []
    for raw in str(char_sheet or "").splitlines():
        line = raw.strip()
        if not line:
            continue
        head = _re.split(r'[—－|｜]', line, maxsplit=1)[0].strip()
        head = _re.sub(r'^\s*\d+\s*[.、]\s*', '', head).strip()
        if head:
            entries.append((head, line))
    return entries

def _page_char_context(chapter_text, char_sheet):
    """只保留本页原文明示姓名的人物，避免把全书反派或主角提前塞进画面。"""
    text = str(chapter_text or "")
    entries = _char_sheet_entries(char_sheet)
    def mentioned(name):
        if not name:
            return False
        aliases = [name]
        # “埃里克·沃斯”在首次登场后通常只写“埃里克”，仍必须命中同一张角色卡。
        aliases += [
            part.strip() for part in name.replace("・", "·").split("·")
            if len(part.strip()) >= 2
        ]
        return any(alias in text for alias in aliases)
    matched = [(name, line) for name, line in entries if mentioned(name)]
    return "\n".join(line for _, line in matched), [name for name, _ in matched], [name for name, _ in entries]

