# ---------- 关键小物件证据页（requiresDetailEvidence） ----------
_EVIDENCE_ACTION_VERBS = (
    "取出", "递出", "偷取", "放入", "按下", "插入", "捡起", "拾起", "交换",
    "藏起", "交付", "展示", "夹出", "掏出", "摸出", "翻出", "抽出", "拔出",
    "拔下", "塞入", "交出", "递上", "收下", "拿取", "探入", "夹住", "夹取",
    "触碰到", "伸向", "探向", "滑入", "握入", "拿到", "取得",
)
_EVIDENCE_OBJECT_WORDS = (
    "钥匙", "戒指", "药片", "药丸", "纸条", "字条", "密信", "信件",
    "存储卡", "U盘", "优盘", "证件", "身份证", "通行证", "硬币", "徽章",
    "怀表", "吊坠", "项链", "小瓶", "药瓶", "芯片", "卡片", "门卡", "门禁卡", "印章",
    "令牌", "碎片", "耳钉", "发簪", "针剂", "子弹", "弹壳",
)


def _requires_detail_evidence(facts=None, text=""):
    """确定性判断：关键小物件动作是否必须让读者看清物体（不新增模型调用）。
    结合动作动词、小物体词、事件/硬事实文本；大型道具和普通肖像页不误判。"""
    t = str(text or "")
    if isinstance(facts, dict):
        t += " " + json.dumps(facts, ensure_ascii=False)
    verbs = [v for v in _EVIDENCE_ACTION_VERBS if v in t]
    objs = [o for o in _EVIDENCE_OBJECT_WORDS if o in t]
    if not verbs or not objs:
        return False, []
    full = []
    bad_prefix = ("取出", "获取", "掏出", "摸到", "拿到", "偷到", "递出",
                  "找出", "拿出", "交出", "收下", "展示", "插入", "塞入")
    for o in objs:
        name = o
        for m in re.finditer(r"[\u4e00-\u9fa5]{0,2}" + re.escape(o), t):
            cand = m.group(0)
            if not any(cand.startswith(p) for p in bad_prefix):
                name = cand
                break
        if name not in full:
            full.append(name)
    return True, full[:2]


def _evidence_panel(objects, owner_hint=""):
    """关键小物件证据小格：物体完整可见，明确主动取出而非对方递交。"""
    obj = str(objects[0] if objects else "关键物品")
    owner = str(owner_hint or "").strip()
    who = owner if owner else "人物"
    return {
        "shot": "特写",
        "subject": "%s特写" % obj,
        "people": [],
        "visible": "%s完整可见，形状清楚，不被手掌、袖口、口袋或阴影遮挡" % obj,
        "action": "%s被%s的手指夹住，完整可见，形状清楚，不是对方递交" % (obj, who),
        "interaction": "",
        "environment": "",
        "staging_subLocation": "",
        "staging_backgroundMode": "minimal",
        "staging_background": "",
    }


def _must_visible_objects(objects, owner_hint=""):
    """mustVisibleObjects 结构化硬约束：物体必须完全可见、不得被遮挡。"""
    owner = str(owner_hint or "").strip()
    return [{
        "object": str(o),
        "state": "被手指夹住，完整可见",
        "owner": owner,
        "visibility": "fully_visible",
        "mustNotBeOccluded": True,
    } for o in (objects or [])]


def _ensure_evidence_visible(plan, objects):
    """mustVisibleObjects 兜底：关键物体必须进入 PanelPlan，否则程序补证据小格。"""
    if not isinstance(plan, dict) or not objects:
        return plan
    owner = ""
    panels = [p for p in (plan.get("panels") or []) if isinstance(p, dict)]
    text = json.dumps(panels, ensure_ascii=False)
    missing = [o for o in objects if o not in text]
    if missing:
        for item in (plan.get("characters") or []):
            if isinstance(item, dict) and str(item.get("name") or "").strip():
                owner = str(item["name"]).strip()
                break
        panels = panels + [_evidence_panel(missing, owner)]
        plan["panels"] = panels
    plan["mustVisibleObjects"] = _must_visible_objects(objects, owner)
    return plan


def choose_onepage_direction(chapter_text, layout_mode="adaptive", preferred_panels=6,
                             detail_facts=None):
    """用稳定的本地规则先做页级导演，避免每段文字机械塞进固定六格。"""
    import re as _re
    text = str(chapter_text or "").strip()
    if str(layout_mode or "").lower() in ("fixed", "fixed6", "classic"):
        key = "1+2+2+1"
        return {"layout": key, **ONEPAGE_LAYOUTS[key], "reason": "用户选择固定六格"}
    need_evidence, evidence_objs = _requires_detail_evidence(detail_facts, text)
    if need_evidence:
        # 关键小物件证据页：禁止单格 hero，自动用大格互动 + 小格物体特写。
        return {
            "layout": "hero+strip",
            **ONEPAGE_LAYOUTS["hero+strip"],
            "reason": "关键小物件证据页：大格表现人物互动与动作来源，小格完整展示%s"
                      % "、".join(evidence_objs),
            "evidenceObjects": evidence_objs,
        }
    if str(layout_mode or "").lower() in ("single", "hero", "fullframe"):
        # 单帧大画幅：一页只画一个画面，冲击力最强，也彻底避开跨格不一致
        return {"layout": "hero", **ONEPAGE_LAYOUTS["hero"], "reason": "用户选择单帧大画幅"}

    quoted = len(_re.findall(r'[“「『"][^”」』"\n]{1,100}[”」』"]', text))
    sentences = len(_re.findall(r'[。！？!?]', text))
    action_words = (
        "冲", "扑", "劈", "砍", "刺", "挥", "撞", "砸", "跳", "跃", "翻", "倒",
        "拔", "射", "爆", "抓", "捏", "踢", "拳", "刀", "剑", "血", "碎", "击",
    )
    action_score = sum(text.count(w) for w in action_words)
    opening = text[:260]
    environment_words = (
        "天空", "天幕", "街", "城市", "城镇", "广场", "建筑", "屋顶", "酒馆",
        "森林", "山", "海", "荒野", "房间", "大厅", "雨", "雪", "夜色", "远处",
        "俯瞰", "全景", "地平线",
    )
    environment_score = sum(opening.count(w) for w in environment_words)
    detail_words = (
        "屋顶", "门窗", "招牌", "酒馆", "圆桌", "衣服", "长裙", "铠甲",
        "眼睛", "脸", "手", "脚踝", "酒杯", "武器", "项链", "戒指",
    )
    detail_score = sum(text.count(w) for w in detail_words)

    if environment_score >= 3 and quoted <= 1 and action_score <= 4:
        if detail_score >= 4 or len(text) >= 290:
            key = "hero+2+2"
            reason = "开篇既要展示大场景，也有多个人物或物件细节，用一大四小承载"
        else:
            key = "hero+strip" if sentences <= 5 else "hero+2"
            reason = "开篇环境信息占主导，优先给大场景足够面积"
    elif environment_score >= 2 and quoted <= 3:
        key = "hero+2" if len(text) < 360 else "hero+2+1"
        reason = "先建立空间，再用小格承接人物动作"
    elif action_score >= 9:
        key = "2+hero+2"
        reason = "动作密度高，把关键命中或揭示放在中间大格"
    elif quoted >= 5 or sentences >= 13:
        key = "1+2+2+1"
        reason = "对白或剧情节拍较多，需要更多连续小格"
    elif quoted >= 3 or action_score >= 5:
        key = "hero+2+2"
        reason = "人物互动较密集，同时保留一个主画面"
    elif len(text) <= 150 and quoted == 0 and action_score <= 1 and detail_score <= 2:
        key = "hero"
        reason = "内容只有一个清楚的视觉中心，采用整页单幅避免补镜头"
    elif len(text) <= 260:
        key = "hero+2"
        reason = "内容较短，减少格数避免重复镜头"
    else:
        key = "hero+2+1"
        reason = "中等信息量，采用一主三辅的清楚节奏"
    return {"layout": key, **ONEPAGE_LAYOUTS[key], "reason": reason}

def build_onepage_messages(chapter_text, char_sheet, art, page_panels=6, scene_hint="", extra="",
                           page_layout="", direction=None, character_state=""):
    """输出一整段提示词，交给 Krea2 一次直出整页多格漫画（出框/不规则格/跨格连贯）。"""
    art = _norm_art(art)
    direction = direction or choose_onepage_direction(chapter_text, "adaptive", page_panels)
    layout_key = str(page_layout or direction.get("layout") or "1+2+2+1")
    layout_info = ONEPAGE_LAYOUTS.get(layout_key, ONEPAGE_LAYOUTS["1+2+2+1"])
    n = int(layout_info["panels"])
    layout_description = layout_info["description"]
    layout_purpose = layout_info["purpose"]
    # 不含程序固定追加的画风锁。格数越多可用字数略增，但不允许把小说和设定卡整段复述给生图模型。
    prompt_budget = 260 + n * 65
    if layout_key in ("hero+strip", "hero+2", "hero+2+1", "hero+2+2") and \
            "开篇" in str(direction.get("reason") or ""):
        director_instruction = (
            "本页属于环境建立页：第一格通栏主画面必须优先画原文最早出现的外部环境或全景，"
            "不得用后面的人物特写替换；原文随后明确进入室内时，后续小格再按原文顺序进入室内。"
        )
    elif layout_key == "2+hero+2":
        director_instruction = (
            "本页属于动作高潮页：前两格只负责蓄势，中间通栏大格必须画原文最关键的命中、"
            "揭示或动作结果，后两格表现余波与人物反应。"
        )
    else:
        director_instruction = (
            "严格按原文先后分配镜头；主画面用于本页最重要且原文已经明确出现的视觉瞬间。"
        )
    system = f"""你是顶级漫画分镜与整页生图提示词专家。你的任务是把用户提供的本页漫画剧情，改写成【一整张竖版多格漫画页】的单段生图提示词，让绘图模型一次生成完整的一页连续漫画。

你的最高目标是：
让这一整页画面既像一页真实可读的连续漫画，又严格呈现用户选定的画风、清晰镜头感和动作张力；即使没有对白、旁白和字幕，读者也能从分格动作中看懂这一回合正在发生什么。

请严格遵守以下规则：

【零、原文事实边界（最高优先级）】
1. 只画【本页要画的漫画事件】里明确发生、明确可见的内容，绝不调用后文剧情。
2. 只有本页原文明示姓名或明确描述为在场的人物，才能出现在画面里；主角、反派即使存在于全书角色卡，只要本页没有出场就禁止出现。
3. 如果本页只有一句对白、尚未揭示说话者身份，保持为画外声音，不得猜测说话者，不得让任何全局角色代替。
4. 如果本页出现角色卡里没有的临时人物，严格按本页原文建立临时外观，禁止拿已有角色顶替。
5. 用户提供的角色卡只是外观参考，不是本页出场名单。
6. 成人内容按原文如实画，不回避、不淡化、不用镜头遮挡或转场替代：原文写到的裸露、性感体态、性行为体位与身体接触，都直接写成可见的画面描述；服装该多暴露就多暴露。同时仍然遵守本规则第1条，不加原文没有的情节。

【一、输出目标】
先在内部完整分析原文，再做画面减法；分析过程绝不输出。
输出内容必须是：一整段、可直接拿去生图的精简中文提示词。
不要解释，不要分析，不要分点，不要加标题，不要加引号，不要输出任何多余内容。
只输出最终提示词本身。

【二、整页结构要求】
1. 开头只用一句短句说明竖版{n}格漫画页和“{layout_key}”版式，不复述长篇创作目标。
2. 【全页共同信息只写一次】本页角色每人只保留3—5个最强辨识锚点；场景每处只保留2—4个建立空间所必需的可见锚点。不要复述完整角色卡、人物经历、性格、关系和不可见状态。
3. 如果某个外观、场景或道具只在一格能看到，就只写在那一格；不要提升为全页共同信息。
4. 然后按顺序写第一格至第{n}格。每格只写：景别/机位、当前可见人物、一个主要动作或状态、不可缺少的道具或环境关系。已经写过的全页共同外观和画风不要逐格重复。
   例如：原文有一百多字，但选中的这一格只展示一个人的背影，最终这一格就只写“景别机位＋单人背影＋背后可见的发型/轮廓/服装＋一个必要环境锚点”；正脸、心理、前因、后续动作和这一镜头看不见的物件全部舍弃。
5. 结尾不再重复画风长句，只补充全页共同的光线或色彩条件；如果前文已有则省略。
6. 本页必须采用“{layout_key}”版式：{layout_description}。版式目的：{layout_purpose}。画格数量、面积关系和阅读顺序必须准确，不得擅自改回平均六格。
7. 每格都把人物脸部、手、武器和主要动作安排在视觉中心或一侧，另一侧或上方明确保留约18%—25%的低细节背景供后期本地排字；这一区域仍须保留环境色彩、光影渐变和轻微场景纹理，禁止画成几何白块、空白框或气泡。
8. 图片本身禁止生成文字、字幕、对白气泡、旁白框、空白气泡、空白框、纯白占位块、
拟声字和无法辨认的符号；排字位置仍然必须是带环境色彩与轻微场景纹理的真实画面。
9. 本页导演指令：{director_instruction}

【三、角色规则】
1. 优先使用用户提供的【固定角色外观卡】；不得擅自修改角色的性别、年龄段、体型、发型、服装和关键辨识特征。
2. 整页每一个分格里，同一人物的外形、年龄感、身材、发型、服装都必须保持一致；脸不必完全一模一样，但外观识别特征必须稳定一致。
3. 儿童、少年和老人不能只写年龄数字，必须同时呈现对应的身高比例、面部成熟度、皱纹白发或佝偻等可见年龄特征；普通成年人的精确岁数不必在每格重复。
4. 角色数量必须准确，动物、武器、物件不算人。
5. 角色卡只用于锁定人物出场时的外观，不是镜头清单；原文没有在本页提到或展示的饰品、身体局部和武器，不得擅自单独做成特写镜头。

【四、场景规则】
1. 忠实保留原文场景顺序。原文明确从街道、建筑外观进入室内时，可以先画外景建立镜头，再切入内景；不得为了“空间统一”删除外景，也不得把内外场景混成同一个不合理空间。
2. 每个子场景内部保持空间连续；相邻分格切换地点时，用门窗、招牌、屋顶、入口或视线方向建立清楚联系。
3. 场景只写长期稳定存在的环境元素，例如墙体、地面、家具、铁架、灯光、窗户、油污、雨水、仓库结构等。
4. 不要把临时动作造成的东西写进固定场景，例如飞溅物、武器挥动轨迹、人物姿势、倒地状态等；这些只写在对应分格里。

【五、分格规则】
1. 一共{n}格，严格使用“{layout_key}”的面积层级；主画面承担本页最重要的视觉信息，小格只承担一个动作或反应。
2. 输出前先在内部列出原文所有候选视觉节拍，再按以下优先级筛选：地点建立 > 冲突开始 > 关键动作 > 明确结果 > 必要反应或关键物件。没有推动阅读的信息直接舍弃，不输出候选清单。
3. 每格只写一个画面中心。动作是中心时，表情、背景和道具只作辅助；表情是中心时，不再加入另一项大动作；纯物件特写不塞入完整人物。
4. 每格写到“足够生成”即停止：一个景别/机位、一个主体、一个动作或状态、最多一个必要空间关系。构图位置和占比只在影响画面理解或排字留白时写；每格通常控制在35—55字。
5. 出框、水花、火星、血迹、碎片等效果只有在它就是本格动作重点时才写，不能每格都加。
6. {n}格之间按原文顺序连贯，但镜头变化必须服务阅读；不得为了凑格重复人物脸部、同一动作或同一环境。
7. 优先写动作完成时清楚、稳定、易读的可见状态，不写动作成因、推理过程、气味、声音、心理或解释。
8. 只描写相机真正能看见的内容，不写对白、旁白、拟声词、字幕框和内心独白。
9. 不平均分配重要性：至少一个明确主画面；大场景用远景展示空间，小格只承接必要动作、反应或关键物件。

【六、忠实原文规则】
1. 必须忠于用户提供的本页漫画剧情。
2. 不得新增原文没有的剧情事实，不得擅自补充原文没有明确发生的情节。
3. 可以为了画面连贯性对动作进行可视化整理，但不得改变事件顺序和核心信息。
4. 不写推断性的结果，不写“像是如何造成的”“似乎意味着什么”这类内容，只写最终画面里能够看到的状态。

【七、画面语言规则】
1. 用户选定的画风是全页视觉表现的最高依据；不得擅自改成写实、动漫或其他风格。
2. 动作画面要清晰，人物结构可信，力量方向明确；夸张程度服从选定画风，但不能破坏动作因果与角色辨识度。
3. 视觉冲击力来自主次、构图、尺度差和动作方向，不来自形容词堆叠。
4. 如果有出框效果，应适度、明确、服务动作焦点，不能让页面显得凌乱。

【八、结尾风格统一语】
程序会在你的输出前固定追加以下画风，不要在正文中再次复述：
{art}

【九、最终输出格式】
直接输出一整段连贯中文提示词。
正文目标长度为{max(220, prompt_budget - 120)}—{prompt_budget}个中文字符，宁短勿杂；每格通常不超过55字。
不要分点。
不要小标题。
不要解释。
不要引号。
不要任何额外说明。"""
    # 新版不再让模型直接写可自由膨胀的生图长文，而只让它提交结构化画面计划；
    # 最终提示词由程序按可见字段确定性编译。保留上面的旧说明只用于源码回退，不再发送给模型。
    fixed_layout = str(direction.get("reason") or "") == "用户选择固定六格"
    if str(direction.get("layout") or "") == "hero":
        layout_rule = (
            '本页是单格hero整页：只有一个视觉瞬间，layout 必须为 "hero"，'
            "panels 必须正好1项。这个唯一画面必须覆盖本页全部出场人物、"
            "动作落点、人物左右位置、互动接触点与关键道具；"
            "不写多镜头，不写第一格/第二格，不拆成连续小格。"
        )
    elif fixed_layout:
        layout_rule = (
            'layout 必须为 "1+2+2+1"，panels 必须正好6项。'
        )
    else:
        layout_rule = (
            "先根据真正不同的视觉节拍选择版式，不按字数凑格："
            '1个画面用"hero"；2个用"hero+strip"；3个用"hero+2"；'
            '4个用"hero+2+1"；5个动作高潮用"2+hero+2"，其他5个用"hero+2+2"；'
            '6个才用"1+2+2+1"。panels数量必须与版式一致。'
        )
    system = f"""你是漫画画面导演。完整理解本页漫画事件后，只提交真正需要生成的可见画面计划；不要输出分析过程，也不要直接写生图长提示词。

【事实边界】
1. 只使用本页原文明示的地点、人物、动作、物件和结果，不调用后文，不猜测说话者，不拿角色卡里未出场人物补位。
2. 角色卡只用于识别外观，不是出场名单。临时人物按本页原文建立。
3. 原因、心理、气味、声音、关系说明和文学修辞只帮助你理解；除非能被相机直接拍到，否则不进入任何画面字段。
4. 只有声音、脚步声或画外喊话，但原文没有写这个人出现在视野中时，这个人不得进入 people、characters、subject 或 visible。

【先分析、后选择】
先在内部识别全部候选视觉节拍，再只保留推动阅读所必需的画面。优先级：地点建立、冲突开始、关键动作、明确结果、必要反应或关键物件。
同一地点、同一人物、同一状态的连续形容合并；小动作和物件没有承担转折时不独占一格。本页文字一百多字也可以只留下一个背影画面。
{layout_rule}

【每格减法】
每格只能有一个画面中心：一个主体的一项主要动作或状态。
只填相机在该机位能看见的信息。背影只填后脑发型、轮廓、背部服装和确实可见的背负物；正脸、眼睛、正面饰品和心理为空。远景只填剪影、体态、服装色块和大型武器。物件特写不填完整人物。
environment 只放理解主体不可缺少的一个空间锚点；不需要就留空。不得把分析过的其他事实顺手塞入。
people 必须逐项列出本格实际入镜人物，每人只列一次；同一人不得因连续动作被复制。纯环境或物件特写填空数组。
近景、特写和浅景深画格只写当前方向可见的1至3个背景锚点，不填完整场景；场景可见范围由场面调度决定，本计划只负责每格可见构成。

【单张图片动作】
每个画格都是一个静止时间点，不是视频片段。原文写挥砍、划向、扑向、冲撞、旋转等连续动作时，action只选择蓄势停顿、已经接触或动作完成后的落点之一，优先选择结果清楚、人体结构稳定的一帧。
action用具体位置写姿势：双脚或身体支点、重心、躯干朝向、手臂和武器停在哪里、对手最后处于什么状态；不用“正在挥砍、划向、扑向、冲向、飞向”等过程词，不写运动轨迹或多重残影。
两人或多人发生拥抱、搀扶、抓握、压制、推拉、亲吻等身体接触时，interaction必须逐人写明画面左右与前后位置、身体朝向、每只手属于谁、手掌接触对方哪个部位。不能只写“拥抱”或“纠缠”。

【输出】
只输出一个JSON对象，不要Markdown、解释、标题或JSON以外的文字：
{{
  "layout": "hero/hero+strip/hero+2/hero+2+1/hero+2+2/2+hero+2/1+2+2+1",
  "characters": [
    {{"name":"本页人物名","anchors":"只写整页实际能看见的3—5个固定辨识锚点；若整页只有背影，不写正脸锚点"}}
  ],
  "scene": "全页共同且实际可见的2—4个环境锚点，没有则空字符串",
  "light": "只写一种必要光线或色彩条件，没有则空字符串",
  "panels": [
    {{
      "shot":"景别和机位，尽量12字内",
      "subject":"当前可见主体，如单人背影/少女正面/生锈屋顶，尽量12字内",
      "people":["本格实际入镜的人物名；纯环境或物件空数组"],
      "visible":"这个机位真正看见的身份特征，尽量24字内",
      "action":"一个主要动作或最终可见状态，尽量24字内",
      "environment":"最多一个必要环境关系，尽量16字内；不需要留空",
      "interaction":"多人发生接触时，逐人写清左右前后、身体朝向、每只手的归属和具体接触部位，尽量42字内；没有身体接触留空"
    }}
  ]
}}

每个画格都用完整的场景画面铺满，画风由程序统一追加，不要在JSON里复述画风。"""
    page_sheet, allowed_names, all_names = _page_char_context(chapter_text, char_sheet)
    page_state, _, _ = _page_char_context(chapter_text, character_state)
    up = []
    up.append("【本页相关角色外观卡（已按本页原文明示姓名过滤；不在这里的人物禁止自行代入）】\n"
              + (page_sheet.strip() or "（本页没有匹配到全局角色卡；只能根据本页原文建立临时人物，禁止调用后文角色）"))
    if page_state.strip():
        up.append("【本章开始时的人物可见状态（只覆盖衣着、伤势、年龄阶段和携带物等变化；本章内的新变化必须等原文事件发生后再画）】\n"
                  + page_state.strip())
    if scene_hint and scene_hint.strip():
        up.append("【固定场景补充（如有）】\n" + scene_hint.strip())
    up.append("【本页要画的漫画事件】\n" + chapter_text.strip()[:2500])
    if extra and extra.strip():
        up.append("【额外要求（可选）】\n" + extra.strip())
    up.append("只输出规定的结构化JSON画面计划。")
    return [{"role": "system", "content": system},
            {"role": "user", "content": "\n\n".join(up)}], 1500

def _onepage_layout_for_count(count, preferred=""):
    count = max(1, min(int(count or 1), 6))
    if count == 1:
        return "hero"
    if count == 2:
        return "hero+strip"
    if count == 3:
        return "hero+2"
    if count == 4:
        return "hero+2+1"
    if count == 5:
        return preferred if preferred in ("hero+2+2", "2+hero+2") else "hero+2+2"
    return "1+2+2+1"

def _visible_anchors_for_shot(anchors, shot, subject):
    """角色卡可以很完整，但最终只取当前机位真实可见的身份锚点。"""
    text = str(anchors or "").replace("，", "；").replace("、", "；").replace(",", "；")
    camera = str(shot or "") + str(subject or "")
    if any(k in camera for k in ("背影", "背对", "背面", "后脑", "从背后")):
        mode = "back"
    elif any(k in camera for k in ("远景", "大远景", "全景", "俯瞰")):
        mode = "far"
    elif any(k in camera for k in ("近脸", "面部", "脸部", "眼睛", "五官")):
        mode = "face"
    elif any(k in camera for k in ("第一人称", "主观", "POV")):
        mode = "pov"
    else:
        mode = "full"
    return _filter_look(text, mode)

_BACK_VIEW_KW = ("背影", "背对", "背面", "后脑", "后背")
_FRONT_VIEW_KW = ("正面", "侧颜", "侧脸", "脸部", "面部", "五官", "表情", "回头", "正脸")

def _single_view_subject(subject):
    """一格里同一个人只能有一个视角。
    模型常写成"背影与侧颜特写"，生图模型就把同一个人画两遍（一个正面一个背影）。
    这里发现"背影+正脸"同时出现就只留信息量更大的正面视角。"""
    text = str(subject or "")
    if not text:
        return text
    has_back = any(k in text for k in _BACK_VIEW_KW)
    has_front = any(k in text for k in _FRONT_VIEW_KW)
    if not (has_back and has_front):
        return text
    import re as _r
    # 去掉"背影/背对…"这一段（含它前后的连接词），保留正面那一半
    cleaned = _r.sub(r'(背影|背对镜头|背对|背面|后脑|后背)\s*(与|和|及|,|，|、)?\s*', '', text)
    cleaned = cleaned.strip("与和及,，、 ")
    return cleaned or text

def _compact_onepage_panel(panel, include_visible=True, character_names=None,
                           character_anchors=None, include_space=False,
                           single_frame=False):
    """把结构化的一格编译成短句；核心字段优先，环境和留白有空间才加入。"""
    import re
    panel = panel if isinstance(panel, dict) else {}
    shot_raw = str(panel.get("shot") or "")
    # shot 字段只保留景别与机位；“展示什么”应由 subject/action 承担。
    shot = _short_visual(
        shot_raw.replace(",", "，").split("，", 1)[0], 20)
    subject = _short_visual(panel.get("subject"), 22)
    subject = _single_view_subject(subject)
    people = panel.get("people") if isinstance(panel.get("people"), list) else []
    people = [_short_visual(name, 10) for name in people if _short_visual(name, 10)]
    if not people and character_names:
        # 人物推断只看主体与可见身份，不看 action：动作里提到人名
        # （如“钥匙被卡洛夹住”）不代表该人物真的入镜。
        panel_text = "".join(str(panel.get(key) or "")
                             for key in ("subject", "visible"))
        people = [name for name in character_names if name and name in panel_text]
    people = list(dict.fromkeys(people))
    # "各出现一次"太弱，压不住"背影与侧颜"这类描述导致的同人重复；改成明确禁令。
    count_lock = (
        "本格画面里总共只有%s个人物，就是%s，同一个人只允许出现一个身影，"
        "不得同时画正面和背影、不得出现同一人的第二个身影" %
        (_cn(len(people)), "、".join(people))
        if people else ""
    )
    visible_raw = str(panel.get("visible") or "")
    camera = shot + subject
    # 角色卡拥有最高优先级。每格重复当前机位能看见的固定锚点，
    # 避免模型临时概括把“短发、有疤”改成“长发、无疤”。
    if character_anchors and people:
        fixed_bits = []
        for name in people:
            anchors = _match_char(name, character_anchors)
            fixed = _visible_anchors_for_shot(anchors, shot, subject)
            fixed = _short_visual(fixed, 62)
            if fixed:
                fixed_bits.append("%s固定：%s" % (name, fixed))
        if fixed_bits:
            # 有可信角色卡时不采用模型临时写出的外观，防止两套特征互相冲突。
            visible_raw = "；".join(fixed_bits)
    visible = _visible_anchors_for_shot(visible_raw, shot, subject)
    visible = _short_visual(visible, 126 if len(people) > 1 else 72)
    action = _freeze_frame_action(panel.get("action"))
    if single_frame and len(people) >= 2:
        actor, target = people[0], people[-1]
        if ("砍" in action or "斩" in action) and "倒" in action:
            action = "%s的武器停在落点，%s已经倒地" % (actor, target)
        elif any(key in action for key in ("击倒", "打倒", "撞倒")):
            action = "%s保持动作落点，%s已经倒地" % (actor, target)
    interaction = _short_visual(panel.get("interaction"), 56)
    if interaction and len(people) >= 2:
        interaction += "；双方头部、躯干与手臂各自连续可辨，接触点清楚"
    environment_raw = str(panel.get("environment") or "")
    # 生图提示词不保留“A或B”备选，避免模型同时画两种环境反应。
    environment = _short_visual(
        environment_raw.split("或", 1)[0], 22)
    required = [x for x in (
        shot, subject, count_lock, visible if include_visible else "", action, interaction) if x]
    optional = [x for x in (environment,) if x]
    sentence = "，".join(required)
    sentence_limit = 196 if interaction else (138 if single_frame else 172)
    for item in optional:
        candidate = sentence + ("，" if sentence else "") + item
        if len(candidate) <= sentence_limit - 4:
            sentence = candidate
    return _short_visual(sentence, sentence_limit)

def _freeze_frame_action(value):
    """把少量常见的连续过程词压到静止落点；主要姿势仍由结构化计划提供。"""
    import re as _re
    text = _short_visual(value, 52)
    if not text:
        return ""
    text = text.replace("正在", "")
    replacements = (
        (r'挥(?:剑|刀)?砍向', '双手握住武器，武器停在动作落点，身体面向'),
        (r'(?:剑刃|刀刃)划向', '刃口停在接触位置，朝向'),
        (r'(?:剑|刀)劈向', '武器停在动作落点，身体面向'),
        (r'(?:剑|刀)斩向', '武器停在动作落点，身体面向'),
        (r'(?:剑|刀)刺向', '武器尖端停在接触位置，身体面向'),
        (r'扑向', '四肢支撑身体贴近'),
        (r'冲向', '前脚落地，身体面向'),
        (r'飞向', '停在'),
    )
    for pattern, replacement in replacements:
        text = _re.sub(pattern, replacement, text)
    text = text.replace("运动模糊", "衣物与环境保持动作后的物理反应")
    text = text.replace("动作轨迹", "动作落点")
    text = text.replace("多重残影", "单一清楚轮廓")
    return _short_visual(text, 52)

def _stable_character_anchors(value):
    """全页角色锁只保留稳定身份，不把倒地、惊恐、流血等本格状态固定到所有格。"""
    import re as _re
    parts = [p.strip() for p in _re.split(r'[；;，,、]', str(value or "")) if p.strip()]
    transient = (
        "倒地", "躺", "惊恐", "哭", "笑", "愤怒", "流血", "血污", "受伤",
        "挥", "冲", "奔跑", "站在", "站立", "姿态", "瞬间", "被砍",
        "跪", "蹲", "死亡",
    )
    stable = [p for p in parts if not any(k in p for k in transient)]
    return "；".join(stable)

def _inactive_weapon_anchors(value):
    """本页没有武器动作时，把角色卡的“手持”改写为明确收纳状态。"""
    import re as _re
    text = str(value or "")
    text = _re.sub(
        r'双手各持一把[^；;，,。]*细剑',
        '双剑完整收在腰侧剑鞘内',
        text)
    text = _re.sub(
        r'双手各持一把[^；;，,。]*',
        '双武器完整收在固定佩戴位置',
        text)
    return text

def _space_mode_constraint(panel, prefix="本格"):
    """按 spaceMode 返回单条空间硬约束；旧数据缺模式时返回空串。"""
    space_mode = str(panel.get("staging_space_mode") or "").strip()
    if space_mode == "interior":
        return ("%s为室内镜头，墙体、屋顶、门窗结构完整；"
                "室外只能通过真实门窗开口少量出现，不得移除墙体，"
                "不得同时完整展示室内与室外，不得形成建筑剖面图" % prefix)
    if space_mode == "exterior":
        return ("%s为室外镜头，只表现外部主空间；"
                "室内仅允许通过窗户或门口少量暗示，"
                "不得同时展示完整室内陈设，不得形成建筑剖面图" % prefix)
    if space_mode == "threshold":
        primary = str(panel.get("staging_primary_space") or "").strip()
        boundary = str(panel.get("staging_boundary_element") or "").strip()
        boundary_txt = ("必须保留%s，" % boundary) if boundary else ""
        return ("%s位于明确空间边界，以%s为主，另一侧仅作辅助；"
                "%s不得移除墙体或将室内外同时完整展开"
                % (prefix, primary or "当前主空间", boundary_txt))
    return ""


def _hero_panel_bit(panel):
    """单格整页的画面正文：一个连续电影画面，不使用“第N格/画格”分格语言。"""
    panel = panel if isinstance(panel, dict) else {}
    parts = []
    sub = str(panel.get("staging_subLocation") or "").strip()
    if sub:
        parts.append("位置：" + sub)
    shot = str(panel.get("shot") or "").strip()
    if shot:
        parts.append(_short_visual(shot.replace(",", "，").split("，", 1)[0], 20))
    subject = _single_view_subject(str(panel.get("subject") or ""))
    if subject:
        parts.append(_short_visual(subject, 22))
    action = _freeze_frame_action(panel.get("action"))
    if action:
        parts.append(action)
    interaction = _short_visual(panel.get("interaction"), 130)
    people = [str(x).strip() for x in (panel.get("people") or []) if str(x).strip()]
    if interaction and len(people) >= 2:
        interaction += "；双方头部、躯干与手臂各自连续可辨，接触点清楚"
    if interaction:
        parts.append(interaction)
    visible = _short_visual(panel.get("visible"), 110)
    if visible:
        parts.append(visible)
    primary = str(panel.get("staging_primary_space") or "").strip()
    if primary:
        parts.append("主空间：" + primary)
    bg = str(panel.get("staging_background") or "").strip()
    if bg:
        parts.append("局部背景：" + bg)
    constraint = _space_mode_constraint(panel, prefix="本画面")
    if constraint:
        parts.append(constraint)
    enclosure = _enclosure_constraint(panel, prefix="本画面")
    if enclosure:
        parts.append(enclosure)
    return "，".join(x for x in parts if x)


def _staging_panel_bit(panel, index):
    """按场面调度编译单格：位置、相机、动作、局部背景和背景表现方式。"""
    mode = str(panel.get("staging_backgroundMode") or "partial")
    mode_text = {
        "establishing": "完整空间建立镜头",
        "partial": "只画当前方向可见的局部环境",
        "shallow_focus": "背景虚化，仅保留场景配色与少量识别物",
        "occluded": "背景被门框、柱体或人物自然遮挡",
        "minimal": "极近景，只保留场景颜色、光线与极少材质线索",
        "detail_closeup": "局部特写，不画完整场景",
    }.get(mode, "局部背景")
    parts = ["位置：" + str(panel.get("staging_subLocation") or "")]
    shot = str(panel.get("staging_shot") or panel.get("shot") or "")
    if shot:
        parts.append(shot)
    cam = str(panel.get("staging_camera") or "")
    if cam:
        parts.append("相机朝向" + cam)
    subject = str(panel.get("subject") or "")
    if subject:
        parts.append(subject)
    action = str(panel.get("action") or "")
    if action:
        parts.append(action)
    interaction = _short_visual(panel.get("interaction"), 90)
    if interaction:
        parts.append(interaction)
    visible = str(panel.get("visible") or "")
    if visible:
        parts.append(visible)
    bg = str(panel.get("staging_background") or "")
    if bg:
        parts.append("局部背景：" + bg)
    parts.append(mode_text)
    constraint = _space_mode_constraint(panel)
    if constraint:
        parts.append(constraint)
    enclosure = _enclosure_constraint(panel)
    if enclosure:
        parts.append(enclosure)
    return "第%d格：%s" % (index, "，".join(parts))

def _compile_onepage_plan(plan, fallback_direction, fixed_layout=False, quick_mode=False,
                          trusted_characters=None, single_frame=False,
                          verbatim_anchors=None, hero_hard_facts=None):
    """把模型的结构化分析结果确定性编译成简短生图正文，不让模型自由复述小说。"""
    if not isinstance(plan, dict):
        return "", fallback_direction
    verbatim = set(verbatim_anchors or ())
    raw_panels = [p for p in (plan.get("panels") or []) if isinstance(p, dict)]
    if not raw_panels:
        return "", fallback_direction
    raw_panels = raw_panels[:6]
    if single_frame:
        # 单帧大画幅：模型常不听话仍给多格，这里强制只保留第一个（按原文顺序最主要的）画面
        raw_panels = raw_panels[:1]
        info = ONEPAGE_LAYOUTS["hero"]
        direction = {"layout": "hero", **info, "reason": "单帧大画幅：整页只画一个画面"}
    requested = str(plan.get("layout") or "").strip()
    if fixed_layout:
        layout = "1+2+2+1"
        # 固定六格仍不能靠补写新剧情凑格；不足六格时按实际有效画面回退为自适应版式。
        if len(raw_panels) != 6:
            layout = _onepage_layout_for_count(len(raw_panels), requested)
    else:
        layout = _onepage_layout_for_count(len(raw_panels), requested)
    if not single_frame:
        info = ONEPAGE_LAYOUTS[layout]
        direction = {
            "layout": layout,
            **info,
            "reason": "根据结构化分析中的有效视觉节拍选择，共%d个画面" % len(raw_panels),
        }
    is_hero = single_frame or layout == "hero"
    if is_hero:
        # 单格整页不是“漫画分格页”：用单张完整电影画面语言，避免 Krea2 自动拼贴。
        bits = ["生成一张独立、完整、连续的竖版电影画面。"
                "整张图只有一个时间点、一个视角和一个连续空间，"
                "不分格，不拼贴，不增加插图或局部特写"]
    elif quick_mode:
        bits = ["竖版%d格连续叙事画面页，%s，所有画格从边缘到边缘铺满场景，格间仅用窄白线" %
                (len(raw_panels), info["description"])]
    else:
        bits = ["竖版%d格连续叙事画面页，%s" % (len(raw_panels), info["description"])]
    char_bits = []
    character_names = []
    character_anchors = {}
    trusted_characters = trusted_characters if isinstance(trusted_characters, dict) else {}
    weapon_active = any(
        any(word in str(panel.get("action") or "")
            for word in ("拔剑", "拔刀", "出鞘", "挥剑", "挥刀", "刺击", "劈砍", "射击"))
        for panel in raw_panels
    )
    if not weapon_active:
        trusted_characters = {
            name: _inactive_weapon_anchors(value)
            for name, value in trusted_characters.items()
        }
    for item in (plan.get("characters") or [])[:4]:
        if not isinstance(item, dict):
            continue
        name = _short_visual(item.get("name"), 10)
        if name:
            character_names.append(name)
        trusted = _match_char(name, trusted_characters)
        anchor_key = re.sub(r"\s*[（(][^）)]*[）)]\s*$", "", name).strip()
        if (name in verbatim or anchor_key in verbatim) and \
                isinstance(trusted, str) and str(trusted).strip():
            anchors_raw = str(trusted).strip()
        else:
            anchors_raw = _stable_character_anchors(trusted or item.get("anchors"))
        if name:
            character_anchors[name] = anchors_raw
        if len(raw_panels) == 1 and not is_hero:
            only_panel = raw_panels[0]
            anchors_raw = _visible_anchors_for_shot(
                anchors_raw, only_panel.get("shot"), only_panel.get("subject"))
        anchors = _short_visual(anchors_raw, 130 if is_hero else 110)
        if name and anchors:
            char_bits.append("%s：%s" % (name, anchors))
    # 模型偶尔漏交 characters，但只要本格明确写了姓名，仍用项目角色卡补回。
    panel_text = json.dumps(raw_panels, ensure_ascii=False)
    for name, anchors_value in trusted_characters.items():
        if name in character_names or name not in panel_text:
            continue
        anchor_key = re.sub(r"\s*[（(][^）)]*[）)]\s*$", "", name).strip()
        if name in verbatim or anchor_key in verbatim:
            anchors_raw = str(anchors_value).strip()
        else:
            anchors_raw = _stable_character_anchors(anchors_value)
        character_names.append(name)
        character_anchors[name] = anchors_raw
        anchors = _short_visual(anchors_raw, 130 if is_hero else 110)
        if anchors:
            char_bits.append("%s：%s" % (name, anchors))
    # 单格整页：完整锚点只写一次在“本画面人物”里，不再塞进每格正文。
    if is_hero:
        if char_bits:
            bits.append("本画面人物：" + "；".join(char_bits))
    elif char_bits and len(raw_panels) > 1 and not quick_mode:
        bits.append("角色固定：" + "；".join(char_bits))
    if is_hero:
        hero_facts = hero_hard_facts if isinstance(hero_hard_facts, dict) else {}
        if character_names:
            names = list(dict.fromkeys(character_names))
            bits.append(
                "本画面总共只有%d个人：%s。除了这%d人，不得出现任何人，"
                "不得复制同一个人物，不得生成额外头像、插图或回忆画面"
                % (len(names), "、".join(names), len(names)))
        forbidden = [str(x).strip() for x in
                     (hero_facts.get("forbidden") or []) if str(x).strip()]
        if forbidden:
            bits.append("本页不得出现：" +
                        "、".join(list(dict.fromkeys(forbidden))[:6]))
        events = [str(x).strip() for x in
                  (hero_facts.get("primaryEvents") or []) if str(x).strip()]
        if events:
            bits.append("本页必须完成的关键事件：" + "；".join(events[:4]))
        restricted = [str(x).strip() for x in
                      (hero_facts.get("restrictedItems") or []) if str(x).strip()]
        if restricted:
            bits.append("禁止出现的道具：" +
                        "、".join(list(dict.fromkeys(restricted))[:6]))
    scene = _short_visual(plan.get("scene"), 90)
    light = _short_visual(plan.get("light"), 40)
    staging_scene = plan.get("stagingScene") if isinstance(
        plan.get("stagingScene"), dict) else {}
    has_staging = any(isinstance(p, dict) and p.get("staging_subLocation")
                      for p in raw_panels)
    # 单格由 panel.environment 承担唯一必要环境；多格才需要一份全页场景锁。
    if staging_scene and len(raw_panels) > 1:
        cs = staging_scene.get("commonScene") if isinstance(
            staging_scene.get("commonScene"), dict) else {}
        scene_bits = [str(staging_scene.get("sceneName") or plan.get("scene") or "场景")]
        if str(cs.get("mainMaterial") or "").strip():
            scene_bits.append("主材质：" + str(cs["mainMaterial"]).strip())
        if str(cs.get("mainColor") or "").strip():
            scene_bits.append("主色调：" + str(cs["mainColor"]).strip())
        if str(cs.get("unifiedLight") or "").strip():
            scene_bits.append(str(cs["unifiedLight"]).strip())
        bits.append("场景：" + "；".join(x for x in scene_bits if x))
    elif scene and len(raw_panels) > 1:
        bits.append("场景：" + scene)
    if light:
        bits.append(light)
    if isinstance(staging_scene, dict):
        local_facts = [str(x) for x in (staging_scene.get("localSceneFacts") or [])
                       if str(x).strip()][:6]
        if local_facts:
            bits.append("本页局部场景事实：" + "；".join(local_facts))
    for index, panel in enumerate(raw_panels, 1):
        if is_hero:
            hero_bit = _hero_panel_bit(panel)
            if hero_bit:
                bits.append(hero_bit)
            continue
        if isinstance(panel, dict) and panel.get("staging_subLocation"):
            bits.append(_staging_panel_bit(panel, index))
            continue
        # 本格可见锚点不能省略：标志武器只写在全页角色表时，生图模型容易漏画。
        brief = _compact_onepage_panel(
            panel,
            include_visible=True,
            character_names=character_names,
            character_anchors=character_anchors,
            include_space=False,
            single_frame=True,
        )
        if brief:
            bits.append("第%d格：%s" % (index, brief))
    if is_hero:
        # 单格整页的公共末尾只写一次硬约束，不堆叠重复规则。
        bits.append(
            "单一完整画面，不分格，不拼贴，不生成蒙太奇，不生成重复人物头像，"
            "不生成局部插图，不生成回忆画面，不添加未要求人物，"
            "不把同一人物画成多个身体，不改变人物性别、年龄和服装")
    elif quick_mode:
        bits.append(
            "同名人物跨格保持发型、伤疤、体型和服装一致；"
            "各格主体清楚，人物、物件与环境纹理填满每个画格，格间只保留窄分隔线")
    else:
        if has_staging:
            bits.append(
                "页面恰好%d个画格，各格按场面调度呈现局部或完整背景；"
                "同名人物跨格保持发型长度、发色、伤疤位置、体型和服装完全一致；"
                "各格主体清楚，背景虚化、遮挡或局部化按格执行，"
                "画格之间只使用窄而整齐的分隔线" %
                len(raw_panels))
        else:
            bits.append(
                "页面恰好%d个画格，每个画格从边缘到边缘呈现完整场景；"
                "同名人物跨格保持发型长度、发色、伤疤位置、体型和服装完全一致；"
                "各格主体清楚，人物、物件和带环境色彩的真实场景纹理覆盖全部画面区域，"
                "画格之间只使用窄而整齐的分隔线" %
                len(raw_panels))
    return "。".join(x.rstrip("。 ") for x in bits if x).rstrip("。 ") + "。", direction

def generate_onepage_package(chapter_text, char_sheet, art, page_panels=6,
                             scene_hint="", extra="", temperature=0.6,
                             layout_mode="adaptive", character_state=""):
    """返回提示词和同一份页级导演数据，确保生图与本地排字使用同一版式。"""
    need_evidence, evidence_objs = _requires_detail_evidence(None, chapter_text)
    direction = choose_onepage_direction(chapter_text, layout_mode, page_panels,
                                         {"text": chapter_text})
    msgs, num_predict = build_onepage_messages(
        chapter_text, char_sheet, art, direction["panels"], scene_hint, extra,
        direction["layout"], direction, character_state)
    page_sheet, allowed_names, all_names = _page_char_context(chapter_text, char_sheet)
    forbidden = [name for name in all_names if name not in allowed_names]
    raw = chat_stream(msgs, temperature, None, num_predict).strip()
    leaked = [name for name in forbidden if name and name in raw]
    if leaked:
        log("⚠ 整页画面计划出现未出场人物，自动重写：" + "、".join(leaked))
        correction = (
            "上一版错误加入了本页原文没有出场的人物：%s。请完全重写。"
            "这些人物不得出现、不得被提及，也不得用来替代临时人物；"
            "严格按本页原文的事件顺序，只输出规定结构的JSON画面计划。"
        ) % "、".join(leaked)
        retry_msgs = msgs + [{"role": "assistant", "content": raw},
                             {"role": "user", "content": correction}]
        raw = chat_stream(retry_msgs, 0.35, None, num_predict).strip()
        leaked = [name for name in forbidden if name and name in raw]
        if leaked:
            raise RuntimeError("整页画面计划仍包含本页未出场人物：" + "、".join(leaked))
    plan = _extract_json(raw)
    if need_evidence and isinstance(plan, dict):
        # 关键小物件必须进入 PanelPlan：模型漏掉时程序补证据小格。
        plan = _ensure_evidence_visible(plan, evidence_objs)
    fixed_layout = str(layout_mode or "").lower() in ("fixed", "fixed6", "classic")
    single_frame = str(layout_mode or "").lower() in ("single", "hero", "fullframe") \
        and not need_evidence
    trusted_characters = parse_char_sheet(page_sheet)
    hero_facts = None
    if single_frame or need_evidence:
        hero_facts = {
            "forbidden": [str(x) for x in forbidden if str(x).strip()][:6],
        }
    if need_evidence:
        panels = [p for p in (plan.get("panels") or []) if isinstance(p, dict)]
        if len(panels) < 2:
            direction = {
                "layout": "hero+strip",
                **ONEPAGE_LAYOUTS["hero+strip"],
                "reason": "关键小物件证据页：大格互动，小格完整展示%s"
                          % "、".join(evidence_objs),
            }
    compiled, compiled_direction = _compile_onepage_plan(
        plan, direction, fixed_layout,
        trusted_characters=trusted_characters,
        single_frame=single_frame,
        hero_hard_facts=hero_facts,
    )
    if compiled:
        direction = compiled_direction
        prompt_body = compiled
    else:
        # 兼容模型偶发的旧式纯文本输出；只在无法解析JSON时使用，且做硬长度保护。
        prompt_budget = 260 + int(direction["panels"]) * 65
        prompt_body = _short_visual(raw, prompt_budget)
        log("⚠ 整页画面计划不是有效JSON，已按旧格式压缩使用")
    prompt = _style_locked_prompt(prompt_body, art, single_frame=single_frame)
    return {
        "prompt": prompt,
        "panel_count": direction["panels"],
        "layout": direction["layout"],
        "direction": direction,
        # 结构化画面计划要留存下来，这样剧本才可编辑、单页才可重出。
        "plan": plan if isinstance(plan, dict) else {},
        "trusted": trusted_characters,
    }

def generate_onepage_prompt(chapter_text, char_sheet, art, page_panels=6,
                            scene_hint="", extra="", temperature=0.6,
                            layout_mode="adaptive", character_state=""):
    """生成整页提示词，并拦截本页未出场的全局人物。"""
    return generate_onepage_package(
        chapter_text, char_sheet, art, page_panels, scene_hint, extra,
        temperature, layout_mode, character_state)["prompt"]

# ================== 提示词预设（存成独立 txt，可手动编辑） ==================
PRESET_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "presets")
os.makedirs(PRESET_DIR, exist_ok=True)
STYLE_PRESET_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "style-presets")
os.makedirs(STYLE_PRESET_DIR, exist_ok=True)
COMIC_STYLE_PRESET_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "comic-style-presets")
os.makedirs(COMIC_STYLE_PRESET_DIR, exist_ok=True)
COMIC_SETTING_PRESET_DIR = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "character-setting-presets")
os.makedirs(COMIC_SETTING_PRESET_DIR, exist_ok=True)

DEFAULT_OPT = (
    "你是AI绘画/生成提示词优化专家。用户会给你一段提示词，或一个简单的想法。"
    "你负责把它改写得更具体、更完整、画面感更强、更适合AI绘图模型直接使用："
    "补全主体、外观、动作、服装、场景、光线、镜头、氛围和画质等要素。"
    "只输出优化后的一段中文提示词本身，不要解释、不要分点、不要加标题、不要英文、不要负面词。"
)

def _preset_model(name, model=None):
    model = str(model or ("anima" if "anima" in str(name).lower() else "krea2")).lower()
    if model not in ("krea2", "anima"):
        raise ValueError("不支持的预设模型")
    return model


def _preset_path(name, model=None):
    safe = "".join(c for c in str(name) if c not in '\\/:*?"<>|').strip() or "未命名"
    model = _preset_model(safe, model)
    scoped = os.path.join(PRESET_DIR, model, safe + ".txt")
    legacy = os.path.join(PRESET_DIR, safe + ".txt")
    if not os.path.isfile(scoped) and os.path.isfile(legacy) and _preset_model(safe) == model:
        return legacy, safe
    return scoped, safe

def load_presets():
    txts = [f for f in os.listdir(PRESET_DIR) if f.endswith(".txt")]
    if not txts:  # 首次运行，播下一个默认预设
        with open(os.path.join(PRESET_DIR, "通用提示词优化.txt"), "w", encoding="utf-8") as f:
            f.write(DEFAULT_OPT)
        txts = ["通用提示词优化.txt"]
    res = {}
    for f in sorted(txts):
        with open(os.path.join(PRESET_DIR, f), encoding="utf-8") as fh:
            model = _preset_model(f[:-4])
            res[(model, f[:-4])] = {"name": f[:-4], "system": fh.read(), "model": model}
    for model in ("krea2", "anima"):
        folder = os.path.join(PRESET_DIR, model)
        if os.path.isdir(folder):
            for f in sorted(os.listdir(folder)):
                if f.endswith(".txt"):
                    with open(os.path.join(folder, f), encoding="utf-8") as fh:
                        res[(model, f[:-4])] = {"name": f[:-4], "system": fh.read(), "model": model}
    # The Anima default has one source; saving it creates an editable model-local override.
    for name, filename in (("Anima·英文词组", "Anima_英文词组.txt"),
                           ("Anima·人设三视图＋面部特写", "Anima_人物三视图.txt")):
        default = os.path.join(str(_package_paths.ROOT), "presets", "instructions", filename)
        if ("anima", name) not in res and os.path.isfile(default):
            with open(default, encoding="utf-8") as fh:
                res[("anima", name)] = {"name": name, "system": fh.read(), "model": "anima", "builtin": True}
    return sorted(res.values(), key=lambda p: (p["model"], p["name"].lower()))

