VIDEO_SAVE_ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "视频提示词存档")


def video_save_next_dir():
    """返回下一个编号存档文件夹（001、002……），用于批量生成视频时按顺序读取。"""
    os.makedirs(VIDEO_SAVE_ROOT, exist_ok=True)
    nums = []
    for name in os.listdir(VIDEO_SAVE_ROOT):
        m = re.match(r"^(\d{3,})", name)
        if m:
            nums.append(int(m.group(1)))
    nxt = (max(nums) + 1) if nums else 1
    folder = os.path.join(VIDEO_SAVE_ROOT, "%03d" % nxt)
    os.makedirs(folder, exist_ok=True)
    return folder, "%03d" % nxt

