def load_comic_setting_presets():
    files = [f for f in os.listdir(COMIC_SETTING_PRESET_DIR) if f.endswith(".json")]
    if not files:
        for name, data in DEFAULT_COMIC_SETTING_PRESETS.items():
            path, _ = _comic_setting_preset_path(name)
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False, indent=2)
    res = []
    for f in sorted(os.listdir(COMIC_SETTING_PRESET_DIR)):
        if not f.endswith(".json"):
            continue
        try:
            data = json.load(open(os.path.join(COMIC_SETTING_PRESET_DIR, f), encoding="utf-8"))
            res.append({
                "name": f[:-5],
                "world": str(data.get("world") or ""),
                "characters": str(data.get("characters") or ""),
                "designDirection": str(data.get("designDirection") or ""),
            })
        except Exception:
            continue
    return res

# ================== ComfyUI 生图（复用用户自己的工作流） ==================
import time, random
from urllib.parse import urlencode
COMFY = "http://127.0.0.1:8188"
WF_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "krea2_workflow.json")

COMFY_DIR = _package_paths.get("comfy_dir")
COMFY_OUT = _package_paths.get("comfy_output") or os.path.join(COMFY_DIR, "ComfyUI", "output")
COMFY_START_LOG = os.path.join(COMFY_DIR, "ComfyUI", "user", "workbench_start_8188.log")
COMIC_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "漫画")
BOOK_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "漫画书")

def safe_name(s):
    return "".join(c for c in str(s) if c not in '\\/:*?"<>|').strip() or "未命名"

def panel_archive_file(archive_dir, archive_name):
    """返回漫画分格的安全归档路径，只允许落在 COMIC_DIR 下。"""
    dparts = [safe_name(x) for x in str(archive_dir or "").replace("\\", "/").split("/") if x]
    return os.path.join(COMIC_DIR, *dparts, safe_name(archive_name) + ".png")

def comfy_up():
    try:
        urllib.request.urlopen(COMFY + "/system_stats", timeout=1.5); return True
    except Exception:
        return False

def comfy_free():
    """让 ComfyUI 卸载显存里的模型（Krea2），给写作模型腾出显存。写作与出图不能共存于24G显存。"""
    try:
        body = json.dumps({"unload_models": True, "free_memory": True}).encode("utf-8")
        urllib.request.urlopen(urllib.request.Request(
            COMFY + "/free", data=body, headers={"Content-Type": "application/json"}), timeout=10)
        return True
    except Exception:
        return False

def comfy_kill():
    """彻底结束 ComfyUI 进程，给写作/视觉模型腾出显存；出图时会自动重启。"""
    try:
        import subprocess as _sp
        out = _sp.check_output(["netstat", "-ano"], timeout=8).decode(
            "utf-8", "replace")
        pid = None
        for line in out.splitlines():
            if ":8188" in line and "LISTENING" in line:
                parts = line.split()
                if len(parts) >= 5 and parts[-1].isdigit():
                    pid = int(parts[-1])
                    break
        if pid:
            _sp.run(["taskkill", "/F", "/PID", str(pid)], timeout=10,
                    capture_output=True)
            for _ in range(15):
                try:
                    urllib.request.urlopen(COMFY + "/system_stats", timeout=2)
                except Exception:
                    return True
                time.sleep(1)
        return True
    except Exception:
        return False

def comfy_stop_all():
    """中断当前 ComfyUI 任务、清空等待队列，再释放模型显存。"""
    if not comfy_up():
        return False
    headers = {"Content-Type": "application/json"}
    for endpoint, payload in (("/interrupt", {}), ("/queue", {"clear": True})):
        try:
            body = json.dumps(payload).encode("utf-8")
            urllib.request.urlopen(urllib.request.Request(
                COMFY + endpoint, data=body, headers=headers), timeout=8).read()
        except Exception:
            pass
    return comfy_free()

def comfy_start():
    """若 ComfyUI 未运行，用整合包的嵌入式 python 自动拉起来。
    注意：必须先把写作模型从显存卸掉，否则显存被占满时 ComfyUI 会启动失败。"""
    _local_model_guard()
    if comfy_up():
        return True
    if not COMFY_DIR or not os.path.isfile(os.path.join(COMFY_DIR, "python", "python.exe")):
        raise RuntimeError("请在 config.json 配置 comfy_dir，或先手动启动 ComfyUI（8188）。")
    try:
        if video_gen_core:
            video_gen_core.service_stop(kill=True)
    except Exception:
        pass
    try:
        ollama_unload()          # 先腾显存，否则 ComfyUI 起不来
        time.sleep(4)
    except Exception:
        pass
    import subprocess
    py = os.path.join(COMFY_DIR, "python", "python.exe")
    if not os.path.exists(py):
        return False
    try:
        log("⚙ ComfyUI 未运行，正在自动启动（约需半分钟）…")
        os.makedirs(os.path.dirname(COMFY_START_LOG), exist_ok=True)
        env = dict(os.environ)
        # rgthree 等插件会输出 emoji；隐藏的 GBK 控制台会因此抛 UnicodeEncodeError 并让进程退出。
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        args = [
            py, "-s", r"ComfyUI\main.py", "--port", "8188", "--disable-auto-launch",
            "--disable-all-custom-nodes", "--whitelist-custom-nodes",
            "ComfyUI-ConditioningKrea2Rebalance", "ComfyUI-Lora-Manager", "rgthree-comfy",
        ]
        with open(COMFY_START_LOG, "ab") as lf:
            subprocess.Popen(
                args, cwd=COMFY_DIR, env=env, stdout=lf, stderr=subprocess.STDOUT,
                creationflags=0x08000000)  # CREATE_NO_WINDOW
        return True
    except Exception as e:
        log("❌ ComfyUI 启动失败：" + str(e))
        return False

def comfy_ensure(timeout=90):
    """确保 ComfyUI API 真正开始监听，而不是只确认进程创建成功。"""
    if comfy_up():
        return True
    if not comfy_start():
        raise RuntimeError("ComfyUI 启动失败，请查看：" + COMFY_START_LOG)
    deadline = time.time() + max(10, int(timeout))
    while time.time() < deadline:
        if GEN_STOP.is_set():
            raise InterruptedError("生图任务已停止")
        time.sleep(2)
        if comfy_up():
            log("✅ Comfyui画图已就绪")
            return True
    raise RuntimeError(
        "ComfyUI 在 %d 秒内没有就绪，请查看启动日志：%s" % (timeout, COMFY_START_LOG)
    )

def comfy_capture():
    """抓取 ComfyUI 最近一次成功运行的工作流，存为模板。"""
    h = json.load(urllib.request.urlopen(COMFY + "/history?max_items=1", timeout=8))
    if not h:
        raise Exception("ComfyUI 历史为空：请先在 ComfyUI 手动出一张图，再抓取。")
    pid = list(h.keys())[-1]
    graph = h[pid]["prompt"][2]
    with open(WF_FILE, "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=False, indent=1)
    return graph

def _find_ksampler(graph):
    for nid, n in graph.items():
        if n.get("class_type") in ("KSampler", "KSamplerAdvanced", "SamplerCustom", "SamplerCustomAdvanced"):
            return nid, n
    return None, None

def _trace_positive(graph):
    """从 KSampler 的 positive 顺着找到那个 CLIPTextEncode 节点id。"""
    _, ks = _find_ksampler(graph)
    if not ks:
        return None
    ref = ks["inputs"].get("positive")
    seen = set()
    while isinstance(ref, list):
        tid = ref[0]
        if tid in seen:
            break
        seen.add(tid)
        node = graph.get(tid, {})
        if node.get("class_type") == "CLIPTextEncode":
            return tid
        nxt = None
        for v in node.get("inputs", {}).values():
            if isinstance(v, list):
                nxt = v; break
        ref = nxt
    return None

_OLLAMA_UNLOAD_TS = [0.0]
def ollama_unload():
    """释放旧版 Ollama 写作模型显存。现在写作/识图已统一为本地 Qwen3.6，
    这里只是切换任务前腾显存；5 秒内重复调用直接跳过，避免日志刷屏。"""
    now = time.time()
    if now - _OLLAMA_UNLOAD_TS[0] < 5:
        return
    _OLLAMA_UNLOAD_TS[0] = now
    try:
        log("💤 释放 Qwen3.6模型显存，准备切换任务…")
        body = json.dumps({"model": MODEL, "keep_alive": 0}).encode("utf-8")
        urllib.request.urlopen(urllib.request.Request(
            "http://localhost:11434/api/generate", data=body,
            headers={"Content-Type": "application/json"}), timeout=15)
    except Exception:
        pass

# 视频导演台统一显存管理：H3 启动时复用现有释放逻辑。
def _video_release_vision_models():
    try:
        qwen36_free()
    except Exception:
        pass
    try:
        qwen25_free()
    except Exception:
        pass
    # 兜底：无论进程句柄是否生效，直接按端口清掉本地视觉 llama-server，
    # 确保 H3 启动前显存真正释放（2026-08-15 实测钩子未清掉 8080 进程）。
    try:
        import subprocess as _sp
        out = _sp.check_output(["netstat", "-ano"], timeout=5).decode("latin1", "replace")
        for line in out.splitlines():
            if ("127.0.0.1:8080" in line or "127.0.0.1:8081" in line) and "LISTENING" in line:
                parts = line.strip().split()
                if parts and parts[-1].isdigit():
                    _sp.run(["taskkill", "/F", "/PID", parts[-1]], timeout=8,
                            capture_output=True)
    except Exception:
        pass

if video_gen_core:
    try:
        video_gen_core.configure_gpu_hooks(
            release_writer=ollama_unload,
            release_vision=_video_release_vision_models,
            stop_krea=comfy_kill,
        )
    except Exception as _video_hook_error:
        log("⚠ 视频导演台显存管理初始化失败：" + str(_video_hook_error))

# 每种格子对应的出图比例（贴合版面槽位，避免事后裁切毁构图）
# 三种格子保持各自版面比例，但总像素拉到相近(~0.9-1.0M)——否则“小格”生成阶段像素太少，
# 手部/伤口/五官更容易崩(评审第六条)。排版阶段再缩小，不在出图阶段就降像素。
PANEL_WH = {"大": (1152, 896), "中": (1344, 704), "小": (1600, 560),
            "页": (896, 1600), "整页": (896, 1600)}  # 竖版整页直出（一次一整页多格）
COMIC_PAGE_WH = {
    "standard": (896, 1600),
    # 比原版增加约28%像素；尺寸仍为64的倍数，兼顾24G显存和排字空间。
    "high": (1024, 1792),
}

def comic_page_wh(quality="high"):
    return COMIC_PAGE_WH.get(str(quality or "").lower(), COMIC_PAGE_WH["high"])

def _set_latent_size(graph, w, h):
    """把工作流里空latent的宽高改成目标尺寸。"""
    done = False
    for n in graph.values():
        ct = n.get("class_type", "")
        ins = n.get("inputs", {})
        if "EmptyLatent" in ct or ("Latent" in ct and "width" in ins and "height" in ins):
            if isinstance(ins.get("width"), (int, float)) and isinstance(ins.get("height"), (int, float)):
                ins["width"], ins["height"] = int(w), int(h); done = True
    if not done:      # 兜底：任何同时有数值 width/height 的节点
        for n in graph.values():
            ins = n.get("inputs", {})
            if isinstance(ins.get("width"), (int, float)) and isinstance(ins.get("height"), (int, float)):
                ins["width"], ins["height"] = int(w), int(h); done = True; break
    return done

def comfy_generate(prompt_text, seed=None, archive=None, wh=None, negative_prompt=None):
    from cores.age_policy import assert_model_request
    assert_model_request(prompt_text, media="image")
    if os.environ.get("V41_NO_MODEL"):
        raise RuntimeError("V41_NO_MODEL=1：零模型测试不许调模型（内嵌图片入口）")
    ollama_unload()   # 先腾显存
    try:
        qwen36_free()   # 出图前也释放本地视觉服务的显存
    except Exception:
        pass
    comfy_ensure()
    if not os.path.exists(WF_FILE):
        comfy_capture()
    graph = json.load(open(WF_FILE, encoding="utf-8"))
    pos = _trace_positive(graph)
    if pos:
        graph[pos]["inputs"]["text"] = prompt_text
    if negative_prompt:
        _, ks = _find_ksampler(graph)
        if ks:
            neg = ks["inputs"].get("negative")
            if isinstance(neg, list) and neg:
                neg_node = graph.get(str(neg[0]))
                if neg_node and neg_node.get("class_type") == "CLIPTextEncode":
                    neg_node["inputs"]["text"] = negative_prompt
    sd = int(seed) if seed not in (None, "") else random.randint(0, 2**31 - 1)
    nid, ks = _find_ksampler(graph)
    for key in ("seed", "noise_seed"):
        if ks and key in ks["inputs"]:
            v = ks["inputs"][key]
            if isinstance(v, list):
                graph[v[0]]["inputs"]["seed"] = sd
            else:
                ks["inputs"][key] = sd
    if wh:
        _set_latent_size(graph, wh[0], wh[1])
    for n in graph.values():
        if n.get("class_type") == "SaveImage":
            n["inputs"]["filename_prefix"] = "manhua_" + str(sd)
    log("🖼 提交 Krea2 出图，seed=%s 尺寸=%s" % (sd, ("%dx%d" % (wh[0], wh[1])) if wh else "默认"))
    set_activity("🖼 Krea2 出图", "seed=%s 尺寸=%s" % (sd, ("%dx%d" % (wh[0], wh[1])) if wh else "默认"))
    _calib_t0 = time.time()
    body = json.dumps({"prompt": graph}).encode("utf-8")
    req = urllib.request.Request(COMFY + "/prompt", data=body, headers={"Content-Type": "application/json"})
    pid = json.load(urllib.request.urlopen(req, timeout=20))["prompt_id"]
    auto_stop = globals().get("AUTO_JOB_STOP")
    try:
        _job_active = auto_job_snapshot().get("status") in ("running", "stopping")
    except Exception:
        _job_active = False
    try:
        for _ in range(900):
            # 只有后台全自动确实在运行时，AUTO_JOB_STOP 才用于中断出图；
            # 否则它可能是上次停止残留的信号，会误杀手动出图。
            if GEN_STOP.is_set() or (_job_active and auto_stop is not None and auto_stop.is_set()):
                raise InterruptedError("生图任务已停止")
            time.sleep(1)
            touch_activity("等待 Krea2 生成完成…")
            op_heartbeat("auto_job")
            op_heartbeat("vchar")
            if _ > 0 and _ % 60 == 0:
                log("⏳ Krea2 出图中，已等待 %d 秒…" % _)
            try:
                hh = json.load(urllib.request.urlopen(COMFY + "/history/" + pid, timeout=8))
            except Exception:
                continue
            if pid in hh:
                for o in hh[pid].get("outputs", {}).values():
                    if o.get("images"):
                        im = o["images"][0]
                        calib_record(_calib_key_for_wh(wh), time.time() - _calib_t0)
                        log("✅ 出图完成：" + im["filename"])
                        if archive:
                            try:
                                src = os.path.join(COMFY_OUT, im.get("subfolder", ""), im["filename"])
                                os.makedirs(os.path.dirname(archive), exist_ok=True)
                                shutil.copyfile(src, archive)
                                log("📁 已归档：" + archive)
                            except Exception as e:
                                log("⚠ 归档失败：%s" % e)
                        return COMFY + "/view?" + urlencode({
                            "filename": im["filename"], "subfolder": im.get("subfolder", ""),
                            "type": im.get("type", "output")})
                raise Exception("已完成但未找到输出图片")
        raise Exception("出图超时")
    finally:
        clear_activity()

def comfy_generate_page(prompt_text, seed=None, archive=None, quality="high"):
    """高清整页失败时自动回退标准尺寸，避免显存波动让整项任务中断。"""
    target = comic_page_wh(quality)
    try:
        return comfy_generate(prompt_text, seed, archive, target)
    except InterruptedError:
        raise
    except Exception as e:
        if target == COMIC_PAGE_WH["standard"]:
            raise
        log("⚠ 高清整页生成失败（%s），自动回退 896x1600 重试" % e)
        return comfy_generate(prompt_text, seed, archive, COMIC_PAGE_WH["standard"])

def _qwen36_fast_up():
    """快速检测本地写作/视觉模型是否在线（1.5秒超时，不阻塞状态轮询）。"""
    try:
        urllib.request.urlopen("http://127.0.0.1:8080/v1/models", timeout=1.5).close()
        return True
    except Exception:
        return False

WRITER_UP_CACHE = {"up": False, "ts": 0.0}
def _writer_up_cached():
    """模型正忙时健康检查可能瞬时超时；用 15 秒缓存避免状态灯乱闪成红色。"""
    now = time.time()
    try:
        up = _qwen36_fast_up()
    except Exception:
        up = False
    if up:
        WRITER_UP_CACHE.update({"up": True, "ts": now})
    elif now - WRITER_UP_CACHE.get("ts", 0) < 15 and WRITER_UP_CACHE.get("up"):
        return True
    else:
        WRITER_UP_CACHE.update({"up": False, "ts": now})
    return up


def build_status():
    st = {"ollama_up": False, "model_available": False, "available_models": [],
          "loaded": [], "comfy_up": comfy_up(),
          "comfy_queue": 0, "app_up": True,
          "writer_up": False, "vc_progress": dict(VC_PROGRESS), "summary": "",
          "activity": dict(ACTIVITY), "logUpdatedAt": (LOG[-1]["ts"] if LOG else 0),
          "now": time.time()}
    writer_up = _writer_up_cached()
    st["writer_up"] = writer_up
    st["model_available"] = writer_up
    try:
        names = ollama_model_names(timeout=1)
        st["ollama_up"] = True
        st["available_models"] = names
        if not writer_up:
            st["model_available"] = ollama_has_writer(names)
        ps = json.load(urllib.request.urlopen("http://localhost:11434/api/ps", timeout=1))
        for m in ps.get("models", []):
            st["loaded"].append({
                "name": m.get("name", ""),
                "vram": round(m.get("size_vram", 0) / 1024 / 1024 / 1024, 1)})
    except Exception:
        pass
    if st["comfy_up"]:
        try:
            q = json.load(urllib.request.urlopen(COMFY + "/queue", timeout=1.5))
            st["comfy_queue"] = len(q.get("queue_running", [])) + len(q.get("queue_pending", []))
        except Exception:
            pass
    vp = st["vc_progress"]
    if vp.get("active"):
        total = max(1, int(vp.get("total") or 1))
        done = int(vp.get("done") or 0)
        now = time.time()
        el = int(now - float(vp.get("start") or now))
        item_el = int(now - float(vp.get("itemStart") or vp.get("start") or now))
        used = "%d分%d秒" % (el // 60, el % 60) if el >= 60 else "%d秒" % el
        item_used = "%d分%d秒" % (item_el // 60, item_el % 60) if item_el >= 60 else "%d秒" % item_el
        cur = str(vp.get("current") or "").strip()
        slow = ""
        if item_el > 240:
            slow = " ⚠已超过通常耗时"
        elif item_el > 150:
            slow = "（偏慢）"
        typical = calib_avg("krea2_896x1600", 90)
        typ_txt = "%d分%d秒" % (int(typical) // 60, int(typical) % 60) if typical >= 60 else "%d秒" % int(typical)
        if total > 1:
            avg = (el / max(1, done)) if done > 0 else typical
            if done == 1:
                avg = avg * 0.5 + typical * 0.5
            remain = max(1, total - done)
            eta_s = int(avg * remain)
            eta = "%d分%d秒" % (eta_s // 60, eta_s % 60) if eta_s >= 60 else "%d秒" % eta_s
            st["summary"] = "配图 第%d/%d张 · 已用%s · 本张%s · 预计还需%s%s" % (
                min(done + 1, total), total, used, item_used, eta, slow)
        else:
            st["summary"] = "配图生成中 · 已用%s · 本张%s（通常约%s）%s" % (used, item_used, typ_txt, slow)
        if cur:
            st["summary"] += " · " + cur
    elif st["comfy_queue"]:
        st["summary"] = "Comfyui画图工作中，还有 %d 张排队" % st["comfy_queue"]
    elif not st["comfy_up"]:
        st["summary"] = "Comfyui画图未启动，正在自动启动（约半分钟）"
    elif not st["model_available"]:
        st["summary"] = "Qwen3.6模型未启动，正在自动启动（首次约1-2分钟）"
    else:
        st["summary"] = "一切就绪，空闲中"
    return st

# ================== 漫画书 PDF 合成（小说原文 + 漫画图+对白字幕） ==================
def _font(size, bold=False):
    from PIL import ImageFont
    for p in ([r"C:\Windows\Fonts\msyhbd.ttc"] if bold else [r"C:\Windows\Fonts\msyh.ttc"]) + [r"C:\Windows\Fonts\simhei.ttf"]:
        try:
            return ImageFont.truetype(p, size)
        except Exception:
            continue
    from PIL import ImageFont as _f
    return _f.load_default()

def _wrap(draw, text, font, max_w):
    lines = []
    for para in text.split("\n"):
        if not para.strip():
            lines.append(""); continue
        cur = ""
        for ch in para:
            if draw.textlength(cur + ch, font=font) <= max_w:
                cur += ch
            else:
                lines.append(cur); cur = ch
        lines.append(cur)
    return lines

INK   = (34, 30, 24)
BROWN = (138, 90, 43)
CREAM = (250, 246, 238)

def _footer(d, W, H, M, txt):
    d.text((W / 2, H - M / 2), txt, font=_font(22), fill=(170, 160, 145), anchor="mm")

def _build_book_pages(title, novel_text, panels, include_cover=True):
    """构建漫画书的每一页（PIL Image 列表），供 PDF 合成或预览用。"""
    from PIL import Image, ImageDraw
    W, H = 1240, 1754            # A4 竖版 @150dpi
    M = 96                       # 页边距
    tmp = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    imgs = [p for p in panels if os.path.exists(p.get("path", ""))]
    total = len(imgs)
    pages = []
    if not include_cover:
        return _build_book_body(novel_text, imgs, W, H, M, tmp)

    # ---------- 封面 ----------
    cover = Image.new("RGB", (W, H), CREAM); d = ImageDraw.Draw(cover)
    d.rectangle([40, 40, W - 40, H - 40], outline=BROWN, width=3)
    d.rectangle([52, 52, W - 52, H - 52], outline=(220, 205, 180), width=1)
    tlines = _wrap(tmp, title, _font(64, True), W - 2 * M - 60)
    ty = 300
    for ln in tlines:
        d.text((W / 2, ty), ln, font=_font(64, True), fill=INK, anchor="mm"); ty += 92
    d.line([(W / 2 - 120, ty + 20), (W / 2 + 120, ty + 20)], fill=BROWN, width=3)
    d.text((W / 2, ty + 70), "AI 漫画书", font=_font(30), fill=BROWN, anchor="mm")
    # 封面配图：第一格缩略图，带相框
    if imgs:
        try:
            th = Image.open(imgs[0]["path"]).convert("RGB")
            box_w, box_h = W - 2 * M - 120, 640          # 完整放入相框，不裁切
            sc = min(box_w / th.size[0], box_h / th.size[1])
            th = th.resize((int(th.size[0] * sc), int(th.size[1] * sc)))
            fx, fy = (W - th.size[0]) // 2, ty + 130
            d.rectangle([fx - 8, fy - 8, fx + th.size[0] + 8, fy + th.size[1] + 8], fill="white", outline=BROWN, width=3)
            cover.paste(th, (fx, fy))
        except Exception:
            pass
    d.text((W / 2, H - 130), time.strftime("%Y-%m-%d"), font=_font(24), fill=(170, 160, 145), anchor="mm")
    pages.append(cover)
    pages += _build_book_body(novel_text, imgs, W, H, M, tmp)
    return pages

def _build_book_body(novel_text, imgs, W, H, M, tmp):
    """正文页：小说段 与 漫画页 交替。返回页面列表（不含封面）。"""
    from PIL import Image, ImageDraw
    import re as _re
    total = len(imgs)
    pages = []
    def text_pages(text, heading):
        res = []; bf, hf, lh = _font(33), _font(40, True), 54
        page = Image.new("RGB", (W, H), "white"); dd = ImageDraw.Draw(page); y = M
        if heading:
            dd.text((M, y), heading, font=hf, fill=BROWN); y += 16
            dd.line([(M, y + 40), (W - M, y + 40)], fill=(228, 220, 205), width=2); y += 70
        for ln in _wrap(tmp, text.strip(), bf, W - 2 * M):
            if y > H - M - 30:
                _footer(dd, W, H, M, heading); res.append(page)
                page = Image.new("RGB", (W, H), "white"); dd = ImageDraw.Draw(page); y = M
            dd.text((M, y), ln, font=bf, fill=INK); y += lh
        _footer(dd, W, H, M, heading); res.append(page)
        return res
    def comic_page(p, idx):
        im = Image.open(p["path"]).convert("RGB")
        page = Image.new("RGB", (W, H), (247, 244, 238)); d = ImageDraw.Draw(page)
        dlg = (p.get("dialog") or "").strip()
        has_cap = dlg and dlg not in ("无", "（无）")
        cap_font = _font(36, True)
        cap_lines = _wrap(tmp, dlg, cap_font, W - 2 * M - 80) if has_cap else []
        cap_h = (len(cap_lines) * 50 + 52) if has_cap else 0
        avail_h = H - 2 * M - cap_h - (40 if has_cap else 0)
        iw, ih = im.size
        scale = min((W - 2 * M) / iw, avail_h / ih)
        nw, nh = int(iw * scale), int(ih * scale)
        im = im.resize((nw, nh))
        ox, oy = (W - nw) // 2, M
        d.rectangle([ox - 4, oy - 4, ox + nw + 4, oy + nh + 4], fill="white", outline=(60, 55, 48), width=3)
        page.paste(im, (ox, oy))
        if has_cap:
            bx0, by0 = M, oy + nh + 24
            bx1, by1 = W - M, by0 + cap_h
            d.rounded_rectangle([bx0, by0, bx1, by1], radius=20, fill=(28, 24, 20))
            d.rounded_rectangle([bx0 + 4, by0 + 4, bx1 - 4, by1 - 4], radius=16, outline=(120, 95, 60), width=2)
            ty = by0 + 26
            for ln in cap_lines:
                d.text((W / 2, ty), ln, font=cap_font, fill="white", anchor="ma"); ty += 50
        _footer(d, W, H, M, "%d / %d" % (idx, total))
        return page
    novel = (novel_text or "").strip()
    segs = []
    if novel and imgs:
        sents = _re.findall(r'[^。！？!?\n]*[。！？!?\n]', novel) or [novel]
        n = len(imgs)
        if len(sents) <= n:
            segs = ["".join([x]) for x in sents] + [""] * (n - len(sents))
        else:
            per = len(sents) / n
            segs = ["".join(sents[int(round(i * per)):int(round((i + 1) * per))]) for i in range(n)]
    for i, p in enumerate(imgs):
        seg = segs[i] if i < len(segs) else ""
        if seg.strip():
            pages += text_pages(seg, "第 %d 段" % (i + 1))
        try:
            pages.append(comic_page(p, i + 1))
        except Exception:
            pass
    if not imgs and novel:
        pages += text_pages(novel, "原文")
    return pages

def _chapter_divider(chap_title):
    from PIL import Image, ImageDraw
    W, H = 1240, 1754
    page = Image.new("RGB", (W, H), CREAM); d = ImageDraw.Draw(page)
    d.line([(140, H/2 - 90), (W - 140, H/2 - 90)], fill=BROWN, width=2)
    for i, ln in enumerate(_wrap(ImageDraw.Draw(Image.new("RGB",(9,9))), chap_title, _font(54, True), W - 300)):
        d.text((W/2, H/2 - 10 + i*76), ln, font=_font(54, True), fill=INK, anchor="mm")
    d.line([(140, H/2 + 90), (W - 140, H/2 + 90)], fill=BROWN, width=2)
    return page

def make_full_book(book_title, chapters, project=None):
    """chapters: [{'name':章名, 'novel_text':正文, 'panels':[{'path','dialog'}]}] → 合并成一本完整 PDF。"""
    from PIL import Image, ImageDraw
    W, H = 1240, 1754; M = 96
    tmp = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    # 总封面（用第一章第一张图）
    first_imgs = []
    for ch in chapters:
        first_imgs = [p for p in ch.get("panels", []) if os.path.exists(p.get("path", ""))]
        if first_imgs:
            break
    cover = Image.new("RGB", (W, H), CREAM); d = ImageDraw.Draw(cover)
    d.rectangle([40, 40, W - 40, H - 40], outline=BROWN, width=3)
    d.rectangle([52, 52, W - 52, H - 52], outline=(220, 205, 180), width=1)
    ty = 300
    for ln in _wrap(tmp, book_title, _font(64, True), W - 2 * M - 60):
        d.text((W / 2, ty), ln, font=_font(64, True), fill=INK, anchor="mm"); ty += 92
    d.line([(W/2-120, ty+20), (W/2+120, ty+20)], fill=BROWN, width=3)
    d.text((W / 2, ty + 70), "AI 小说 · 漫画合集", font=_font(30), fill=BROWN, anchor="mm")
    if first_imgs:
        try:
            th = Image.open(first_imgs[0]["path"]).convert("RGB")
            bw, bh = W - 2*M - 120, 640; sc = min(bw/th.size[0], bh/th.size[1])
            th = th.resize((int(th.size[0]*sc), int(th.size[1]*sc)))
            fx, fy = (W - th.size[0])//2, ty + 130
            d.rectangle([fx-8, fy-8, fx+th.size[0]+8, fy+th.size[1]+8], fill="white", outline=BROWN, width=3)
            cover.paste(th, (fx, fy))
        except Exception: pass
    d.text((W/2, H-130), time.strftime("%Y-%m-%d"), font=_font(24), fill=(170,160,145), anchor="mm")
    pages = [cover]
    pages += _build_front_matter_pages(project or {}, W, H)
    for idx, ch in enumerate(chapters, 1):
        imgs = [p for p in ch.get("panels", []) if os.path.exists(p.get("path", ""))]
        pages.append(_chapter_divider("第%d章 %s" % (idx, ch.get("name", ""))))
        pages += _build_book_body(ch.get("novel_text", ""), imgs, W, H, M, tmp)
    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(BOOK_DIR, safe_name(book_title) + "（全）.pdf")
    pages[0].save(out, "PDF", save_all=True, append_images=pages[1:], resolution=150.0)
    log("📚 合并全本已生成：" + out)
    return out

PAGE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "漫画页")
SIZE_W = {"大": 0.46, "中": 0.30, "小": 0.20}

def _fit_crop(im, w, h):
    """缩放并裁切到正好 w×h。纵向偏上裁（人脸多在上半部，避免把头切掉）。"""
    iw, ih = im.size
    sc = max(w / iw, h / ih)
    nw, nh = max(1, int(iw * sc)), max(1, int(ih * sc))
    im = im.resize((nw, nh))
    x = (nw - w) // 2
    y = int((nh - h) * 0.22)          # 偏上，保住头部
    return im.crop((x, y, x + w, y + h))

def _group_pages(panels, max_per_page=4):
    """按大小权重把分镜分页：一页最多4格，权重和不超过1。"""
    pages, cur, wsum = [], [], 0.0
    for p in panels:
        w = SIZE_W.get(p.get("size", "中"), 0.30)
        if cur and (len(cur) >= max_per_page or wsum + w > 1.02):
            pages.append(cur); cur, wsum = [], 0.0
        cur.append(p); wsum += w
    if cur:
        pages.append(cur)
    return pages

def _build_rows(page_panels):
    """行布局：默认整行一格；连续两个『小』并排一行。"""
    rows, i = [], 0
    while i < len(page_panels):
        p = page_panels[i]
        if (p.get("size") == "小" and i + 1 < len(page_panels)
                and page_panels[i + 1].get("size") == "小"):
            rows.append([p, page_panels[i + 1]]); i += 2
        else:
            rows.append([p]); i += 1
    return rows

def compose_manga_pages(panels, out_dir, title=""):
    """把已出好的分格图，按大中小排版合成竖屏漫画页(1080×1920)。返回页面文件路径列表。"""
    from PIL import Image, ImageDraw
    W, H = 1080, 1920
    M, G = 28, 14                      # 外边距 / 格间距
    imgs = [p for p in panels if os.path.exists(p.get("path", ""))]
    if not imgs:
        return []
    os.makedirs(out_dir, exist_ok=True)
    tmp = ImageDraw.Draw(Image.new("RGB", (9, 9)))
    outs = []
    for pi, page_panels in enumerate(_group_pages(imgs), 1):
        page = Image.new("RGB", (W, H), "white")
        d = ImageDraw.Draw(page)
        rows = _build_rows(page_panels)
        weights = [max(SIZE_W.get(q.get("size", "中"), 0.30) for q in r) for r in rows]
        tot = sum(weights) or 1
        avail_h = H - 2 * M - G * (len(rows) - 1)
        y = M
        for r, wt in zip(rows, weights):
            rh = int(avail_h * wt / tot)
            n = len(r)
            cw = (W - 2 * M - G * (n - 1)) // n
            x = M
            for q in r:
                try:
                    im = Image.open(q["path"]).convert("RGB")
                except Exception:
                    x += cw + G; continue
                im = _fit_crop(im, cw, rh)
                page.paste(im, (x, y))
                d.rectangle([x, y, x + cw - 1, y + rh - 1], outline=(20, 18, 16), width=3)
                # 旁白：左上白框
                nar = (q.get("narration") or "").strip()
                if nar:
                    f = _font(26)
                    lines = _wrap(tmp, nar, f, cw - 60)[:3]
                    bh = len(lines) * 34 + 18
                    d.rectangle([x + 10, y + 10, x + cw - 10, y + 10 + bh], fill="white", outline=(20, 18, 16), width=2)
                    ty = y + 18
                    for ln in lines:
                        d.text((x + 22, ty), ln, font=f, fill=(20, 18, 16)); ty += 34
                # 对白：底部白框（只放真台词，避免和上面的旁白重复）
                dlg = (q.get("speech") or "").strip()
                if dlg and dlg != nar:
                    f = _font(30, True)
                    lines = _wrap(tmp, dlg, f, cw - 70)[:3]
                    bh = len(lines) * 38 + 20
                    by = y + rh - bh - 12
                    d.rounded_rectangle([x + 14, by, x + cw - 14, by + bh], radius=14,
                                        fill="white", outline=(20, 18, 16), width=3)
                    ty = by + 10
                    for ln in lines:
                        d.text((x + cw / 2, ty), ln, font=f, fill=(20, 18, 16), anchor="ma"); ty += 38
                x += cw + G
            y += rh + G
        fp = os.path.join(out_dir, "第%02d页.png" % pi)
        page.save(fp)
        outs.append(fp)
    log("📄 漫画页已合成：%d 页 → %s" % (len(outs), out_dir))
    return outs

def make_comic_book(title, novel_text, panels, project=None):
    """panels: [{'path': 绝对png路径, 'dialog': 对白}]，返回生成的 PDF 路径。做成一本排版精致的漫画书。"""
    body_pages = _build_book_pages(title, novel_text, panels)
    front_pages = _build_front_matter_pages(project or {})
    pages = ([body_pages[0]] + front_pages + body_pages[1:]) if body_pages else front_pages
    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(BOOK_DIR, safe_name(title) + ".pdf")
    pages[0].save(out, "PDF", save_all=True, append_images=pages[1:], resolution=150.0)
    log("📚 漫画书已生成：" + out)
    return out

