def project_path(name):
    safe = "".join(c for c in name if c not in '\\/:*?"<>|').strip() or "未命名"
    return os.path.join(DATA_DIR, safe + ".json"), safe

AUTO_JOB_STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "auto_job_state.json")
QUICK_COMIC_STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "quick_comic_state.json")
CREATIVE_STATE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "creative_state.json")
AUTO_JOB_LOCK = threading.Lock()
QUICK_COMIC_LOCK = threading.Lock()
CREATIVE_LOCK = threading.Lock()
AUTO_JOB_STOP = threading.Event()
AUTO_JOB = {
    "status": "idle", "project": "", "stage": "", "message": "暂无后台任务",
    "progress": 0, "current": 0, "total": 0, "pdfUrl": "", "error": "",
    "updatedAt": time.time(),
}

def atomic_write_json(path, data):
    """同目录临时文件 + 原子替换，断电或并发读取时不会留下半截 JSON。"""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp.%s" % threading.get_ident()
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except Exception: pass

def save_project_atomic(project):
    p, safe = project_path(project.get("title", "未命名"))
    atomic_write_json(p, project)
    return p, safe

def load_quick_comic_state():
    with QUICK_COMIC_LOCK:
        try:
            if os.path.exists(QUICK_COMIC_STATE_FILE):
                with open(QUICK_COMIC_STATE_FILE, encoding="utf-8") as f:
                    data = json.load(f)
                    return data if isinstance(data, dict) else {}
        except Exception:
            pass
    return {}

def save_quick_comic_state(**updates):
    with QUICK_COMIC_LOCK:
        state = {}
        try:
            if os.path.exists(QUICK_COMIC_STATE_FILE):
                with open(QUICK_COMIC_STATE_FILE, encoding="utf-8") as f:
                    old = json.load(f)
                    if isinstance(old, dict):
                        state.update(old)
        except Exception:
            pass
        state.update(updates)
        state["updatedAt"] = time.time()
        atomic_write_json(QUICK_COMIC_STATE_FILE, state)
        return dict(state)

