def _save_auto_job_state(snapshot):
    try:
        atomic_write_json(AUTO_JOB_STATE_FILE, snapshot)
    except Exception as e:
        log("⚠ 后台任务状态保存失败：%s" % e)

def set_auto_job(**updates):
    with AUTO_JOB_LOCK:
        AUTO_JOB.update(updates)
        AUTO_JOB["updatedAt"] = time.time()
        snapshot = dict(AUTO_JOB)
    _save_auto_job_state(snapshot)
    # 同步到统一进度中心，网页进度条直接读这里
    st = snapshot.get("status")
    if st in ("running", "stopping"):
        op_ensure("auto_job", snapshot.get("message") or "后台任务",
                  total=int(snapshot.get("total") or 0),
                  detail=snapshot.get("message") or "")
        op_update("auto_job",
                  done=int(snapshot.get("current") or 0),
                  total=int(snapshot.get("total") or 0),
                  detail=snapshot.get("message") or "",
                  status=st,
                  percent=float(snapshot.get("progress") or 0),
                  label=snapshot.get("message") or "后台任务")
    elif st == "complete":
        op_end("auto_job", "complete", snapshot.get("message") or "")
    elif st in ("paused", "error"):
        op_end("auto_job", st, snapshot.get("message") or "")
    return snapshot

def auto_job_snapshot():
    with AUTO_JOB_LOCK:
        return dict(AUTO_JOB)

def restore_auto_job_snapshot(snapshot):
    if not isinstance(snapshot, dict):
        return
    with AUTO_JOB_LOCK:
        AUTO_JOB.clear()
        AUTO_JOB.update(snapshot)
        current = dict(AUTO_JOB)
    _save_auto_job_state(current)

def _restore_auto_job_state():
    if not os.path.exists(AUTO_JOB_STATE_FILE):
        return
    try:
        old = json.load(open(AUTO_JOB_STATE_FILE, encoding="utf-8"))
        if isinstance(old, dict):
            AUTO_JOB.update(old)
            if AUTO_JOB.get("status") in ("running", "stopping"):
                AUTO_JOB["status"] = "paused"
                AUTO_JOB["message"] = "服务曾重启，进度已保存；点击“继续上次任务”即可恢复"
                AUTO_JOB["error"] = ""
            elif AUTO_JOB.get("status") == "complete" and AUTO_JOB.get("stage") != "complete":
                AUTO_JOB["stage"] = "complete"
                AUTO_JOB["message"] = "✅ 后台任务已完成"
            AUTO_JOB["updatedAt"] = time.time()
    except Exception:
        pass

_restore_auto_job_state()

class AutoJobStopped(Exception):
    pass

def _auto_check_stop():
    if AUTO_JOB_STOP.is_set():
        raise AutoJobStopped()

def _auto_retry(label, fn, attempts=3, delay=2):
    last = None
    for attempt in range(1, attempts + 1):
        _auto_check_stop()
        try:
            return fn()
        except AutoJobStopped:
            raise
        except Exception as e:
            last = e
            if attempt < attempts:
                log("⚠ %s失败（%d/%d）：%s；稍后重试" % (label, attempt, attempts, e))
                set_auto_job(message="%s失败，正在第 %d 次重试…" % (label, attempt + 1))
                for _ in range(max(1, delay * attempt * 2)):
                    _auto_check_stop()
                    time.sleep(0.5)
    raise last or RuntimeError(label + "失败")

def _comic_art_key(art):
    return hashlib.sha256(_norm_art(art).encode("utf-8")).hexdigest()[:20]

def _lock_project_comic_style(project, config, resume=False):
    """新任务保存项目级画风；断点续做必须沿用该画风，不能被全局设置临时改变。"""
    requested = _norm_art((config or {}).get("art"))
    locked = str((project or {}).get("comicStyle") or "").strip()
    art = _norm_art(locked) if resume and locked else requested
    project["comicStyle"] = art
    project["comicStyleKey"] = _comic_art_key(art)
    if (config or {}).get("comicStyleName"):
        project["comicStyleName"] = str(config.get("comicStyleName") or "").strip()
    config["art"] = art
    return art

def _complete_missing_chapters(project, chapters, length, novel_rules):
    """先把所有正文补齐，再做全书人物扫描和漫画，避免后登场角色漏进设定卡。"""
    total = max(1, len(chapters))
    written = 0
    for i, chapter in enumerate(chapters):
        _auto_check_stop()
        content = str(chapter.get("content") or "")
        incomplete = bool(chapter.get("autoIncomplete"))
        if content.strip() and not incomplete:
            continue
        chap = chapter.get("title") or ("第%d章" % (i + 1))
        set_auto_job(
            stage="writing", current=i + 1, total=len(chapters),
            progress=0.12 * i / total,
            message="✍ 先补齐小说：第%d/%d章《%s》写作中…" %
                    (i + 1, len(chapters), chap))
        mode = "continue" if content.strip() else "new"
        chapter.setdefault("characterStateBefore", str(project.get("bible") or ""))
        msgs, num_predict = build_messages(
            project, mode, chapter.get("brief", ""), content, length, novel_rules)
        generated = chat_stream(msgs, 0.8, None, num_predict)
        if AUTO_JOB_STOP.is_set():
            partial = content + generated if mode == "continue" else generated
            if partial.strip():
                chapter["content"] = partial
                chapter["autoIncomplete"] = True
                save_project_atomic(project)
            raise AutoJobStopped()
        content = content + generated if mode == "continue" else generated
        if not content.strip():
            raise RuntimeError("第%d章没有生成正文" % (i + 1))
        chapter["content"] = content
        chapter["savedAt"] = time.time() * 1000
        chapter.pop("autoIncomplete", None)
        save_project_atomic(project)
        written += 1
        try:
            chapter["summary"] = _auto_retry(
                "第%d章摘要" % (i + 1), lambda t=content: summarize(t), 2, 1).strip()
            save_project_atomic(project)
        except Exception as e:
            log("⚠ 第%d章摘要失败，正文已保存：%s" % (i + 1, e))
        _auto_check_stop()
        try:
            project["bible"] = _auto_retry(
                "第%d章角色状态" % (i + 1),
                lambda t=content: update_bible(project.get("bible", ""), t), 2, 1
            ).strip() or project.get("bible", "")
            chapter["characterState"] = project["bible"]
            save_project_atomic(project)
        except Exception as e:
            log("⚠ 第%d章角色状态更新失败，继续执行：%s" % (i + 1, e))
    if written:
        log("✅ 小说正文已先补齐：新增/续写 %d 章，开始扫描全书人物" % written)
    return written

def _character_names_from_project(project):
    import re as _re
    names = set(parse_char_sheet(str(project.get("charSheet") or "")).keys())
    for raw in str(project.get("chars") or "").splitlines():
        line = _re.sub(r'^\s*\d+\s*[.、]\s*', '', raw).strip()
        if not line:
            continue
        name = _re.split(r'[｜|—–\-:：]', line, 1)[0].strip()
        if 1 <= len(name) <= 24:
            names.add(name)
    return names

def _same_character_name(a, b):
    a = str(a or "").strip()
    b = str(b or "").strip()
    if not a or not b:
        return False
    if a == b:
        return True
    # 兼容“凯尔”与“凯尔·维斯”这类正文简称；单字姓氏不用于模糊匹配。
    return min(len(a), len(b)) >= 2 and (a in b or b in a)

def _looks_like_named_character(name):
    """拒绝把“瘦高个A、主考官、女法师”一类临时称呼升级成长期角色。"""
    import re as _re
    name = str(name or "").strip()
    if not (2 <= len(name) <= 16) or _re.search(r'[A-Za-z0-9]', name):
        return False
    generic = {
        "大汉", "壮汉", "独眼大汉", "瘦高个", "胖子", "瘦子", "老头", "瘦削老头",
        "老人", "老者", "男人", "男子", "女人", "女子", "少年", "少女", "孩子",
        "主考官", "考官", "导师", "院长", "女法师", "男法师", "法师", "学徒",
        "守卫", "卫兵", "士兵", "骑士", "队长", "店主", "老板", "侍者", "伙计",
        "流氓", "佣兵", "刺客", "黑衣人", "蒙面人", "路人", "村民", "贵族",
    }
    return name not in generic

def discover_chapter_characters(chapter_text, known_names, art,
                                world_visual_profile=None):
    """从一章正文提取尚未建档、且正文明确点名的人物外观卡。"""
    known = "、".join(sorted(known_names)) or "无"
    system = (
        "你是长篇漫画的人物连续性编辑。阅读一章小说，找出正文中【明确写出姓名】、"
        "但不在已有名单里的新人物，为其建立稳定的画图外观卡。只收录真正参与剧情的人物；"
        "排除无姓名的路人、守卫、人群、动物、组织、地点和物品；“独眼大汉、瘦高个A、主考官、"
        "女法师、老头”等外貌称呼或职业称呼都不算姓名，绝对不要输出。姓名必须逐字出现在正文。"
        "每人一行，严格格式：姓名—性别与年龄段；脸型五官；发型发色；正常可信的肤色体型体态；"
        "完整上装；完整下装；鞋靴；必要外层服装；最多一处固定疤痕或配饰；"
        "正文明确存在且长期使用的固定道具。人物服装、材料和道具必须符合给定的世界视觉基准。"
        "正文没写清的普通细节可根据时代与身份补成一套克制、可长期复用的设计，但不得改动原文明示事实。"
        "当前伤势、血污、破损、临时变身、当前手持物和某章换装不进入固定卡。"
        "不同人物的轮廓、主色、体态与标志物必须明显区分。没有新人物只输出：无。不要编号、不要解释。"
    )
    user = (
        "【当前全书画风】\n" + _norm_art(art) +
        "\n\n【题材与世界视觉基准】\n" + _profile_text(world_visual_profile) +
        "\n\n【已有角色，禁止重复】\n" + known +
        "\n\n【本章正文】\n" + str(chapter_text or "").strip()[:6500]
    )
    raw = chat_stream(
        [{"role": "system", "content": system}, {"role": "user", "content": user}],
        0.25, None, 1200).strip()
    if raw in ("无", "（无）", "none", "None"):
        return {}
    parsed = parse_char_sheet(raw)
    source = str(chapter_text or "")
    clean = {}
    for name, desc in parsed.items():
        name = str(name or "").strip()
        desc = str(desc or "").strip()
        already_known = any(_same_character_name(name, old) for old in known_names)
        if (name and desc and name in source and not already_known
                and _looks_like_named_character(name)
                and 1 <= len(name) <= 24 and len(clean) < 8):
            clean[name] = desc
    return clean

def sync_project_characters(project, art):
    """扫描所有已完成章节；只重扫正文发生变化的章节，并把新人物补进设定与角色卡。"""
    chapters = project.get("chapters") or []
    scan = project.get("characterScan")
    if not isinstance(scan, dict):
        scan = {}
    known = _character_names_from_project(project)
    additions = {}
    for i, chapter in enumerate(chapters):
        _auto_check_stop()
        content = str(chapter.get("content") or "").strip()
        if not content or chapter.get("autoIncomplete"):
            continue
        digest = hashlib.sha256(content.encode("utf-8")).hexdigest()[:20]
        if scan.get(str(i)) == digest:
            continue
        set_auto_job(
            stage="characters", current=i + 1, total=len(chapters),
            message="🧍 扫描章节人物 %d/%d…" % (i + 1, len(chapters)))
        found = _auto_retry(
            "第%d章人物扫描" % (i + 1),
            lambda t=content, n=set(known): discover_chapter_characters(
                t, n, art, project.get("world_visual_profile")),
            2, 1)
        for name, desc in found.items():
            if name not in known:
                additions[name] = desc
                known.add(name)
        scan[str(i)] = digest
    project["characterScan"] = scan
    if additions:
        old_sheet = str(project.get("charSheet") or "").strip()
        new_lines = ["%s—%s" % (name, desc) for name, desc in additions.items()]
        project["charSheet"] = "\n".join(x for x in (old_sheet, "\n".join(new_lines)) if x)
        profiles = project.get("character_profiles")
        if not isinstance(profiles, list):
            profiles = []
        for added_index, (name, desc) in enumerate(additions.items(), len(profiles)):
            state = "present" if any(word in desc for word in _PROP_KW) else "unset"
            profiles.append({
                "name": name,
                "character_id": _character_id(
                    name, project.get("premise") or project.get("title") or "", added_index),
                "version": 1,
                "story_profile": {
                    "raw": _profile_value("章节新增人物", "chapter_state", False),
                    "explicitFacts": _profile_value(name, "chapter_state", True),
                },
                "visual_profile": {
                    "manualRaw": _profile_value(desc, "world_derived", False),
                },
                "visual_policy": _default_visual_policy(
                    added_index, project.get("world_visual_profile"),
                    desc, project.get("premise") or ""),
                "propState": _profile_value(
                    state, "world_derived" if state == "present" else "ai_optional", False),
                "assembledCard": name + "—" + desc,
                "generation_state": {
                    "profileVersion": 1,
                    "assetVersion": 0,
                    "worldProfileVersion": int(
                        (project.get("world_visual_profile") or {}).get("version") or 1),
                    "masterStatus": "pending",
                },
            })
        project["character_profiles"] = profiles
        old_chars = str(project.get("chars") or "").strip()
        start = len([x for x in old_chars.splitlines() if x.strip()]) + 1
        supplement = [
            "%d. %s｜章节新增人物｜%s" % (start + j, name, desc)
            for j, (name, desc) in enumerate(additions.items())
        ]
        project["chars"] = "\n".join(x for x in (old_chars, "\n".join(supplement)) if x)
        save_project_atomic(project)
        log("✅ 已从完整小说补齐 %d 位章节人物：%s" %
            (len(additions), "、".join(additions.keys())))
    else:
        save_project_atomic(project)
        log("✅ 全书章节人物扫描完成，没有遗漏的新人物")
    return additions

CHARACTER_MAIN_PROMPT_VERSION = "character_asset_v4"
CHARACTER_PRODUCTION_PROMPT_VERSION = "character_production_v2"
ACTUAL_PROP_WORDS = (
    "剑", "刀", "枪", "弓", "弩", "斧", "锤", "盾", "法杖", "魔杖",
    "书", "卷轴", "扇", "提篮", "手杖", "权杖", "面具", "机械臂", "义肢",
)

def _positive_prompt_fragments(text):
    import re as _re
    bad = (
        "不要", "不得", "禁止", "避免", "不能", "没有", "无需", "不出现",
        "不包含", "无武器", "无枪", "无刀", "无道具", "无场景", "无文字",
        "无标签", "无水印", "无气泡", "无其他",
    )
    clean = []
    for part in _re.split(r'[；;\n]+', str(text or "")):
        part = part.strip(" ，,。")
        if part and not any(word in part for word in bad):
            clean.append(part)
    return clean

def _project_character_profile(project, name):
    for item in (project or {}).get("character_profiles") or []:
        if isinstance(item, dict) and _same_character_name(item.get("name"), name):
            return item
    return {}

def _normalize_character_description(description):
    """清理模型标签占位与字段错位，不把配色、站姿或识别特征误当成道具。"""
    import re as _re
    text = str(description or "").strip()
    text = text.replace("固定道具具体描述：", "").replace("3-5个识别特征：", "")
    parts = []
    for raw in _re.split(r'[；;\n]+', text):
        part = raw.strip(" ，,。")
        if not part:
            continue
        if _re.search(r'^固定标志[:：]\s*(?:无|没有|空|无固定标志)$', part):
            continue
        match = _re.match(r'^固定道具[:：]\s*(.+)$', part)
        if match:
            value = match.group(1).strip()
            looks_like_trait_list = bool(_re.match(r'^\d+\s*[.、]', value)) or any(
                word in value for word in ("配色", "站姿", "轮廓", "反差", "识别特征"))
            if looks_like_trait_list and not any(word in value for word in ACTUAL_PROP_WORDS):
                part = "识别特征：" + value
            elif value in ("无", "没有", "空", "留空"):
                continue
        parts.append(part)
    return "；".join(parts)

def _character_prop_state(project, name, description=""):
    profile = _project_character_profile(project, name)
    state = str(_profile_node_value(profile.get("propState"), "") or "").strip()
    if state in ("unset", "locked_empty"):
        return state
    clean = _normalize_character_description(description)
    fixed_prop = ""
    import re as _re
    match = _re.search(r'固定道具[:：]\s*([^；;\n]+)', clean)
    if match:
        fixed_prop = match.group(1).strip()
    profile_prop = ""
    visual_profile = profile.get("visual_profile") if isinstance(profile, dict) else {}
    if isinstance(visual_profile, dict):
        profile_prop = str(_profile_node_value(
            visual_profile.get("固定道具"), "") or "").strip()
    contextual_prop = _re.search(
        r'(?:固定道具|背负|携带|手持|腰挂|佩戴)[:：]?\s*[^；;\n]{0,24}(?:'
        + "|".join(_re.escape(word) for word in ACTUAL_PROP_WORDS) + r')',
        clean)
    actual_present = (
        (fixed_prop and any(word in fixed_prop for word in ACTUAL_PROP_WORDS))
        or (profile_prop and any(word in profile_prop for word in ACTUAL_PROP_WORDS))
        or bool(contextual_prop)
    )
    if actual_present:
        return "present"
    return "unset"

def _character_visual_policy(project, name, description=""):
    profile = _project_character_profile(project, name)
    policy = profile.get("visual_policy") if isinstance(profile, dict) else {}
    if isinstance(policy, dict) and policy.get("roleVisualTier"):
        result = dict(policy)
        requested = result.get("styleDirection") or "auto"
        if requested == "auto" or not result.get("styleDirectionResolved"):
            result["styleDirectionResolved"] = resolve_hero_style(
                (project or {}).get("world_visual_profile"),
                description,
                (project or {}).get("premise") or "",
                requested)
        return result
    profiles = [
        item for item in (project or {}).get("character_profiles") or []
        if isinstance(item, dict)
    ]
    index = next(
        (i for i, item in enumerate(profiles)
         if _same_character_name(item.get("name"), name)), 0)
    return _default_visual_policy(
        index, (project or {}).get("world_visual_profile"), description,
        (project or {}).get("premise") or "")

def _character_asset_art(art, policy):
    raw = str(_norm_art(art) or "")
    realistic = any(word in raw for word in (
        "写实", "真人", "摄影", "纪实", "电影", "照片"))
    if realistic:
        return (
            "真人电影角色美术设定，真实演员骨相与自然皮肤质感，"
            "电影美术部门角色圣经，精致可信的服装材质，成熟高级的角色设计"
        )
    return "，".join(_positive_prompt_fragments(raw)) + "，专业角色美术设定"

def _character_world_prompt(profile, include_tools=True):
    """人物资产只读取服装相关世界字段，防止建筑与背景抢走人物设计。"""
    if not isinstance(profile, dict):
        return "统一可信的题材时代、服装工艺、材料与色彩体系"
    fields = profile.get("fields") if isinstance(profile.get("fields"), dict) else profile
    labels = {
        "genre": "题材", "era": "时代", "civilization": "文明审美",
        "technology": "技术层级", "materials": "常见材料",
        "clothingSystem": "服装体系", "visualTone": "角色色彩气质",
    }
    parts = []
    for key in ("genre", "era", "materials", "clothingSystem", "visualTone"):
        value = _profile_node_value(fields.get(key), "")
        if isinstance(value, list):
            value = "、".join(str(x).strip() for x in value if str(x).strip())
        clean = "、".join(_positive_prompt_fragments(value))[:110]
        if clean:
            parts.append(labels[key] + "：" + clean)
    return "，".join(parts[:5]) or "统一可信的题材时代、服装工艺、材料与色彩体系"

def _hero_visual_fragments(policy):
    if not isinstance(policy, dict):
        return []
    if policy.get("roleVisualTier") != "main_character":
        return ["角色身份明确，轮廓与配色具有稳定辨识度"]
    override = policy.get("beautyOverride")
    direction = HERO_STYLE_DIRECTIONS.get(
        policy.get("styleDirectionResolved"), HERO_STYLE_DIRECTIONS["hardline_handsome"])
    parts = [direction]
    if not override:
        outfit_level = policy.get("outfitDesignLevel") or "heroic"
        outfit_text = {
            "refined": "精致克制的主角服装设计，剪裁考究，材质高级，细节集中且轮廓清楚",
            "legendary": "传奇华丽的主角服装设计，多层结构与高级材质形成强烈剪影，身份细节精美醒目",
        }.get(
            outfit_level,
            "主角级服装设计，层次清晰，剪裁精致，材质高级，稳定配色形成鲜明剪影")
        parts.extend((
            "电影主演级真人外貌，五官协调清晰，眼神有吸引力",
            "高挑修长且匀称的人体比例，肩腰关系清楚，四肢自然偏长，站姿挺拔",
            outfit_text,
        ))
    return parts

def _costume_design_fragments(policy, world_profile=None):
    """最后写入具体服装设计方向，优先级高于蓝图里可能过于普通的基础衣物描述。"""
    if not isinstance(policy, dict):
        return []
    override = str(policy.get("outfitOverride") or "").strip()
    if override in ("朴素", "简朴", "破旧", "制服"):
        return [
            "最终服装保持%s定位，结构完整，材质与身份可信，轮廓和配色清楚" % override
        ]
    level = policy.get("outfitDesignLevel") or (
        "legendary" if policy.get("roleVisualTier") == "main_character" else "refined")
    if level == "legendary":
        return [
            "最终服装采用华丽繁复且好看的主角级造型，内层、中层、外层形成清晰完整的多层轮廓",
            "领部、肩部、袖口、腰封与衣摆都有精致结构，高级织物、皮革或金属辅件形成丰富材质对比",
            "细密刺绣、暗纹滚边、身份徽记与精工扣件集中在视觉重点，主色与两种辅色形成鲜明统一的角色配色",
            "服装具有盛装般的繁华观感与可行动的剪裁，远景剪影醒目，近景细节精美",
        ]
    if level in ("heroic", "refined"):
        return [
            "最终服装采用精致华丽的角色级造型，内外层次清楚，领肩袖腰剪裁考究",
            "高级材质、细密滚边、局部刺绣与身份配饰形成统一配色和稳定剪影",
        ]
    return ["最终服装结构完整，身份鲜明，材质、剪裁与配色具有角色辨识度"]

def _world_visual_prompt(profile, include_tools=True):
    """只拼世界中可见且正向的字段；权限/禁用规则仅供文字校验。"""
    if not isinstance(profile, dict):
        return "统一可信的时代、文明、材料、服装与建筑体系"
    fields = profile.get("fields") if isinstance(profile.get("fields"), dict) else profile
    parts = []
    for key in WORLD_VISUAL_FIELDS:
        if key == "allowedMixedElements" or (key == "toolSystem" and not include_tools):
            continue
        value = _profile_node_value(fields.get(key), "")
        if isinstance(value, list):
            value = "、".join(str(x).strip() for x in value if str(x).strip())
        fragments = _positive_prompt_fragments(value)
        if not include_tools:
            fragments = [
                part for part in fragments
                if not any(word in part for word in
                           (_PROP_KW + ("枪械", "手枪", "步枪", "火器")))
            ]
        parts.extend(fragments)
    return "，".join(parts[:12]) or "统一可信的时代、文明、材料、服装与建筑体系"

def _visual_card_segments(description, prop_state):
    import re as _re
    allowed = (
        "性别", "年龄", "脸", "五官", "眉", "眼", "鼻", "唇", "发型", "发色",
        "肤色", "体型", "体态", "身高", "上装", "下装", "鞋", "靴", "外层",
        "服装", "衣", "裙", "袍", "裤", "甲", "斗篷", "固定标志", "配饰",
        "疤痕", "纹身", "识别特征", "固定道具", "背负", "携带",
    )
    state_words = ("道具状态", "unset", "locked_empty", "present")
    prop_words = _PROP_KW + ("火器", "手枪", "步枪", "枪械")
    parts = []
    for raw in _re.split(r'[；;\n]+', _normalize_character_description(description)):
        part = raw.strip(" ，,。")
        if not part or any(word in part for word in state_words):
            continue
        if prop_state != "present" and any(word in part for word in prop_words):
            continue
        if any(word in part for word in allowed):
            parts.extend(_positive_prompt_fragments(part))
    if not parts:
        for part in _positive_prompt_fragments(description):
            if prop_state != "present" and any(word in part for word in prop_words):
                continue
            parts.append(part)
    return parts[:14]

def validate_character_visual_card(description, world_profile=None, prop_state="unset"):
    text = str(description or "")
    issues = []
    for label in ("上装", "下装", "鞋"):
        if label not in text and (label != "鞋" or "靴" not in text):
            issues.append("缺少完整" + ("鞋靴" if label == "鞋" else label))
    conflicts = (
        (("极度消瘦", "肌肉壮硕"), "体型同时极度消瘦和肌肉壮硕"),
        (("年迈衰弱", "年轻体态"), "年龄体态互相冲突"),
        (("中世纪", "战术裤"), "中世纪服装混入战术裤"),
        (("贵族礼服", "赤脚"), "贵族固定服装与赤脚状态冲突"),
    )
    combined = text + "\n" + _profile_text(world_profile)
    for words, issue in conflicts:
        if all(word in combined for word in words):
            issues.append(issue)
    permissions = (
        world_profile.get("permissions")
        if isinstance(world_profile, dict) and isinstance(world_profile.get("permissions"), dict)
        else {}
    )
    modern_allowed = bool(_profile_node_value(
        permissions.get("modernFirearmsAllowed"), False))
    magic_allowed = bool(_profile_node_value(
        permissions.get("magicFirearmsAllowed"), False))
    if any(word in text for word in ("手枪", "步枪", "现代枪械", "自动武器")):
        if not modern_allowed:
            issues.append("人物出现了世界基准没有允许的现代枪械")
    if any(word in text for word in ("魔法枪", "魔导枪", "符文枪", "炼金火器")):
        if not magic_allowed:
            issues.append("人物出现了世界基准没有允许的魔法火器")
    if prop_state == "locked_empty" and any(word in text for word in _PROP_KW):
        issues.append("道具已锁定为空但视觉卡仍包含武器或道具")
    marker_text = ""
    for part in text.split("；"):
        if any(word in part for word in ("固定标志", "疤痕", "纹身", "配饰")):
            marker_text += "、" + part
    if len(_split_profile_list(marker_text)) > 4:
        issues.append("固定标志堆积过多")
    return issues

def repair_character_visual_card(name, description, world_profile, prop_state):
    issues = validate_character_visual_card(description, world_profile, prop_state)
    if not issues:
        return str(description or "").strip(), []
    prop_rule = (
        "该人物的固定道具状态为locked_empty，修订结果完全省略固定道具字段和相关词。"
        if prop_state == "locked_empty"
        else "固定道具仅保留原卡中已经明确存在且符合世界的内容。"
    )
    messages = [
        {"role": "system", "content":
         "你是人物视觉卡校对员。只修正用户指出的字段，不重写故事、身份或整份蓝图。"
         "输出一行修订后的画图外观，必须包含正常可信的人体、上装、下装、鞋靴、必要外层服装，"
         "并符合给定世界的时代、材料和职业。固定标志最多一处。"
         + prop_rule + "只输出外观内容，不写姓名、解释或检查过程。"},
        {"role": "user", "content":
         "【世界视觉基准】\n" + _profile_text(world_profile) +
         "\n\n【人物】" + str(name) +
         "\n【当前视觉卡】" + str(description or "") +
         "\n【只修这些问题】" + "；".join(issues)},
    ]
    fixed = chat_stream(messages, 0.2, None, 900).strip()
    fixed = fixed.splitlines()[0].strip() if fixed else str(description or "").strip()
    remaining = validate_character_visual_card(fixed, world_profile, prop_state)
    return fixed, remaining

def _character_identity_prompt(name, description, art, world_profile=None,
                               prop_state="unset", visual_policy=None):
    art_text = _character_asset_art(art, visual_policy or {})
    world_text = _character_world_prompt(
        world_profile, include_tools=prop_state == "present")
    visible = "，".join(_visual_card_segments(description, prop_state))
    parts = [
        art_text,
        world_text,
        "角色身份：" + str(name),
        *_hero_visual_fragments(visual_policy),
        visible,
        *_costume_design_fragments(visual_policy, world_profile),
    ]
    return "，".join(x for x in parts if str(x or "").strip())

def _project_asset_character_sheet(project, fallback=""):
    """给分镜模型的稳定文字角色资产；Krea2不接参考图，因此以角色ID和视觉锚点传递一致性。"""
    rows = parse_char_sheet(str((project or {}).get("charSheet") or fallback or ""))
    lines = []
    for index, (name, description) in enumerate(rows.items()):
        profile = _project_character_profile(project, name)
        policy = _character_visual_policy(project, name, description)
        prop_state = _character_prop_state(project, name, description)
        char_id = profile.get("character_id") or _character_id(
            name, (project or {}).get("premise") or (project or {}).get("title") or "", index)
        visible = "；".join(_visual_card_segments(description, prop_state))
        hero = "；".join(_hero_visual_fragments(policy)[:3])
        lines.append("%s[%s]—%s%s" % (
            name, char_id, visible, ("；" + hero) if hero else ""))
    return "\n".join(lines) or str(fallback or "")

def _character_asset_dimensions(visual_policy=None, sheet_type="master"):
    if sheet_type == "production":
        return 1536, 1024
    return 1536, 1024

def _character_asset_prompt(name, description, art, world_profile=None,
                            prop_state="unset", visual_policy=None,
                            sheet_type="master"):
    identity = _character_identity_prompt(
        name, description, art, world_profile, prop_state, visual_policy)
    if sheet_type == "production":
        parts = [
            identity,
            "3:2宽幅漫画制作角色参考页，同一名角色在所有分区保持完全一致的骨相、五官距离、发型轮廓、体型比例、服装结构、固定标志与颜色方案",
            "上排展示平静、轻微微笑、愤怒、震惊、受伤忍耐五种面部表情",
            "下排展示自然行走、回头警戒、战斗准备、快速闪避、常用手势五种全身动作",
            "动作重心清楚，关节方向可信，手部姿态清晰",
            "浅色中性角色设计工作台背景，清晰网格分区，均匀柔和光线，高细节角色资产参考",
        ]
        return "，".join(x for x in parts if str(x or "").strip()) + "。"
    parts = [
        identity,
        "3:2宽幅纯白底角色设定图，同一名角色在一张图中展示四次，四个形象共享完全一致的年龄、骨相、五官、发型、身材比例、服装结构、固定标志与颜色",
        "左侧依次排列正面、九十度标准侧面、背面三张站立全身三视图，三人等高等比例，从头顶到鞋底完整入镜",
        "三视图采用自然挺拔的中性正站姿，双臂自然放松，双手与十指清楚可见，服装前侧后结构准确对应",
        "右侧为一张更大、更有魅力的四分之三全身角色立绘，姿态自信帅气，人物气质与身份鲜明",
        "完整上装、完整下装、鞋靴、外层服装与华丽装饰在四个形象中完全统一",
        "纯白背景，均匀柔和棚拍光，干净整齐的专业角色设定版面，高细节角色美术资产",
    ]
    if prop_state == "present":
        prop_parts = [
            part for part in _visual_card_segments(description, "present")
            if any(word in part for word in _PROP_KW)
        ]
        if prop_parts:
            parts.append("固定携带物细节：" + "，".join(prop_parts))
    return "，".join(x for x in parts if str(x or "").strip()) + "。"

def _character_portrait_prompt(name, description, art, world_profile=None,
                               prop_state="unset", visual_policy=None):
    """兼容旧调用；新版本默认生成角色资产主设定页。"""
    return _character_asset_prompt(
        name, description, art, world_profile, prop_state,
        visual_policy or _default_visual_policy(
            0, world_profile, description, ""), "master")

def _character_asset_is_current(project, name, description, record):
    """旧图只有在提示词、人物卡和世界版本都一致时才算完整。"""
    if not isinstance(record, dict):
        return False
    profile = _project_character_profile(project, name)
    world_profile = project.get("world_visual_profile")
    return (
        str(record.get("promptVersion") or "") == CHARACTER_MAIN_PROMPT_VERSION
        and _normalize_character_description(record.get("description"))
        == _normalize_character_description(description)
        and int(record.get("worldProfileVersion") or 0)
        == int((world_profile or {}).get("version") or 1)
        and int(record.get("characterVisualVersion") or 0)
        == int(profile.get("version") or 1)
    )

def ensure_project_character_images(project, art):
    """为所有缺失或已过期人物生成角色资产页；手动按钮也复用此流程。"""
    rows = parse_char_sheet(str(project.get("charSheet") or ""))
    old = {
        str(x.get("name") or "").strip(): x
        for x in (project.get("characterImages") or [])
        if isinstance(x, dict) and str(x.get("name") or "").strip()
    }
    missing = [
        (name, desc) for name, desc in rows.items()
        if not _character_asset_is_current(project, name, desc, old.get(name))
    ][:30]
    if not missing:
        return 0
    world_profile = project.get("world_visual_profile")
    prepared = []
    repaired_rows = dict(rows)
    for name, desc in missing:
        prop_state = _character_prop_state(project, name, desc)
        try:
            fixed, remaining = repair_character_visual_card(
                name, desc, world_profile, prop_state)
            if fixed:
                desc = fixed
                repaired_rows[name] = fixed
            if remaining:
                log("⚠ 人物视觉卡仍需人工检查：%s（%s）" %
                    (name, "；".join(remaining)))
        except Exception as e:
            log("⚠ 人物视觉卡轻量校对未完成，沿用当前卡：%s（%s）" % (name, e))
        policy = _character_visual_policy(project, name, desc)
        profile = _project_character_profile(project, name)
        char_id = profile.get("character_id") or _character_id(
            name, project.get("premise") or project.get("title") or "", len(prepared))
        prepared.append((name, desc, prop_state, policy, char_id))
    if repaired_rows != rows:
        project["charSheet"] = "\n".join(
            name + "—" + desc for name, desc in repaired_rows.items())
        save_project_atomic(project)
    if not comfy_up() and not comfy_start():
        log("⚠ Comfyui画图无法启动；人物文字设定已保存，可稍后手动生成设定图")
        return 0
    title = project.get("title") or "未命名"
    made = 0
    for i, (name, desc, prop_state, policy, char_id) in enumerate(prepared, 1):
        _auto_check_stop()
        set_auto_job(
            stage="character_images", current=i, total=len(missing),
            message="🧍 生成角色资产 %d/%d：%s…" % (i, len(missing), name))
        archive = panel_archive_file(title + "/人物设定", name)
        prompt = _character_asset_prompt(
            name, desc, art, world_profile, prop_state, policy, "master")
        width, height = _character_asset_dimensions(policy, "master")
        identity_prompt = _character_identity_prompt(
            name, desc, art, world_profile, prop_state, policy)
        seed = int(hashlib.sha256((title + "|" + name).encode("utf-8")).hexdigest()[:8], 16)
        try:
            _auto_retry(
                "人物设定图·" + name,
                lambda p=prompt, s=seed, a=archive, size=(width, height):
                    comfy_generate(p, s, a, size),
                3, 2)
            rel = os.path.relpath(archive, COMIC_DIR).replace("\\", "/")
            old[name] = {
                "name": name, "characterId": char_id,
                "roleVisualTier": policy.get("roleVisualTier"),
                "assetType": "master",
                "description": desc, "identityPrompt": identity_prompt, "prompt": prompt,
                "assembledPrompt": prompt,
                "promptVersion": CHARACTER_MAIN_PROMPT_VERSION,
                "visualPolicy": policy,
                "worldProfileVersion": int((world_profile or {}).get("version") or 1),
                "characterVisualVersion": int(
                    _project_character_profile(project, name).get("version") or 1),
                "generatedAt": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                "width": width, "height": height,
                "url": "/panel?" + urlencode({"p": rel}), "relPath": rel,
            }
            project.setdefault("characterPromptLog", []).append({
                "name": name, "characterId": char_id, "assetType": "master",
                "promptVersion": CHARACTER_MAIN_PROMPT_VERSION,
                "assembledPrompt": prompt,
                "worldProfileVersion": int((world_profile or {}).get("version") or 1),
                "characterVisualVersion": int(
                    _project_character_profile(project, name).get("version") or 1),
                "generatedAt": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
            })
            project["characterPromptLog"] = project["characterPromptLog"][-100:]
            project["characterImages"] = list(old.values())
            project["characterAssets"] = list(old.values())
            profile = _project_character_profile(project, name)
            if profile:
                profile["character_id"] = char_id
                profile["visual_policy"] = policy
                state = profile.setdefault("generation_state", {})
                state.update({
                    "assetVersion": int(state.get("assetVersion") or 0) + 1,
                    "worldProfileVersion": int((world_profile or {}).get("version") or 1),
                    "masterStatus": "ready",
                })
            save_project_atomic(project)
            made += 1
        except AutoJobStopped:
            raise
        except Exception as e:
            log("⚠ 人物设定图生成失败，漫画继续：%s（%s）" % (name, e))
    if made:
        log("✅ 已生成 %d 张人物设定图" % made)
    return made

def _auto_plan_key(content, char_sheet, art, max_panels, rules):
    raw = "\u241f".join(map(str, (content, char_sheet, art, max_panels, rules)))
    return "v5:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]

def _valid_panel_image(path):
    if not os.path.isfile(path) or os.path.getsize(path) < 1024:
        return False
    try:
        from PIL import Image
        with Image.open(path) as im:
            im.verify()
        return True
    except Exception:
        return False

def _comic_rel_file(rel_path):
    """把项目里保存的漫画相对路径安全解析到 COMIC_DIR。"""
    parts = [safe_name(x) for x in str(rel_path or "").replace("\\", "/").split("/") if x and x not in (".", "..")]
    if not parts:
        return ""
    path = os.path.abspath(os.path.join(COMIC_DIR, *parts))
    try:
        if os.path.commonpath([path, os.path.abspath(COMIC_DIR)]) != os.path.abspath(COMIC_DIR):
            return ""
    except Exception:
        return ""
    return path

def _plain_story_synopsis(project, limit=240):
    """卷首只保留一段白话梗概，不再堆叠世界观和整份大纲。"""
    import re as _re
    project = project if isinstance(project, dict) else {}
    premise = str(
        project.get("storySummary") or project.get("synopsis")
        or project.get("premise") or "").strip()
    outline = str(project.get("outline") or "").strip()

    def clean(value):
        value = _re.sub(r'【[^】]{1,20}】', '', str(value or ""))
        value = _re.sub(r'^\s*(?:故事简介|剧情梗概|一句话起稿)\s*[：:]\s*', '', value)
        value = _re.sub(r'\s+', ' ', value).strip(" ，,；;。")
        return value

    premise = clean(premise)
    outline = clean(outline)
    core = premise
    if len(core) < 70 and outline:
        # 只补大纲开头的一句话，用来交代主线，不把阶段规划塞进卷首。
        pieces = [x.strip() for x in _re.split(r'(?<=[。！？!?])', outline) if x.strip()]
        supplement = pieces[0] if pieces else outline
        supplement = _re.sub(
            r'^\s*(?:故事承诺|故事主线|主线|开端|阶段发展)\s*[：:]\s*',
            '', supplement)
        if supplement and supplement not in core:
            core = (core.rstrip("。") + "。" + supplement).strip()
    if not core:
        return ""
    core = core[:limit].rstrip("，,；; ")
    if len(core) == limit:
        core = core.rstrip("。") + "……"
    elif core[-1:] not in "。！？!?……":
        core += "。"
    return core

def _brief_character_intro(description, limit=90):
    """人物页只回答“他/她是谁”，不复述整张外观卡。"""
    import re as _re
    visual_terms = (
        "脸", "眉", "眼", "鼻", "嘴", "唇", "发型", "发色", "头发", "肤色",
        "身材", "体型", "服装", "穿着", "衣", "裤", "裙", "鞋", "靴",
        "疤", "纹身", "配饰", "武器", "道具", "五官",
    )
    parts = [
        _re.sub(r'^\s*(?:身份年龄|身份|年龄|人物定位)\s*[：:]\s*', '', x.strip())
        for x in _re.split(r'[｜|]+', str(description or ""))
        if x.strip()
    ]
    chosen = []
    for part in parts:
        if any(term in part for term in visual_terms):
            continue
        if part in ("章节新增人物", "主要人物", "人物"):
            continue
        chosen.append(part)
        if len(chosen) >= 1:
            break
    text = "；".join(chosen).strip("；。 ")
    if not text:
        text = next((x for x in parts if x not in ("章节新增人物", "主要人物", "人物")), "")
    slash_parts = [x.strip() for x in _re.split(r'[/／]+', text) if x.strip()]
    if len(slash_parts) >= 2:
        text = "，".join(slash_parts[:2])
    text = _re.sub(r'\s+', ' ', text)[:limit].rstrip("，,；; ")
    if text and text[-1:] not in "。！？!?":
        text += "。"
    return text or "故事中的重要人物。"

def _front_character_rows(project):
    import re as _re
    images = {}
    for item in project.get("characterImages", []) if isinstance(project, dict) else []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "").strip()
        if name:
            images[name] = item
    rows = []
    seen = set()
    for raw in str((project or {}).get("chars") or "").splitlines():
        line = _re.sub(r'^\s*\d+\s*[.、]\s*', '', raw).strip()
        if not line:
            continue
        parts = [x.strip() for x in _re.split(r'[｜|]', line) if x.strip()]
        if len(parts) >= 2:
            name, desc = parts[0], "｜".join(parts[1:])
        else:
            m = _re.match(r'^([^—–\-:：]{1,20})\s*[—–\-:：]\s*(.+)$', line)
            if not m:
                continue
            name, desc = m.group(1).strip(), m.group(2).strip()
        if not name or name in seen:
            continue
        seen.add(name)
        image = images.get(name)
        if not image:
            image = next((v for k, v in images.items() if k in name or name in k), None)
        rows.append({
            "name": name,
            "description": _brief_character_intro(desc),
            "image": image or {},
        })
    for name, image in images.items():
        if name not in seen:
            rows.append({
                "name": name,
                "description": _brief_character_intro(image.get("description")),
                "image": image,
            })
    return rows

def _paste_contained(base, source_path, box):
    from PIL import Image, ImageDraw
    x1, y1, x2, y2 = map(int, box)
    d = ImageDraw.Draw(base)
    d.rounded_rectangle([x1, y1, x2, y2], radius=12, fill="white", outline=(220, 211, 198), width=2)
    if not source_path or not os.path.isfile(source_path):
        d.text(((x1 + x2) / 2, (y1 + y2) / 2), "人物设定图", font=_font(26), fill=(185, 177, 165), anchor="mm")
        return
    try:
        with Image.open(source_path) as src:
            im = src.convert("RGB")
            pad = 18
            max_w, max_h = x2 - x1 - pad * 2, y2 - y1 - pad * 2
            scale = min(max_w / im.width, max_h / im.height)
            im = im.resize((max(1, int(im.width * scale)), max(1, int(im.height * scale))))
            px = x1 + (x2 - x1 - im.width) // 2
            py = y1 + (y2 - y1 - im.height) // 2
            base.paste(im, (px, py))
    except Exception:
        pass

def _build_front_matter_pages(project, W=1240, H=1754):
    """实体漫画式卷首：一段短白话梗概，随后是简短人物身份页。"""
    from PIL import Image, ImageDraw
    project = project if isinstance(project, dict) else {}
    title = str(project.get("title") or "").strip()
    chars = _front_character_rows(project)
    synopsis = _plain_story_synopsis(project)
    if not synopsis and not chars:
        return []
    pages = []
    if synopsis:
        page = Image.new("RGB", (W, H), CREAM); d = ImageDraw.Draw(page)
        d.rectangle([42, 42, W - 42, H - 42], outline=BROWN, width=3)
        d.rectangle([54, 54, W - 54, H - 54], outline=(220, 205, 180), width=1)
        d.text((W / 2, 180), title or "故事", font=_font(52, True), fill=INK, anchor="mm")
        d.text((W / 2, 268), "STORY  ·  剧情梗概", font=_font(25, True), fill=BROWN, anchor="mm")
        d.line([(190, 320), (W - 190, 320)], fill=BROWN, width=2)
        intro_font = _font(34)
        intro_step = 58
        intro_lines = _wrap(d, synopsis, intro_font, W - 320)
        text_h = max(intro_step, len(intro_lines) * intro_step)
        y = max(430, int((H - text_h) / 2) - 40)
        for line in intro_lines:
            d.text((160, y), line, font=intro_font, fill=INK)
            y += intro_step
        _footer(d, W, H, 150, "STORY SUMMARY")
        pages.append(page)

    has_character_art = any(
        _comic_rel_file((row.get("image") or {}).get("relPath") or "")
        for row in chars
    )
    per_character_page = 2 if has_character_art else 5
    for start in range(0, len(chars), per_character_page):
        page = Image.new("RGB", (W, H), CREAM); d = ImageDraw.Draw(page)
        d.text((90, 88), "CHARACTERS", font=_font(28, True), fill=BROWN)
        d.text((W - 90, 92), "人物介绍", font=_font(30, True), fill=INK, anchor="ra")
        d.line([(90, 142), (W - 90, 142)], fill=BROWN, width=2)
        if has_character_art:
            block_h, block_gap = min(650, max(520, (H - 335) // 2)), 30
        else:
            block_h, block_gap = 245, 20
        for slot, row in enumerate(chars[start:start + per_character_page]):
            top = 185 + slot * (block_h + block_gap)
            bottom = top + block_h
            d.rounded_rectangle([80, top, W - 80, bottom], radius=18, fill=(255, 253, 249), outline=(224, 213, 198), width=2)
            item = row.get("image") or {}
            rel = item.get("relPath") or ""
            path = _comic_rel_file(rel)
            if path:
                portrait_right = 105 + int((W - 210) * 0.42)
                text_left = portrait_right + 40
                _paste_contained(page, path, (105, top + 25, portrait_right, bottom - 25))
            else:
                text_left = 125
            name_font = _font(36 if W < 1000 else 42, True)
            name_y = top + (50 if has_character_art else 38)
            line_y = top + (110 if has_character_art else 92)
            d.text((text_left, name_y), row.get("name") or "未命名", font=name_font, fill=INK)
            d.line([(text_left, line_y), (W - 120, line_y)], fill=(205, 183, 155), width=2)
            y = top + (145 if has_character_art else 120)
            desc_size = max(21, min(27, int(W / 42)))
            desc_font = _font(desc_size)
            desc_step = int(desc_size * 1.55)
            desc_lines = _wrap(d, str(row.get("description") or "")[:650], desc_font, W - 120 - text_left)
            max_desc_lines = max(4, int((bottom - 50 - y) / desc_step) + 1)
            if len(desc_lines) > max_desc_lines:
                desc_lines = desc_lines[:max_desc_lines]
                desc_lines[-1] = desc_lines[-1].rstrip("，。；、 ") + "……"
            for line in desc_lines:
                d.text((text_left, y), line, font=desc_font, fill=(69, 62, 54))
                y += desc_step
        _footer(d, W, H, 90, "CHARACTER FILE")
        pages.append(page)
    return pages

def _auto_pdf(title, page_paths, project=None):
    _pdf_t0 = time.time()
    from PIL import Image
    valid = [p for p in page_paths if os.path.isfile(p)]
    if not valid:
        raise RuntimeError("没有可合并的漫画分页")
    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(BOOK_DIR, safe_name(title or "漫画") + "·完整分页版.pdf")
    tmp = out + ".tmp.pdf"
    ims = []
    try:
        with Image.open(valid[0]) as sample:
            front_w, front_h = sample.size
        ims = _build_front_matter_pages(project or {}, front_w, front_h)
        ims += [Image.open(p).convert("RGB") for p in valid]
        ims[0].save(tmp, "PDF", save_all=True, append_images=ims[1:], resolution=150.0)
        if not os.path.isfile(tmp) or os.path.getsize(tmp) < 1024:
            raise RuntimeError("PDF 文件生成失败")
        os.replace(tmp, out)
    finally:
        for im in ims:
            try: im.close()
            except Exception: pass
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except Exception: pass
    from urllib.parse import quote
    calib_record("pdf_merge", time.time() - _pdf_t0)
    return out, "/book/" + quote(os.path.basename(out))

def _cinematic_still_pdf(title, entries, project=None):
    """把宽银幕剧照与对应小说原文排在同一页；图片本身始终保持无字。"""
    from PIL import Image, ImageDraw, ImageOps
    valid = [
        x for x in (entries or [])
        if isinstance(x, dict) and os.path.isfile(str(x.get("path") or ""))
    ]
    if not valid:
        raise RuntimeError("没有可合并的电影剧照")
    W, H = 1800, 1280
    margin = 72
    image_box = (margin, 96, W - margin, 995)
    title_font = _font(34, True)
    text_font = _font(27)
    meta_font = _font(20)
    pages = []
    for index, entry in enumerate(valid, 1):
        page = Image.new("RGB", (W, H), (247, 244, 238))
        draw = ImageDraw.Draw(page)
        page_title = str(entry.get("name") or "第%02d幕" % index)
        draw.text((margin, 42), page_title, font=title_font, fill=(38, 34, 30))
        draw.text((W - margin, 52), "%02d / %02d" % (index, len(valid)),
                  font=meta_font, fill=(125, 115, 102), anchor="ra")
        with Image.open(entry["path"]) as source:
            still = ImageOps.fit(source.convert("RGB"),
                                 (image_box[2] - image_box[0], image_box[3] - image_box[1]),
                                 method=Image.Resampling.LANCZOS,
                                 centering=(0.5, 0.5))
        page.paste(still, (image_box[0], image_box[1]))
        draw.rectangle(image_box, outline=(47, 43, 38), width=3)
        y = 1035
        draw.text((margin, y), "小说原文", font=_font(22, True), fill=(130, 83, 40))
        y += 40
        source_text = str(entry.get("source") or "").strip()
        lines = _wrap(draw, source_text, text_font, W - margin * 2)
        for line in lines[:5]:
            draw.text((margin, y), line, font=text_font, fill=(55, 50, 45))
            y += 40
        pages.append(page)
    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(BOOK_DIR, safe_name(title or "电影剧照册") + "·电影级剧照册.pdf")
    tmp = out + ".tmp.pdf"
    try:
        pages[0].save(tmp, "PDF", save_all=True, append_images=pages[1:], resolution=150.0)
        if not os.path.isfile(tmp) or os.path.getsize(tmp) < 1024:
            raise RuntimeError("电影剧照册PDF生成失败")
        os.replace(tmp, out)
    finally:
        for page in pages:
            try: page.close()
            except Exception: pass
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except Exception: pass
    from urllib.parse import quote
    return out, "/book/" + quote(os.path.basename(out))

def _creative_album_pdf(title, entries, mode_label="快速创作"):
    """为写真、设定、世界观和图鉴生成无损留白图册；文字由本地排版。"""
    from PIL import Image, ImageDraw, ImageOps
    valid = [
        x for x in (entries or [])
        if isinstance(x, dict) and os.path.isfile(str(x.get("path") or ""))
    ]
    if not valid:
        raise RuntimeError("没有可合并的图集图片")
    W, H = 1600, 1900
    margin = 76
    image_box = (margin, 160, W - margin, 1600)
    pages = []
    for index, entry in enumerate(valid, 1):
        page = Image.new("RGB", (W, H), (249, 247, 243))
        draw = ImageDraw.Draw(page)
        draw.text((margin, 50), str(entry.get("name") or "第%02d张" % index),
                  font=_font(38, True), fill=(42, 37, 32))
        draw.text((W - margin, 60), "%s · %02d/%02d" %
                  (mode_label, index, len(valid)), font=_font(20),
                  fill=(125, 115, 102), anchor="ra")
        with Image.open(entry["path"]) as source:
            image = source.convert("RGB")
            image.thumbnail((image_box[2] - image_box[0],
                             image_box[3] - image_box[1]), Image.Resampling.LANCZOS)
            x = image_box[0] + (image_box[2] - image_box[0] - image.width) // 2
            y = image_box[1] + (image_box[3] - image_box[1] - image.height) // 2
            page.paste(image, (x, y))
            draw.rectangle((x - 2, y - 2, x + image.width + 2, y + image.height + 2),
                           outline=(217, 209, 197), width=2)
        y = 1655
        description = str(entry.get("description") or "").strip()
        for line in _wrap(draw, description, _font(27), W - margin * 2)[:5]:
            draw.text((margin, y), line, font=_font(27), fill=(58, 52, 46))
            y += 42
        pages.append(page)
    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(BOOK_DIR, safe_name(title or mode_label) + "·图集.pdf")
    tmp = out + ".tmp.pdf"
    try:
        pages[0].save(tmp, "PDF", save_all=True, append_images=pages[1:], resolution=150.0)
        if not os.path.isfile(tmp) or os.path.getsize(tmp) < 1024:
            raise RuntimeError("图集PDF生成失败")
        os.replace(tmp, out)
    finally:
        for page in pages:
            try: page.close()
            except Exception: pass
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except Exception: pass
    from urllib.parse import quote
    return out, "/book/" + quote(os.path.basename(out))

def _premium_album_pdf(title, entries, mode_label="Krea2高质量画册"):
    """高质量画册：封面 + 一图一页，按原图方向自适应版面并保留大尺寸细节。"""
    from PIL import Image, ImageDraw, ImageOps
    valid = [
        x for x in (entries or [])
        if isinstance(x, dict) and os.path.isfile(str(x.get("path") or ""))
    ]
    if not valid:
        raise RuntimeError("没有可合并的画册图片")

    with Image.open(valid[0]["path"]) as first:
        landscape = first.width >= first.height
    W, H = ((2000, 1450) if landscape else (1600, 2200))
    margin = 82
    pages = []

    cover = Image.new("RGB", (W, H), (27, 24, 22))
    draw = ImageDraw.Draw(cover)
    accent = (202, 158, 91)
    draw.rectangle((margin, margin, W - margin, H - margin), outline=accent, width=3)
    draw.line((margin * 2, H * .38, W - margin * 2, H * .38), fill=accent, width=2)
    draw.text((W // 2, int(H * .27)), str(title or "未命名画册")[:36],
              font=_font(64, True), fill=(247, 241, 230), anchor="mm")
    draw.text((W // 2, int(H * .46)), str(mode_label or "Krea2高质量画册"),
              font=_font(30), fill=accent, anchor="mm")
    draw.text((W // 2, int(H * .54)), "%d 幅精选作品" % len(valid),
              font=_font(24), fill=(188, 180, 169), anchor="mm")
    draw.text((W // 2, H - margin * 2), "KREA 2 · CURATED ALBUM",
              font=_font(21, True), fill=(128, 119, 108), anchor="mm")
    pages.append(cover)

    for index, entry in enumerate(valid, 1):
        page = Image.new("RGB", (W, H), (246, 242, 235))
        draw = ImageDraw.Draw(page)
        title_text = str(entry.get("name") or ("第%02d幅" % index)).strip()
        draw.text((margin, 48), title_text[:40], font=_font(36, True), fill=(38, 34, 30))
        draw.text((W - margin, 58), "%02d / %02d" % (index, len(valid)),
                  font=_font(22), fill=(126, 111, 91), anchor="ra")
        image_top = 122
        image_bottom = H - 210
        image_box = (margin, image_top, W - margin, image_bottom)
        with Image.open(entry["path"]) as source:
            image = ImageOps.exif_transpose(source).convert("RGB")
            image.thumbnail((image_box[2] - image_box[0],
                             image_box[3] - image_box[1]), Image.Resampling.LANCZOS)
            x = image_box[0] + (image_box[2] - image_box[0] - image.width) // 2
            y = image_box[1] + (image_box[3] - image_box[1] - image.height) // 2
            page.paste(image, (x, y))
            draw.rectangle((x - 2, y - 2, x + image.width + 2, y + image.height + 2),
                           outline=(207, 194, 176), width=2)
        description = str(entry.get("description") or "").strip()
        y = H - 165
        for line in _wrap(draw, description, _font(24), W - margin * 2)[:3]:
            draw.text((margin, y), line, font=_font(24), fill=(72, 65, 57))
            y += 34
        pages.append(page)

    os.makedirs(BOOK_DIR, exist_ok=True)
    out = os.path.join(
        BOOK_DIR, safe_name(title or mode_label) + "·Krea2高质量画册.pdf")
    tmp = out + ".tmp.pdf"
    try:
        pages[0].save(tmp, "PDF", save_all=True, append_images=pages[1:],
                      resolution=200.0, quality=95)
        if not os.path.isfile(tmp) or os.path.getsize(tmp) < 1024:
            raise RuntimeError("高质量画册PDF生成失败")
        os.replace(tmp, out)
    finally:
        for page in pages:
            try:
                page.close()
            except Exception:
                pass
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except Exception:
                pass
    from urllib.parse import quote
    return out, "/book/" + quote(os.path.basename(out))

def run_auto_job(project_name, config):
    """完全运行在后端的持久全自动任务；网页关闭后线程仍继续。"""
    resume = bool(config.get("resume"))
    art = _norm_art(config.get("art"))
    max_panels = max(2, min(int(config.get("maxPanels") or 30), 100))
    length = str(config.get("length") or "medium")
    novel_rules = str(config.get("novelRules") or "")
    sb_rules = str(config.get("sbRules") or "")
    try:
        p, _ = project_path(project_name)
        if not os.path.exists(p):
            raise RuntimeError("找不到项目：" + project_name)
        project = json.load(open(p, encoding="utf-8"))
        chapters = project.get("chapters", [])
        if not chapters:
            raise RuntimeError("项目没有章节")
        title = project.get("title") or project_name or "小说"
        total = len(chapters)
        art = _lock_project_comic_style(project, config, resume)
        save_project_atomic(project)
        set_auto_job(status="running", project=title, stage="prepare", current=0, total=total,
                     progress=0, pdfUrl="", error="", message="正在准备后台任务…",
                     startedAt=time.time(), config=config)
        log("🟢 后台全自动开始：《%s》，共 %d 章" % (title, total))

        _complete_missing_chapters(project, chapters, length, novel_rules)
        char_sheet = str(project.get("charSheet") or "").strip()
        if not char_sheet and str(project.get("chars") or "").strip():
            set_auto_job(stage="characters", message="生成并保存漫画角色设定卡…")
            char_sheet = _auto_retry(
                "角色设定卡",
                lambda: gen_charsheet(
                    project.get("chars", ""), art,
                    project.get("world_visual_profile"), project.get("premise", "")),
                3, 2).strip()
            if char_sheet:
                project["charSheet"] = char_sheet
                save_project_atomic(project)
        if not char_sheet:
            char_sheet = str(project.get("chars") or "").strip()
        sync_project_characters(project, art)
        char_sheet = _project_asset_character_sheet(
            project, str(project.get("charSheet") or char_sheet)).strip()

        cached = project.get("autoComicPlan", [])
        if not isinstance(cached, list):
            cached = []
        plan = []
        fresh_indexes = set()
        art_key = _comic_art_key(art)

        # 阶段1：每完成正文、摘要、状态或分镜，立刻原子保存。
        for i, chapter in enumerate(chapters):
            _auto_check_stop()
            chap = chapter.get("title") or ("第%d章" % (i + 1))
            content = str(chapter.get("content") or "")
            incomplete = bool(chapter.get("autoIncomplete"))
            if not content.strip() or incomplete:
                set_auto_job(stage="writing", current=i + 1, total=total,
                             progress=0.48 * i / total,
                             message="✍ 后台续做：第%d/%d章《%s》写作中…" % (i + 1, total, chap))
                mode = "continue" if content.strip() else "new"
                chapter.setdefault("characterStateBefore", str(project.get("bible") or ""))
                chunks = []
                msgs, num_predict = build_messages(
                    project, mode, chapter.get("brief", ""), content, length, novel_rules)
                generated = chat_stream(msgs, 0.8, chunks.append, num_predict)
                if AUTO_JOB_STOP.is_set():
                    partial = content + generated if mode == "continue" else generated
                    if partial.strip():
                        chapter["content"] = partial
                        chapter["autoIncomplete"] = True
                        save_project_atomic(project)
                    raise AutoJobStopped()
                content = content + generated if mode == "continue" else generated
                if not content.strip():
                    raise RuntimeError("第%d章没有生成正文" % (i + 1))
                chapter["content"] = content
                chapter["savedAt"] = time.time() * 1000
                chapter.pop("autoIncomplete", None)
                save_project_atomic(project)

                try:
                    chapter["summary"] = _auto_retry(
                        "第%d章摘要" % (i + 1), lambda: summarize(content), 2, 1).strip()
                    save_project_atomic(project)
                except Exception as e:
                    log("⚠ 第%d章摘要失败，正文已保存：%s" % (i + 1, e))
                _auto_check_stop()
                try:
                    project["bible"] = _auto_retry(
                        "第%d章角色状态" % (i + 1),
                        lambda: update_bible(project.get("bible", ""), content), 2, 1).strip() or project.get("bible", "")
                    chapter["characterState"] = project["bible"]
                    save_project_atomic(project)
                except Exception as e:
                    log("⚠ 第%d章角色状态更新失败，继续执行：%s" % (i + 1, e))
            else:
                content = chapter["content"]

            key = _auto_plan_key(content, char_sheet, art, max_panels, sb_rules)
            exact = next((x for x in cached if isinstance(x, dict) and x.get("index") == i
                          and x.get("key") == key and isinstance(x.get("panels"), list)
                          and x.get("panels")), None)
            old = exact
            if old:
                panels = old["panels"]
                log("♻ 沿用第%d章已保存分镜（%d格）" % (i + 1, len(panels)))
                set_auto_job(stage="storyboard", current=i + 1, total=total,
                             progress=0.48 * (i + 0.8) / total,
                             message="♻ 第%d/%d章沿用已保存分镜（%d格）" % (i + 1, total, len(panels)))
            else:
                fresh_indexes.add(i)
                set_auto_job(stage="storyboard", current=i + 1, total=total,
                             progress=0.48 * (i + 0.5) / total,
                             message="🎬 第%d/%d章正在生成分镜…" % (i + 1, total))
                def make_storyboard():
                    msgs, np = build_storyboard_messages(content, char_sheet,
                                                         chapter.get("characterStateBefore", ""),
                                                         max_panels, sb_rules)
                    raw = chat_stream(msgs, 0.7, None, np)
                    _auto_check_stop()
                    panels_out, _ = assemble_storyboard(raw, art, parse_char_sheet(char_sheet))
                    if not panels_out:
                        raise RuntimeError("未解析出分镜")
                    return panels_out
                panels = _auto_retry("第%d章分镜" % (i + 1), make_storyboard, 3, 2)
                log("🎞 第%d章分镜已保存：%d格" % (i + 1, len(panels)))

            entry = {"index": i, "key": key, "artKey": art_key, "chap": chap,
                     "dir": title + "/" + chap, "panels": panels}
            plan.append(entry)
            remaining = [x for x in cached if isinstance(x, dict) and int(x.get("index", -1)) > i]
            project["autoComicPlan"] = plan + remaining
            save_project_atomic(project)
            set_auto_job(progress=0.48 * (i + 1) / total)

        # 阶段2：先自动补齐人物设定图，再逐图校验、最多重试3次。
        _auto_check_stop()
        all_panels = sum(len(x["panels"]) for x in plan)
        if not all_panels:
            raise RuntimeError("没有可生成的漫画分镜")
        if not comfy_up():
            set_auto_job(stage="images", message="正在启动Comfyui画图…")
            if not comfy_start():
                raise RuntimeError("Comfyui画图无法启动")
        ollama_unload()
        ensure_project_character_images(project, art)
        base_seed = int(config.get("seedBase") or int(time.time()) % 2000000000)
        done = 0
        reused_images = 0
        all_pages = []
        missing = []
        for entry in plan:
            _auto_check_stop()
            panel_rows = []
            for j, panel in enumerate(entry["panels"]):
                _auto_check_stop()
                name = "第%02d格" % (j + 1)
                archive = panel_archive_file(entry["dir"], name)
                done += 1
                can_reuse = entry["index"] not in fresh_indexes and _valid_panel_image(archive)
                if can_reuse:
                    reused_images += 1
                    log("♻ 沿用已有图片：%s/%s.png" % (entry["dir"], name))
                else:
                    set_auto_job(stage="images", current=done, total=all_panels,
                                 progress=0.48 + 0.47 * done / all_panels,
                                 message="🖼 后台出图 %d/%d（%s）…" % (done, all_panels, entry["chap"]))
                    wh = PANEL_WH.get(str(panel.get("size") or "中").strip())
                    seed = (base_seed + entry["index"] * 1009 + j) % 2147483647
                    try:
                        def make_image():
                            comfy_generate(panel.get("prompt", ""), seed, archive, wh)
                            if not _valid_panel_image(archive):
                                raise RuntimeError("图片未正确归档")
                            return True
                        _auto_retry("第%d章第%d格出图" % (entry["index"] + 1, j + 1),
                                    make_image, 3, 3)
                    except Exception as e:
                        missing.append("%s/%s：%s" % (entry["chap"], name, e))
                        log("❌ 缺图：%s/%s（%s）" % (entry["chap"], name, e))
                panel_rows.append({
                    "path": archive, "speech": panel.get("speech") or panel.get("dialog") or "",
                    "narration": panel.get("narration") or "", "size": panel.get("size") or "中"})
                set_auto_job(current=done, total=all_panels,
                             progress=0.48 + 0.47 * done / all_panels)
            invalid = [x["path"] for x in panel_rows if not _valid_panel_image(x["path"])]
            if invalid:
                continue
            out_parts = [safe_name(x) for x in entry["dir"].replace("\\", "/").split("/") if x]
            out_dir = os.path.join(PAGE_DIR, *out_parts)
            pages = compose_manga_pages(panel_rows, out_dir, title + "·" + entry["chap"])
            if not pages:
                missing.append(entry["chap"] + "：分页失败")
            else:
                all_pages.extend(pages)

        if missing:
            project["autoMissing"] = missing
            save_project_atomic(project)
            raise RuntimeError("仍有 %d 项缺失，已保留进度；再次继续会只补缺失部分" % len(missing))
        project.pop("autoMissing", None)
        save_project_atomic(project)

        # 阶段3：只有全部图片及分页均存在时才原子生成最终PDF。
        set_auto_job(stage="pdf", current=len(all_pages), total=len(all_pages), progress=0.97,
                     message="📚 全部图片已校验，正在合并完整 PDF…")
        out, url = _auto_pdf(title, all_pages, project)
        project["autoResult"] = {
            "pdf": out, "url": url, "pages": len(all_pages),
            "panels": all_panels, "completedAt": time.time(),
        }
        save_project_atomic(project)
        set_auto_job(status="complete", stage="complete", progress=1, pdfUrl=url, error="",
                     message="✅ 成品已生成：%d章、%d格、%d页（沿用%d格图片）" %
                             (len(plan), all_panels, len(all_pages), reused_images))
        log("✅ 后台全自动完成：%s" % out)
    except AutoJobStopped:
        set_auto_job(status="paused", stage="paused", error="",
                     message="⛔ 后台任务已停止；正文、分镜和图片均已保存，可继续")
        log("⛔ 后台全自动已停止，进度已保存")
    except Exception as e:
        log("❌ 后台全自动中断：%s" % e)
        log(traceback.format_exc()[-1800:])
        set_auto_job(status="error", stage="error", error=str(e),
                     message="❌ %s" % e)

REALISTIC_CINEMA = ("真人电影剧照质感，真实皮肤纹理与人体比例，电影级布光，冷峻低饱和电影调色，"
                    "浅景深，35mm电影镜头，胶片颗粒，photorealistic")

def _comic_story_units(text, soft_limit=180):
    """把超长段落拆成完整句群，短段落保持原样，避免一整段被硬塞进同一页。"""
    import re as _re
    paras = [s.strip() for s in _re.split(r'\n+', text or "") if s.strip()]
    units = []
    for para in paras:
        if len(para) <= soft_limit:
            units.append(para)
            continue
        buf = ""
        for ch in para:
            buf += ch
            if ch in "。！？!?":
                if len(buf) >= 45:
                    units.append(buf.strip()); buf = ""
        if buf.strip():
            if units and len(buf) < 36:
                units[-1] += buf
            else:
                units.append(buf.strip())
    return units

def _split_pages_for_comic(text, per=380):
    """按完整剧情节拍切页；字数只作容量参考，不在动作或悬空对白中间截断。"""
    import re as _re
    paras = _comic_story_units(text, max(150, int(per * .48)))
    pages = []; cur = []; cur_len = 0
    hard_max = int(per * 1.7)
    scene_turn = _re.compile(
        r'^(与此同时|另一边|另一面|片刻后|不久后|第二天|次日|当晚|夜里|清晨|黄昏|'
        r'就在这时|忽然|突然|门外|屋外|街上|回到|镜头)'
    )
    for idx, p in enumerate(paras):
        cur.append(p); cur_len += len(p)
        # 独立对白、冒号结尾或极短承接词需要带上后续反应；完整短句本身可以成为页尾。
        bridge = (bool(_re.match(r'^[“"「『].*[”"」』]$', p, _re.S))
                  or bool(_re.search(r'[：:，,、]$', p))
                  or (len(p) < 24 and not _re.search(r'[。！？!?]$', p)))
        nxt = paras[idx + 1] if idx + 1 < len(paras) else ""
        natural_turn = bool(nxt and scene_turn.match(nxt))
        sentence_closed = bool(_re.search(r'[。！？!?”」』]$', p))
        enough = cur_len >= int(per * .78)
        if ((enough and sentence_closed and (not bridge or natural_turn))
                or cur_len >= hard_max):
            pages.append("\n".join(cur)); cur = []; cur_len = 0
    if cur:
        pages.append("\n".join(cur))
    if len(pages) >= 2 and len(pages[-1]) < per * 0.4:
        # 不要在 pop() 的同一条增量赋值里使用 pages[-2]：
        # 列表缩短后下标会漂移，可能覆盖前一页并留下重复尾页。
        tail = pages.pop()
        pages[-1] += "\n" + tail
    return pages or ([text.strip()] if text and text.strip() else [])

def extract_page_dialogue(page_text):
    """用本地写作模型从一页原文里提取对白（角色：台词），没有就返回空串。"""
    sysmsg = ("从下面这段小说里，把人物真正说出口的对白按出现顺序提取出来，每条一行，格式为 角色：台词。"
              "只提取加了引号或明显是说出来的话；旁白、心理活动、动作描写一律不要。"
              "没有任何对白就只输出两个字：无。不要解释、不要编号、不要多余的字。")
    msgs = [{"role": "system", "content": sysmsg}, {"role": "user", "content": page_text}]
    raw = chat_stream(msgs, 0.3, None, 500).strip()
    return "" if raw in ("无", "（无）", "none", "None") else raw

def _is_pure_sound_effect(text):
    """拦截被引号包住的纯拟声词，避免排成“人物：咔哒”。"""
    import re as _re
    value = _re.sub(r'[\s—\-~～…·.!！?？。，,]+', '', str(text or ""))
    if not value or len(value) > 8:
        return False
    return bool(_re.fullmatch(
        r'(?:咔|哒|咯|嘎|啪|砰|嘭|轰|哐|咚|当|叮|铛|嗖|嘶|哗|刺|啦|'
        r'呲|滋|嗡|喀|嚓|吱|呀|噗|扑|唰|咻|咳|哼|呃|嗯|唔)+',
        value))

def _fallback_lettering_from_quotes(source, panel_count, names=None):
    """模型漏交排字计划时，确定性保留少量原文对白，不改写任何字。"""
    import re as _re
    text = str(source or "")
    n = max(1, min(int(panel_count or 1), 8))
    rows = []
    seen = set()
    for match in _re.finditer(r'[“「『"]([^”」』"\n]{1,42})[”」』"]', text):
        quote = match.group(1).strip()
        if not quote or quote in seen or _is_pure_sound_effect(quote):
            continue
        speaker = _infer_dialogue_speaker(text, quote) or "画外"
        if speaker in ("他说", "她说", "男人", "女人", "男性", "女性"):
            speaker = "画外"
        # 只认已知角色名：否则会把台词前半句当成说话人（例："你妹妹真"说"陈牧？"）
        if names and speaker != "画外" and speaker not in names:
            speaker = "画外"
        panel = min(n, max(1, int(match.start() / max(1, len(text)) * n) + 1))
        rows.append({
            "panel": panel,
            "kind": "dialogue",
            "text": quote,
            "speaker": speaker,
            "position": "top_left" if len(rows) % 2 == 0 else "top_right",
        })
        seen.add(quote)
        if len(rows) >= min(3, n):
            break
    return rows

def _infer_dialogue_speaker(source, quote):
    """从引号附近的“某人终于开口/某人说”中提取干净姓名。"""
    import re as _re
    text = str(source or "")
    value = str(quote or "")
    pos = text.find(value)
    if pos < 0:
        return ""
    verbs = r'(?:说|问|喊|骂|开口|回答|答道|说道|喊道|骂道)'
    adverbs = ("终于", "随即", "轻声", "低声", "沙哑地", "冷冷地", "缓缓")

    def clean(candidate):
        candidate = str(candidate or "").strip()
        changed = True
        while changed:
            changed = False
            for suffix in adverbs:
                if candidate.endswith(suffix):
                    candidate = candidate[:-len(suffix)].strip()
                    changed = True
        if (candidate in ("他", "她", "男人", "女人", "男性", "女性")
                or any(word in candidate for word in ("声音", "男声", "女声", "陌生", "神秘"))):
            return ""
        return candidate if 2 <= len(candidate) <= 12 else ""

    after = text[pos + len(value):pos + len(value) + 60]
    match = _re.search(r'([\u4e00-\u9fff·]{2,12})' + verbs, after)
    speaker = clean(match.group(1) if match else "")
    if speaker:
        return speaker
    before = text[max(0, pos - 120):pos]
    matches = list(_re.finditer(r'([\u4e00-\u9fff·]{2,12})' + verbs, before))
    return clean(matches[-1].group(1)) if matches else ""

def extract_page_lettering(page_text, panel_count=6, visual_prompt="", names=None):
    """生成本地排字计划；所有文字必须逐字存在于原文，模型不能改写。"""
    import re as _re
    n = max(1, min(int(panel_count or 6), 8))
    sysmsg = f"""你是中文漫画编辑，只负责从本页文字剧本中挑选漫画页需要的旁白和人物对白，并映射到{n}个画格。
只输出 JSON 数组，不要解释。每项格式：
{{"panel":1,"kind":"narration或dialogue","text":"原文原句","speaker":"人物名或画外","position":"top_left或top_right或bottom_left或bottom_right"}}

硬性规则：
1. text 必须逐字复制用户原文中连续存在的文字，不得改写、缩写、纠错或补字。
2. dialogue 只选人物真正说出口的台词；酒馆名、拟声词、物品名称不算对白。
3. narration 只选真正帮助理解地点、时间、人物或关键转折的原文，整页最多2条，每条尽量不超过36个汉字。
4. 对白保留原句内容，但 text 字段不带最外层引号。
5. 同一句不能重复；总数不超过{min(6, max(3, n))}条、总文字尽量不超过130个汉字；没有价值的文字宁可不放。
6. panel 按原文事件顺序映射到第1至第{n}格。
7. 每格通常只放1条，主画面最多2条；不要让多个文字框挤在同一角落。
8. position 只给出大致角落；本地程序会在成图后自动寻找该画格相对平整的位置。人物在右侧时优先放左侧，反之亦然。"""
    visual = str(visual_prompt or "").strip()
    user_content = "【本页文字剧本（文字只能从这里逐字复制）】\n" + str(page_text or "")
    if visual:
        user_content += (
            "\n\n【已经确定的分格画面（只用于判断文字应该放第几格，"
            "禁止从这里复制或改写文字）】\n" + visual[:5000])
    raw = chat_stream(
        [{"role": "system", "content": sysmsg},
         {"role": "user", "content": user_content}],
        0.15, None, 900).strip()
    m = _re.search(r'\[[\s\S]*\]', raw)
    try:
        rows = json.loads(m.group(0) if m else raw)
    except Exception:
        rows = []
    if not isinstance(rows, list):
        rows = []
    source = str(page_text or "")
    valid = []
    seen = set()
    positions = {"top_left", "top_right", "bottom_left", "bottom_right"}
    narration_count = 0
    total_chars = 0
    per_panel = {}
    max_items = min(6, max(3, n))
    for row in rows:
        if not isinstance(row, dict):
            continue
        kind = str(row.get("kind") or "").strip().lower()
        if kind not in ("narration", "dialogue"):
            continue
        text = str(row.get("text") or "").strip()
        if kind == "dialogue":
            text = text.strip('“”"「」『』').strip()
        if not text or text in seen or text not in source:
            continue
        if kind == "narration" and narration_count >= 2:
            continue
        if len(text) > (42 if kind == "dialogue" else 38):
            continue
        # 对白必须在原文里确实带有引号；避免把酒馆名或拟声词当台词。
        if kind == "dialogue":
            quoted = any(a + text + b in source for a, b in
                         (("“", "”"), ('"', '"'), ("「", "」"), ("『", "』")))
            if not quoted:
                # 剧本对白段常用“人物名：台词”格式（无引号），同样视为有效对白。
                quoted = any(
                    _re.match(r"[^\n：:]{1,14}[：:]\s*" + _re.escape(text) + r"\s*$", seg)
                    for seg in source.splitlines())
            if not quoted or _is_pure_sound_effect(text):
                continue
        try:
            panel = max(1, min(int(row.get("panel") or 1), n))
        except Exception:
            panel = 1
        if per_panel.get(panel, 0) >= (2 if panel == 1 else 1):
            continue
        if total_chars + len(text) > 140:
            continue
        pos = str(row.get("position") or "top_left").strip()
        if pos not in positions:
            pos = "top_left"
        speaker = str(row.get("speaker") or "").strip()
        for suffix in ("终于", "随即", "轻声", "低声", "沙哑地", "冷冷地", "缓缓"):
            if speaker.endswith(suffix):
                speaker = speaker[:-len(suffix)].strip()
        if speaker and speaker != "画外" and speaker not in source:
            speaker = "画外"
        # 只认已知角色名当说话人。否则模型会把台词从中间切断，
        # 把前半句当成说话人（例："你妹妹真"说"陈牧？"），排出来的框就是乱码。
        if names and speaker and speaker != "画外" and speaker not in names:
            speaker = "画外"
        if speaker in ("男性", "女性", "男人", "女人", "男声", "女声", "声音",
                       "陌生人", "神秘人", "未知", "不明"):
            speaker = "画外"
        inferred = _infer_dialogue_speaker(source, text) if kind == "dialogue" else ""
        if inferred and speaker in ("", "画外"):
            speaker = inferred
        valid.append({
            "panel": panel, "kind": kind, "text": text,
            "speaker": speaker,
            "position": pos,
        })
        seen.add(text)
        narration_count += int(kind == "narration")
        total_chars += len(text)
        per_panel[panel] = per_panel.get(panel, 0) + 1
        if len(valid) >= max_items:
            break
    # 同一句被切成两条时（一条是另一条的片段），只留完整的那条
    valid = [a for a in valid
             if not any(b is not a and a["text"] in b["text"] and len(a["text"]) < len(b["text"])
                        for b in valid)]
    return valid or _fallback_lettering_from_quotes(source, n, names)

def _letter_panel_boxes(width, height, panel_count, layout=""):
    """返回与页级导演完全一致的画格坐标，供后期排字使用。"""
    n = max(1, min(int(panel_count or 1), 8))
    W, H = int(width), int(height)
    if layout == "hero+strip":
        y = int(H * .72)
        return [(0, 0, W, y), (0, y, W, H)]
    if layout == "hero+2":
        y = int(H * .62)
        return [(0, 0, W, y), (0, y, W // 2, H), (W // 2, y, W, H)]
    if layout == "hero+2+1":
        y1, y2 = int(H * .48), int(H * .74)
        return [(0, 0, W, y1),
                (0, y1, W // 2, y2), (W // 2, y1, W, y2),
                (0, y2, W, H)]
    if layout == "hero+2+2":
        y1, y2 = int(H * .42), int(H * .71)
        return [(0, 0, W, y1),
                (0, y1, W // 2, y2), (W // 2, y1, W, y2),
                (0, y2, W // 2, H), (W // 2, y2, W, H)]
    if layout == "2+hero+2":
        y1, y2 = int(H * .25), int(H * .70)
        return [(0, 0, W // 2, y1), (W // 2, 0, W, y1),
                (0, y1, W, y2),
                (0, y2, W // 2, H), (W // 2, y2, W, H)]
    if layout == "1+2+2+1" or (not layout and n == 6):
        ys = [0, int(H * .25), int(H * .50), int(H * .75), H]
        return [(0, ys[0], W, ys[1]),
                (0, ys[1], W // 2, ys[2]), (W // 2, ys[1], W, ys[2]),
                (0, ys[2], W // 2, ys[3]), (W // 2, ys[2], W, ys[3]),
                (0, ys[3], W, ys[4])]
    if layout == "1+2+1+1" or (not layout and n == 5):
        ys = [0, int(H * .25), int(H * .50), int(H * .75), H]
        return [(0, ys[0], W, ys[1]),
                (0, ys[1], W // 2, ys[2]), (W // 2, ys[1], W, ys[2]),
                (0, ys[2], W, ys[3]), (0, ys[3], W, ys[4])]
    rows = (n + 1) // 2
    boxes = []
    for i in range(n):
        row = i // 2; col = i % 2
        y1, y2 = int(H * row / rows), int(H * (row + 1) / rows)
        if i == n - 1 and n % 2:
            boxes.append((0, y1, W, y2))
        else:
            boxes.append((col * W // 2, y1, (col + 1) * W // 2, y2))
    return boxes

def _letter_box_size(draw, text, max_w, max_h, bold=False, start_size=27, min_size=18):
    """在限定区域里自动缩字号，确保中文完整放入。"""
    no_line_start = set("，。！？；：、）》”】」』")
    min_size = max(15, int(min_size))
    for size in range(int(start_size), min_size - 1, -1):
        font = _font(size, bold)
        lines = _wrap(draw, text, font, max_w)
        line_h = size + max(6, size // 3)
        bad_wrap = any(line and line[0] in no_line_start for line in lines[1:])
        if lines and not bad_wrap and len(lines) * line_h <= max_h:
            return font, lines, line_h
    font = _font(min_size, bold)
    return font, _wrap(draw, text, font, max_w), min_size + max(6, min_size // 3)

def _rect_overlap_area(a, b):
    x1, y1 = max(a[0], b[0]), max(a[1], b[1])
    x2, y2 = min(a[2], b[2]), min(a[3], b[3])
    return max(0, x2 - x1) * max(0, y2 - y1)

def _letter_region_density(image, rect):
    """估算候选区域的视觉繁忙程度；优先把字放在平整、低细节的负空间。"""
    from PIL import ImageFilter, ImageStat
    x1, y1, x2, y2 = [int(v) for v in rect]
    crop = image.crop((max(0, x1), max(0, y1), min(image.width, x2), min(image.height, y2)))
    if crop.width < 2 or crop.height < 2:
        return 9999.0
    crop.thumbnail((180, 180))
    gray = crop.convert("L")
    stat = ImageStat.Stat(gray)
    variance = float(stat.var[0]) ** .5
    edges = ImageStat.Stat(gray.filter(ImageFilter.FIND_EDGES)).mean[0]
    # 轮廓密集通常意味着脸、手、武器或复杂背景；方差用于回避高反差区域。
    return edges * 1.9 + variance * .7

def _best_letter_rect(image, panel_box, bw, bh, outer, preferred, occupied):
    x1, y1, x2, y2 = panel_box
    candidates = {
        "top_left": (x1 + outer, y1 + outer),
        "top_right": (x2 - bw - outer, y1 + outer),
        "bottom_left": (x1 + outer, y2 - bh - outer),
        "bottom_right": (x2 - bw - outer, y2 - bh - outer),
    }
    best = None
    for name, (bx, by) in candidates.items():
        bx = max(5, min(int(bx), image.width - int(bw) - 5))
        by = max(5, min(int(by), image.height - int(bh) - 5))
        rect = (bx, by, bx + int(bw), by + int(bh))
        density = _letter_region_density(image, rect)
        overlap = sum(_rect_overlap_area(rect, old) for old in occupied)
        score = density + overlap / max(1, bw * bh) * 1000
        if name != preferred:
            score += 4.0  # 模型建议只是轻微偏好，实际图像空白度优先。
        if best is None or score < best[0]:
            best = (score, rect, name)
    return best[1], best[2]

def add_lettering_to_page(img_path, plan, out_path, panel_count=6, layout="",
                           lettering_size="compact"):
    """把经原文校验的旁白框/对白气泡绘制到漫画页，保留无字原图。"""
    _letter_t0 = time.time()
    from PIL import Image, ImageDraw
    from PIL.PngImagePlugin import PngInfo
    im = Image.open(img_path).convert("RGB")
    W, H = im.size
    draw = ImageDraw.Draw(im, "RGBA")
    boxes = _letter_panel_boxes(W, H, panel_count, layout)
    rendered = 0
    occupied = []
    scale = {"compact": .76, "balanced": 1.0, "large": 1.16}.get(
        str(lettering_size or "").lower(), .76)
    for item in plan or []:
        try:
            panel = max(1, min(int(item.get("panel") or 1), len(boxes)))
        except Exception:
            panel = 1
        x1, y1, x2, y2 = boxes[panel - 1]
        pw, ph = x2 - x1, y2 - y1
        kind = str(item.get("kind") or "narration")
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        kind = str(item.get("kind") or "narration")
        if kind == "dialogue":
            text = text.strip('“”"「」『』')
            # v2.6起气泡只渲染 visibleText；speakerId 仅作内部逻辑，
            # 禁止把角色姓名/冒号重新拼进可见文字。
        pad = max(11, W // 82)
        outer = max(14, W // 64)
        max_w = min(int(pw * .78), int(W * .46))
        max_h = min(int(ph * .48), int(H * .13))
        if kind == "sfx":
            font, lines, line_h = _letter_box_size(
                draw, text, max_w, max_h, False,
                int(W * .045), max(22, int(W * .028)))
            if not lines:
                continue
            sy = y2 - len(lines) * line_h - pad
            for line in lines:
                draw.text((x1 + pad, sy), line, font=font,
                          fill=(170, 25, 20, 255))
                sy += line_h
            rendered += 1
            occupied.append((x1, y2 - len(lines) * line_h - 2 * pad, x2, y2))
            continue
        base = max(19, int(W * .028 * scale))
        minimum = max(16, int(W * .019 * scale))
        font, lines, line_h = _letter_box_size(
            draw, text, max_w - 2 * pad, max_h - 2 * pad,
            kind == "narration", base - 1 if kind == "narration" else base,
            minimum)
        if not lines:
            continue
        tw = int(max(draw.textlength(line, font=font) for line in lines))
        bw = min(max_w, tw + 2 * pad)
        bh = len(lines) * line_h + 2 * pad
        pos = str(item.get("position") or "top_left")
        chosen, actual_pos = _best_letter_rect(
            im, (x1, y1, x2, y2), bw, bh, outer, pos, occupied)
        bx, by, rx, ry = chosen
        rect = [bx, by, rx, ry]
        if kind == "dialogue":
            draw.rounded_rectangle(rect, radius=max(16, W // 55),
                                   fill=(255, 255, 252, 242),
                                   outline=(20, 18, 15, 255), width=max(2, W // 360))
        elif kind == "innerThought":
            draw.rounded_rectangle(rect, radius=max(14, W // 60),
                                   fill=(232, 240, 252, 235),
                                   outline=(50, 90, 170, 255),
                                   width=max(2, W // 360))
            draw.ellipse([bx + bw - 18, by + bh - 8, bx + bw - 6, by + bh + 8],
                         fill=(232, 240, 252, 235),
                         outline=(50, 90, 170, 255), width=max(2, W // 400))
        else:
            draw.rounded_rectangle(rect, radius=max(5, W // 150),
                                   fill=(245, 235, 210, 238),
                                   outline=(80, 55, 30, 255), width=max(2, W // 360))
            draw.rectangle([bx, by, bx + max(7, W // 100), by + bh],
                           fill=(125, 80, 35, 255))
        yy = by + pad
        for line in lines:
            draw.text((bx + pad + (4 if kind == "narration" else 0), yy),
                      line, font=font, fill=(25, 22, 18, 255))
            yy += line_h
        rendered += 1
        occupied.append(tuple(rect))
        item["rendered_position"] = actual_pos
    meta = PngInfo()
    try:
        with Image.open(img_path) as src_meta:
            src_info = dict(src_meta.info)
            if src_info.get("prompt"):
                meta.add_text("prompt", src_info["prompt"])
    except Exception:
        pass
    meta.add_text("lettering_plan", json.dumps(plan or [], ensure_ascii=False))
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    im.save(out_path, pnginfo=meta)
    calib_record("lettering", time.time() - _letter_t0)
    return rendered


def _render_world_text_overlay(img_path, overlay, out_path):
    """本地把家族死亡记录刻入中央石碑安全区（纯本地，不调用模型）。
    无半透明矩形/UI面板；两层文字制造凹刻感；不覆盖分隔线与人物。"""
    from PIL import Image, ImageDraw, ImageFont
    im = Image.open(img_path).convert("RGB")
    W, H = im.size
    draw = ImageDraw.Draw(im, "RGBA")
    candidates = (
        r"C:\Windows\Fonts\timesbd.ttf", r"C:\Windows\Fonts\times.ttf",
        r"C:\Windows\Fonts\georgiab.ttf", r"C:\Windows\Fonts\georgia.ttf",
        r"C:\Windows\Fonts\simhei.ttf", r"C:\Windows\Fonts\simsun.ttc",
    )
    font_path = next((f for f in candidates if os.path.exists(f)), None)
    if not font_path:
        raise RuntimeError("找不到可用字体")
    title_font = ImageFont.truetype(font_path, 22)
    row_font = ImageFont.truetype(font_path, 14)
    # 中央石碑安全区（固定）：位于下格中部，避开上下格分隔线与石碑边框。
    x0 = int(W * 0.34)
    x1 = int(W * 0.66)
    y0 = int(H * 0.74)
    box_w = x1 - x0

    def fit_text(text, font, max_w):
        text = str(text or "")
        while font.getlength(text) > max_w and len(text) > 1:
            text = text[:-1]
        return text

    title = fit_text(str(overlay.get("title") or "DEATH REGISTER"),
                     title_font, box_w - 16)
    rows = (overlay.get("rows") or [])[:6]
    highlight = int(overlay.get("highlightRow") or 0)
    y = y0 + 8
    # 两层文字：底层向右下偏移2px深灰低透明度，上层浅灰偏暗。
    for layer in (0, 1):
        dx = 2 if layer else 0
        dy = y + (2 if layer else 0)
        draw.text((x0 + 8 + dx, dy), title, font=title_font,
                  fill=(28, 26, 30, 90) if layer == 0 else (172, 162, 142, 190))
    y += 30
    for i, row in enumerate(rows):
        name = fit_text(str(row.get("name") or ""), row_font, int(box_w * 0.56))
        date = fit_text(str(row.get("date") or ""), row_font, int(box_w * 0.38))
        for layer in (0, 1):
            dx = 2 if layer else 0
            dy = y + (2 if layer else 0)
            fill = (28, 26, 30, 90) if layer == 0 else (166, 156, 136, 180)
            draw.text((x0 + 12 + dx, dy), name, font=row_font, fill=fill)
            draw.text((x0 + box_w - 12 - dx, dy), date, font=row_font,
                      anchor="ra", fill=fill)
        if i == highlight:
            draw.line([x0 + 10, y + 19, x1 - 10, y + 19],
                      fill=(140, 40, 40, 170), width=2)
        y += 24
    im.save(out_path)
    return 1


def add_caption_to_page(img_path, caption, out_path):
    """把对白排版到整页图底部的对白条上，另存为成品页。无对白则原样另存。"""
    from PIL import Image, ImageDraw
    im = Image.open(img_path).convert("RGB"); W, H = im.size
    cap = (caption or "").strip()
    if not cap or cap in ("无", "（无）", "none", "None"):
        im.save(out_path); return 0
    pad = 26; fs = max(26, W // 30); lh = fs + 14
    font = _font(fs)
    d0 = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    lines = _wrap(d0, cap, font, W - 2 * pad)
    ch = pad * 2 + len(lines) * lh
    canvas = Image.new("RGB", (W, H + ch), (247, 244, 236))
    canvas.paste(im, (0, 0))
    d = ImageDraw.Draw(canvas)
    d.line([(0, H + 1), (W, H + 1)], fill=(150, 140, 120), width=3)
    y = H + pad
    for ln in lines:
        d.text((pad, y), ln, font=font, fill=(28, 24, 18)); y += lh
    canvas.save(out_path); return len(lines)

# ==================== 剧本：漫画工作流的一等产物 ====================
# 剧本独立存盘（不挂在小说下面），因为漫画工作流可以脱离小说单独跑。
# 每页存的是“结构化分格”而不是编译后的提示词字符串——这样才能改、才能单页重出。
SCRIPT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "剧本")
os.makedirs(SCRIPT_DIR, exist_ok=True)

def script_path(name):
    return os.path.join(SCRIPT_DIR, safe_name(name) + ".json"), safe_name(name)

def script_series_meta(script, fallback_title=""):
    """兼容新旧剧本，返回稳定的系列名和话数。"""
    title = str(script.get("title") or fallback_title or "未命名").strip()
    series_title = str(script.get("seriesTitle") or "").strip()
    episode_no = int(script.get("episodeNo") or 0)
    match = re.match(r"^(.*?)·第(\d+)话$", title)
    if not series_title:
        series_title = (match.group(1).strip() if match else title) or "未命名"
    if episode_no <= 0:
        episode_no = int(match.group(2)) if match else 1
    return series_title, max(1, episode_no)

def comic_episode_digest(title, page_texts, episode_no=1):
    """用逐页施工文字生成轻量连续性记录，不额外调用模型。"""
    lines = []
    for i, text in enumerate(page_texts or [], 1):
        clean = re.sub(r"\s+", " ", str(text or "")).strip()
        if clean:
            lines.append("第%d页：%s" % (i, clean[:180]))
    return {
        "episodeNo": max(1, int(episode_no or 1)),
        "title": str(title or "").strip(),
        "digest": "\n".join(lines)[:2600],
    }

def list_scripts():
    out = []
    for f in sorted(os.listdir(SCRIPT_DIR)):
        if not f.endswith(".json"):
            continue
        # 新漫画在生成剧本前会先保存一份设定图草稿。它只是供预览图、单张重出
        # 和提示词核对使用，不应混进“已有剧本 / 继续下一话”的列表。
        if f.startswith("__设定草稿__"):
            continue
        p = os.path.join(SCRIPT_DIR, f)
        try:
            d = json.load(open(p, encoding="utf-8"))
            pages = d.get("pages") or []
            done = len([x for x in pages if _valid_panel_image(
                os.path.join(COMIC_DIR, *str(x.get("image") or "").replace("\\", "/").split("/"))
                if x.get("image") else "")])
            series_title, episode_no = script_series_meta(d, f[:-5])
            out.append({"name": f[:-5], "title": d.get("title") or f[:-5],
                        "pages": len(pages), "done": done,
                        "source": (d.get("source") or {}).get("type", ""),
                        "seriesTitle": series_title, "episodeNo": episode_no,
                        "previousEpisode": d.get("previousEpisode") or
                                           (d.get("source") or {}).get("continueFrom", ""),
                        "updatedAt": os.path.getmtime(p)})
        except Exception:
            continue
    out.sort(key=lambda x: x.get("updatedAt", 0), reverse=True)
    return out

def load_script(name):
    p, _ = script_path(name)
    if not os.path.exists(p):
        raise RuntimeError("找不到剧本：" + str(name))
    script = json.load(open(p, encoding="utf-8"))
    if script.get("charSheet"):
        script["charSheet"] = _clean_char_sheet_text(script.get("charSheet"))
    return script

def save_script(script):
    name = script.get("name") or script.get("title") or "未命名剧本"
    p, safe = script_path(name)
    script["name"] = safe
    script.setdefault("directorVersion", "stable_fullpage_core_v1")
    if not script.get("originalDirectorVersion"):
        script["originalDirectorVersion"] = script["directorVersion"]
    script["currentDirectorVersion"] = script["directorVersion"]
    script["updatedAt"] = time.time()
    atomic_write_json(p, script)
    return p

def setting_confirmation_snapshot(data):
    """用户确认时锁定的基础设定；逐页内容和图片不属于这个阶段。"""
    lead_options = data.get("leadOptions") if isinstance(data.get("leadOptions"), dict) else {}
    character_options = (data.get("characterOptions")
                         if isinstance(data.get("characterOptions"), list) else [])
    if not character_options and lead_options:
        character_options = [lead_options]
    return {
        "charSheet": _clean_char_sheet_text(data.get("charSheet")),
        "sceneSetting": str(data.get("sceneSetting") or data.get("worldSetting") or "").strip(),
        "designDirection": str(data.get("designDirection") or "").strip(),
        "episodeSynopsis": str(data.get("episodeSynopsis") or "").strip(),
        "themeCategory": str(data.get("themeCategory") or "auto").strip(),
        "designMood": str(data.get("designMood") or "auto").strip(),
        "aestheticExtra": str(data.get("aestheticExtra") or "").strip(),
        "scenePreset": str(data.get("scenePreset") or "auto").strip(),
        "sceneScale": str(data.get("sceneScale") or "auto").strip(),
        "sceneLight": str(data.get("sceneLight") or "auto").strip(),
        "contentBias": str(data.get("contentBias") or "").strip(),
        "contentBiasCustom": str(data.get("contentBiasCustom") or "").strip(),
        "characterOptions": character_options,
        "art": _norm_art(data.get("art")),
    }

def setting_confirmation_hash(data):
    snapshot = setting_confirmation_snapshot(data)
    return hashlib.sha256(json.dumps(
        snapshot, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:24]

def save_setting_draft(data):
    """保存“先确认基础设定”阶段的临时资料；这里永远不保存逐页剧本。"""
    series_title = str(data.get("seriesTitle") or data.get("title") or "新漫画").strip()
    requested = str(data.get("name") or "").strip()
    if not requested.startswith("__设定草稿__"):
        requested = "__设定草稿__" + safe_name(series_title)
    old = {}
    try:
        old = load_script(requested)
    except Exception:
        pass
    series_id = str(old.get("seriesId") or "").strip() or os.urandom(6).hex()
    char_sheet = _clean_char_sheet_text(data.get("charSheet"))
    scene_setting = str(data.get("sceneSetting") or "").strip()
    design_direction = str(data.get("designDirection") or "").strip()
    episode_synopsis = str(data.get("episodeSynopsis") or "").strip()
    theme_category = str(data.get("themeCategory") or "auto").strip()
    design_mood = str(data.get("designMood") or "auto").strip()
    aesthetic_extra = str(data.get("aestheticExtra") or "").strip()
    scene_preset = str(data.get("scenePreset") or "auto").strip()
    scene_scale = str(data.get("sceneScale") or "auto").strip()
    scene_light = str(data.get("sceneLight") or "auto").strip()
    lead_options = data.get("leadOptions") if isinstance(data.get("leadOptions"), dict) else {}
    character_options = (data.get("characterOptions")
                         if isinstance(data.get("characterOptions"), list) else [])
    if not character_options and lead_options:
        character_options = [lead_options]
    art = _norm_art(data.get("art"))
    world_rules = data.get("projectWorldRules") if isinstance(
        data.get("projectWorldRules"), dict) else None
    if not world_rules and isinstance(old.get("projectWorldRules"), dict):
        world_rules = old["projectWorldRules"]  # 同系列草稿内延续，跨系列不共享
    world_rules = world_rules if isinstance(world_rules, dict) else {}
    current_confirmation_hash = setting_confirmation_hash(data)
    confirm_now = bool(data.get("confirmNow"))
    keep_confirmation = (
        not confirm_now and bool(data.get("settingConfirmed")) and
        bool(old.get("settingConfirmed")) and
        str(old.get("confirmedSettingsHash") or "") == current_confirmation_hash
    )
    setting_confirmed = confirm_now or keep_confirmation
    confirmed_at = (time.time() if confirm_now else
                    (old.get("confirmedAt") if keep_confirmation else None))
    confirmed_snapshot = (setting_confirmation_snapshot(data) if confirm_now else
                          (old.get("confirmedSnapshot") if keep_confirmation else {}))
    settings_hash = hashlib.sha256(json.dumps({
        "charSheet": char_sheet, "sceneSetting": scene_setting,
        "designDirection": design_direction, "themeCategory": theme_category,
        "designMood": design_mood, "aestheticExtra": aesthetic_extra,
        "scenePreset": scene_preset,
        "sceneScale": scene_scale, "sceneLight": scene_light,
        "contentBias": str(data.get("contentBias") or "").strip(),
        "contentBiasCustom": str(data.get("contentBiasCustom") or "").strip(),
        "leadOptions": lead_options,
        "characterOptions": character_options, "art": art,
    }, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:20]
    old_assets = old.get("assets") if old.get("settingsHash") == settings_hash else {}
    supplied_assets = data.get("assets") if isinstance(data.get("assets"), dict) else None
    draft = {
        "name": requested,
        # 设定图直接归档到“漫画/系列名/设定图”，正式第1话只引用它们，不复制、不重画。
        "title": series_title,
        "seriesTitle": series_title,
        "seriesId": series_id,
        "episodeNo": 0,
        "isSettingDraft": True,
        "settingsHash": settings_hash,
        "art": art,
        "projectWorldRules": world_rules,
        "seriesBible": data.get("seriesBible") if isinstance(
            data.get("seriesBible"), dict) else {},
        "charSheet": char_sheet,
        "sceneSetting": scene_setting,
        "settingWorld": scene_setting,
        "designDirection": design_direction,
        "themeCategory": theme_category,
        "designMood": design_mood,
        "aestheticExtra": aesthetic_extra,
        "scenePreset": scene_preset,
        "sceneScale": scene_scale, "sceneLight": scene_light,
        "contentBias": str(data.get("contentBias") or "").strip(),
        "contentBiasCustom": str(data.get("contentBiasCustom") or "").strip(),
        "seriesPlanText": str(data.get("seriesPlanText") or "").strip(),
        "leadOptions": lead_options,
        "characterOptions": character_options,
        "episodeSynopsis": episode_synopsis,
        # 逐页内容只能在用户确认设定并生成本话之后产生。
        "episodeOutline": "",
        "currentSettingsHash": current_confirmation_hash,
        "settingConfirmed": setting_confirmed,
        "confirmedSettingsHash": current_confirmation_hash if setting_confirmed else "",
        "confirmedAt": confirmed_at,
        "confirmedSnapshot": confirmed_snapshot,
        "worldLock": "",
        "source": {"type": "setting_draft"},
        "pages": [],
        "assets": supplied_assets if supplied_assets is not None else (old_assets or {}),
        "sceneAssetMode": "off",
        "sceneAssetHashes": dict(old.get("sceneAssetHashes") or {}),
        "createdAt": old.get("createdAt") or time.time(),
    }
    save_script(draft)
    return draft

def _hero_page_hard_facts(script, page):
    """单格整页的页级硬事实：本页不出场人物、关键事件、禁止道具。"""
    facts = {}
    on_page = set()
    for item in (page.get("characters") or []):
        if isinstance(item, dict) and str(item.get("name") or "").strip():
            on_page.add(_staging_base_name(str(item["name"])))
    for p in (page.get("panels") or []):
        if not isinstance(p, dict):
            continue
        for n in (p.get("people") or []):
            if str(n or "").strip():
                on_page.add(_staging_base_name(str(n)))
    forbidden = []
    for name in ((script.get("comicAnchors") or {}).keys()):
        base = _staging_base_name(str(name))
        if base and base not in on_page and base not in forbidden:
            forbidden.append(base)
    if forbidden:
        facts["forbidden"] = forbidden[:6]
    try:
        idx = max(0, int(page.get("page") or 1) - 1)
    except Exception:
        idx = -1
    events = []
    if idx >= 0:
        eplan = script.get("episodePlan") if isinstance(
            script.get("episodePlan"), dict) else {}
        pplans = eplan.get("pagePlans") or []
        if idx < len(pplans) and isinstance(pplans[idx], dict):
            pids = [str(x) for x in (pplans[idx].get("primaryEventIds") or [])
                    if str(x).strip()]
            crit = eplan.get("episode") if isinstance(
                eplan.get("episode"), dict) else {}
            ev_map = {}
            for ev in (crit.get("criticalEvents") or []):
                if isinstance(ev, dict) and str(ev.get("eventId") or "").strip():
                    ev_map[str(ev["eventId"]).strip()] = str(ev.get("event") or "")
            for pid in pids:
                txt = ev_map.get(pid)
                events.append("%s：%s" % (pid, txt) if txt else pid)
    if events:
        facts["primaryEvents"] = events[:4]
    rules = script.get("projectWorldRules") if isinstance(
        script.get("projectWorldRules"), dict) else {}
    restricted = [str(x).strip() for x in (rules.get("restrictedElements") or [])
                  if str(x).strip()]
    if restricted:
        facts["restrictedItems"] = restricted[:6]
    return facts or None


def script_page_prompt(script, page):
    """把剧本里某一页的结构化分格，重新编译成生图提示词。
    用户改了分格文字后，重出这一页就是重走这个函数——不再问模型。"""
    art = _norm_art(script.get("art"))
    if "极致写实的真人电影剧照" in art:
        art = (
            "写实真人电影感，成人商业漫画质感，真实自然的演员面孔、皮肤与人体结构，"
            "电影级场景布光，清晰主体与自然景深，photorealistic"
        )
    plan = {
        "layout": page.get("layout") or "",
        "scene": page.get("scene") or "",
        "light": page.get("light") or "",
        "characters": page.get("characters") or [],
        "panels": json.loads(json.dumps(page.get("panels") or [], ensure_ascii=False)),
        "stagingScene": page.get("stagingScene") or {},
    }
    if isinstance(plan["stagingScene"], dict) and \
            str(page.get("scene") or "").strip():
        # 进入新场景（如六角石室）后，公共场景名以页面实际地点为准，
        # 不再被长期主场景名覆盖。
        plan["stagingScene"] = dict(plan["stagingScene"])
        plan["stagingScene"]["sceneName"] = str(page.get("scene")).strip()
    fixed_cards = parse_char_sheet(script.get("charSheet") or "")
    page_story = str(page.get("source_text") or "")
    episode_context = str(script.get("episodeSynopsis") or "")
    try:
        is_continuation = bool(script.get("previousEpisode")) or int(
            script.get("episodeNo") or 1) > 1
    except Exception:
        is_continuation = bool(script.get("previousEpisode"))
    weapon_words = (
        "法杖", "魔杖", "长剑", "短剑", "佩剑", "刀", "枪", "弓", "弩",
        "锤", "斧", "武器",
    )
    weapon_removed_this_page = (
        any(word in page_story for word in weapon_words) and
        any(state in page_story for state in (
            "脱手", "掉进", "掉入", "丢失", "遗失", "被夺走", "被抢走",
            "折断", "断裂", "碎裂", "消失在", "不在手中", "空着双手",
            "不见踪影", "无杖", "空空无杖",
        ))
    )
    persistent_weapon_removed = (
        is_continuation and any(word in episode_context for word in weapon_words) and
        any(state in episode_context for state in (
            "仍留在镜中", "仍在镜中", "仍然丢失", "依旧丢失", "没有找回",
            "未找回", "右手空着", "空手状态",
        ))
    )
    weapon_removed_this_page = weapon_removed_this_page or persistent_weapon_removed
    persistent_states = []
    if is_continuation and "左肩" in episode_context and any(
            state in episode_context for state in (
                "左肩伤口继续流血", "左肩仍在流血", "保持左肩受伤", "左肩受伤",
            )) and not any(
                state in episode_context for state in ("伤口愈合", "已经止血", "完成包扎")
            ):
        persistent_states.append("左肩外套保持破口，伤口持续流血")
    if persistent_weapon_removed:
        persistent_states.append("右手掌心与五指完整可见")
    if weapon_removed_this_page:
        for panel in plan["panels"]:
            if not isinstance(panel, dict):
                continue
            visible = str(panel.get("visible") or "")
            visible = visible.replace("右手空空无杖", "右手张开，掌心与五指完整可见")
            visible = visible.replace("左手空空无杖", "左手张开，掌心与五指完整可见")
            visible = visible.replace("双手空空无杖", "双手张开，掌心与五指完整可见")
            panel["visible"] = visible
    def base_name(value):
        return re.sub(r"\s*[（(][^）)]*[）)]\s*$", "", str(value or "")).strip()
    def prompt_card(value):
        parts = [x.strip() for x in re.split(r"[；;\n]+", str(value or "")) if x.strip()]
        visual_first = []
        for terms in (("发", "辫", "马尾"), ("内搭", "上装", "外套", "风衣", "长袍",
                       "披风", "马甲"), ("腰", "下装", "裙", "裤"), ("鞋", "靴"),
                      ("脸", "眉", "眼", "鼻", "唇", "肤色"), ("痣", "疤", "纹身"),
                      ("男", "女", "年龄", "岁"), ("身高", "头身", "肩宽", "腰围")):
            visual_first.extend(x for x in parts if x not in visual_first and
                                any(k in x for k in terms))
        visual_first.extend(x for x in parts if x not in visual_first)
        hair = next((x for x in visual_first if any(k in x for k in ("发", "辫", "马尾"))), "")
        clothes = next((x for x in visual_first if any(
            k in x for k in ("内搭", "上装", "外套", "风衣", "长袍", "披风", "马甲"))), "")
        if hair and clothes:
            visual_first = [hair + "，" + clothes] + [
                x for x in visual_first if x not in (hair, clothes)]
        return "；".join(visual_first)
    trusted = {}
    anchors_map = {}
    for anchor_name, anchor_val in ((script.get("comicAnchors") or {}).items()):
        if isinstance(anchor_val, dict) and \
                str(anchor_val.get("comicAnchor") or "").strip():
            anchors_map[base_name(str(anchor_name))] = \
                str(anchor_val["comicAnchor"]).strip()
    for item in (page.get("characters") or []):
        if isinstance(item, dict) and item.get("name"):
            name = str(item["name"]).strip()
            fixed = fixed_cards.get(name) or next((
                look for card_name, look in fixed_cards.items()
                if base_name(card_name) == base_name(name)), "")
            # 固定 comicAnchor 原样复用：同一人物每一页使用完全相同的锚点，
            # 不再每页重新概括；旧剧本没有 comicAnchors 时退回原来的确定性概括。
            card = anchors_map.get(base_name(name)) or (
                prompt_card(fixed) if fixed else str(item.get("anchors") or ""))
            # 本页明确写了武器脱手、丢失、损坏或被夺走时，固定人物卡只保留
            # 外貌与服装。武器仍由本页动作描述一次，不能又作为“固定携带物”
            # 塞回同一格，否则就会出现法杖刚掉进镜子、下一格又回到手里的错误。
            if weapon_removed_this_page:
                card = "；".join(
                    part for part in card.split("；")
                    if not any(word in part for word in weapon_words)
                )
            trusted[name] = card
    fallback = {"layout": page.get("layout") or "",
                "panels": len(page.get("panels") or []) or 1,
                "description": "", "purpose": ""}
    single = int(page.get("panel_count") or 0) == 1 or str(page.get("layout") or "") == "hero"
    evidence_facts = {"text": page_story}
    try:
        ev_idx = max(0, int(page.get("page") or 1) - 1)
    except Exception:
        ev_idx = -1
    if ev_idx >= 0:
        eplan = script.get("episodePlan") if isinstance(
            script.get("episodePlan"), dict) else {}
        ev_plans = eplan.get("pagePlans") or []
        if ev_idx < len(ev_plans) and isinstance(ev_plans[ev_idx], dict):
            evidence_facts["plan"] = ev_plans[ev_idx]
    need_evidence, evidence_objs = _requires_detail_evidence(
        evidence_facts, page_story)
    if single and need_evidence:
        # 关键小物件证据页：旧 hero 页重出时自动转 2 格（大格互动+小格物体特写），不写盘。
        base_panels = [p for p in (plan.get("panels") or []) if isinstance(p, dict)][:1]
        owner = ""
        for item in (page.get("characters") or []):
            if isinstance(item, dict) and str(item.get("name") or "").strip():
                owner = str(item["name"]).strip()
                break
        if not any(o in json.dumps(base_panels, ensure_ascii=False)
                   for o in evidence_objs):
            base_panels = base_panels + [_evidence_panel(evidence_objs, owner)]
        plan["panels"] = base_panels
        plan["mustVisibleObjects"] = _must_visible_objects(evidence_objs, owner)
        fallback = {"layout": "hero+strip", "panels": 2,
                    "description": "", "purpose": ""}
        single = False
    # 旧数据缺 enclosureMode：按位置/场景确定性回退，只改内存副本。
    scene_name = str(page.get("scene") or "")
    for panel in (plan.get("panels") or []):
        if isinstance(panel, dict) and not str(
                panel.get("staging_enclosure_mode") or "").strip():
            panel["staging_enclosure_mode"] = _infer_enclosure_mode(
                panel.get("staging_space_mode"), scene_name,
                panel.get("staging_subLocation"))
    # 面板身份一致性：矛盾时用确认人物卡确定性修正（不调模型）。
    for panel in (plan.get("panels") or []):
        if not isinstance(panel, dict):
            continue
        p_errs = validate_panel_identity_consistency(panel, trusted, page_story)
        if p_errs:
            log("⚠ 面板身份矛盾（确定性修正）：%s" % "；".join(p_errs[:3]))
            _fix_panel_identity(panel, trusted)
    reflection_rule = _detect_reflection_rule(
        page_story, evidence_facts.get("plan"),
        [str(c.get("name") or "") for c in (page.get("characters") or [])])
    if reflection_rule:
        r_errors = validate_reflection_rule(reflection_rule)
        if r_errors:
            raise RuntimeError("镜像规则自相矛盾：" + "；".join(r_errors))
        # 镜像页面板文本净化：禁止“镜前无人影”这类会删除现实人物的表达。
        char = str(reflection_rule.get("character") or "人物")
        for panel in (plan.get("panels") or []):
            if not isinstance(panel, dict):
                continue
            for key in ("visible", "action", "subject"):
                v = str(panel.get(key) or "")
                if "镜前无人影" in v:
                    v = v.replace(
                        "镜前无人影",
                        "镜面内对应位置为空，镜中不反射%s" % char)
                    panel[key] = v
    hero_facts = _hero_page_hard_facts(script, page) if single else None
    body, direction = _compile_onepage_plan(plan, fallback, False,
                                            trusted_characters=trusted,
                                            single_frame=single,
                                            verbatim_anchors=set(anchors_map),
                                            hero_hard_facts=hero_facts)
    if not body:
        return "", direction
    if weapon_removed_this_page or persistent_states:
        current_states = list(persistent_states)
        for panel in plan["panels"]:
            if not isinstance(panel, dict):
                continue
            visible = _short_visual(panel.get("visible"), 72)
            if visible and visible not in current_states:
                current_states.append(visible)
        if current_states:
            body = (
                "本页人物当前状态优先于固定装备：" +
                "；".join(current_states[:3]) + "。" + body
            )
    # 主要场景设定图只用于核对整部作品的空间审美，不是所有页面的固定摄影棚。
    # 正式漫画只锁本页剧情实际发生的地点；整张场景卡不再逐页硬注入。
    world = str(page.get("scene") or "").strip()
    night = _is_night_page(page_story, world, evidence_facts.get("plan"))
    if night:
        world = _filter_daytime_text(world)
    if world:
        body = "本页剧情地点与整体美术：" + world + "。" + body
    if night:
        body = body + "。" + _night_window_rule()
    reflection_text = _reflection_rule_text(reflection_rule)
    if reflection_text:
        body = body + "。" + reflection_text
    overlay = _build_world_text_overlay(script, page_story)
    overlay_hint = _world_text_overlay_prompt_hint(overlay) if overlay else ""
    if overlay_hint:
        body = body + "。" + overlay_hint
    world_text = _world_text_rule(script.get("projectWorldRules"))
    if world_text:
        body = body + "。世界内文字：" + world_text
    return _style_locked_prompt(body, art, single_frame=single), direction

def _compact_visual_for(anchor):
    """从 comicAnchor 提取紧凑视觉描述：性别年龄感/发型/主要服装/一个稳定特征。
    不保留人物姓名；长袍强制长袖。"""
    text = str(anchor or "").strip()
    text = re.sub(r"^[^，,。；;]{1,10}[，,]", "", text)  # 去掉姓名段
    parts = [p.strip("。；;，,、 ") for p in re.split(r"[。；;，,、]", text) if p.strip()]
    whole = "".join(parts)
    gender = "男" if "男" in whole[:8] else ("女" if "女" in whole[:8] else "")
    if "青年" in whole:
        age = "青年"
    elif "老年" in whole or "58岁" in whole or "60岁" in whole:
        age = "老年"
    elif "成年" in whole:
        age = "成年"
    else:
        age = ""
    hair = next((p[:8] for p in parts if any(k in p for k in ("发", "辫", "马尾"))), "")
    cloths = [p[:20] for p in parts if any(
        k in p for k in ("袍", "服", "衣", "裙", "装", "裤", "靴", "鞋",
                         "外套", "风衣", "马甲", "包")) and
        not any(k in p for k in ("发", "辫"))]
    cloth_joined = []
    for c in cloths:
        if "长袍" in c and "袖" not in c:
            c = c.replace("长袍", "长袖长袍")
        if c not in cloth_joined:
            cloth_joined.append(c)
    cloth = "、".join(cloth_joined[:4])[:40]
    mark = next((p[:10] for p in parts if any(
        k in p for k in ("疤", "耳钉", "痣", "纹身"))), "")
    bits = []
    if gender or age:
        bits.append((gender or "") + (age or "") + "感")
    if hair:
        bits.append(hair)
    if cloth:
        bits.append(cloth)
    if mark:
        bits.append(mark)
    return "，".join(bits)[:52]


def _card_text_for(character, comic_anchor, char_card):
    """从已确认人物卡或comicAnchor取人物描述文本。"""
    if isinstance(char_card, dict):
        base = _staging_base_name(str(character))
        for name, look in char_card.items():
            if _staging_base_name(str(name)) == base:
                return str(look or "")
        if str(character or "").strip() in char_card:
            return str(char_card[str(character)].strip())
    return str(comic_anchor or "")


def _hair_anchor_for(character, comic_anchor, char_card):
    """从已确认人物卡提取发型短语（如“黑色长直发扎成高马尾”）。"""
    card = _card_text_for(character, comic_anchor, char_card)
    hairs = []
    for sentence in re.split(r"[。；;]", card):
        for p in re.split(r"[，,、]", sentence):
            p = p.strip("。；;，,、 ：:()（）\"'")
            if p and any(k in p for k in ("发", "马尾", "辫")):
                hairs.append(p)
    return "".join(hairs)[:40]


def _hair_style(hair_anchor):
    """发型类别：long/short，用于清除旧分镜中冲突发型。"""
    if any(k in str(hair_anchor or "") for k in
           ("马尾", "长直发", "长发", "盘发", "辫")):
        return "long"
    if any(k in str(hair_anchor or "") for k in ("短发", "齐耳", "寸头", "板寸")):
        return "short"
    return ""


def _clean_hair_conflicts(text, hair_styles):
    """已确认发型优先：删除与人物卡发型冲突的旧分镜描述。
    只清理发型词，保留动作、姿势、表情与朝向。"""
    text = str(text or "")
    styles = [s for s in (hair_styles or []) if s]
    if "long" in styles:
        text = re.sub(r"短发(?:少女|女生|女孩|女子|学生)", "人物", text)
        text = re.sub(r"(?:齐耳|利落|清爽)短发"
                      r"(?=背影|正面|侧面|看向|抬头|低头|站在|回头|转向|侧身)",
                      "", text)
        text = re.sub(r"短发(?=背影|正面|侧面|看向|抬头|低头|站在|回头|"
                      r"转向|侧身)", "", text)
        text = text.replace("短发", "")
        for w in ("披肩发", "齐肩发", "散发", "中长发"):
            text = text.replace(w, "")
    elif "short" in styles:
        text = re.sub(r"(?:黑色|深色)?(?:长直发|披肩发|高马尾|马尾|长发)"
                      r"(?:少女|女生|女孩|女子)?", "", text)
    text = re.sub(r"[，,、；;]{2,}", "，", text)
    text = re.sub(r"\s+", " ", text).strip("，,、；; ")
    return text


def _classify_scene(scene):
    """当前场景类别与核心识别点（sceneLine最高优先级依据）。"""
    scene = str(scene or "")
    if "图书馆" in scene or "夹层" in scene:
        return "现代校园旧图书馆夹层", ["斑驳白墙", "生锈铁书架", "倾斜木屋架"]
    if "档案" in scene:
        return "现代学校档案室", ["金属文件柜", "档案盒", "档案工作台"]
    if "石室" in scene or "地下" in scene:
        return "地下石室", ["实心黑石墙"]
    if "古堡" in scene or "城堡" in scene:
        return "古堡室内", ["黑石墙", "尖拱门"]
    if "楼梯" in scene or "走廊" in scene:
        return "现代校园楼梯间", ["楼梯扶手", "走廊白墙", "消防栓"]
    if "教学楼" in scene and "前台" in scene:
        return "现代校园教学楼资料室", \
            ["金属档案柜", "成排文件盒", "编号标签"]
    if "教学楼" in scene or "大厅" in scene:
        return "现代校园教学楼", ["白墙", "前台"]
    if "教室" in scene or "校园" in scene:
        return "现代校园教室", ["课桌", "黑板", "白墙"]
    if "办公室" in scene:
        return "现代办公室", ["办公桌", "日光灯", "玻璃隔断"]
    return "现代校园室内", []


_LIBRARY_MEZZANINE_CONFLICT = ("椽子", "木屋架", "铁质书架", "生锈",
                               "夹层", "高窗", "旧图书馆", "铁梯")


def _scene_conflict_words(scene_type):
    """当前场景类别不兼容的旧图书馆夹层残片（最小词表）。"""
    t = str(scene_type or "")
    if "图书馆" in t or "夹层" in t:
        return ()
    if any(k in t for k in ("校园", "教学楼", "楼梯", "走廊", "档案",
                            "教室", "办公室")):
        return _LIBRARY_MEZZANINE_CONFLICT
    return ()


def _drop_scene_conflict_segments(text, words):
    """按当前sceneLine删除冲突环境残片，保留动作所需物体。"""
    if not words:
        return str(text or "")
    text = str(text or "")
    segs = re.split(r"(，|,|、|；|;)", text)
    out = []
    for seg in segs:
        if seg in ("，", ",", "、", "；", ";"):
            if out and out[-1]:
                out.append(seg)
            continue
        if any(w in seg for w in words):
            continue
        out.append(seg)
    joined = "".join(out)
    return re.sub(r"[，,、；;]{2,}", "，", joined).strip("，,、；; ")


def _compact_full_outfit_for(character, comic_anchor, char_card, world_rules=None):
    """从已确认人物卡确定性提取完整服装锚点：
    性别年龄感/发型/稳定特征 + 上装/下装/鞋袜/状态/随身。
    不调用模型、不重新设计服装；缺字段用泛化正面回退，不编造款式。"""
    card = ""
    if isinstance(char_card, dict):
        base = _staging_base_name(str(character))
        for name, look in char_card.items():
            if _staging_base_name(str(name)) == base:
                card = str(look or "")
                break
        if not card and str(character or "").strip() in char_card:
            card = str(char_card[str(character)].strip())
    if not card:
        card = str(comic_anchor or "")

    def _short_parts(text, limit):
        out = []
        n = 0
        for p in re.split(r"[，,、；;]", str(text or "")):
            p = p.strip("。；;，,、 ：:()（）")
            if not p:
                continue
            if n + len(p) > limit:
                break
            out.append(p)
            n += len(p) + 1
        return "、".join(out)

    pieces = []
    for sentence in re.split(r"[。；;]", card):
        for p in re.split(r"[，,、]", sentence):
            p = p.strip("。；;，,、 ：:()（）\"'")
            if p:
                pieces.append(p)
    base_name = str(character or "").strip()
    if base_name:
        pieces = [p.replace(base_name, "本人") for p in pieces]
    skip_words = ("整体着装", "整体造型", "无明显", "无特殊", "无纹身",
                  "无疤痕", "无装备", "无武器", "无珠宝", "无装饰",
                  "无特殊装备", "非肥胖")
    top_kw = ("衬衫", "外套", "制服", "上衣", "长袍", "袍", "马甲",
              "西装", "衣", "衫", "装")
    bottom_kw = ("裙", "裤")
    shoe_kw = ("鞋", "靴", "袜")
    state_kw = ("扣子", "扣紧", "系至", "拉链", "敞开", "半开",
                "系紧", "系着")
    acc_kw = ("耳钉", "眼镜", "徽章", "工牌", "腰带", "帽子", "围巾",
              "怀表", "手套", "包")
    hair_kw = ("发", "马尾", "辫")
    mark_kw = ("疤", "痣", "纹身")

    tops, bottoms, shoes, states, accs, marks, hairs = \
        [], [], [], [], [], [], []
    for p in pieces:
        if p.startswith("无") or any(k in p for k in skip_words):
            continue
        if p.startswith(("裤线", "袖口", "领口和", "整体")):
            continue
        if any(k in p for k in state_kw):
            states.append(p)
        elif any(k in p for k in shoe_kw):
            shoes.append(p)
        elif any(k in p for k in bottom_kw):
            bottoms.append(p)
        elif any(k in p for k in acc_kw):
            accs.append(p)
        elif any(k in p for k in mark_kw):
            marks.append(p)
        elif any(k in p for k in hair_kw):
            hairs.append(p)
        elif any(k in p for k in top_kw):
            tops.append(p)

    def _dedupe(items):
        out = []
        for x in items:
            if x not in out:
                out.append(x)
        return out

    tops = _dedupe(tops)
    bottoms = _dedupe(bottoms)
    shoes = _dedupe(shoes)
    states = _dedupe(states)
    accs = _dedupe(accs)
    marks = _dedupe(marks)
    hairs = _dedupe(hairs)

    whole = "".join(pieces)
    gender = "男" if "男" in whole[:20] else ("女" if "女" in whole[:20] else "")
    m = re.search(r"(\d{1,2})岁", whole[:60])
    if m:
        age = m.group(1) + "岁"
    elif "青年" in whole:
        age = "青年"
    elif "老年" in whole or "58岁" in whole or "60岁" in whole:
        age = "老年"
    elif "成年" in whole:
        age = "成年"
    else:
        age = ""
    head = ""
    if gender or age:
        head = (gender or "") + (age or "") + "感"
    if hairs:
        hair = _short_parts("；".join(hairs), 14)
        head += "，" + hair if head else hair
    if marks:
        mark = _short_parts("；".join(marks), 12)
        head += "，" + mark if head else mark

    def _force_long_sleeve(t):
        if "长袍" in t and "袖" not in t:
            t = t.replace("长袍", "长袖长袍")
        return t

    def _clean_cloth(p, label):
        p = re.sub(r"^(?:下身为|下装为|塞入|脚蹬|内穿|外穿|内搭|身穿|"
                   r"外层穿着|穿着|佩戴|腰间系|左耳)+", "", p)
        p = re.sub(r"中$", "", p)
        return p.strip("，,、；; ")

    outfit = []
    if tops:
        outfit.append("上装：" + _short_parts(
            "；".join(_force_long_sleeve(_clean_cloth(t, "上装"))
                      for t in tops), 36))
    elif card:
        outfit.append("上装：衣物完整正常穿着")
    if bottoms:
        outfit.append("下装：" + _short_parts(
            "；".join(_clean_cloth(b, "下装") for b in bottoms), 16))
    else:
        outfit.append("下装：完整正常穿着")
    if shoes:
        outfit.append("鞋袜：" + _short_parts(
            "；".join(_clean_cloth(s, "鞋袜") for s in shoes), 16))
    else:
        outfit.append("鞋袜：完整正常穿着")
    if states:
        state = _short_parts("；".join(states), 26)
        if "正常穿着" not in state:
            state += "、衣物整体正常穿着"
        outfit.append("状态：" + state)
    else:
        outfit.append("状态：衣物整体正常穿着")
    if accs:
        outfit.append("随身：" + _short_parts(
            "；".join(_clean_cloth(a, "随身") for a in accs), 18))
    bits = []
    if head:
        bits.append(head[:30])
    bits += outfit
    return "，".join(bits)[:150]


def _compact_scene_identity(scene, panel, staging=None, light="",
                            local_facts=None):
    """当前场景身份锚点：场景类型 + 3至5个固定识别点 + 当前光源。
    只使用当前页数据，不注入完整场景卡；正面描述防止串题材。"""
    scene = str(scene or "")
    scene_type, core = _classify_scene(scene)
    conflict = _scene_conflict_words(scene_type)

    def _clean_pt(s):
        s = str(s or "").strip(" \t\r\n，,、；;。")
        if not s:
            return ""
        if s == "反":
            return ""
        if "及其上" in s:
            s = s.replace("及其上", "上的").replace("的的", "的")
        if any(k in s for k in ("层高", "面积", "约2.5")):
            return ""
        return s.strip("，,、；; ")

    pts = []
    bg = str((panel or {}).get("staging_background") or "").strip()
    if bg:
        for p in re.split(r"[，,、；;]", bg):
            p = _clean_pt(p)
            if p and len(p) >= 2 and p not in pts and not any(
                    k in p for k in ("袖口", "长袍", "燕尾服", "外套", "衬衫")) \
                    and not any(k in p for k in conflict):
                pts.append(p[:20])
            if len(pts) >= 2:
                break
    sub = str((panel or {}).get("staging_subLocation") or "").strip()
    sub = _clean_pt(sub)
    if sub and len(sub) >= 2 and sub not in pts and \
            not any(k in sub for k in conflict):
        pts.append(sub[:20])
    if isinstance(staging, dict):
        lf = staging.get("localSceneFacts")
        if isinstance(lf, list):
            for x in lf:
                for part in re.split(r"[，,、；;]", str(x)):
                    p = _clean_pt(part)
                    if p and len(p) >= 2 and p not in pts and \
                            not any(k in p for k in conflict):
                        pts.append(p[:20])
                    if len(pts) >= 3:
                        break
                if len(pts) >= 3:
                    break
    for c in core[:2]:
        if c not in pts:
            pts.append(c)
    light = str(light or "").strip()
    if not light and isinstance(staging, dict):
        lf = staging.get("localSceneFacts")
        if isinstance(lf, list):
            for x in lf:
                s = str(x or "")
                if any(k in s for k in conflict):
                    continue
                if any(k in s for k in
                       ("光源", "烛光", "自然光", "阳光", "灯光", "光柱",
                        "斜射")):
                    m = re.search(
                        r"([^，,、；;。]{0,16}?(?:烛光|自然光|阳光|灯光|"
                        r"光柱|斜射光)[^，,、；;。]{0,10})", s)
                    if m:
                        light = m.group(1)
                        break
    if not light:
        if "古堡" in scene or "石室" in scene or "地下" in scene:
            light = "烛光"
        elif "白天" in scene or "自然光" in scene:
            light = "白天自然光"
        else:
            light = "日光灯"
    points = list(dict.fromkeys(
        [c for c in core if c] + [p for p in pts if p and p not in core]))[:3]
    return "场景：%s，%s。光源：%s" % (scene_type, "、".join(points), light[:12])


def _foreign_cloth_seg(seg, people_bases, anchors):
    """判断文本段是否含本格人物之外的服装描述（用于精简提示词人物隔离）。"""
    seg = str(seg or "")
    if not any(k in seg for k in ("袍", "燕尾服", "服", "衣", "裙", "装", "裤", "外套")):
        return False
    own = []
    for base in people_bases:
        m = re.search(r"[^；;，,。]{0,8}(?:长袍|燕尾服|西装|礼服|风衣)",
                      str(anchors.get(base) or ""))
        if m:
            own.append(m.group(0))
    for phrase in own:
        if phrase in seg:
            return False
        if "长袍" in phrase and "长袍" in seg:
            return False
        if "燕尾服" in phrase and "燕尾服" in seg:
            return False
    return True


def _foreign_scar_seg(seg, people_bases, anchors):
    """判断文本段是否含本格人物之外的伤疤描述。"""
    seg = str(seg or "")
    if "疤" not in seg:
        return False
    for base in people_bases:
        if "疤" in str(anchors.get(base) or ""):
            return False
    return True


