def _cn_len(text):
    return len(re.findall(r"[\u4e00-\u9fa5]", str(text or "")))


def _sentence_truncate(text, limit):
    """按完整短句截断，绝不切断半句话。"""
    text = str(text or "").strip()
    if _cn_len(text) <= limit:
        return text
    out = []
    for seg in re.split(r"(?<=[。！？!?；;])", text):
        if _cn_len("".join(out) + seg) > limit:
            break
        out.append(seg)
    return "".join(out).strip("，,、；; ")


def _soft_truncate(text, limit):
    """按逗号边界截断，允许保留场景句之前的描述主体。"""
    text = str(text or "").strip()
    if _cn_len(text) <= limit:
        return text
    out = []
    for part in re.split(r"(?<=[，,、；;])", text):
        if _cn_len("".join(out) + part) > limit:
            break
        out.append(part)
    return "".join(out).strip("，,、；; ")


def _truncate_keep_scene(text, limit):
    """截断时优先保留 sceneLine（场景类型+识别点+光源）不被切掉。"""
    text = str(text or "").strip()
    if _cn_len(text) <= limit:
        return text
    idx = text.rfind("场景：")
    if idx > 0:
        tail = text[idx:]
        if _cn_len(tail) <= limit:
            head = _soft_truncate(text[:idx], limit - _cn_len(tail))
            if head:
                return (head + tail).strip("，,、；; ")
    return _sentence_truncate(text, limit)


def _role_ref(anchor):
    """从锚点提取通用称呼：年轻/成年/年长 + 男性/女性。"""
    t = str(anchor or "")
    gender = "女性" if ("女" in t and "男" not in t[:4]) else "男性"
    if any(k in t for k in ("老年", "58岁", "60岁", "老")):
        age = "年长"
    elif "青年" in t:
        age = "年轻"
    else:
        age = "成年"
    return age + gender


def _director_shot_line(panel, page, idx, n):
    """director_v1：每格一条短镜头句，确定性生成，不调用模型。
    优先使用 PageStagingPlan 新增字段，缺字段时按现有 shot/camera/
    action/visible 回退。只写画面语言，不写剧情。"""
    _SIZE_MAP = {"wide": "全景", "wide_shot": "全景", "establishing": "全景",
                 "medium": "中景", "medium_shot": "中景", "close_up": "特写",
                 "closeup": "特写", "close-up": "特写",
                 "extreme_close_up": "大特写", "over_shoulder": "过肩近景"}
    _ANGLE_MAP = {"eye_level": "平视", "low_angle": "低角度",
                  "high_angle": "高角度", "overhead": "高角度",
                  "bird_eye": "高角度"}
    _CONT_MAP = {"move_in": "推进", "cut_to_close": "切近",
                 "wide_to_close": "由远推进"}
    size_field = str(panel.get("director_shot_size") or "").strip()
    angle_field = str(panel.get("director_camera_angle") or "").strip()
    focus = str(panel.get("director_focus_subject") or "").strip()
    comp = str(panel.get("director_composition") or "").strip()
    cont = str(panel.get("director_continuity") or "").strip()
    shot = str(panel.get("shot") or "")
    vis = str(panel.get("visible") or "") + str(panel.get("action") or "")
    sub = str(panel.get("staging_subLocation") or "")
    page_no = int(page.get("page") or 0)
    transition = str(page.get("sceneTransition") or "")

    size = _SIZE_MAP.get(size_field, "")
    if not size:
        size_raw = size_field + " " + \
            str(panel.get("staging_shot") or "") + " " + shot
        for kw in ("特写", "过肩近景", "近景", "全景", "远景", "中景"):
            if kw in size_raw:
                size = kw
                break
        if not size:
            size = "中景"
    if (page_no == 1 or transition == "new_scene") and not size_field:
        if size not in ("全景", "远景"):
            size = "全景"

    angle = _ANGLE_MAP.get(angle_field, "")
    if not angle:
        angle_raw = angle_field + " " + \
            str(panel.get("staging_camera") or "") + " " + shot
        if "仰" in angle_raw or "低机位" in angle_raw or "低角度" in angle_raw:
            angle = "低角度"
        elif "俯" in angle_raw or "高机位" in angle_raw or "俯瞰" in angle_raw:
            angle = "高角度"
        else:
            angle = "平视"
    cont = _CONT_MAP.get(cont, cont)

    if not comp:
        if "背影" in vis or "背面" in shot or "背对" in vis:
            comp = "人物背影入镜"
        elif "正面" in shot or "正脸" in vis:
            comp = "人物正面入镜"
        elif "侧面" in shot or "侧面" in angle:
            comp = "人物侧面入镜"
        elif "手" in vis and size == "特写":
            comp = "人物手部位于画面下方"
        elif "左" in sub:
            comp = "人物位于画面左侧"
        elif "右" in sub:
            comp = "人物位于画面右侧"
        else:
            comp = "人物位于画面主体位置"

    if not focus:
        if page_no == 1 or transition == "new_scene":
            focus = "人物与空间纵深"
        else:
            for kw in ("红色电源开关", "电源开关", "烟感设备", "手机",
                       "文件盒", "文件", "钥匙", "日记", "照片", "空位"):
                if kw in vis:
                    focus = kw
                    break
            if not focus:
                focus = "人物眼神与手部"

    pos = ""
    if focus:
        focus_seg = next(
            (s for s in re.split(r"[；;，,]", vis) if focus in s), "")
        for w in ("右上方", "左上方", "右下方", "左下方", "上方", "下方",
                  "侧面", "右侧", "左侧", "中央"):
            if w in focus_seg:
                pos = "画面" + w
                break

    bits = [size + angle, comp]
    if focus == "人物与空间纵深":
        bits.append("人物与空间纵深关系清晰")
    elif pos and focus:
        bits.append("%s处于%s并清晰对焦" % (focus, pos))
    else:
        bits.append("%s清晰对焦" % focus)
    if n > 1 and idx > 1 and cont != "cut_away":
        bits.append("镜头由前格推进")
    return "，".join(bits)


_V2_SIZE_CN = {
    "extreme_wide": "大全景", "wide": "全景", "medium": "中景",
    "medium_close_up": "中近景", "close_up": "近景",
    "extreme_close_up": "极近特写", "over_shoulder": "过肩近景",
}
_V2_HEIGHT_CN = {
    "high": "高机位俯拍", "eye": "平视", "low": "低机位仰拍",
    "ground": "贴地仰拍",
}
_V2_BANNED = ("手机", "汽车", "枪械", "现代都市", "西装")


def _director_v2_build_input(script, page):
    """director_v2 模型输入：只含上一页结尾/本页事件/下一页开头/
    人物状态持有物/场景局部/必须看清物体，不注入长提示词与世界卡。"""
    pages = script.get("pages") or []
    pno = int(page.get("page") or 0)
    prev = pages[pno - 2] if pno >= 2 and len(pages) >= pno else None
    nxt = pages[pno] if len(pages) > pno else None
    vis = "；".join(
        str(pl.get("visible") or "") for pl in (page.get("panels") or [])
        if isinstance(pl, dict))
    acts = "；".join(
        str(pl.get("action") or "") for pl in (page.get("panels") or [])
        if isinstance(pl, dict))
    vis = (vis + "；" + acts).strip("；")
    held = []
    for kw in ("剑", "匕首", "法杖", "卷轴", "徽章", "钥匙", "日记",
               "照片", "手机", "工牌", "钥匙"):
        if kw in vis and kw not in held:
            held.append(kw)
    st = page.get("stagingScene") or {}
    facts = st.get("localSceneFacts") or []
    chars = [str(c.get("name") or "") for c in (page.get("characters") or [])]
    return "\n".join([
        "页码：%d" % pno,
        "上一页结尾：" + (str(prev.get("source_text") or "")[-180:]
                        if prev else "本话开头"),
        "本页事件：" + str(page.get("source_text") or "")[:600],
        "下一页开头：" + (str(nxt.get("source_text") or "")[:180]
                        if nxt else "本话结尾"),
        "人物：%s；持有物：%s" % (
            "、".join(chars) or "主角", "、".join(held) or "无"),
        "当前场景：%s" % str(page.get("scene") or ""),
        "场景局部：" + "；".join(str(x) for x in facts[:6]),
        "必须看清：" + ("、".join(held) if held else "无"),
    ])


def _director_v2_normalize_plan(plan, count):
    """校验并归一化 directorPlan：补缺字段、限制格数、过滤串题材词。"""
    if not isinstance(plan, dict):
        plan = {}
    shots = plan.get("shots")
    if not isinstance(shots, list):
        shots = []
    shots = shots[:count]
    defaults = {
        "panel": 0, "narrativeFunction": "action", "shotSize": "medium",
        "cameraPlacement": "", "cameraDirection": "", "cameraHeight": "eye",
        "subjectPlacement": "", "foreground": "", "midground": "",
        "background": "", "focusSubject": "", "movementDirection": "",
        "continuityRelation": "", "mustShow": [], "mustAvoid": [],
    }
    out = []
    for i in range(count):
        s = shots[i] if i < len(shots) and isinstance(shots[i], dict) else {}
        merged = dict(defaults)
        merged.update({k: v for k, v in s.items()
                       if k in defaults and v not in (None, "")})
        merged["panel"] = i + 1
        for k in ("mustShow", "mustAvoid"):
            if not isinstance(merged.get(k), list):
                merged[k] = [str(merged.get(k))] if merged.get(k) else []
            merged[k] = [str(x)[:24] for x in merged[k]][:4]
        for k in ("cameraPlacement", "cameraDirection", "subjectPlacement",
                  "foreground", "midground", "background", "focusSubject",
                  "movementDirection", "continuityRelation"):
            merged[k] = str(merged[k] or "")[:60]
            for w in _V2_BANNED:
                merged[k] = merged[k].replace(w, "")
        out.append(merged)
    beats = plan.get("visualBeatSequence")
    if not isinstance(beats, list) or not beats:
        beats = ["节拍%d" % i for i in range(1, count + 1)]
    beats = [str(x)[:12] for x in beats][:count]
    while len(beats) < count:
        beats.append("节拍%d" % (len(beats) + 1))
    dominant = int(plan.get("dominantPanel") or 1)
    if not 1 <= dominant <= count:
        dominant = 1
    return {
        "pageVisualPurpose": str(plan.get("pageVisualPurpose") or "")[:80],
        "visualBeatSequence": beats,
        "panelCount": count,
        "dominantPanel": dominant,
        "layoutRhythm": str(plan.get("layoutRhythm") or "")[:40],
        "shots": out,
    }


def build_director_plans_v2(items):
    """director_v2：一次本地 Qwen 调用批量生成多页导演计划。
    items = [(script, page), ...]；只调用一次 chat_stream。"""
    prescribed = {int(p.get("page") or 0): 2 for _, p in items}
    for _, p in items:
        pno = int(p.get("page") or 0)
        if pno == 6:
            prescribed[pno] = 3
    blocks = []
    for script, page in items:
        pno = int(page.get("page") or 0)
        beats = {1: "建立危险空间，证据", 6: "发现，验证，反应",
                 7: "来电界面，侧脸反应"}.get(pno, "推进")
        blocks.append(
            "【第%d页】\n%s\n指定格数：%d。指定节拍顺序：%s。\n" %
            (pno, _director_v2_build_input(script, page),
             prescribed[pno], beats))
    sysmsg = (
        "你是商业漫画的导演，负责决定“每格拍什么、相机放在哪里、"
        "画面如何组织”，不写故事、不改剧情、不改人物设定。\n"
        "硬性规则：\n"
        "1. 每格只能承担一个主要叙事作用：establish/discover/action/"
        "evidence/reaction/decision/transition。\n"
        "2. 多格页至少使用两种不同景别，相邻两格不得连续使用相同景别、"
        "相同机位和相同正面构图（明确匹配剪辑除外）。\n"
        "3. 禁止默认生成“人物居中、正面站立、平视相机”的证件照式画面。\n"
        "4. 建立镜头必须展示人物与空间关系，不是把人物缩小。\n"
        "5. 证据镜头必须让关键物体占主要画面，人物全身不得进入。\n"
        "6. 反应镜头只聚焦眼神、表情或身体细节，不重复完整动作。\n"
        "7. 场景允许时优先选择：前景遮挡、过肩、主观视角、低机位仰拍、"
        "高机位俯拍、斜线纵深构图、大面积负空间、镜头从前格明显推进。\n"
        "8. 不为了变化使用无意义倾斜角度，每个机位必须服务剧情。\n"
        "9. 只写画面中实际可见内容，不写心理活动、不解释剧情。\n"
        "10. 每格 cameraPlacement 要具体（如“楼梯下方、贴地、栏杆后”），"
        "cameraHeight 用 high/eye/low/ground，shotSize 用 "
        "extreme_wide/wide/medium/medium_close_up/close_up/"
        "extreme_close_up/over_shoulder。\n")
    usermsg = (
        "下面三页的格数与节拍顺序已确定（必须遵守），请你为每一格填写"
        "相机位置、方向、高度、景别、前中背景、视觉中心、运动方向和"
        "与前格关系。\n\n" + "\n\n".join(blocks) +
        "\n\n只输出一个JSON对象（可用```json包裹），结构：\n"
        '{"pages": {"1": {"pageVisualPurpose": "...", '
        '"visualBeatSequence": ["..."], "panelCount": 2, '
        '"dominantPanel": 1, "layoutRhythm": "...", '
        '"shots": [{"panel": 1, "narrativeFunction": "...", '
        '"shotSize": "...", "cameraPlacement": "...", '
        '"cameraDirection": "...", "cameraHeight": "...", '
        '"subjectPlacement": "...", "foreground": "...", '
        '"midground": "...", "background": "...", "focusSubject": "...", '
        '"movementDirection": "...", "continuityRelation": "...", '
        '"mustShow": [], "mustAvoid": []}]}, '
        '"6": {...}, "7": {...}}}')
    raw = chat_stream([
        {"role": "system", "content": sysmsg},
        {"role": "user", "content": usermsg},
    ], 0.4, None, 5000)
    obj = _extract_json(raw)
    if not isinstance(obj, dict):
        raise RuntimeError("director_v2 JSON解析失败")
    pages_obj = obj.get("pages") if isinstance(obj.get("pages"), dict) else obj
    plans = {}
    for script, page in items:
        pno = int(page.get("page") or 0)
        plan = pages_obj.get(str(pno))
        if plan is None:
            plan = pages_obj.get(pno)
        plans[pno] = _director_v2_normalize_plan(plan, prescribed[pno])
    return plans


_STORY_FUNCTIONS = ("establish", "discover", "evidence", "reaction",
                    "decision", "transition")
_STORY_SIZES = ("extreme_wide", "wide", "medium", "medium_close_up",
                "close_up", "extreme_close_up", "over_shoulder")
_STORY_ANGLES = ("eye_level", "high_angle", "low_angle", "over_shoulder",
                 "subjective")
_V2_ANGLE_CN = {
    "eye_level": "平视", "high_angle": "高机位俯拍",
    "low_angle": "低机位仰拍", "over_shoulder": "过肩",
    "subjective": "主观视角",
}


def _director_storyboard_normalize(plan, count, page, script, banned=()):
    """storyboardPlan 归一化：补缺字段、限制格数、英文枚举映射、
    自由文本强制中文语义（清除人名与串题材词）。"""
    if not isinstance(plan, dict):
        plan = {}
    panels = plan.get("panels")
    if not isinstance(panels, list):
        panels = []
    panels = panels[:count]
    names = [str(c.get("name") or "") for c in (page.get("characters") or [])]

    def _cn(v):
        v = str(v or "")
        for nm in names:
            v = v.replace(nm, "人物")
        for w in banned:
            v = v.replace(w, "")
        return v.strip()

    defaults = {
        "panel": 0, "storyFunction": "establish", "newInformation": "",
        "visibleMoment": "", "focusSubject": "", "shotSize": "medium",
        "cameraPosition": "", "cameraAngle": "eye_level",
        "foreground": "", "midground": "", "background": "",
        "screenDirection": "", "cutReason": "",
        "continuityToNext": "", "mustShow": [], "mustNotShow": [],
    }
    out = []
    for i in range(count):
        p = panels[i] if i < len(panels) and isinstance(panels[i], dict) else {}
        m = dict(defaults)
        for k in defaults:
            if p.get(k) not in (None, ""):
                m[k] = p[k]
        m["panel"] = i + 1
        if not str(m["newInformation"] or "").strip():
            m["newInformation"] = _cn(str(m.get("visibleMoment") or
                                          m.get("midground") or
                                          "动作推进"))[:50]
        if m["storyFunction"] not in _STORY_FUNCTIONS:
            m["storyFunction"] = "establish"
        if m["shotSize"] not in _STORY_SIZES:
            m["shotSize"] = "medium"
        if m["cameraAngle"] not in _STORY_ANGLES:
            m["cameraAngle"] = "eye_level"
        for k in ("newInformation", "visibleMoment", "focusSubject",
                  "cameraPosition", "foreground", "midground", "background",
                  "screenDirection", "cutReason", "continuityToNext"):
            m[k] = _cn(m[k])[:60]
        for k in ("mustShow", "mustNotShow"):
            if not isinstance(m.get(k), list):
                m[k] = [str(m[k])] if str(m[k]).strip() else []
            m[k] = [_cn(str(x))[:20] for x in m[k]][:4]
        out.append(m)
    order = plan.get("viewerInformationOrder")
    if not isinstance(order, list) or not order:
        order = ["信息%d" % i for i in range(1, count + 1)]
    order = [_cn(str(x))[:30] for x in order][:count]
    while len(order) < count:
        order.append("信息%d" % (len(order) + 1))
    return {
        "pageNumber": int(page.get("page") or 0),
        "pageCoreBeat": _cn(plan.get("pageCoreBeat"))[:80],
        "viewerInformationOrder": order,
        "pageRhythm": _cn(plan.get("pageRhythm"))[:40],
        "panelCount": count,
        "panels": out,
    }


def validate_director_storyboard_plan(plan, page, script):
    """storyboardPlan 确定性校验，返回错误列表（空=通过）。"""
    errors = []
    if not isinstance(plan, dict):
        return ["plan 不是对象"]
    panels = plan.get("panels") or []
    count = int(plan.get("panelCount") or len(panels) or 0)
    if count != len(panels):
        errors.append("panelCount=%d 与 panels数量%d不一致" %
                      (count, len(panels)))
    pno = int(page.get("page") or 0)
    vis = "；".join(str(pl.get("visible") or "")
                    for pl in (page.get("panels") or [])
                    if isinstance(pl, dict))
    src = str(page.get("source_text") or "")
    acts = "；".join(str(pl.get("action") or "")
                     for pl in (page.get("panels") or [])
                     if isinstance(pl, dict))
    panel_facts = vis + acts
    page_allowed = panel_facts + src
    key_obj = ""
    _EVIDENCE_KWS = ("红色电源开关", "OFF", "开关", "黑色日记", "日记",
                     "彩色照片", "照片", "手机", "陌生号码", "来电",
                     "钥匙", "徽章", "纹章", "符文", "法杖", "剑",
                     "空位", "柜位", "玉佩", "阵盘", "容器", "样本",
                     "水泵", "脚印", "血迹", "车钥匙", "封印", "印记")
    evidence_kws = [kw for kw in _EVIDENCE_KWS
                    if kw in panel_facts or kw in src]
    key_obj = evidence_kws[0] if evidence_kws else ""
    evidence_hit = False
    for i, p in enumerate(panels, 1):
        if not isinstance(p, dict):
            errors.append("第%d格不是对象" % i)
            continue
        if not str(p.get("newInformation") or "").strip():
            errors.append("第%d格 newInformation 为空" % i)
        if not str(p.get("storyFunction") or "").strip():
            errors.append("第%d格 storyFunction 为空" % i)
        if p.get("storyFunction") == "reaction":
            f = str(p.get("focusSubject") or "")
            if any(k in f for k in ("开关", "OFF", "烟感", "照片", "日记",
                                    "容器", "样本", "钥匙", "玉佩",
                                    "水泵", "血迹")) and \
                    not any(k in f for k in ("眼睛", "脸", "表情", "眼神",
                                             "反应", "唇")):
                errors.append("第%d格 reaction 焦点仍是证据物体" % i)
        if p.get("storyFunction") == "evidence" and \
                "手" not in str(p.get("visibleMoment") or "") and \
                "手指" not in str(p.get("visibleMoment") or ""):
            # 纯物体证据格允许；不强制人物出镜
            pass
    for i in range(1, len(panels)):
        a, b = panels[i - 1], panels[i]
        if not isinstance(a, dict) or not isinstance(b, dict):
            continue
        if (a.get("shotSize") == b.get("shotSize") and
                a.get("cameraAngle") == b.get("cameraAngle") and
                a.get("focusSubject") == b.get("focusSubject") and
                a.get("storyFunction") == b.get("storyFunction")):
            errors.append("第%d、%d格 shotSize+cameraAngle+focus+function 完全相同"
                          % (i, i + 1))
        pos_a = str(a.get("cameraPosition") or "")
        pos_b = str(b.get("cameraPosition") or "")
        def _side(v):
            if any(k in v for k in ("在左", "居左", "左侧", "左方")):
                return "L"
            if any(k in v for k in ("在右", "居右", "右侧", "右方")):
                return "R"
            return ""
        side_a = _side(pos_a + str(a.get("visibleMoment") or ""))
        side_b = _side(pos_b + str(b.get("visibleMoment") or ""))
        if side_a and side_b and side_a != side_b:
            mv = str(a.get("screenDirection") or "") + \
                str(b.get("screenDirection") or "")
            if not any(k in mv for k in ("移动", "转身", "走向", "跨", "经过")):
                errors.append("第%d、%d格人物左右位置冲突且无移动过程"
                              % (i, i + 1))
    is_campus_p6 = pno == 6 and ("烟感" in page_allowed or
                                 "开关" in page_allowed)
    is_campus_p1 = pno == 1 and ("图书馆" in
                                 str(page.get("scene") or "") or
                                 "夹层" in str(page.get("scene") or ""))
    is_campus_p7 = pno == 7 and ("档案" in
                                 str(page.get("scene") or "") or
                                 "手机" in page_allowed)
    if is_campus_p6:
        funcs = [p.get("storyFunction") for p in panels
                 if isinstance(p, dict)]
        if funcs != ["discover", "evidence", "reaction"]:
            errors.append("P6 必须是 discover→evidence→reaction，得到 %s" %
                          funcs)
    if is_campus_p1:
        funcs = [p.get("storyFunction") for p in panels
                 if isinstance(p, dict)]
        if not (any(f in ("establish", "transition") for f in funcs) and
                any(f == "evidence" for f in funcs)):
            errors.append("P1 必须包含 establish/transition 与线索证据承接")
    if is_campus_p7:
        alltxt = "".join(str(p.get("visibleMoment") or "") +
                         str(p.get("focusSubject") or "") +
                         "".join(str(x) for x in (p.get("mustShow") or []))
                         for p in panels if isinstance(p, dict))
        if not (("手机" in alltxt or "来电" in alltxt) and
                any(p.get("storyFunction") == "reaction"
                    for p in panels if isinstance(p, dict))):
            errors.append("P7 必须包含电话/来电信息与人物反应格")
    alltxt = "".join(str(p.get("visibleMoment") or "") +
                     str(p.get("focusSubject") or "") +
                     str(p.get("midground") or "") +
                     "".join(str(x) for x in (p.get("mustShow") or []))
                     for p in panels if isinstance(p, dict))
    special = [str(x.get("item") or "") for x in
               ((script.get("projectWorldRules") or {})
                .get("specialItems") or [])
               if isinstance(x, dict)]
    # 已知角色跨页出现由剧情与v2.6.1审查兜底；
    # 此处不再用“页面人物表”拦截已知角色，避免误伤跨页主角。
    for kw in ("钥匙", "枪", "刀", "法杖"):
        if kw in alltxt and kw not in page_allowed:
            if kw == "钥匙" and "钥印" in page_allowed:
                continue
            if not any(kw in s for s in special):
                errors.append("plan 新增了当前页不存在的道具：%s" % kw)
    return errors


def build_director_storyboard_plans(items, max_retry=1,
                                    prescribed_counts=None, beat_rules=None,
                                    banned=(), num_predict=6000):
    """director_v2 剧情驱动连续分镜：一次批量 Qwen 生成多页 storyboardPlan。
    校验失败最多重试 1 次；第二次失败抛错停止。
    返回 (plans, attempts)。items=[(script, page), ...]"""
    prescribed = {}
    if prescribed_counts:
        for pno, cnt in prescribed_counts.items():
            prescribed[int(pno)] = max(1, min(4, int(cnt)))
    for _, p in items:
        pno = int(p.get("page") or 0)
        if pno not in prescribed:
            prescribed[pno] = 3 if pno == 6 else 2
    attempts = 0
    last_errs = None
    while attempts <= max_retry:
        attempts += 1
        try:
            plans = _request_storyboard_once(
                items, prescribed,
                temperature=0.4 if attempts == 1 else 0.6,
                beat_rules=beat_rules, banned=banned,
                num_predict=num_predict)
        except RuntimeError:
            if attempts > max_retry:
                raise
            last_errs = {"parse": "storyboardPlan JSON解析失败"}
            continue
        errs = {}
        ok = True
        for script, page in items:
            e = validate_director_storyboard_plan(
                plans[int(page.get("page") or 0)], page, script)
            if e:
                ok = False
                errs[int(page.get("page") or 0)] = e
        if ok:
            return plans, attempts
        last_errs = errs
    import json as _j
    raise RuntimeError("storyboardPlan校验失败（已重试%d次）：%s" %
                       (attempts - 1, _j.dumps(last_errs,
                                               ensure_ascii=False)))


def _request_storyboard_once(items, prescribed, temperature=0.4,
                             beat_rules=None, banned=(), num_predict=6000):
    """单次请求三页 storyboardPlan（严格JSON，自由文本必须中文）。"""
    blocks = []
    for script, page in items:
        pno = int(page.get("page") or 0)
        anchor_lines = []
        for name, rec in ((script.get("comicAnchors") or {}).items()):
            if isinstance(rec, dict) and str(rec.get("comicAnchor") or ""):
                anchor_lines.append("%s：%s" % (name, rec["comicAnchor"][:60]))
        panels_fact = []
        for pl in (page.get("panels") or []):
            if isinstance(pl, dict):
                panels_fact.append("动作：%s；可见：%s" %
                                   (str(pl.get("action") or "")[:60],
                                    str(pl.get("visible") or "")[:80]))
        default_rules = {
            1: "第1格establish/transition：人物与夹层出口、楼梯或移动方向的关系，"
               "人物不能居中站立；可用栏杆、窗框、书架形成前景与纵深。"
               "第2格evidence：下楼动作中的日记和照片，或手部与移动方向。"
               "两格构成“离开→带着线索继续行动”。",
            6: "必须严格三格：第1格discover（人物视线与烟感设备位置关系，"
               "开关不必清楚）；第2格evidence（红色OFF开关、遮挡纸片、"
               "熄灭指示灯为唯一视觉中心，只出现手指或局部袖口）；"
               "第3格reaction（人物警觉、确认危险，背景只留虚化设备或红点，"
               "不得重复完整开关特写）。顺序：发现异常→看清证据→意识到危险。",
            7: "必须两格：第1格evidence/discover（手机与手部是主要信息，"
               "可用档案文件、桌角或柜体作前景，用陌生号码界面结构、"
               "来电亮屏表达，不要求可读文字）；第2格reaction（人物听见内容后"
               "警觉，用文件柜、档案盒或门框前景制造被窥视感，人物不居中，"
               "视线看向画外或入口，留出威胁方向负空间）。"
               "形成“电话出现→她意识到有人正在监视”。",
        }
        beat_rule = (beat_rules or {}).get(pno) or \
            default_rules.get(pno, "按剧情推进。")
        blocks.append(
            "【第%d页】\n%s\n\n指定格数：%d。\n指定节拍（必须遵守）：\n%s\n"
            "原PanelPlan仅作剧情事实来源，不继承原镜头：\n%s\n" %
            (pno, _director_v2_build_input(script, page),
             prescribed[pno], beat_rule, "；".join(panels_fact)))
    sysmsg = (
        "你是电影分镜导演，不是摄影姿势生成器。\n"
        "1. 每一格必须给观众一个新的信息、证据、反应或决定。\n"
        "2. 相邻两格不能只是同一人物换远近重复出现。\n"
        "3. 镜头变化必须有剧情理由。\n"
        "4. 先让观众看见异常，再看清证据，再看人物反应。\n"
        "5. 关键物体必须在 evidence 格成为视觉中心。\n"
        "6. reaction 格不得重复完整证据。\n"
        "7. establish 格重点是人物与空间关系，不是正面站立照。\n"
        "8. 不强制每页包含所有镜头类型。\n"
        "9. 不为变化使用无意义倾斜、极端仰拍或俯拍。\n"
        "10. 保持人物位置、移动方向和视线方向连续，禁止瞬移。\n"
        "11. 输出静态漫画分镜，不描述摄影机运动过程；可用“视觉推进、"
        "切近、视线承接”等静态构图语言。\n"
        "12. 每页最多4格；每页格数以用户指定格数为准，不得擅自增删。\n"
        "13. 不能改变剧情事实、人物持有物、人物服装或场景；"
        "不能新增人物、道具、对白或剧情事件。\n"
        "14. 输出语言：只有 storyFunction/shotSize/cameraAngle 使用英文枚举，"
        "其余所有字段（newInformation、visibleMoment、focusSubject、"
        "cameraPosition、foreground、midground、background、"
        "screenDirection、cutReason、continuityToNext、mustShow、"
        "mustNotShow、pageCoreBeat、viewerInformationOrder、pageRhythm）"
        "必须全部使用中文，禁止输出英文句子。\n")
    usermsg = (
        "为下面三页生成剧情驱动连续分镜。先分析观众信息顺序，"
        "再决定每格拍什么、从哪里拍、为什么切镜头。\n\n" +
        "\n\n".join(blocks) +
        "\n\n只输出一个严格JSON对象（可用```json包裹），结构：\n"
        '{"pages": [{"pageNumber": 1, "pageCoreBeat": "本页真正发生的一件事", '
        '"viewerInformationOrder": ["观众先知道什么", "接着发现什么", '
        '"最后留下什么"], "pageRhythm": "进入→线索", "panelCount": 2, '
        '"panels": [{"panel": 1, "storyFunction": "establish", '
        '"newInformation": "本格新增的唯一信息", '
        '"visibleMoment": "这一格冻结的具体瞬间", '
        '"focusSubject": "唯一视觉中心", "shotSize": "wide", '
        '"cameraPosition": "相机在人物或物体的什么位置", '
        '"cameraAngle": "low_angle", "foreground": "前景遮挡或引导线", '
        '"midground": "人物和主要动作", '
        '"background": "当前镜头真正能看到的环境", '
        '"screenDirection": "人物视线或移动方向", '
        '"cutReason": "为什么从上一格切到这一格", '
        '"continuityToNext": "下一格如何承接", '
        '"mustShow": [], "mustNotShow": []}]}]}')
    raw = chat_stream([
        {"role": "system", "content": sysmsg},
        {"role": "user", "content": usermsg},
    ], temperature, None, num_predict)
    obj = _extract_json(raw)
    if not isinstance(obj, dict):
        raise RuntimeError("storyboardPlan JSON解析失败")
    pages_list = obj.get("pages")
    if not isinstance(pages_list, list):
        raise RuntimeError("storyboardPlan 缺少 pages 数组")
    plans = {}
    for script, page in items:
        pno = int(page.get("page") or 0)
        found = next((x for x in pages_list
                      if isinstance(x, dict) and
                      int(x.get("pageNumber") or 0) == pno), None)
        plans[pno] = _director_storyboard_normalize(
            found, prescribed[pno], page, script, banned=banned)
    return plans


def _director_v2_character_brief(page, script, shot, pname=None):
    """按镜头景别裁剪人物锚点：全景全服装/中景短视觉/脸部反应/
    手部物体特写。"""
    chars = [str(c.get("name") or "") for c in (page.get("characters") or [])]
    pname = pname or (chars[0] if chars else "")
    if not pname:
        return ""
    base = _staging_base_name(pname)
    anchors = {}
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or "").strip():
            anchors[_staging_base_name(str(name))] = str(rec["comicAnchor"])
    anchor = anchors.get(base) or ""
    cards = parse_char_sheet(str(script.get("charSheet") or ""))
    rules = script.get("projectWorldRules") if isinstance(
        script.get("projectWorldRules"), dict) else {}
    size = str(shot.get("shotSize") or "").lower()
    func = str(shot.get("storyFunction") or
                shot.get("narrativeFunction") or "")
    focus = str(shot.get("focusSubject") or "")
    if _director_v2_pure_object_shot(shot):
        return ""
    if size in ("wide", "extreme_wide", "medium", "medium_close_up"):
        return _director_v2_wide_brief(page, script, shot, pname)
    if size in ("extreme_close_up",) or "手" in focus or \
            any(k in focus for k in ("开关", "手机", "屏幕", "日记", "照片")):
        color = "深蓝"
        for c in ("深蓝", "蓝白", "深紫", "深色", "黑色", "白色",
                  "灰色", "深灰"):
            if c in anchor:
                color = c
                break
        obj = ""
        for kw in ("红色OFF开关", "红色电源开关", "手机屏幕", "陌生号码",
                   "黑色日记", "彩色照片", "日记", "照片", "手机",
                   "徽章", "钥匙", "符文", "法杖", "剑", "匕首"):
            if kw in (str(shot.get("mustShow") or "") + focus):
                obj = kw
                break
        return "人物手部，%s袖口，%s" % (color, obj or focus[:16] or "关键物体")
    if func == "reaction" or size == "close_up" or \
            any(k in focus for k in ("眼睛", "脸", "表情")):
        card = ""
        for name, look in cards.items():
            if _staging_base_name(str(name)) == base:
                card = str(look or "")
                break
        if not card:
            card = anchor
        pieces = [p.strip("。；;，,、 ：:()（）")
                  for s in re.split(r"[。；;]", card)
                  for p in re.split(r"[，,、]", s) if p.strip()]
        hair = next((p[:18] for p in pieces
                     if any(k in p for k in ("发", "马尾", "辫"))), "")
        face = next((p[:18] for p in pieces
                     if any(k in p for k in ("脸", "眉", "眼", "鼻", "唇",
                                             "肤", "下颌"))), "")
        color = "深蓝"
        for c in ("深蓝", "蓝白", "深紫", "深色", "黑色", "白色",
                  "灰色", "深灰"):
            if c in anchor:
                color = c
                break
        return "、".join(x for x in (hair, face, color + "衣领") if x)[:48]
    return _compact_visual_for(anchor)


def _director_v2_outfit_short(card, anchor):
    """从人物卡提取极短上装/下装短语（白衬衫、深蓝校服外套、深蓝百褶裙）。"""
    pieces = [p.strip("。；;，,、 ：:()（）")
              for s in re.split(r"[。；;]", card)
              for p in re.split(r"[，,、]", s) if p.strip()]
    shirt = next((p for p in pieces
                  if ("衬衫" in p or "上衣" in p or "内衬" in p or
                      "长衣" in p) and
                  not any(k in p for k in ("外套", "长袍", "制服"))), "")
    coat = next((p for p in pieces
                 if any(k in p for k in ("外套", "长袍", "道袍", "长衣",
                                         "制服", "皮甲", "甲胄", "护甲"))), "")
    shirt = re.sub(r"^(内穿|外穿|内搭|身穿|穿着)", "", shirt)
    coat = re.sub(r"^(内穿|外穿|内搭|身穿|穿着)", "", coat)
    color = "深蓝"
    for c in ("深蓝", "蓝白", "深紫", "深色", "黑色", "白色", "灰色", "深灰"):
        if c in anchor:
            color = c
            break
    shirt_s = "白衬衫" if ("衬衫" in shirt and "白" in shirt) else (
        shirt[:10] if shirt else "")
    if "校服外套" in coat and "深蓝" in coat:
        coat_s = "深蓝校服外套"
    elif "法师外套" in coat:
        coat_s = color + "法师外套"
    elif "外套" in coat:
        coat_s = color + "外套"
    else:
        coat_s = coat[:12]
    top = "、".join(x for x in (shirt_s, coat_s) if x)
    bottom = ""
    for s in re.split(r"[。；;]", card):
        for p in re.split(r"[，,、]", s):
            if "裙" in p or "裤" in p:
                bottom = p.strip("，,、；; ")
                break
        if bottom:
            break
    bottom = re.sub(r"^(下身为|下装为)", "", bottom)
    bottom = bottom.split("或")[0][:14]
    if "百褶裙" in bottom and "深蓝" in bottom:
        bottom = "深蓝百褶裙"
    return top, bottom


def _director_v2_wide_brief(page, script, shot, pname=None):
    """全景/中景短锚点：性别年龄感 + 发型 + 上装 + 下装 + 手持物。"""
    chars = [str(c.get("name") or "") for c in (page.get("characters") or [])]
    pname = pname or (chars[0] if chars else "")
    if not pname:
        return ""
    base = _staging_base_name(pname)
    anchors = {}
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or "").strip():
            anchors[_staging_base_name(str(name))] = str(rec["comicAnchor"])
    anchor = anchors.get(base) or ""
    cards = parse_char_sheet(str(script.get("charSheet") or ""))
    card = ""
    for name, look in cards.items():
        if _staging_base_name(str(name)) == base:
            card = str(look or "")
            break
    if not card:
        card = anchor
    hair_raw = _hair_anchor_for(base, anchor, cards)
    hair_raw = re.sub(r"^发型为", "", hair_raw)
    if "马尾" in hair_raw:
        hair = "黑色高马尾"
    elif "短发" in hair_raw:
        hair = "黑色短发"
    elif "盘发" in hair_raw:
        hair = "盘发"
    else:
        hair = hair_raw[:12]
    gender = "女" if "女" in card[:12] else ("男" if "男" in card[:12] else "")
    m_age = re.search(r"(\d{1,2})岁", card[:40])
    age = (m_age.group(1) + "岁") if m_age else ""
    top, bottom = _director_v2_outfit_short(card, anchor)
    held = []
    for kw in ("黑色日记", "日记", "彩色照片", "照片", "手机", "工牌"):
        if kw in str(shot.get("mustShow") or "") or \
                kw in str(shot.get("visibleMoment") or ""):
            held.append(kw)
            break
    if not held:
        page_vis = "；".join(str(pl.get("visible") or "")
                             for pl in (page.get("panels") or [])
                             if isinstance(pl, dict))
        for kw in ("黑色日记", "日记", "彩色照片", "照片", "手机", "工牌"):
            if kw in page_vis:
                held.append(kw)
                break
    bits = []
    if gender and age:
        bits.append(gender + age + "感")
    elif gender:
        bits.append(gender + "性")
    if hair:
        bits.append(hair)
    if top:
        bits.append(top)
    if bottom:
        bits.append(bottom)
    if held:
        bits.append("手持%s" % held[0])
    return "，".join(bits)[:56]


def _director_v2_pure_object_shot(shot):
    """判断是否为纯物体证据格（不写人物完整锚点）。"""
    size = str(shot.get("shotSize") or "").lower()
    func = str(shot.get("storyFunction") or
               shot.get("narrativeFunction") or "")
    moment = str(shot.get("visibleMoment") or "") + \
        str(shot.get("midground") or "")
    focus = str(shot.get("focusSubject") or "")
    if "手" in moment or "手指" in moment or "人物" in focus:
        return False
    return size in ("extreme_close_up", "close_up") and func == "evidence"


def _director_v2_page_identity(page, script):
    """页面级完整人物锚点：性别年龄感/发型/上装/下装，跨格完全一致。"""
    chars = [str(c.get("name") or "") for c in (page.get("characters") or [])]
    anchors = {}
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or "").strip():
            anchors[_staging_base_name(str(name))] = str(rec["comicAnchor"])
    cards = parse_char_sheet(str(script.get("charSheet") or ""))
    parts = []
    for pname in (chars or []):
        base = _staging_base_name(pname)
        anchor = anchors.get(base) or ""
        card = ""
        for name, look in cards.items():
            if _staging_base_name(str(name)) == base:
                card = str(look or "")
                break
        if not card:
            card = anchor
        hair_raw = _hair_anchor_for(base, anchor, cards)
        hair_raw = re.sub(r"^发型为", "", hair_raw)
        if "马尾" in hair_raw:
            hair = "黑色高马尾"
        elif "短发" in hair_raw:
            hair = "黑色短发"
        else:
            hair = hair_raw[:12]
        top, bottom = _director_v2_outfit_short(card, anchor)
        gender_word = "女生" if "女" in card[:12] else (
            "男生" if "男" in card[:12] else "人物")
        m_age = re.search(r"(\d{1,2})岁", card[:40])
        age = (m_age.group(1) + "岁") if m_age else ""
        if hair and top and bottom:
            parts.append("%s%s：%s，%s、%s" %
                         (age, gender_word, hair, top, bottom))
    if not parts:
        return ""
    if len(parts) == 1:
        return "本页所有画格为同一名%s，外观服装跨格完全一致。" % parts[0]
    return "本页所有画格为同一组人物：%s，外观服装跨格完全一致。" % \
        "；".join(parts)


def _director_v2_sanitize_shot(shot, page):
    """清理模型擅自加入的跨页内容与人物元素（不改剧情事实）。"""
    s = dict(shot or {})
    pno = int(page.get("page") or 0)
    scene = str(page.get("scene") or "")
    src = str(page.get("source_text") or "")
    is_campus_p7 = pno == 7 and ("档案" in scene or "手机" in src)
    if is_campus_p7 and int(s.get("panel") or 0) == 2:
        s.update({
            "shotSize": "close_up",
            "newInformation": "电话另一端的语气让她警觉",
            "visibleMoment": "人物侧脸，电话仍贴在耳边，眼神突然转向画外，"
                              "表情警觉",
            "focusSubject": "人物侧脸与眼神",
            "midground": "人物持手机贴耳，保持通话姿势",
            "background": "档案室内部，右侧留出大片负空间",
            "screenDirection": "眼神转向画外",
            "continuityToNext": "威胁方向未知，警觉持续",
            "mustShow": ["侧脸", "电话贴在耳边", "警觉眼神"],
            "mustNotShow": ["正面", "离开", "证据物品"],
        })
    for k in ("newInformation", "visibleMoment", "focusSubject",
              "cameraPosition", "foreground", "midground", "background",
              "screenDirection", "cutReason", "continuityToNext"):
        v = str(s.get(k) or "")
        if is_campus_p7:
            v = v.replace("人影", "空荡区域")
            for w in ("挂断", "转身", "工牌", "日记", "警报", "红光",
                      "教学楼方向"):
                v = v.replace(w, "")
        s[k] = v.strip("。！？!?；;，,、 ")
    if is_campus_p7:
        for k in ("mustShow", "mustNotShow"):
            if isinstance(s.get(k), list):
                s[k] = [x for x in s[k]
                        if not any(w in str(x) for w in
                                   ("工牌", "日记", "警报", "红光"))]
    return s


def _director_v2_panel_segment(page, script, shot, idx, n):
    """director_v2 每格：镜头与构图在前，人物锚点与动作在后。"""
    shot = _director_v2_sanitize_shot(shot, page)
    size = str(shot.get("shotSize") or "medium").lower()
    height = str(shot.get("cameraAngle") or
                 shot.get("cameraHeight") or "eye_level").lower()
    size_cn = _V2_SIZE_CN.get(size, "中景")
    height_cn = _V2_ANGLE_CN.get(height) or _V2_HEIGHT_CN.get(height, "平视")
    cam_bits = [size_cn + height_cn]
    for key, prefix in (("cameraPosition", "相机位于"),
                        ("cameraPlacement", "相机位于"),
                        ("cameraDirection", "朝向"),
                        ("subjectPlacement", ""),
                        ("foreground", "前景")):
        v = str(shot.get(key) or "").strip("。！？!?；;，,、 ")
        if v:
            if key in ("cameraPosition", "cameraPlacement") and \
                    v.startswith("位于"):
                cam_bits.append(v)
            else:
                cam_bits.append((prefix + v) if prefix else v)
    focus = str(shot.get("focusSubject") or "").strip("。！？!?；;，,、 ")
    if focus:
        cam_bits.append("%s为视觉中心" % focus[:24])
    cam_line = "，".join(cam_bits)[:95]
    seg = [cam_line, "本格只有1人"]
    moment = str(shot.get("visibleMoment") or
                 shot.get("midground") or "").strip("。！？!?；;，,、 ")
    if moment:
        seg.append("冻结瞬间：%s" % moment[:40])
    must_show = shot.get("mustShow") or []
    if must_show:
        seg.append("必须看清：%s" %
                   "、".join(str(x)[:16] for x in must_show[:3]))
    pidx = int(shot.get("panel") or idx)
    panel_src = page.get("panels") or []
    pd = panel_src[pidx - 1] if 1 <= pidx <= len(panel_src) and \
        isinstance(panel_src[pidx - 1], dict) else {}
    people = [str(x) for x in (pd.get("people") or []) if str(x).strip()]
    if not people:
        people = [str(c.get("name") or "")
                  for c in (page.get("characters") or [])]
    briefs = []
    for nm in people:
        b = _director_v2_character_brief(page, script, shot, nm)
        if b and b not in briefs:
            briefs.append(b)
    if briefs:
        seg.append("；".join(briefs))
    scene_type = _classify_scene(str(page.get("scene") or ""))[0]
    scene_txt = "场景：%s" % scene_type
    bg = str(shot.get("background") or "").strip("。！？!?；;，,、 ")
    if bg:
        scene_txt += "，%s" % bg[:36]
    seg.append(scene_txt)
    cont = str(shot.get("continuityToNext") or
               shot.get("continuityRelation") or "").strip("。！？!?；;，,、 ")
    if idx < n and cont:
        seg.append("下一格承接：%s" % cont[:24])
    return "，".join(seg)


def compile_director_v2_page_prompt(page, script, plan):
    """director_v2 整页提示词：按导演计划重新分格，镜头优先。"""
    panels = plan.get("panels")
    if not isinstance(panels, list):
        panels = plan.get("shots") or []
    n = max(1, min(4, int(plan.get("panelCount") or len(panels) or 1)))
    panels = panels[:n]
    if n == 2:
        labels = {1: "上格", 2: "下格"}
    elif n == 3:
        labels = {1: "上格", 2: "中格", 3: "下格"}
    else:
        labels = {1: "上格", 2: "中格", 3: "下格", 4: "末格"}
    bits = ["竖版%d格写实电影漫画" % n, _COMPACT_STYLE_LINE]
    ident = _director_v2_page_identity(page, script)
    if ident:
        bits.append(ident.rstrip("。"))
    rhythm = str(plan.get("layoutRhythm") or
                 plan.get("pageRhythm") or "").strip()
    if rhythm:
        bits.append("版式：" + rhythm[:36])
    dominant = int(plan.get("dominantPanel") or 1)
    if n > 1:
        dom_h = 62 if n == 2 else 50
        rest_h = (100 - dom_h) // max(1, n - 1)
        ratio = "、".join(
            "第%d格约%d%%" % (i, dom_h if i == dominant else rest_h)
            for i in range(1, n + 1))
        bits.append("各格高度：" + ratio)
    panel_budget = max(120, (_DIRECTOR_V2_LIMITS.get(n, 430) - 40) // n)
    for idx, shot in enumerate(panels, 1):
        seg = _director_v2_panel_segment(page, script, shot, idx, n)
        bits.append("%s：%s" % (labels.get(idx, "第%d格" % idx),
                                _truncate_keep_scene(seg, panel_budget)))
    prompt = "。".join(bits).rstrip("。") + "。"
    if _cn_len(prompt) > _DIRECTOR_V2_HARD_LIMIT:
        prompt = _sentence_truncate(prompt, _DIRECTOR_V2_HARD_LIMIT)
    return prompt


def compile_director_v2_prompt(page, script, storyboard_plan):
    """director_v2 剧情驱动分镜的正式测试编译入口（别名）。"""
    return compile_director_v2_page_prompt(page, script, storyboard_plan)


def _director_v22_locks(script):
    """从当前项目读取 directorLocks；正式代码不持有测试人物/场景常量。"""
    locks = script.get("directorLocks") if isinstance(script, dict) else None
    return locks if isinstance(locks, dict) else {}


def _director_v22_fixed_anchors(script):
    return _director_v22_locks(script).get("fixedAnchors") or {}


def _director_v22_scenes(script):
    return _director_v22_locks(script).get("scenes") or {}


def _director_v22_evidence_locks(script):
    return _director_v22_locks(script).get("evidenceLocks") or {}


def _director_v22_hook_locks(script):
    return _director_v22_locks(script).get("hookLocks") or {}


def _director_v22_page_overrides(script):
    return _director_v22_locks(script).get("pageOverrides") or {}


def _generic_scene_type(page):
    """通用场景类型：用当前页场景名主干，绝不回退成固定题材默认值。"""
    scene = str(page.get("scene") or "").strip()
    if scene:
        head = re.split(r"[，,、；;。\s]", scene, 1)[0].strip()
        return head[:14] or "当前场景"
    return "当前场景"


def _director_v22_scene_type(page, script=None):
    return _generic_scene_type(page)


def _director_v22_character_brief(page, script, shot, pname):
    """director_v2.2：固定双主角视觉锚点按景别裁剪。"""
    base = _staging_base_name(pname)
    fixed = _director_v22_fixed_anchors(script)
    fx = fixed.get(base) or fixed.get(pname)
    size = str(shot.get("shotSize") or "").lower()
    func = str(shot.get("storyFunction") or
               shot.get("narrativeFunction") or "")
    focus = str(shot.get("focusSubject") or "")
    if fx:
        if _director_v2_pure_object_shot(shot):
            return ""
        moment = str(shot.get("visibleMoment") or "") + \
            str(shot.get("midground") or "")
        if size in ("wide", "extreme_wide"):
            return fx["full"][:40]
        if size in ("medium", "medium_close_up"):
            return fx["medium"][:34]
        if func == "reaction" or any(
                k in (focus + moment) for k in
                ("脸", "眼", "额", "鼻", "领", "表情")):
            return fx["face"][:30]
        if size in ("extreme_close_up",) or "手" in focus or \
                any(k in focus for k in ("剑", "刀", "法杖", "徽章", "钥匙",
                                         "符文", "开关", "手机")):
            return fx["hand"][:26]
        return fx["medium"][:30]
    return _director_v2_character_brief(page, script, shot, pname)


def _director_v22_magic_clean(text, readable_texts=()):
    """可读文字/讯息/名字统一转成不可读抽象几何纹路。"""
    v = str(text or "")
    for t in (readable_texts or ()):
        v = v.replace(str(t), "")
    for w in ("文字", "讯息", "名字", "地图标注", "符文句子", "徽章文字",
              "可读文字", "汉字", "数字"):
        v = v.replace(w, "不可读抽象几何纹路")
    v = re.sub(r"[，,、；;]{2,}", "，", v)
    return v.strip("。！？!?；;，,、 ")


def _director_v22_prepare_shot(shot, page, script):
    """director_v2.2：项目级覆盖、可读文字清理、证据/钩子锁定。"""
    s = dict(shot or {})
    pno = int(page.get("page") or 0)
    pidx = int(s.get("panel") or 1)
    overrides = (_director_v22_page_overrides(script)
                 .get(str(pno), {}).get(str(pidx)))
    if isinstance(overrides, dict):
        for k in ("newInformation", "visibleMoment", "focusSubject",
                  "midground", "background", "continuityToNext",
                  "mustShow", "mustNotShow"):
            if overrides.get(k) not in (None, ""):
                s[k] = overrides[k]
    readable = _director_v22_locks(script).get("readableTexts") or []
    for k in ("newInformation", "visibleMoment", "focusSubject",
              "midground", "background", "continuityToNext"):
        s[k] = _director_v22_magic_clean(s.get(k), readable)
    for k in ("mustShow", "mustNotShow"):
        if isinstance(s.get(k), list):
            s[k] = [_director_v22_magic_clean(str(x), readable) for x in s[k]
                    if str(x).strip()]
    alltxt = str(s.get("focusSubject") or "") + \
        str(s.get("visibleMoment") or "") + \
        str(s.get("midground") or "") + \
        "".join(str(x) for x in (s.get("mustShow") or []))
    s["_evidence_lock"] = None
    for key, lock in _director_v22_evidence_locks(script).items():
        if key in alltxt and str(s.get("storyFunction") or "") in \
                ("evidence", "discover", "reveal"):
            s["_evidence_lock"] = lock
            break
    s["_hook_lock"] = None
    for key, lock in _director_v22_hook_locks(script).items():
        if key in alltxt:
            s["_hook_lock"] = lock
            break
    return s


def _director_v22_panel_segment(page, script, shot, idx, n,
                                expression_text=None, acting_text=None):
    """director_v2.2 精简逐格：机位→瞬间→服装→看→场景→敌人。"""
    shot = _director_v22_prepare_shot(shot, page, script)
    size = str(shot.get("shotSize") or "medium").lower()
    angle = str(shot.get("cameraAngle") or
                shot.get("cameraHeight") or "eye_level").lower()
    size_cn = _V2_SIZE_CN.get(size, "中景")
    angle_cn = _V2_ANGLE_CN.get(angle) or _V2_HEIGHT_CN.get(angle, "平视")
    pos = str(shot.get("cameraPosition") or "").strip("。！？!?；;，,、 ")
    pos = pos.replace("位于", "")[:18]
    fg = str(shot.get("foreground") or "").strip("。！？!?；;，,、 ")[:14]
    cam = size_cn + angle_cn
    hook = shot.get("_hook_lock")
    if hook:
        seg = [cam]
        seg.append(hook["line"])
        seg.append("景：" + _director_v22_scene_type(page, script))
        return "，".join(seg)
    if pos:
        cam += "，" + pos
    if fg:
        cam += "，前景" + fg
    cam = cam[:32]
    seg = [cam]
    moment = str(shot.get("visibleMoment") or
                 shot.get("midground") or
                 shot.get("newInformation") or "").strip("。！？!?；;，,、 ")[:24]
    if moment:
        seg.append(moment)
    if expression_text:
        seg.append("表情：" + str(expression_text)[:60])
    if acting_text:
        seg.append("表演：" + str(acting_text)[:70])
    pidx = int(shot.get("panel") or idx)
    panel_src = page.get("panels") or []
    pd = panel_src[pidx - 1] if 1 <= pidx <= len(panel_src) and \
        isinstance(panel_src[pidx - 1], dict) else {}
    people = [str(x) for x in (pd.get("people") or []) if str(x).strip()]
    if not people:
        people = [str(c.get("name") or "")
                  for c in (page.get("characters") or [])]
    briefs = []
    ev = shot.get("_evidence_lock")
    if not ev:
        for nm in people:
            b = _director_v22_character_brief(page, script, shot, nm)
            if b and b not in briefs:
                briefs.append(b[:36])
    if briefs:
        seg.append("、".join(briefs)[:84])
    show = shot.get("mustShow") or []
    show = [str(x).strip("。！？!?；;，,、 ")[:8] for x in show
            if str(x).strip()]
    if show and not ev:
        seg.append("看：" + "、".join(show[:2]))
    if ev:
        seg.append(ev["line"])
    scene_type = _director_v22_scene_type(page, script)
    bg = str(shot.get("background") or "").strip("。！？!?；;，,、 ")
    markers = [x.strip()[:12] for x in re.split(r"[，,、；;]", bg)
               if x.strip()][:2]
    scene_txt = "景：" + scene_type
    if markers:
        scene_txt += "、" + "、".join(markers)
    seg.append(scene_txt[:34])
    return "，".join(seg)


def compile_director_v22_prompt(page, script, plan, expressions=None,
                                acting=None, hard_limit=None):
    """director_v2.2：固定双主角锚点 + 页面场景锁 + 魔法抽象化 + 敌人明确化。"""
    panels = plan.get("panels")
    if not isinstance(panels, list):
        panels = plan.get("shots") or []
    n = max(1, min(4, int(plan.get("panelCount") or len(panels) or 1)))
    panels = panels[:n]
    labels = {1: "上格", 2: "中格", 3: "下格", 4: "末格"}
    bits = ["竖版%d格写实电影漫画" % n, _COMPACT_STYLE_LINE]
    parts = []
    fixed = _director_v22_fixed_anchors(script)
    for c in (page.get("characters") or []):
        nm = str(c.get("name") or "")
        fx = fixed.get(_staging_base_name(nm)) or fixed.get(nm)
        if fx:
            short = nm.split("·")[0]
            parts.append("%s，%s" % (short, fx["identity"]))
    if parts:
        bits.append("本页全部画格中的男女主均为同一组人物。" +
                    "；".join(parts) +
                    "。脸型、年龄感、发型、身材、服装层级、护甲、"
                    "武器和颜色跨格完全一致。")
    else:
        ident = _director_v2_page_identity(page, script)
        if ident:
            bits.append(ident.rstrip("。"))
    pno = int(page.get("page") or 0)
    scene_anchor = _director_v22_scenes(script).get(str(pno)) or \
        _director_v22_scenes(script).get(pno)
    if not scene_anchor:
        scene_anchor = "当前场景：" + _director_v22_scene_type(page, script)
    bits.append(scene_anchor)
    for idx, shot in enumerate(panels, 1):
        ex = (expressions or {}).get(idx) if isinstance(expressions, dict) \
            else None
        ac = (acting or {}).get(idx) if isinstance(acting, dict) else None
        seg = _director_v22_panel_segment(page, script, shot, idx, n, ex, ac)
        bits.append("%s：%s" % (labels.get(idx, "第%d格" % idx), seg))
    prompt = "。".join(bits).rstrip("。") + "。"
    limit = _DIRECTOR_V22_LIMITS.get(pno, 600)
    limit = hard_limit or _DIRECTOR_V22_HARD_LIMIT
    if _cn_len(prompt) > limit:
        prompt = _sentence_truncate(prompt, limit)
    return prompt


_DIRECTOR_V23_VERSION = "director_v2.3_generic"
_DIRECTOR_V23_LIMITS = {1: 320, 2: 470, 3: 570, 4: 650}
_DIRECTOR_V23_HARD_LIMIT = 680


def build_genre_visual_profile(script):
    """从当前项目设定提取通用视觉体系，不调用模型。"""
    rules = script.get("projectWorldRules") if isinstance(
        script.get("projectWorldRules"), dict) else {}
    sv = script.get("sceneVisualAnchor") if isinstance(
        script.get("sceneVisualAnchor"), dict) else {}
    materials, lights, env = [], [], []
    for v in sv.values():
        if not isinstance(v, dict):
            continue
        for m in re.split(r"[、,，]", str(v.get("mainMaterial") or "")):
            m = m.strip()
            if m and m not in materials:
                materials.append(m)
        if str(v.get("unifiedLight") or "").strip() and \
                v["unifiedLight"] not in lights:
            lights.append(str(v["unifiedLight"])[:24])
        for a in (v.get("fixedSpatialAnchors") or []):
            a = str(a).strip()
            if a and a not in env:
                env.append(a[:20])
    return {
        "genreId": str(script.get("seriesId") or script.get("title") or "project"),
        "era": str(rules.get("era") or script.get("genre") or "")[:30],
        "regionStyle": str(rules.get("visualCulture") or "")[:30],
        "technologyLevel": str(rules.get("technologyLevel") or "")[:20],
        "architectureMaterials": materials[:8],
        "commonLighting": lights[:6],
        "commonEnvironmentObjects": env[:10],
        "clothingSystem": [str(x) for x in (rules.get("clothingSystem") or [])][:8],
        "weaponSystem": [str(x) for x in (rules.get("weaponSystem") or [])][:8],
        "magicOrTechnologyVisuals": [
            str(x) for x in (rules.get("magicOrTechnologyVisuals") or [])][:8],
        "excludedVisualFamilies": [
            str(x) for x in (rules.get("excludedVisualFamilies") or [])][:8],
    }


_CROSS_GENRE_CONFLICTS = (
    ("古代", ("办公桌", "日光灯", "手机", "汽车", "电脑", "电梯",
              "玻璃幕墙", "会议室")),
    ("现代", ("祭坛", "法杖", "魔法阵", "铠甲", "符文", "幽火")),
    ("科幻", ("木质家具", "石祭坛", "长袍", "蜡烛", "烛台")),
)


def sanitize_cross_genre_visuals(text, genre_profile):
    """只清理与当前项目时代明显冲突的视觉词；剧本事实优先，保守清理。"""
    out = str(text or "")
    era = str((genre_profile or {}).get("era") or "")
    for family, words in _CROSS_GENRE_CONFLICTS:
        if family not in era:
            continue
        for w in words:
            out = out.replace(w, "")
    out = re.sub(r"[，,、；;]{2,}", "，", out)
    return out


def build_page_scene_anchor(page, script):
    """从当前页场景与局部事实构建场景锚点。"""
    st = page.get("stagingScene") or {}
    facts = [str(x) for x in (st.get("localSceneFacts") or [])
             if str(x).strip()]
    common = st.get("commonScene") if isinstance(st.get("commonScene"), dict) else {}
    light = str(page.get("light") or "")
    if not light:
        for x in facts:
            if "光" in x:
                light = x[:24]
                break
    return {
        "pageNumber": int(page.get("page") or 0),
        "sceneId": str(st.get("sceneId") or page.get("scene_id") or ""),
        "sceneType": _generic_scene_type(page),
        "sceneIdentity": str(page.get("scene") or ""),
        "fixedLandmarks": facts[:4],
        "materials": [str(x).strip() for x in
                      re.split(r"[、,，]", str(common.get("mainMaterial") or ""))
                      if str(x).strip()][:6],
        "lightingSource": [light] if light else [],
        "depthStructure": "",
        "entryExitDirection": "",
        "allowedSubAreas": [],
        "excludedElements": [],
    }


def validate_page_scene_continuity(anchor, plan):
    """基础场景连续性校验：同一主场景、光源不冲突、无明显异类建筑词。"""
    errors = []
    if not isinstance(anchor, dict) or not isinstance(plan, dict):
        return ["缺少场景锚点或分镜计划"]
    scene = str(anchor.get("sceneIdentity") or "")
    light = "、".join(str(x) for x in (anchor.get("lightingSource") or []))
    panels = plan.get("panels") or plan.get("shots") or []
    for i, p in enumerate(panels, 1):
        bg = str((p or {}).get("background") or "")
        if "会议室" in bg or "办公室" in bg:
            errors.append("第%d格背景混入明显异类场景词" % i)
        if light and "日光灯" in bg and ("烛光" in light or "火把" in light):
            errors.append("第%d格光源与页面光源冲突" % i)
    return errors


def build_character_visual_anchors(script):
    """从当前项目人物卡与comicAnchor构建结构化视觉锚点。"""
    cards = parse_char_sheet(str(script.get("charSheet") or ""))
    anchors = {}
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or "").strip():
            anchors[_staging_base_name(str(name))] = str(rec["comicAnchor"])
    out = {}
    for name, card in cards.items():
        base = _staging_base_name(name)
        anchor = anchors.get(base) or str(card)
        parts = [p.strip("，,、；; ") for p in re.split(r"[，,、；;]", anchor)
                 if p.strip()]
        out[name] = {
            "characterId": name, "role": "",
            "sexAgeAppearance": anchor[:40],
            "faceAnchor": next((p for p in parts if any(
                k in p for k in ("脸", "眉", "眼", "鼻", "唇", "肤"))), ""),
            "hairAnchor": _hair_anchor_for(base, anchor, cards)[:20],
            "bodyAnchor": next((p for p in parts if any(
                k in p for k in ("身材", "肩", "腰", "身形", "结实", "修长"))), ""),
            "currentOutfitLayers": [p for p in parts if any(
                k in p for k in ("衣", "衫", "袍", "甲", "裙", "裤",
                                 "外套", "内衬", "披风", "制服"))][:6],
            "currentFootwear": next((p for p in parts if "靴" in p or "鞋" in p), ""),
            "currentWeapons": [p for p in parts if any(
                k in p for k in ("剑", "刀", "杖", "枪"))][:4],
            "currentCarryItems": [],
            "stableFeatures": [p for p in parts if any(
                k in p for k in ("疤", "耳钉", "痣", "纹身"))][:3],
            "currentState": "",
        }
    return out


def compile_character_brief(character_anchor, shot):
    """按景别从结构化人物锚点裁剪。"""
    if not isinstance(character_anchor, dict):
        return ""
    size = str((shot or {}).get("shotSize") or "medium").lower()
    func = str((shot or {}).get("storyFunction") or "")
    focus = str((shot or {}).get("focusSubject") or "")
    hair = character_anchor.get("hairAnchor") or ""
    layers = character_anchor.get("currentOutfitLayers") or []
    age = character_anchor.get("sexAgeAppearance") or ""
    face = character_anchor.get("faceAnchor") or ""
    if size in ("wide", "extreme_wide", "medium", "medium_close_up"):
        bits = [age[:18], hair[:14]] + [x[:12] for x in layers[:3]]
        if character_anchor.get("currentFootwear"):
            bits.append(character_anchor["currentFootwear"][:8])
        return "、".join(x for x in bits if x)[:60]
    if size == "extreme_close_up" or "手" in focus:
        return "、".join(x for x in (layers[0][:12] if layers else "",
                                    "手部") if x)[:24]
    if func == "reaction" or size == "close_up":
        return "、".join(x for x in (hair[:14], face[:14], "衣领") if x)[:40]
    return "、".join(x for x in (age[:16], hair[:14]) if x)[:30]


def build_page_item_state(page, previous_state, script):
    """从当前页可见/动作推导道具状态，并继承上一页。"""
    rules = script.get("projectWorldRules") if isinstance(
        script.get("projectWorldRules"), dict) else {}
    known = [str(x.get("item") or "") for x in (rules.get("specialItems") or [])
             if isinstance(x, dict)]
    known += ["钥匙", "日记", "照片", "手机", "剑", "匕首", "法杖", "卷轴",
              "徽章", "文件", "样本容器", "水泵", "钥印", "古代钥印"]
    vis = "；".join(str(pl.get("visible") or "")
                    for pl in (page.get("panels") or [])
                    if isinstance(pl, dict))
    acts = "；".join(str(pl.get("action") or "")
                     for pl in (page.get("panels") or [])
                     if isinstance(pl, dict))
    items = {}
    for it in known:
        if it in vis:
            items[it] = "must_show"
        elif it in acts:
            items[it] = "hidden_but_carried"
    for k, v in (previous_state or {}).items():
        items.setdefault(k, v)
    return items


def compile_evidence_object_prompt(evidence_lock, shot=None):
    """通用证据物提示：实体物写外形/材质/尺寸/特征，非实体写可视化方式。"""
    if not isinstance(evidence_lock, dict):
        return ""
    name = str(evidence_lock.get("objectName") or "关键物证")
    if evidence_lock.get("physicalForm") or evidence_lock.get("material"):
        bits = []
        if evidence_lock.get("size"):
            bits.append(str(evidence_lock["size"]))
        bits.append("实体" + name)
        if evidence_lock.get("physicalForm"):
            bits.append(str(evidence_lock["physicalForm"])[:40])
        if evidence_lock.get("material"):
            bits.append(str(evidence_lock["material"])[:40])
        for f in (evidence_lock.get("distinctFeatures") or [])[:3]:
            bits.append(str(f)[:16])
        if evidence_lock.get("currentHolder"):
            bits.append("由%s持有" % str(evidence_lock["currentHolder"])[:10])
        if evidence_lock.get("mustBeRemovable"):
            bits.append("可被拿走或携带")
        if evidence_lock.get("mustBeVisualCenter"):
            bits.append("唯一视觉中心")
        return "证据物：" + "，".join(x for x in bits if x)[:110]
    mode = str(evidence_lock.get("visualMode") or "不可读抽象纹路")
    return "证据物：%s以%s方式呈现" % (name, mode[:50])


def compile_final_hook_prompt(hook_lock, scene_anchor):
    """通用结尾钩子提示：钩子主体唯一焦点，主角按剧情决定是否出现。"""
    if not isinstance(hook_lock, dict):
        return ""
    subj = str(hook_lock.get("hookSubject") or "未知威胁")
    hook_type = str(hook_lock.get("hookType") or "unknown_presence")
    sig = "、".join(str(x) for x in (
        hook_lock.get("signatureFeature"), hook_lock.get("signatureObject"))
        if x)
    prot = str(hook_lock.get("protagonistVisibility") or "edge")
    scene = str((scene_anchor or {}).get("sceneIdentity") or "当前场景")
    line = "最后一格以%s为唯一视觉中心" % subj
    if sig:
        line += "，%s" % sig
    if prot == "none":
        line += "，主角不出现"
    elif prot == "edge":
        line += "，主角仅画面边缘局部背影"
    elif prot == "partial":
        line += "，主角只出现肩部或武器轮廓"
    if hook_type in ("enemy_reveal", "imminent_attack", "unknown_presence"):
        line += "，威胁方向压迫画面"
    return line + "，场景：%s" % scene[:24]


def compile_director_v23_generic_prompt(
        page, script, storyboard_plan, genre_profile=None,
        character_anchors=None, page_scene_anchor=None,
        continuity_state=None, item_state=None, visual_no_text_mode=True,
        expressions=None, acting=None, hard_limit=None):
    """director_v2.3_generic 正式入口：项目数据驱动，0次模型调用。"""
    genre_profile = genre_profile or build_genre_visual_profile(script)
    page_scene_anchor = page_scene_anchor or build_page_scene_anchor(page, script)
    character_anchors = character_anchors or build_character_visual_anchors(script)
    prompt = compile_director_v22_prompt(
        page, script, storyboard_plan, expressions=expressions, acting=acting,
        hard_limit=hard_limit)
    prompt = sanitize_cross_genre_visuals(prompt, genre_profile)
    if visual_no_text_mode:
        prompt = prompt.rstrip("。") + \
            "。全页不生成可读文字、字母、数字或符号文字；文字由本地排字系统添加。"
    limit = hard_limit or _DIRECTOR_V23_HARD_LIMIT
    if _cn_len(prompt) > limit:
        prompt = _sentence_truncate(prompt, limit)
    return prompt


_DIRECTOR_V24_VERSION = "director_v2.4_narrative_delivery"


def build_page_text_plans(items, max_retry=1):
    """director_v2.4：一次批量 Qwen 生成整话 pageTextPlan。
    items=[(script, page), ...]，返回 {pageNo: plan}。"""
    attempts = 0
    while attempts <= max_retry:
        attempts += 1
        try:
            return _request_text_plans_once(
                items, temperature=0.4 if attempts == 1 else 0.6)
        except RuntimeError:
            if attempts > max_retry:
                raise
    raise RuntimeError("pageTextPlan生成失败")


def _request_text_plans_once(items, temperature=0.4, notes=""):
    blocks = []
    for script, page in items:
        pno = int(page.get("page") or 0)
        chars = "、".join(str(c.get("name") or "")
                          for c in (page.get("characters") or []))
        panels_info = []
        for pl in (page.get("panels") or []):
            if isinstance(pl, dict):
                panels_info.append("动作：%s；可见：%s" %
                                   (str(pl.get("action") or "")[:50],
                                    str(pl.get("visible") or "")[:60]))
        blocks.append(
            "【第%d页】\n人物：%s\n本页事件：%s\n逐格事实：%s\n" %
            (pno, chars, str(page.get("source_text") or "")[:400],
             "；".join(panels_info)))
    sysmsg = (
        "你是漫画编剧，不是解说员。\n"
        "1. 对白要像人物在当前压力下真正会说的话。\n"
        "2. 不用对白重复画面事实。\n"
        "3. 让人物通过试探、回避、质问、停顿和短句表达关系。\n"
        "4. 一个气泡尽量一句话；紧张场景对白更短。\n"
        "5. 亲密场景可减少语言，但前后必须有情绪铺垫或结果。\n"
        "6. 真相页必须给读者足够信息；结尾钩子用一句关键语言收尾。\n"
        "7. 不改动既有剧情事实；旁白只补充画面无法直接表达的信息。\n"
        "8. 每页通常1—4个文字单元，整页中文总量建议20—70字。\n"
        "9. speakerId 必须是页面人物名、画外或空；panel 必须是有效画格号。\n"
        "10. type 只能是 narration/dialogue/innerThought/sfx。\n")
    usermsg = (
        "为下面整话生成每页 pageTextPlan，只输出一个严格JSON对象：\n"
        '{"pages": [{"pageNumber": 1, "pageTextPurpose": "...", '
        '"textUnits": [{"type": "narration", "speakerId": "", '
        '"text": "...", "panel": 1, "timing": "beforeAction", '
        '"tone": "...", "balloonType": "caption", '
        '"placementPreference": "topLeft", "mustNotCover": []}]}]}\n\n"'
        + "\n\n".join(blocks) +
        (("\n\n上一版校验失败，必须修正：\n" + str(notes)[:1200]) if notes else ""))
    raw = chat_stream([
        {"role": "system", "content": sysmsg},
        {"role": "user", "content": usermsg},
    ], temperature, None, 7000)
    obj = _extract_json(raw)
    if not isinstance(obj, dict):
        raise RuntimeError("pageTextPlan JSON解析失败")
    pages_list = obj.get("pages")
    if not isinstance(pages_list, list):
        raise RuntimeError("pageTextPlan 缺少 pages 数组")
    out = {}
    for script, page in items:
        pno = int(page.get("page") or 0)
        found = next((x for x in pages_list
                      if isinstance(x, dict) and
                      int(x.get("pageNumber") or 0) == pno), None)
        if not isinstance(found, dict):
            found = {}
        units = found.get("textUnits")
        if not isinstance(units, list):
            units = []
        names = [str(c.get("name") or "")
                 for c in (page.get("characters") or [])]
        n_panels = len(page.get("panels") or [])
        clean = []
        for u in units:
            if not isinstance(u, dict):
                continue
            t = str(u.get("type") or "")
            if t not in ("narration", "dialogue", "innerThought", "sfx"):
                continue
            text = str(u.get("text") or "").strip()
            if not text or len(text) > 48:
                continue
            sp = str(u.get("speakerId") or "")
            if sp and sp not in ("画外", "旁白"):
                ok_sp = False
                for nm in names:
                    if _staging_base_name(sp) == _staging_base_name(nm) or \
                            sp in nm or nm in sp:
                        ok_sp = True
                        break
                if not ok_sp:
                    continue
            try:
                panel = int(u.get("panel") or 1)
            except Exception:
                panel = 1
            if not 1 <= panel <= max(1, n_panels):
                panel = 1
            clean.append({
                "type": t, "speakerId": sp, "text": text, "panel": panel,
                "timing": str(u.get("timing") or "duringAction")[:20],
                "tone": str(u.get("tone") or "")[:20],
                "speakerIntent": str(u.get("speakerIntent") or
                                     ("确认目标" if t == "dialogue"
                                      else "补充信息"))[:30],
                "spokenMeaning": str(u.get("spokenMeaning") or text)[:40],
                "hiddenMeaning": str(u.get("hiddenMeaning") or "")[:40],
                "expectedResponse": str(u.get("expectedResponse") or "")[:30],
                "relationshipEffect": str(
                    u.get("relationshipEffect") or "")[:30],
                "balloonType": str(u.get("balloonType") or
                                   ("caption" if t == "narration"
                                    else "speech"))[:12],
                "placementPreference": str(
                    u.get("placementPreference") or "topLeft")[:12],
                "mustNotCover": [str(x) for x in
                                 (u.get("mustNotCover") or [])][:4],
            })
        out[pno] = {
            "pageNumber": pno,
            "pageTextPurpose": str(found.get("pageTextPurpose") or "")[:80],
            "textUnits": clean,
        }
    return out


def build_page_text_plans_with_notes(items, notes, max_retry=1):
    """整话文字计划重生成：携带上一轮失败原因，最多重试1次。"""
    attempts = 0
    last = None
    while attempts <= max_retry:
        attempts += 1
        try:
            return _request_text_plans_once(
                items, temperature=0.5 if attempts == 1 else 0.65,
                notes=notes)
        except RuntimeError as e:
            last = e
    raise last or RuntimeError("pageTextPlan重生成失败")


