def build_panel_expression_plans(page, script, storyboard_plan, text_plan):
    """director_v2.4：由分镜功能与对白意图确定性生成每格表情。"""
    panels = (storyboard_plan or {}).get("panels") or []
    names = [str(c.get("name") or "")
             for c in (page.get("characters") or [])]
    exprs = []
    prev_emotion = None
    units = (text_plan or {}).get("textUnits") or []
    for i, shot in enumerate(panels, 1):
        func = str(shot.get("storyFunction") or "reaction")
        base = _EMOTION_MAP.get(func, _EMOTION_MAP["reaction"])
        pidx = int(shot.get("panel") or i)
        panel_units = [u for u in units if int(u.get("panel") or 1) == pidx]
        speaker_emotion = ""
        for u in panel_units:
            if u.get("type") in ("dialogue", "innerThought"):
                tone = str(u.get("tone") or "")
                for k, v in _TONE_EMOTION.items():
                    if k in tone:
                        speaker_emotion = v
                        break
                if speaker_emotion:
                    break
        panel_src = page.get("panels") or []
        pd = panel_src[pidx - 1] if 1 <= pidx <= len(panel_src) and \
            isinstance(panel_src[pidx - 1], dict) else {}
        people = [str(x) for x in (pd.get("people") or []) if str(x).strip()]
        if not people:
            people = names
        chars_expr = []
        for nm in people:
            is_speaker = any(
                _staging_base_name(str(u.get("speakerId") or "")) ==
                _staging_base_name(nm) for u in panel_units)
            if is_speaker and speaker_emotion in _EXPR_VARIANTS:
                e = dict(_EXPR_VARIANTS[speaker_emotion])
                e["emotion"] = speaker_emotion
            else:
                e = dict(base)
                e["emotion"] = func
            e["gazeTarget"] = str(shot.get("focusSubject") or "前方")[:16]
            e["microAction"] = ""
            if func == "reaction" and i > 1:
                e["microAction"] = "动作停顿"
            e["intensity"] = 2 if func in ("discover", "evidence") else 1
            chars_expr.append({"characterId": nm, **e})
        if prev_emotion == func and i > 1:
            for c in chars_expr:
                c["microAction"] = "表情进一步收紧"
                c["intensity"] = min(3, int(c.get("intensity") or 1) + 1)
        prev_emotion = func
        exprs.append({"panel": pidx, "characterExpressions": chars_expr})
    return {"pageNumber": int(page.get("page") or 0),
            "panels": exprs}


def _compose_expression_text(expression_plan):
    """把表情计划压缩成一句逐格提示词。"""
    if not isinstance(expression_plan, dict):
        return ""
    parts = []
    for panel in (expression_plan.get("panels") or []):
        for c in (panel.get("characterExpressions") or []):
            cid = str(c.get("characterId") or "人物").split("（")[0]
            bits = [str(c.get("eyes") or ""), str(c.get("brows") or ""),
                    str(c.get("mouth") or ""),
                    str(c.get("microAction") or "")]
            parts.append("%s：%s" % (cid,
                                     "、".join(x for x in bits if x)[:34]))
    return "；".join(x for x in parts if x)[:80]


_DIRECTOR_V25_VERSION = "director_v2.5_story_readability"


def build_episode_opening_plan(script):
    """director_v2.5：从已确认设定确定性生成开场定位计划（0次模型）。"""
    rules = script.get("projectWorldRules") if isinstance(
        script.get("projectWorldRules"), dict) else {}
    sv = script.get("sceneVisualAnchor") if isinstance(
        script.get("sceneVisualAnchor"), dict) else {}
    pages = script.get("pages") or []
    synopsis = str((script.get("episodePlan") or {}).get(
        "episodeSynopsis") or "")
    first_scene = str(pages[0].get("scene") or "") if pages else ""
    chars = []
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or ""):
            chars.append("%s：%s" % (name.split("（")[0],
                                    rec["comicAnchor"][:36]))
    last_scene = str(pages[-1].get("source_text") or "")[-80:] if pages else ""
    return {
        "isSeriesOpening": int(script.get("episodeNo") or 1) == 1 and
        not str(script.get("previousEpisode") or "").strip(),
        "worldContext": "%s，%s" % (
            str(rules.get("visualCulture") or script.get("genre") or ""),
            str(rules.get("era") or "")),
        "locationIdentity": first_scene,
        "currentSituation": synopsis[:80],
        "protagonistIntroductions": chars[:4],
        "missionGoal": synopsis[:120],
        "relationshipContext": next(
            (k for k in ("旧情", "隔阂", "曾经", "并肩", "分道")
             if k in synopsis), ""),
        "immediateRisk": last_scene,
        "openingQuestion": "他们能否在宗门追查前找到真相？",
        "orientationPageCount": 3,
        "sceneMaterials": [str(x) for v in sv.values()
                           if isinstance(v, dict)
                           for x in re.split(r"[、,，]",
                                             str(v.get("mainMaterial") or ""))
                           if str(x).strip()][:8],
    }


def build_reader_knowledge_plans(script, storyboard_plans):
    """director_v2.5：逐页读者知识计划（确定性推导）。"""
    pages = script.get("pages") or []
    plans = {}
    known_before = []
    for p in pages:
        pno = int(p.get("page") or 0)
        sbp = (storyboard_plans or {}).get(str(pno)) or {}
        beats = [str(x) for x in
                 ((sbp.get("viewerInformationOrder") or []) +
                  [str(s.get("newInformation") or "")[:30]
                   for s in (sbp.get("panels") or [])]) if x.strip()]
        must_learn = beats[:2] or [str(p.get("source_text") or "")[:40]]
        funcs = [str(s.get("storyFunction") or "")
                 for s in (sbp.get("panels") or [])]
        method = ["visual"]
        if any(f in funcs for f in ("establish", "discover", "evidence")):
            method.append("evidence")
        if any(f == "reaction" for f in funcs):
            method.append("reaction")
        if any(u["type"] in ("narration", "dialogue")
               for u in (text_plans_cache.get(str(pno), {})
                         .get("textUnits") or [])):
            method.append("narration")
        plans[pno] = {
            "pageNumber": pno,
            "readerKnowsBefore": list(known_before),
            "readerMustLearn": must_learn,
            "readerQuestionAfter": str(p.get("source_text") or "")[-40:],
            "informationMethod": list(dict.fromkeys(method)),
        }
        known_before = known_before + must_learn
    return plans


text_plans_cache = {}


def build_panel_acting_plans(page, script, storyboard_plan,
                             expression_plan, text_plan):
    """director_v2.5：按分镜功能与关系类型生成每格人物表演。"""
    panels = (storyboard_plan or {}).get("panels") or []
    names = [str(c.get("name") or "")
             for c in (page.get("characters") or [])]
    out = []
    prev_emotion = {}
    units = (text_plan or {}).get("textUnits") or []
    for i, shot in enumerate(panels, 1):
        pidx = int(shot.get("panel") or i)
        func = str(shot.get("storyFunction") or "action")
        panel_units = [u for u in units if int(u.get("panel") or 1) == pidx]
        rel = _infer_relationship(func, panel_units, shot)
        panel_src = page.get("panels") or []
        pd = panel_src[pidx - 1] if 1 <= pidx <= len(panel_src) and \
            isinstance(panel_src[pidx - 1], dict) else {}
        people = [str(x) for x in (pd.get("people") or []) if str(x).strip()]
        if not people:
            people = names
        expr_panel = None
        for pe in ((expression_plan or {}).get("panels") or []):
            if int(pe.get("panel") or 0) == pidx:
                expr_panel = pe
                break
        chars = []
        for j, nm in enumerate(people):
            emo = ""
            if expr_panel:
                for c in expr_panel.get("characterExpressions") or []:
                    if _staging_base_name(str(c.get("characterId"))) == \
                            _staging_base_name(nm):
                        emo = str(c.get("emotion") or "")
                        break
            shift = ""
            if emo and prev_emotion.get(nm) and emo != prev_emotion[nm]:
                shift = "由%s转为%s" % (prev_emotion[nm], emo)
            pose = _ACTING_POSE.get(func, "站立观察")
            hand = _ACTING_HAND.get(func, "双手自然下垂")
            distance = _REL_DISTANCE.get(rel, "保持距离")
            contact = _REL_CONTACT.get(rel, "")
            if j == 1 and len(people) > 1:
                distance = "与对方距离" + \
                    {"合作": "一前一后", "冲突": "缩短", "保护": "贴身",
                     "亲密": "贴近"}.get(rel, "适中")
                contact = _REL_CONTACT.get(rel, "")
            chars.append({
                "characterId": nm,
                "currentIntent": _ACTING_INTENT.get(func, "推进剧情"),
                "emotionalShift": shift,
                "bodyPose": pose,
                "weightDistribution": "重心前移" if rel in
                ("冲突", "保护") else "重心稳定",
                "handAction": hand,
                "gazeTarget": str(shot.get("focusSubject") or "前方")[:16],
                "headDirection": "朝向%s" % (
                    "对方" if rel in ("冲突", "亲密") else
                    str(shot.get("focusSubject") or "前方"))[:14],
                "shoulderState": "肩膀绷紧" if func == "reaction" else
                "肩膀放松",
                "distanceToOther": distance,
                "contactPoint": contact,
                "movementDirection": str(
                    shot.get("movementDirection") or "")[:16],
                "microExpression": emo,
                "reactionTiming": "停顿后反应" if i > 1 else "即时反应",
            })
            prev_emotion[nm] = emo
        out.append({"panel": pidx, "characters": chars})
    return {"pageNumber": int(page.get("page") or 0), "panels": out}


_ACTING_INTENT = {
    "establish": "确认方位与威胁", "discover": "确认异常",
    "evidence": "核实关键物证", "reaction": "评估新信息",
    "decision": "做出决定", "transition": "移动进入下一区域",
}
_ACTING_POSE = {
    "establish": "站定观察四周", "discover": "动作中断，定住",
    "evidence": "俯身或伸手检查", "reaction": "转身或偏头",
    "decision": "身体转向行动方向", "transition": "侧身移动",
}
_ACTING_HAND = {
    "establish": "一手按武器，一手垂放", "discover": "手指停在半空",
    "evidence": "手持或指向物证", "reaction": "手部收紧或悬停",
    "decision": "握拳或扶剑", "transition": "一手拨开障碍",
}
_REL_DISTANCE = {"合作": "一前一后，保持两步", "冲突": "缩短至一臂内",
                 "保护": "贴身，一人挡在另一人前方",
                 "亲密": "贴近，呼吸可闻", "普通": "保持两步"}
_REL_CONTACT = {"合作": "", "冲突": "手腕相触或阻挡",
                "保护": "一手控腕，一手护肩背",
                "亲密": "手碰脸侧或肩颈", "普通": ""}


def _infer_relationship(func, panel_units, shot=None):
    txt = "".join(str(u.get("text") or "") for u in panel_units) + func
    if shot:
        txt += str(shot.get("visibleMoment") or "") + \
            str(shot.get("focusSubject") or "")
    if any(k in txt for k in ("吻", "亲密", "脸侧", "触碰", "指尖",
                              "接触", "贴近", "拥抱")):
        return "亲密" if ("吻" in txt or "亲密" in txt) else "保护"
    if any(k in txt for k in ("别碰", "质问", "冲突", "甩开")):
        return "冲突"
    if any(k in txt for k in ("护", "躲", "危险", "小心", "挡")):
        return "保护"
    if func in ("establish", "transition", "evidence"):
        return "合作"
    return "普通"


def shot_repetition_validator(plan):
    """检测相邻两格是否重复正面近景构图，返回 [(后一格下标, 原因)]。"""
    panels = (plan or {}).get("panels") or []
    issues = []
    for i in range(1, len(panels)):
        a, b = panels[i - 1], panels[i]
        if not isinstance(a, dict) or not isinstance(b, dict):
            continue
        if a.get("shotSize") in ("close_up", "medium", "medium_close_up") and \
                a.get("shotSize") == b.get("shotSize") and \
                a.get("cameraAngle") == b.get("cameraAngle") and \
                a.get("cameraAngle") in ("eye_level", "") and \
                not str(b.get("foreground") or "").strip() and \
                not str(b.get("subjectPlacement") or "").strip():
            issues.append((i, "连续正面近景且构图未变化"))
    return issues


def adjust_repeated_shots(plan):
    """对重复镜头确定性调整后一格（返回新计划副本，不改原计划）。"""
    import copy as _copy
    new = _copy.deepcopy(plan)
    panels = new.get("panels") or []
    for i, _reason in shot_repetition_validator(plan):
        if i >= len(panels):
            continue
        b = panels[i]
        angle = str(b.get("cameraAngle") or "")
        if angle == "over_shoulder":
            b["cameraAngle"] = "low_angle"
        elif angle == "low_angle":
            b["cameraAngle"] = "high_angle"
        else:
            b["cameraAngle"] = "over_shoulder"
        if not str(b.get("subjectPlacement") or "").strip():
            b["subjectPlacement"] = "人物位于画面一侧，另一侧留出负空间"
        b["cameraPosition"] = (str(b.get("cameraPosition") or "") +
                               "，从人物肩后切近").strip("，")
    return new


def build_outfit_continuity_state(script):
    """director_v2.5：服装连续状态（无换装剧情则始终完整穿着）。"""
    anchors = {}
    for name, rec in ((script.get("comicAnchors") or {}).items()):
        if isinstance(rec, dict) and str(rec.get("comicAnchor") or ""):
            anchors[_staging_base_name(str(name))] = str(rec["comicAnchor"])
    cards = parse_char_sheet(str(script.get("charSheet") or ""))
    out = {}
    for name in cards:
        base = _staging_base_name(name)
        anchor = anchors.get(base) or str(cards[name])
        layers = [p.strip("，,、；; ") for p in
                  re.split(r"[，,、；;]", anchor)
                  if any(k in p for k in
                         ("衣", "袍", "甲", "裙", "裤", "外套", "内衬",
                          "披风", "制服"))]
        out[name] = {
            "characterId": name,
            "currentOutfitLayers": layers[:6],
            "currentExposureState": "完整穿着",
            "outfitChangeReason": "",
            "lastChangePage": None,
            "lastChangePanel": None,
        }
    return out


def _compose_acting_text(acting_plan):
    """把表演计划压缩成一句逐格提示词。"""
    if not isinstance(acting_plan, dict):
        return ""
    parts = []
    for panel in (acting_plan.get("panels") or []):
        for c in (panel.get("characters") or []):
            cid = str(c.get("characterId") or "人物").split("（")[0]
            bits = [str(c.get("bodyPose") or ""),
                    str(c.get("handAction") or ""),
                    str(c.get("distanceToOther") or ""),
                    str(c.get("contactPoint") or "")]
            parts.append("%s：%s" % (cid,
                                     "、".join(x for x in bits if x)[:40]))
    return "；".join(x for x in parts if x)[:90]


def compile_director_v25_prompt(page, script, storyboard_plan,
                                text_plan=None, visual_no_text_mode=True):
    """director_v2.5：读者导向 + 表演 + 表情 + 镜头去重 正式入口。"""
    plan = adjust_repeated_shots(storyboard_plan)
    panels = plan.get("panels") or []
    if not any(str(s.get("shotSize") or "") in ("wide", "extreme_wide")
               for s in panels) and panels:
        first = panels[0]
        if str(first.get("storyFunction") or "") in ("establish",
                                                     "transition"):
            first["shotSize"] = "wide"
            first["cameraPlacement"] = "远景或全景位置"
    pno = int(page.get("page") or 0)
    last_panel = panels[-1] if panels else None
    if pno == int(page.get("episodePageCount") or
                  len((script.get("pages") or [])) or 0) and last_panel:
        txt = str(last_panel.get("visibleMoment") or "") + \
            str(last_panel.get("focusSubject") or "")
        if any(k in txt for k in ("骑士", "枪", "敌", "堵", "门")):
            last_panel["focusSubject"] = "黑银圣殿骑士与幽火长枪"
            last_panel["visibleMoment"] = (
                "石门即将合拢的缝隙外，黑银圣殿骑士持蓝绿色幽火长枪"
                "堵住唯一出口")
            last_panel["background"] = "即将合拢的雕花石门门缝、门外黑暗石廊"
            last_panel["mustShow"] = ["黑银板甲", "封闭头盔",
                                      "幽火长枪", "门缝"]
    expr = build_panel_expression_plans(page, script, plan, text_plan or {})
    acting = build_panel_acting_plans(page, script, plan, expr, text_plan or {})
    expressions = {}
    acting_texts = {}
    for pe in expr.get("panels") or []:
        expressions[int(pe["panel"])] = _compose_expression_text(
            {"panels": [pe]})
    for pa in acting.get("panels") or []:
        acting_texts[int(pa["panel"])] = _compose_acting_text(
            {"panels": [pa]})
    prompt = compile_director_v23_generic_prompt(
        page, script, plan, expressions=expressions,
        acting=acting_texts, visual_no_text_mode=visual_no_text_mode,
        hard_limit=1200)
    return prompt, expr, acting, plan


