def visual_quality_review(page, script, plan, prompt):
    """director_v2.5_finished：出图前程序级视觉质量检查。
    真实画面目视需人工/具备视觉能力的运行环境。"""
    failures = []
    pno = int(page.get("page") or 0)
    labels = ["上格", "中格", "下格", "末格"][:len(plan.get("panels") or [])]
    if any((lb + "：") not in prompt for lb in labels):
        failures.append("camera_failure: 画格缺失")
    if "全页不生成可读文字" not in prompt:
        failures.append("unwanted_text_failure: 无文字规则缺失")
    if "表演：" not in prompt:
        failures.append("acting_failure: 表演缺失")
    if "表情：" not in prompt:
        failures.append("acting_failure: 表情缺失")
    for w in ("办公桌", "教室", "会议室", "手机"):
        if w in prompt:
            failures.append("scene_failure: 串题材词 %s" % w)
    return {"page": pno, "passed": not failures, "failures": failures}


def lettering_quality_review(page_no, rows, plans, text_units):
    """director_v2.5_finished：排字质量程序检查。"""
    failures = []
    if not rows:
        failures.append("lettering_missing: 本页无排字")
    n_panels = len((plans or {}).get("panels") or [])
    for r in rows:
        if not 1 <= int(r.get("panel") or 1) <= max(1, n_panels):
            failures.append("lettering_out_of_panel: 画格号越界")
        if r.get("kind") == "dialogue" and \
                str(r.get("text") or "").startswith(("沈青梧：", "洛疏影：")):
            failures.append("dialogue_prefix: 对白带角色名前缀")
    return {"page": page_no, "passed": not failures, "failures": failures}


def episode_readability_review(script, opening, reader, text_plans):
    """director_v2.5_finished：整话可读性程序检查（画面目视除外）。"""
    results = {
        "world": bool(opening.get("worldContext")),
        "location": bool(opening.get("locationIdentity")),
        "heroes": bool(opening.get("protagonistIntroductions")),
        "mission": bool(opening.get("missionGoal")),
        "relationship": bool(opening.get("relationshipContext")),
        "per_page_progress": all(
            bool(reader[str(p)]["readerMustLearn"]) for p in range(1, 11)
            if str(p) in reader),
        "truth_page_language": any(
            "长老会" in "".join(u["text"] for u in text_plans[str(p)]["textUnits"])
            for p in text_plans),
        "hook_page_language": any(
            any(k in u["text"] for k in ("执法者", "堵", "门", "危险"))
            for p in text_plans for u in text_plans[p]["textUnits"]),
    }
    return {"results": results,
            "passed": all(results.values()),
            "visualConfirmation": "需目视确认"}


def run_finished_comic_pipeline(script, plans, text_plans, out_dir,
                                redo_pages=None):
    """director_v2.5_finished_comic 正式入口编排：
    storyboard/text 已有时直接编译、出图、排字、PDF、审查。"""
    import os as _os, json as _j, time as _t, re as _re, hashlib as _h
    pages = script.get("pages") or []
    opening = build_episode_opening_plan(script)
    reader = build_reader_knowledge_plans(script, plans)
    outfits = build_outfit_continuity_state(script)
    _j.dump(opening, open(_os.path.join(out_dir, "episode_opening_plan.json"),
                          "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    _j.dump(reader, open(_os.path.join(out_dir, "reader_knowledge_plans.json"),
                         "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    _j.dump(outfits, open(_os.path.join(out_dir, "outfit_continuity.json"),
                          "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    prompts = {}
    expr_all = {}
    acting_all = {}
    used = {}
    for p in pages:
        pno = int(p.get("page") or 0)
        prompt, expr, acting, plan = compile_director_v25_prompt(
            p, script, plans[str(pno)], text_plan=text_plans[str(pno)])
        prompts[pno] = prompt
        expr_all[pno] = expr
        acting_all[pno] = acting
        used[pno] = plan
    _j.dump(expr_all, open(_os.path.join(out_dir, "expression_plans.json"),
                           "w", encoding="utf-8"), ensure_ascii=False,
            indent=2)
    _j.dump(acting_all, open(_os.path.join(out_dir, "acting_plans.json"),
                             "w", encoding="utf-8"), ensure_ascii=False,
            indent=2)
    _j.dump(used, open(_os.path.join(out_dir, "storyboard_plans_adjusted.json"),
                       "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    return prompts, expr_all, acting_all, used


