def _v26_text_scrub(text):
    """Krea 底图禁止出现任何文字诱导词：替换成不可读抽象几何描述。"""
    v = str(text or "")
    repl = dict(_TEXT_REPLACEMENTS)
    for w in _TEXT_BANNED_WORDS:
        if w in v:
            v = v.replace(w, repl.get(w, "抽象几何纹理"))
    v = re.sub(r"[，,、；;]{2,}", "，", v)
    return v.strip("。！？!?；;，,、 ")


def _v26_no_text_scene_fix(text):
    """把容易诱导Krea生成文字的物件改成“空白表面/无字状态”。"""
    v = str(text or "")
    for w, r in (
            ("白板", "空白白板"),
            ("公示栏", "空白公示栏"),
            ("榜单", "空白榜单"),
            ("告示板", "空白告示板"),
            ("屏幕", "无字暗屏"),
            ("显示器", "无字暗屏"),
            ("全息界面", "抽象光点界面"),
            ("全息屏", "抽象光点屏"),
            ("时钟", "熄灭表盘"),
            ("计时器", "熄灭表盘"),
            ("HUD", "抽象光点"),
            ("数据", "抽象光点"),
            ("代码", "无字光带"),
            ("数字", "无字光点"),
            ("文字", "空白表面"),
            ("铭文", "无字刻痕")):
        v = v.replace(w, r)
    return v


def _v26_strip_names(text, script, page=None):
    """从提示词片段删除人物姓名，只保留视觉/动作描述。"""
    v = str(text or "")
    names = set()
    for c in ((page or {}).get("characters") or []):
        if isinstance(c, dict) and str(c.get("name") or "").strip():
            names.add(str(c["name"]).strip())
    for c in (((script or {}).get("comicAnchors") or {}).keys()):
        base = _staging_base_name(str(c))
        if base:
            names.add(base)
    for nm in sorted(names, key=len, reverse=True):
        v = v.replace(nm + "：", "")
        v = v.replace(nm + ":", "")
        v = v.replace(nm, "人物")
    return v


def _v26_identity_hits(text, identities):
    """题材中立的身份命中：完整身份/去掉常见修饰前缀/尾部角色词，
    任一≥3字片段出现在文字中即算命中。"""
    txt = str(text or "")
    hits = 0
    for it in (identities or []):
        it = str(it or "").strip()
        if not it:
            continue
        cands = {it}
        if len(it) > 6:
            cands.add(it[-6:].lstrip("的在了是一名位"))
        cands.add(re.sub(
            r"^(一名|一位|即将|已经|被|从|来自|在|年轻|资深|落魄|神秘|"
            r"失去|部分|想要|试图|城市|现代|古代|中国|西方|东瀛|中年|"
            r"老年|少年|少女|采矿|深空|太空|废弃|地下|深海|学院|"
            r"前线|退役|老练)", "", it))
        if any(c and len(c) >= 3 and c in txt for c in cands):
            hits += 1
    return hits


def strip_speaker_prefix(text):
    """清理可见文字中的角色名前缀/旁白前缀/内心前缀。"""
    v = str(text or "").strip()
    for _ in range(3):
        nv = re.sub(r"^[^：:]{1,14}[：:]\s*", "", v, count=1)
        if nv == v:
            nv = re.sub(r"^(旁白|内心|角色ID)[：:]\s*", "", v, count=1)
        if nv == v:
            break
        v = nv.strip()
    return v.strip("。！？!?；;，,、 ")


def _speaker_prefix_name(text):
    """若文本以“名字：”开头则返回名字，否则返回空串。"""
    m = re.match(r"^([^：:]{1,14})[：:]\s*", str(text or "").strip())
    return m.group(1).strip() if m else ""


_CONTRACT_KEYS = (
    "worldSituation", "primaryLocation", "protagonists",
    "relationshipBeforeEpisode", "missionGoal", "missionReason",
    "centralMystery", "keyEvidence", "opposition", "emotionalArc",
    "partialTruth", "finalThreat", "nextEpisodeQuestion",
)


def validate_episode_story_contract(contract):
    """EpisodeStoryContract 完整性与 8 项故事契约检查。返回错误列表。"""
    errors = []
    if not isinstance(contract, dict):
        return ["episodeStoryContract 不是对象"]
    for key in _CONTRACT_KEYS:
        if not str(contract.get(key) or "").strip():
            errors.append("contract 缺少 %s" % key)
    pros = contract.get("protagonists")
    if not isinstance(pros, list) or not pros:
        errors.append("protagonists 必须至少 1 人")
    else:
        for i, p in enumerate(pros, 1):
            if not isinstance(p, dict):
                errors.append("protagonists[%d] 不是对象" % i)
                continue
            for k in ("characterId", "identity", "currentGoal",
                      "personalStake", "secretOrConflict"):
                if not str(p.get(k) or "").strip():
                    errors.append("protagonists[%d] 缺少 %s" % (i, k))
    stake = str(contract.get("missionReason") or "") + \
        "".join(str(p.get("personalStake") or "")
                for p in (pros if isinstance(pros, list) else []))
    if len(stake) < 8:
        errors.append("读者缺乏关注这件事的理由（missionReason/personalStake）")
    if not str(contract.get("missionGoal") or "").strip():
        errors.append("人物为什么必须行动（missionGoal）为空")
    if len(pros or []) >= 2 and not str(
            contract.get("relationshipBeforeEpisode") or "").strip():
        errors.append("两人为什么一起行动/未解决关系为空")
    if not str(contract.get("keyEvidence") or "").strip():
        errors.append("证据为什么重要（keyEvidence）为空")
    if not str(contract.get("opposition") or "").strip():
        errors.append("反派或组织做了什么（opposition）为空")
    if not str(contract.get("partialTruth") or "").strip():
        errors.append("本话能揭示到什么程度（partialTruth）为空")
    if not str(contract.get("nextEpisodeQuestion") or "").strip():
        errors.append("最后留下什么新问题（nextEpisodeQuestion）为空")
    return errors


def assert_no_production_fixture(bible):
    """正式入口禁止读取任何确定性人物/场景/逐页模板。"""
    if isinstance(bible, dict) and bible.get("usedProductionFixture"):
        raise RuntimeError("production fixture is forbidden in oneline entry")
    return True


def validate_oneline_bible_structure(bible, one_line_story=""):
    """一句话世界档案结构校验（0次模型调用）。"""
    errors = []
    if not isinstance(bible, dict):
        return ["bible 不是对象"]
    for k in ("seriesId", "seriesTitle", "genre", "art", "worldSituation",
              "primaryLocation", "worldRules", "characters",
              "characterRelations", "sceneSetting",
              "episodeStoryContract"):
        if not str(bible.get(k) or "").strip():
            errors.append("bible 缺少 %s" % k)
    if len(parse_char_sheet(str(bible.get("characters") or ""))) < 2:
        errors.append("人物卡至少需要2个主要角色")
    errors += validate_episode_story_contract(
        bible.get("episodeStoryContract"))
    if one_line_story:
        joined = "".join([
            str(bible.get("worldSituation") or ""),
            str(bible.get("characterRelations") or ""),
            str(bible.get("sceneSetting") or ""),
            str(bible.get("characters") or ""),
            json.dumps(bible.get("episodeStoryContract") or {},
                       ensure_ascii=False),
        ])
        if _premise_overlap(str(one_line_story), joined) < 0.22:
            errors.append("一句话关键实体在bible中大量丢失")
    return errors


def _v26_dialogue_action_consistent(page, text_plans, storyboard_plans):
    """结尾对白与动作一致性：说“跑”时画面必须正在撤退。"""
    pno = int(page.get("page") or 0)
    txt = _v26_page_text(pno, {**page, "pages": [page]}, text_plans,
                         storyboard_plans)
    panels = ((storyboard_plans or {}).get(str(pno)) or {}).get("panels") or []
    combat = any(any(k in str(p.get("visibleMoment") or "") +
                     str(p.get("midground") or "")
                     for k in ("拔剑", "挥剑", "迎战", "战斗", "持剑", "举剑"))
                 for p in panels)
    retreat = any(any(k in str(p.get("visibleMoment") or "") +
                      str(p.get("midground") or "")
                      for k in ("撤退", "后退", "逃", "跑出", "转身跑"))
                  for p in panels)
    if "跑" in txt and combat and not retreat:
        return False
    return True


def build_oneline_series_bible(one_line_story, genre=None, art_style=None,
                               character_preferences=None, target_pages=10):
    """一句话→世界/人物/关系/场景/第一话故事契约（一次本地 Qwen 调用）。"""
    set_auto_job(stage="world", progress=0.01,
                 message="正在从一句话建立世界、人物、场景与故事契约…")
    sysmsg = (
        "你是商业连载漫画的系列策划。只根据用户的一句话建立第一话所需的最小生产档案，"
        "不写逐页剧情、不分格、不写生图提示词、不写小说正文。\n"
        "硬性要求：\n"
        "1. 用户一句话中的所有明确实体必须保留：人物、职业、地点、组织、物品、异常现象。\n"
        "2. 关键物品（钥匙、名单、徽章、装置、活物等）必须进入 worldRules.specialItems 与"
        " episodeStoryContract.keyEvidence，不能丢失或改名。\n"
        "3. 人物卡每行严格格式：名字（身份）—性别与年龄段、脸型与关键五官、发型发色、"
        "肤色体型、完整上装、完整下装、鞋靴、必要外层服装、固定疤痕或配饰。"
        "主角服装采用题材内可信的完整多层结构；不写性格、心理、当前伤势或剧情。\n"
        "4. 场景卡每个场景一行：【场景：名称】材质、主色、光源、3—5个固定识别物。\n"
        "5. worldRules 是结构化JSON：era（时代）、visualCulture（视觉文化）、"
        "technologyLevel（技术层级）、clothingSystem（服装体系数组）、"
        "weaponSystem（武器体系数组）、magicOrTechnologyVisuals（魔法或科技视觉数组）、"
        "excludedVisualFamilies（与本题材冲突的视觉家族数组）、"
        "specialItems（[{item, importance}]）。\n"
        "6. episodeStoryContract 必须完整填写：worldSituation、primaryLocation、"
        "protagonists（[{characterId, identity, currentGoal, personalStake,"
        " secretOrConflict}]）、relationshipBeforeEpisode、missionGoal、"
        "missionReason、centralMystery、keyEvidence、opposition、emotionalArc、"
        "partialTruth、finalThreat、nextEpisodeQuestion。"
        "其中 missionReason/personalStake 必须让读者明确为什么现在必须行动；"
        "relationshipBeforeEpisode 必须写明两人之间未解决的过去；"
        "opposition 必须写明反派或组织具体做了什么；"
        "partialTruth 写明本话能揭示到什么程度；"
        "nextEpisodeQuestion 写清楚本话最后留下的新问题。\n"
        "7. 前3页读者定位要求：第1页建立世界/时代/地点/地点发生过什么/一个悬念；"
        "第2页说明主要人物身份、当前任务、寻找什么、为什么必须找到；"
        "第3页说明两人过去或当前关系、一项未解决矛盾、进入危险区域、页末第一处异常。\n"
        "8. 禁止出现用户一句话之外的新主角；禁止把一句话中的异常解释成普通巧合。\n"
        "只输出一个JSON对象，不要Markdown、解释或JSON以外的文字：\n"
        '{"seriesId": "小写字母数字下划线", "seriesTitle": "标题", "genre": "题材",'
        ' "art": "画风一句话", "worldSituation": "世界现状", '
        '"primaryLocation": "主地点", "worldRules": {...}, '
        '"characters": "人物卡文本", "characterRelations": "关系一句话", '
        '"sceneSetting": "场景卡文本", "episodeStoryContract": {...}}'
    )
    pref = str(character_preferences or "").strip()
    user = (
        "用户一句话故事：\n%s\n\n目标页数：%d页\n题材：%s\n画风：%s%s"
        % (str(one_line_story or "").strip()[:2500], int(target_pages or 10),
           str(genre or "自动推导").strip(), str(art_style or "写实真人电影").strip(),
           "\n\n用户附加人物/题材偏好：\n" + pref[:800] if pref else "")
    )

    def generate():
        raw = chat_stream(
            [{"role": "system", "content": sysmsg},
             {"role": "user", "content": user}],
            0.35, None, 6000)
        bible = _extract_json_value(raw)
        errors = []
        if not isinstance(bible, dict):
            errors.append("bible 不是JSON对象")
            return None, errors
        for k in ("seriesId", "seriesTitle", "genre", "art", "worldSituation",
                  "primaryLocation", "worldRules", "characters",
                  "characterRelations", "sceneSetting",
                  "episodeStoryContract"):
            if not str(bible.get(k) or "").strip():
                errors.append("bible 缺少 %s" % k)
        if not errors and len(parse_char_sheet(str(bible.get("characters") or ""))) < 2:
            errors.append("人物卡必须至少2个主要角色")
        if not errors and not str(bible.get("sceneSetting") or "").strip():
            errors.append("场景卡为空")
        if not errors:
            errors += validate_episode_story_contract(
                bible.get("episodeStoryContract"))
        if not errors:
            joined = "".join([
                str(bible.get("worldSituation") or ""),
                str(bible.get("characterRelations") or ""),
                str(bible.get("sceneSetting") or ""),
                str(bible.get("characters") or ""),
                json.dumps(bible.get("episodeStoryContract") or {},
                           ensure_ascii=False),
            ])
            if _premise_overlap(str(one_line_story or ""), joined) < 0.22:
                errors.append("一句话关键实体在bible中大量丢失")
        return bible, errors

    last_bible = None
    for attempt in range(1, 4):
        try:
            bible, errors = generate()
            if bible is not None and not errors:
                set_auto_job(stage="world", progress=0.05,
                             message="✅ 世界/人物/场景/故事契约已建立")
                return bible
            last_bible = bible
            log("⚠ bible 校验失败（第%d次）：%s" %
                (attempt, "；".join((errors or ["未知"])[:6])))
        except Exception as e:
            log("⚠ bible 生成异常：%s" % e)
    raise RuntimeError("一句话世界档案建立失败")


def build_comic_anchors_from_char_sheet(char_sheet):
    """从已确认人物卡确定性建立 comicAnchors（0次模型调用）。"""
    out = {}
    for name, look in parse_char_sheet(str(char_sheet or "")).items():
        out[name] = {
            "comicAnchor": str(look or "").strip(),
            "comicAnchorVersion": 1,
            "cardHash": "oneline_auto",
        }
    return out


def _v26_visible_range_for_shot(shot):
    size = str((shot or {}).get("shotSize") or "medium").lower()
    focus = str((shot or {}).get("focusSubject") or "")
    if size in ("extreme_close_up",) or "手" in focus:
        return "手部局部"
    if size == "close_up":
        return "脸部与上半身"
    if size in ("medium", "medium_close_up", "over_shoulder"):
        return "半身"
    return "全身"


def enforce_panel_cast(page, storyboard_plan, script):
    """为每个画格生成 panelCast/expectedPersonCount/forbidExtraPeople。
    人物数量以页面硬事实（panels[].people）为准；0次模型调用。"""
    import copy as _copy
    plan = _copy.deepcopy(storyboard_plan) if isinstance(
        storyboard_plan, dict) else {}
    panels = plan.get("panels")
    if not isinstance(panels, list):
        panels = []
    src_panels = page.get("panels") or []
    page_chars = [str(c.get("name") or "")
                  for c in (page.get("characters") or [])]
    src_text = str(page.get("source_text") or "")
    for i, shot in enumerate(panels, 1):
        if not isinstance(shot, dict):
            continue
        pidx = int(shot.get("panel") or i)
        src = src_panels[pidx - 1] if 1 <= pidx <= len(src_panels) and \
            isinstance(src_panels[pidx - 1], dict) else {}
        people = _v26_infer_panel_people(page, shot, src, page_chars)
        expected = len(people)
        if expected == 0 and _v26_visible_range_for_shot(shot) == "手部局部":
            expected = 1
            people = page_chars[:1]
        cast = [{
            "characterId": _staging_base_name(nm),
            "instanceCount": 1,
            "screenPosition": str(shot.get("subjectPlacement") or
                                  shot.get("cameraPosition") or ""),
            "visibleBodyRange": _v26_visible_range_for_shot(shot),
            "action": str(shot.get("visibleMoment") or
                          shot.get("midground") or "")[:40],
        } for nm in people]
        shot["panelCast"] = cast
        shot["expectedPersonCount"] = expected
        shot["forbidExtraPeople"] = True
        dup = None
        panel_src_visible = str(src.get("visible") or "")
        if any(k in (src_text + panel_src_visible) for k in
               ("镜子", "倒影", "照片", "回忆", "幻象", "投影", "映像")):
            dup = "mirror_or_photo_or_illusion"
        shot["duplicateAllowedReason"] = dup
    plan["panelCount"] = len(panels)
    return plan


def _v26_infer_panel_people(page, shot, src, page_chars):
    """按页面硬事实+分镜文本推断本格实际人物：
    - 只保留页面人物名单（含剧情允许的敌人/神秘人）；
    - 分镜点名的人物优先；
    - 证据/手部特写不计泛称“人物”，避免把受害者误算成在场人物；
    - 非特写格中“人物/两人”等泛称数量作为人数下限，封顶为页面人物数。"""
    bases = {_staging_base_name(x) for x in page_chars}
    people = [str(x) for x in (src.get("people") or []) if str(x).strip()]
    people = [x for x in people if _staging_base_name(x) in bases]
    shot_txt = str(shot.get("visibleMoment") or "") + \
        str(shot.get("midground") or "") + \
        str(shot.get("newInformation") or "")
    named = [nm for nm in page_chars
             if _staging_base_name(nm) in shot_txt or nm in shot_txt]
    func = str(shot.get("storyFunction") or "")
    size = str(shot.get("shotSize") or "").lower()
    focus = str(shot.get("focusSubject") or "")
    is_object = func == "evidence" and size in ("close_up", "extreme_close_up")
    is_hand = "手" in focus
    generic_floor = 0
    if not (is_object or is_hand):
        if any(k in shot_txt for k in ("三人", "三个人", "三名")):
            generic_floor = 3
        elif any(k in shot_txt for k in
                 ("两人", "两个", "一前一后", "并排", "双方", "并肩")):
            generic_floor = 2
        elif shot_txt.count("人物") >= 2:
            generic_floor = 2
        elif shot_txt.count("人物") == 1:
            generic_floor = 1
        generic_floor = min(generic_floor, len(page_chars))
    out, seen = [], set()
    for x in people + named:
        b = _staging_base_name(x)
        if b and b not in seen:
            out.append(x)
            seen.add(b)
    target = max(len(out), min(generic_floor, len(page_chars)))
    target = min(target, len(page_chars))
    for nm in page_chars:
        if len(out) >= target:
            break
        b = _staging_base_name(nm)
        if b not in seen:
            out.append(nm)
            seen.add(b)
    if not out and is_hand and page_chars:
        # 手部特写默认归属本页第1名主角（画面实际包含手/袖口）
        out = page_chars[:1]
    return out


def _fallback_storyboard_from_page(page, script):
    """Qwen 分镜失败时的确定性回退：直接由页面硬事实生成合法 storyboardPlan。
    仅用于保持一句话入口不中断；字段全部来自当前页，不新增剧情。"""
    src_panels = page.get("panels") or []
    count = max(1, min(4, int(page.get("panel_count") or len(src_panels) or 1)))
    func_map = {"远景": "establish", "全景": "establish",
                "中景": "action", "半身": "action",
                "近景": "discover", "特写": "evidence", "极近特写": "evidence"}
    size_map = {"远景": "wide", "全景": "wide", "中景": "medium",
                "半身": "medium_close_up", "近景": "close_up",
                "特写": "close_up", "极近特写": "extreme_close_up"}
    panels = []
    for i in range(count):
        pd = src_panels[i] if i < len(src_panels) and \
            isinstance(src_panels[i], dict) else {}
        shot = str(pd.get("shot") or "中景")
        cam = str(pd.get("staging_camera") or "")
        angle = "eye_level"
        if any(k in cam for k in ("低", "仰")):
            angle = "low_angle"
        elif any(k in cam for k in ("高", "俯")):
            angle = "high_angle"
        moment = str(pd.get("action") or pd.get("visible") or "动作推进")
        panels.append({
            "panel": i + 1,
            "storyFunction": func_map.get(shot, "action"),
            "newInformation": moment[:50],
            "visibleMoment": moment[:60],
            "focusSubject": str(pd.get("subject") or pd.get("visible") or
                                "画面主体")[:30],
            "shotSize": size_map.get(shot, "medium"),
            "cameraPosition": cam[:30],
            "cameraAngle": angle,
            "foreground": "",
            "midground": moment[:60],
            "background": str(pd.get("staging_background") or "")[:50],
            "screenDirection": "",
            "cutReason": "剧情推进",
            "continuityToNext": "承接下一格",
            "mustShow": [str(pd.get("visible") or "")[:20]],
            "mustNotShow": [],
        })
    plan = {
        "pageNumber": int(page.get("page") or 0),
        "pageCoreBeat": str(page.get("source_text") or "")[:80],
        "viewerInformationOrder": ["信息%d" % i for i in range(1, count + 1)],
        "pageRhythm": "按剧情推进",
        "panelCount": count,
        "panels": panels,
    }
    return _director_storyboard_normalize(plan, count, page, script)


def validate_panel_cast(plan):
    """确定性校验人物数量与复制规则。返回错误列表。"""
    errors = []
    panels = (plan or {}).get("panels") or []
    for i, shot in enumerate(panels, 1):
        cast = shot.get("panelCast")
        if not isinstance(cast, list):
            errors.append("第%d格缺少 panelCast" % i)
            continue
        expected = int(shot.get("expectedPersonCount") or len(cast))
        if len(cast) != expected:
            errors.append("第%d格 panelCast数量%d != expectedPersonCount%d" %
                          (i, len(cast), expected))
        for c in cast:
            if int(c.get("instanceCount") or 1) != 1 and \
                    not shot.get("duplicateAllowedReason"):
                errors.append("第%d格 %s instanceCount不为1且无duplicateAllowedReason"
                              % (i, c.get("characterId")))
        if expected > 0 and not shot.get("forbidExtraPeople"):
            errors.append("第%d格未禁止额外人物" % i)
    return errors


def calculate_page_render_risk(page, storyboard_plan):
    """整页/分格/混合渲染风险评估（确定性，0次模型调用）。"""
    panels = (storyboard_plan or {}).get("panels") or []
    src = str(page.get("source_text") or "")
    visible = "；".join(str(p.get("visible") or "")
                        for p in (page.get("panels") or [])
                        if isinstance(p, dict))
    alltxt = src + visible
    score = 0
    reasons = []
    dual = 0
    char_counts = {}
    for shot in panels:
        if not isinstance(shot, dict):
            continue
        cast = shot.get("panelCast") or []
        if len(cast) >= 2:
            dual += 1
        for c in cast:
            cid = str(c.get("characterId") or "")
            char_counts[cid] = char_counts.get(cid, 0) + 1
    if dual >= 2:
        score += 3
        reasons.append("multiple_dual_panels")
    if dual >= 1:
        score += 1
    if any(k in alltxt for k in
           ("拥抱", "接吻", "搀扶", "扭打", "拉扯", "抱住", "吻", "贴身")):
        score += 4
        reasons.append("contact_or_intimacy")
    if len(panels) > 3 and dual:
        score += 2
        reasons.append("many_panels_with_dual")
    if char_counts and max(char_counts.values()) >= 3:
        score += 1
        reasons.append("same_character_repeated")
    funcs = [str(p.get("storyFunction") or "") for p in panels
             if isinstance(p, dict)]
    if "evidence" in funcs and "reaction" in funcs and \
            funcs.index("evidence") < funcs.index("reaction"):
        score += 1
        reasons.append("evidence_to_reaction")
    if any(k in alltxt for k in
           ("剑", "刀", "枪", "法杖", "扭打", "战斗", "迎战", "堵")):
        score += 1
        reasons.append("complex_action")
    if any(k in alltxt for k in
           ("敌人", "追兵", "骑士", "卫兵", "对手", "凶手", "怪物")):
        score += 1
        reasons.append("enemy_present")
    sizes = [str(p.get("shotSize") or "") for p in panels
             if isinstance(p, dict)]
    if any(sizes[i] == sizes[i + 1] for i in range(len(sizes) - 1)):
        score += 1
        reasons.append("repeated_shot_size")
    hist = page.get("v26FailureHistory") if isinstance(page, dict) else None
    if isinstance(hist, list) and any(
            f in ("duplicate_character", "extra_character") for f in hist):
        score += 3
        reasons.append("past_duplicate_failure")
    if score >= 6:
        mode = "split_panels"
    elif score >= 3:
        mode = "hybrid"
    else:
        mode = "full_page"
    return {"riskScore": score, "reasons": reasons, "renderMode": mode}


_V26_SIZE_ORDER = ("extreme_wide", "wide", "medium", "medium_close_up",
                   "close_up", "extreme_close_up", "over_shoulder")
_V26_ANGLE_ORDER = ("eye_level", "low_angle", "high_angle",
                    "over_shoulder", "subjective")


def _v26_next_shot_size(cur, func):
    if str(func or "") == "evidence":
        allowed = ("medium_close_up", "close_up", "extreme_close_up")
    else:
        allowed = _V26_SIZE_ORDER
    if cur not in allowed:
        return allowed[0]
    return allowed[(allowed.index(cur) + 1) % len(allowed)]


def _v26_diversify_shots(plan, prev_plan=None):
    """确定性镜头多样性层：页内相邻格景别/机位去重、全平视页补高低机位、
    跨页首格与上页末格避免相同镜头。只改视觉机位，不改剧情/人物/证据。"""
    import copy as _copy
    plan = _copy.deepcopy(plan) if isinstance(plan, dict) else {}
    panels = plan.get("panels")
    if not isinstance(panels, list) or not panels:
        return plan
    for i, shot in enumerate(panels):
        if not isinstance(shot, dict):
            continue
        if i > 0 and isinstance(panels[i - 1], dict):
            prev = panels[i - 1]
            if str(shot.get("shotSize") or "") == str(prev.get("shotSize") or ""):
                shot["shotSize"] = _v26_next_shot_size(
                    str(shot.get("shotSize") or ""),
                    shot.get("storyFunction"))
            if str(shot.get("cameraAngle") or "") == \
                    str(prev.get("cameraAngle") or ""):
                cur = str(shot.get("cameraAngle") or "eye_level")
                if cur in _V26_ANGLE_ORDER:
                    shot["cameraAngle"] = _V26_ANGLE_ORDER[
                        (_V26_ANGLE_ORDER.index(cur) + 1) % len(_V26_ANGLE_ORDER)]
    angles = [str(p.get("cameraAngle") or "eye_level")
              for p in panels if isinstance(p, dict)]
    if len(angles) >= 2 and all(a == "eye_level" for a in angles):
        for i, shot in enumerate(panels):
            if isinstance(shot, dict) and i % 2 == 1:
                shot["cameraAngle"] = "low_angle" if (i // 2) % 2 == 0 \
                    else "high_angle"
    if isinstance(prev_plan, dict):
        pp = prev_plan.get("panels") or []
        last = pp[-1] if pp and isinstance(pp[-1], dict) else None
        first = panels[0] if isinstance(panels[0], dict) else None
        if last and first and str(last.get("storyFunction") or "") != "evidence" \
                and str(first.get("storyFunction") or "") != "evidence":
            if str(last.get("shotSize") or "") == \
                    str(first.get("shotSize") or "") and \
                    str(last.get("cameraAngle") or "") == \
                    str(first.get("cameraAngle") or ""):
                first["shotSize"] = _v26_next_shot_size(
                    str(first.get("shotSize") or "medium"),
                    first.get("storyFunction"))
                first["cameraAngle"] = "low_angle" if str(
                    first.get("cameraAngle") or "") == "eye_level" else "eye_level"
    return plan


def _v26_diversity_line(plan):
    panels = plan.get("panels") or []
    if len(panels) >= 2:
        return "本页各格景别、机位与人物朝向互不相同，避免重复构图"
    return ""


def _v26_scene_identity_line(page, script, shot=None):
    """当前画格场景身份锚点：类型 + 3-5个局部识别点 + 光源。"""
    scene = str(page.get("scene") or "").strip()
    scene_type = _generic_scene_type(page)
    st = page.get("stagingScene") if isinstance(page.get("stagingScene"), dict) \
        else {}
    facts = [str(x) for x in (st.get("localSceneFacts") or [])
             if str(x).strip()]
    light = str(page.get("light") or "").strip()
    if not light:
        for x in facts:
            if "光" in x:
                light = x[:20]
                break
    if shot and isinstance(shot, dict):
        bg = str(shot.get("background") or "").strip("。！？!?；;，,、 ")
        bg_pts = [x.strip("，,、；; ")
                  for x in re.split(r"[，,、；;]", bg)
                  if x.strip("，,、；; ")]
        for b in bg_pts:
            if len(b) >= 2 and b not in facts:
                facts.append(b[:14])
    picks = facts[:4]
    if not picks:
        picks = [scene_type]
    line = "场景：%s" % scene_type
    if picks:
        line += "（" + "、".join(
            _v26_no_text_scene_fix(x) for x in picks[:4]) + "）"
    if light:
        line += "，" + light
    return _v26_no_text_scene_fix(line[:90])


def _director_v26_style_line(script):
    """从项目 art 字段确定性生成画风行，不再硬编码写实真人。"""
    art = str((script or {}).get("art") or "").strip()
    pairs = (
        ("冷色", "冷色调写实电影画面，低饱和冷色，真实皮肤与自然人体结构"),
        ("暗色", "暗色调电影画面，深色环境与真实皮肤质感"),
        ("古装", "写实古装影视画面，古代服饰与古代场景，真实皮肤与自然人体结构"),
        ("水墨", "中国风水墨厚涂，宣纸质感与留白构图"),
        ("水彩", "透明水彩质感，柔和晕染与自然纸纹"),
        ("赛璐璐", "赛璐璐动画质感，干净线稿与色块"),
        ("2D", "日系2D动画画面，清晰线稿与平涂上色"),
        ("动漫", "日系动漫画面，鲜明线稿与柔和光影"),
        ("漫画", "美式漫画画面，高对比线稿与厚涂阴影"),
        ("厚涂", "厚涂插画质感，明确笔触与强烈光影"),
        ("像素", "像素画风格"),
        ("油画", "油画质感，厚重笔触"),
        ("3D", "三维渲染画面，真实材质与自然光影"),
        ("CG", "三维CG渲染画面，逼真材质"),
        ("写实", "写实真人电影画面，真实皮肤与自然人体结构"),
    )
    for kw, line in pairs:
        if kw in art:
            return line
    if art:
        return "电影级" + art[:20] + "画面"
    return _COMPACT_STYLE_LINE


def _director_v26_genre_anchor(script):
    """题材与核心事实锚点：把题材名+本话任务+关键证据写进提示词，
    让Krea在都市犯罪/仙侠/历史/科幻等题材之间保持区分。"""
    contract = script.get("episodeStoryContract") \
        if isinstance(script, dict) else None
    bits = []
    genre = str((script or {}).get("genre") or "").strip()
    if genre:
        bits.append(genre[:12])
    if isinstance(contract, dict):
        for key in ("missionGoal", "keyEvidence", "centralMystery"):
            v = _v26_contract_text(contract.get(key))
            if v:
                bits.append(v[:22])
                break
        for key in ("keyEvidence", "opposition"):
            v = _v26_contract_text(contract.get(key))
            if v:
                bits.append(v[:18])
    if not bits:
        return ""
    return "题材与核心事实：" + "，".join(x for x in bits if x)[:96]


def _v26_contract_text(value):
    """故事契约字段可能是字符串或数组，统一成可读文本。"""
    if isinstance(value, list):
        return "、".join(str(x) for x in value[:2] if str(x).strip())
    return str(value or "").strip()


