_COMPOUND_EVENT_VERBS = (
    "阻止", "取出", "拿走", "递交", "发现", "进入", "打开", "触碰", "警告",
    "偷走", "摘下", "推开", "插入", "看见", "掏出", "夺取", "交出", "抓住",
    "划伤", "读取", "记录",
)


def _event_primary_pages(ev):
    """返回 core 事件的 primaryPage 归一化列表（1~2个连续页）。"""
    v = ev.get("primaryPage") if isinstance(ev, dict) else None
    if isinstance(v, list):
        out = [int(x) for x in v if str(x).isdigit()]
    elif isinstance(v, int) or (isinstance(v, str) and str(v).strip().isdigit()):
        out = [int(v)]
    else:
        out = []
    return sorted(set(out))


def _is_compound_core_event(ev):
    """启发式拦截明显包含两个独立核心动作的 core 事件。
    规则：含“被”且其后另有核心动作动词；或两个以上子句各含不同核心动词。"""
    text = str(ev.get("event") or "")
    if not text:
        return False
    if "被" in text:
        after = text.split("被", 1)[1]
        if any(v in after for v in _COMPOUND_EVENT_VERBS):
            return True
    verbs_found = [v for v in _COMPOUND_EVENT_VERBS if v in text]
    if len(verbs_found) >= 2 and len(re.split(r"[，,、；;]", text)) >= 2:
        return True
    return False


def validate_episode_narrative_plan(plan, premise="", target_pages=None):
    """校验本话故事计划：结构完整、因果清楚、无空泛词。返回错误列表。"""
    errors = []
    _EP_FORBIDDEN = (
        "推进剧情", "冲突升级", "发现重要线索", "情况发生变化",
        "主角决定继续", "危机出现",
    )
    if not isinstance(plan, dict):
        return ["本话故事计划不是JSON对象"]
    for key in ("episodeGoal", "motivation", "startingState", "mainObstacle",
                "turningPoint", "cost", "episodeResult", "nextEpisodeDrive"):
        if not str(plan.get(key) or "").strip():
            errors.append("缺少字段：" + key)
        elif len(str(plan.get(key) or "").strip()) < 6:
            errors.append("字段过短：" + key)
    key_choices = plan.get("keyChoices")
    if not isinstance(key_choices, list) or not key_choices:
        errors.append("keyChoices 必须至少包含一次人物选择")
    else:
        for i, c in enumerate(key_choices):
            if not isinstance(c, dict):
                errors.append("keyChoices[%d] 不是对象" % i)
                continue
            for k in ("choice", "reason", "result"):
                if not str(c.get(k) or "").strip():
                    errors.append("keyChoices[%d] 缺少 %s" % (i, k))
    hfs = plan.get("hardFinalState")
    if not isinstance(hfs, dict):
        errors.append("hardFinalState 必须是对象")
    else:
        for k in ("locations", "injuries", "equipment", "relationships", "knowledge"):
            if not isinstance(hfs.get(k), dict):
                errors.append("hardFinalState.%s 必须是对象" % k)
    for key in ("episodeGoal", "motivation", "startingState", "mainObstacle",
                "turningPoint", "cost", "episodeResult", "nextEpisodeDrive"):
        t = str(plan.get(key) or "")
        hit = [w for w in _PLAN_VAGUE_WORDS if w in t]
        if hit:
            errors.append("%s 含空泛词：%s" % (key, "、".join(hit[:3])))
        hit2 = [w for w in _EP_FORBIDDEN if w in t]
        if hit2:
            errors.append("%s 含空话：%s" % (key, "、".join(hit2[:3])))
    for i, c in enumerate(key_choices if isinstance(key_choices, list) else []):
        if isinstance(c, dict):
            for k in ("choice", "reason", "result"):
                t = str(c.get(k) or "")
                hit = [w for w in _EP_FORBIDDEN + _PLAN_VAGUE_WORDS if w in t]
                if hit:
                    errors.append("keyChoices[%d].%s 含空话：%s" %
                                  (i, k, "、".join(hit[:3])))
    # criticalEvents：核心事件清单必须存在、结构合法、至少一个core、ID唯一
    crit = plan.get("criticalEvents")
    if not isinstance(crit, list) or not crit:
        errors.append("criticalEvents 必须是数组且至少包含一个core事件")
    else:
        seen_ids = set()
        core_count = 0
        for i, ev in enumerate(crit):
            if not isinstance(ev, dict):
                errors.append("criticalEvents[%d] 不是对象" % i)
                continue
            eid = str(ev.get("eventId") or "").strip()
            if not eid:
                errors.append("criticalEvents[%d] 缺少 eventId" % i)
            elif eid in seen_ids:
                errors.append("criticalEvents eventId 重复：%s" % eid)
            seen_ids.add(eid)
            importance = str(ev.get("importance") or "")
            if importance not in ("core", "major", "support"):
                errors.append("criticalEvents[%d] importance 只能是 core/major/support，得到：%s" %
                              (i, importance))
            if importance == "core":
                core_count += 1
            event_text = str(ev.get("event") or "").strip()
            if len(event_text) < 4:
                errors.append("criticalEvents[%d] event 过短或为空" % i)
            result_text = str(ev.get("requiredResult") or "").strip()
            if importance == "core" and len(result_text) < 4:
                errors.append("criticalEvents[%d] core 事件缺少 requiredResult" % i)
            if importance == "core" and _is_compound_core_event(ev):
                errors.append(
                    "criticalEvents[%d] 是复合事件，必须拆成多个单动作事件：%s" %
                    (i, event_text[:40]))
            if importance == "core":
                pages = _event_primary_pages(ev)
                if not pages:
                    errors.append("criticalEvents[%d] core 事件缺少 primaryPage" % i)
                elif len(pages) > 2 or (len(pages) == 2 and pages[1] != pages[0] + 1):
                    errors.append(
                        "criticalEvents[%d] core 事件 primaryPage 最多两个连续页，得到：%s" %
                        (i, pages))
                if target_pages and any(p < 1 or p > target_pages for p in pages):
                    errors.append("criticalEvents[%d] primaryPage 超出页数范围" % i)
                facts = ev.get("requiredFacts")
                if not isinstance(facts, list) or not facts:
                    errors.append("criticalEvents[%d] core 事件缺少 requiredFacts" % i)
                else:
                    for gi, g in enumerate(facts):
                        if not isinstance(g, dict):
                            errors.append("criticalEvents[%d].requiredFacts[%d] 不是对象" %
                                          (i, gi))
                            continue
                        if not str(g.get("label") or "").strip():
                            errors.append("criticalEvents[%d].requiredFacts[%d] 缺少 label" %
                                          (i, gi))
                        anyof = [str(x) for x in (g.get("anyOf") or []) if str(x).strip()]
                        if not anyof:
                            errors.append("criticalEvents[%d].requiredFacts[%d] anyOf 为空" %
                                          (i, gi))
            if str(ev.get("hardFinalEvent") or "").lower() in ("true", "1"):
                if importance != "core":
                    errors.append("criticalEvents[%d] hardFinalEvent 必须为 core" % i)
                hf_pages = _event_primary_pages(ev)
                if target_pages and hf_pages and \
                        any(p < target_pages - 1 for p in hf_pages):
                    errors.append(
                        "criticalEvents[%d] hardFinalEvent 只能绑定最后一页或倒数第二页" % i)
            for key in ("setupPages", "aftermathPages"):
                v = ev.get(key)
                if v is not None and not isinstance(v, list):
                    errors.append("criticalEvents[%d].%s 必须是数组" % (i, key))
            for key in ("event", "requiredResult"):
                t = str(ev.get(key) or "")
                hit = [w for w in _EP_FORBIDDEN + _PLAN_VAGUE_WORDS if w in t]
                if hit:
                    errors.append("criticalEvents[%d].%s 含空话：%s" %
                                  (i, key, "、".join(hit[:3])))
        if core_count < 1:
            errors.append("criticalEvents 必须至少包含一个 importance=core 的事件")
    return errors


def build_episode_narrative_plan(premise, scene_setting, char_sheet,
                                 target_pages=11, previous_context=""):
    """第一轮：逐页扩写前先做“本话故事计划”，校验失败只重试本步骤。"""
    set_auto_job(stage="story", progress=0.02,
                 message="正在编排本话故事计划…")
    continuation = (
        "\n连载承接资料（位置、伤势、装备、关系、秘密必须原样承接）：\n" +
        str(previous_context or "").strip()[:6000]
    ) if str(previous_context or "").strip() else ""
    sysmsg = (
        "你是商业连载漫画的故事策划。根据用户已经人工确认的“本话剧情大意”，"
        "先做本话内部的故事结构计划，不写逐页内容、不分格、不写生图提示词、不写小说正文。\n\n"
        "硬性要求：\n"
        "1. 严格忠于已确认的大意：大意里的关键动作、伤势、装备去向、人物关系变化和最后位置"
        "都是硬约束，不能省略、替换或提前结束。\n"
        "2. 不得增加会改变故事方向的新反派、新主线或新秘密；人物只能来自大意和固定人物卡。\n"
        "3. 主角必须有明确目标或当前需求；事件之间必须存在“原因→行动→结果”。\n"
        "4. 至少一次人物选择或局面转折；写明本话付出的代价或发生的实际变化。\n"
        "5. hardFinalState 必须对应本话大意最后一句写明的最终状态。\n"
        "6. 全部使用能直接画的大白话，禁止“仿佛、宛若、宿命、氛围感、压迫感、"
        "冲突升级、危机降临、留下悬念、情绪交织”等空话。\n"
        "7. keyChoices 必须写具体：choice=人物主动做了什么；reason=根据前面哪件事作出这个决定；"
        "result=这个选择直接造成什么结果。禁止“推进剧情、冲突升级、发现重要线索、"
        "情况发生变化、主角决定继续、危机出现”等空话。\n"
        "8. criticalEvents 是本话关键事件清单：把用户大意中的核心异常、人物选择、"
        "关系变化、装备变化、位置变化和最终状态全部提取为事件。"
        "不允许用自己更容易写的事件替代用户明确事件：例如“镜中没有主角倒影”"
        "不能被“地面出现法阵”替代；“从管家袖口取出钥匙”不能改成“管家主动递交钥匙”；"
        "“看见家族灭门记录”不能只写“普通划痕”。"
        "importance=core 表示缺失后本话故事不成立（核心异常、选择、转折、最终状态通常都是core）；"
        "major 表示重要发展或转折；support 表示辅助铺垫或连接。"
        "所有core事件必须保留到页面计划并最终落实。\n"
        "9. criticalEvents 中一条事件只能表达一个独立完成的事情，必须拆分以下复合情况："
        "不同人物分别完成两个关键动作；一个事件即使缺少后半部分、前半部分仍可单独发生；"
        "同一句包含两个会分别改变剧情状态的动作；前一个动作是后一个动作的原因。"
        "例如“管家阻止进入地下室，被卡洛从袖口取出钥匙”必须拆成"
        "“管家明确伸手阻止卡洛进入地下室”和“卡洛主动从管家袖口内取出黄铜钥匙”两条，"
        "分别记录 requiredResult。\n"
        "10. 每个core事件必须给出 primaryPage（准确发生页，最多两个连续页）、"
        "setupPages（只铺垫）、aftermathPages（只表现反应和结果）、"
        "requiredFacts（按组列出必须同时命中的事实，每组 anyOf 是同义表达，"
        "例如人物组[“卡洛”]、对象组[“落地镜”“镜子”“镜面”]、"
        "异常结果组[“没有自己的倒影”“镜中没有自己”]）。"
        "support事件可以不指定准确页，但core必须指定。\n"
        "11. 用户大意最后一句中的最终位置、手中装备、是否空手、伤势、人物关系、"
        "必须看到的发现，必须自动生成 hardFinalEvent=true 的core事件，"
        "例如“卡洛已经进入六角石室”“卡洛进入石室时双手空着，没有持有钥匙或法杖”"
        "“卡洛清楚看见墙上记录着家族灭门记录”。如果大意最后一句同时包含位置变化、"
        "装备/空手状态和必须看到的发现，必须分别生成三条独立的 hardFinalEvent=true 的core事件，"
        "不能合并成一条；它们只能绑定最后一页或倒数第二页。\n"
        "12. hardFinalState.equipment 必须写清装备去向；如果本话大意最后写明主角空手/未携带装备，"
        "equipment 必须体现这一点，且最终状态不得让主角手持任何物品。\n\n"
        "13. 人物姓名必须严格使用【固定人物视觉卡】里的姓名：主角用视觉卡第一段人物的姓名，"
        "其他人物用各自人物卡的姓名；禁止使用其他姓名、化名或示例名。"
        "提示词示例中的“卡洛”只是格式示例，不是本作人物，不得出现在任何事件、"
        "requiredFacts 或状态描述里。\n\n"
        "只输出一个JSON对象，不要Markdown、解释或JSON以外的文字：\n"
        '{\n  "episodeGoal": "主角本话的目标或当前需求",\n'
        '  "motivation": "为什么必须现在做",\n'
        '  "startingState": "本话开始时谁在哪、什么状态、手里有什么、当前问题是什么",\n'
        '  "mainObstacle": "本话最主要的阻碍（具体的人/物/规则/信息）",\n'
        '  "keyChoices": [{"choice": "人物主动做了什么", "reason": "根据前面哪件事", "result": "直接造成什么结果"}],\n'
        '  "turningPoint": "哪件事改变了原来的判断或局面",\n'
        '  "cost": "选择造成的损失、风险或关系变化",\n'
        '  "episodeResult": "本话结束时实际发生了什么",\n'
        '  "nextEpisodeDrive": "为什么故事还需要继续（必须来自大意，不能新造主线）",\n'
        '  "criticalEvents": [{"eventId": "E1", "event": "单个独立完成的事件", "importance": "core", '
        '"requiredResult": "这件事发生后造成的具体结果", "primaryPage": 3, '
        '"setupPages": [2], "aftermathPages": [4], "hardFinalEvent": false, '
        '"requiredFacts": [{"label": "人物", "anyOf": ["卡洛"]}, '
        '{"label": "对象", "anyOf": ["落地镜", "镜子"]}, '
        '{"label": "异常结果", "anyOf": ["没有自己的倒影", "镜中没有自己"]}]}],\n'
        '  "hardFinalState": {"locations": {"主地点": "具体状态"}, '
        '"injuries": {"部位": "伤势"}, "equipment": {"物品": "去向"}, '
        '"relationships": {"人物关系": "变化"}, "knowledge": {"秘密或信息": "谁知道了"}}\n}'
    )
    usermsg = (
        "已经人工确认的本话剧情大意（硬约束）：\n%s\n\n"
        "固定主要场景设定：\n%s\n\n固定人物视觉卡：\n%s\n\n"
        "本话页数：%d页%s"
        % (str(premise or "").strip()[:3000],
           str(scene_setting or "").strip()[:6500],
           str(char_sheet or "").strip()[:5000],
           target_pages, continuation)
    )

    def generate():
        raw = chat_stream(
            [{"role": "system", "content": sysmsg},
             {"role": "user", "content": usermsg}],
            0.4, None, 3200).strip()
        plan = _extract_json_value(raw)
        errors = validate_episode_narrative_plan(plan, premise, target_pages)
        if errors:
            log("⚠ 本话故事计划校验失败：" + "；".join(errors[:5]) +
                "；原始输出前300字：" + str(raw)[:300])
            raise RuntimeError("本话故事计划不合格：" + "；".join(errors[:5]))
        return plan, raw, errors

    plan, raw, errors = _auto_retry("本话故事计划", generate, 5, 2)
    set_auto_job(stage="story", progress=0.05,
                 message="✅ 本话故事计划已编排")
    return {"narrative": plan, "raw": str(raw)[:20000], "errors": errors}


def validate_page_narrative_plans(plans, target_pages, narrative=None):
    """校验每页叙事任务：数量、结构、实质推进、stateChange 不能长期为空。"""
    errors = []
    warnings = []
    if not isinstance(plans, list):
        return ["每页叙事任务不是JSON数组"]
    if len(plans) != target_pages:
        return ["每页叙事任务数量%d与目标页数%d不一致" % (len(plans), target_pages)]
    seen_moments = set()
    stalled = 0
    crit_events = ((narrative or {}).get("criticalEvents")) or []
    crit_ids = {str(ev.get("eventId") or "").strip()
                for ev in crit_events if isinstance(ev, dict)}
    core_ids = {str(ev.get("eventId") or "").strip()
                for ev in crit_events if isinstance(ev, dict) and
                str(ev.get("importance") or "") == "core"}
    assigned_ids = set()
    for i, p in enumerate(plans):
        if not isinstance(p, dict):
            errors.append("第%d页计划不是对象" % (i + 1))
            continue
        num = int(p.get("pageNumber") or 0)
        if num != i + 1:
            errors.append("第%d项 pageNumber=%s，应为%d" % (i + 1, num, i + 1))
        for key in ("pagePurpose", "readerTakeaway", "stateChange",
                    "keyMoment", "pageEnding", "location",
                    "causedBy", "pageResult", "leadsTo"):
            if not str(p.get(key) or "").strip():
                errors.append("第%d页缺少 %s" % (i + 1, key))
        if not isinstance(p.get("mustIncludeEvents"), list):
            errors.append("第%d页 mustIncludeEvents 必须是数组" % (i + 1))
        if not isinstance(p.get("criticalEventIds"), list):
            errors.append("第%d页 criticalEventIds 必须是数组" % (i + 1))
        else:
            for eid in p.get("criticalEventIds"):
                eid = str(eid or "").strip()
                if eid and eid not in crit_ids:
                    errors.append("第%d页 criticalEventIds 引用了不存在的 %s" %
                                  (i + 1, eid))
                if eid:
                    assigned_ids.add(eid)
        for key in ("primaryEventIds", "setupEventIds", "aftermathEventIds"):
            if not isinstance(p.get(key), list):
                errors.append("第%d页 %s 必须是数组" % (i + 1, key))
            else:
                for eid in p.get(key):
                    eid = str(eid or "").strip()
                    if eid and eid not in crit_ids:
                        errors.append("第%d页 %s 引用了不存在的 %s" %
                                      (i + 1, key, eid))
                    if key == "primaryEventIds" and eid and \
                            eid not in (p.get("criticalEventIds") or []):
                        errors.append("第%d页 %s 中的 %s 未出现在 criticalEventIds" %
                                      (i + 1, key, eid))
        if not isinstance(p.get("characters"), list):
            errors.append("第%d页 characters 必须是数组" % (i + 1))
        if not str(p.get("pageResultId") or "").strip():
            errors.append("第%d页缺少 pageResultId" % (i + 1))
        if i > 0 and not str(p.get("causedByResultId") or "").strip():
            errors.append("第%d页缺少 causedByResultId" % (i + 1))
        moment = str(p.get("keyMoment") or "").strip()
        if moment and moment in seen_moments:
            errors.append("第%d页 keyMoment 与前面重复" % (i + 1))
        seen_moments.add(moment)
        purpose = str(p.get("pagePurpose") or "") + \
            str(p.get("readerTakeaway") or "") + str(p.get("keyMoment") or "")
        if any(w in purpose for w in _PAGE_STALL_WORDS) and \
                not any(w in purpose for w in _PAGE_PROGRESS_WORDS):
            stalled += 1
        else:
            stalled = 0
        if stalled >= 3:
            errors.append("第%d页起连续%d页只有走路/观察/转头/站立类任务" %
                          (i - 1, stalled))
            stalled = 0
    filled_state = sum(1 for p in plans if isinstance(p, dict) and
                       str(p.get("stateChange") or "").strip())
    if filled_state < max(1, int(target_pages * 0.8)):
        errors.append("stateChange 长期为空：只有%d/%d页有状态变化" %
                      (filled_state, target_pages))
    missing_core = sorted(core_ids - assigned_ids)
    if missing_core:
        errors.append("core事件未分配到任何页面：%s" % "、".join(missing_core))
    # 因果链改用显式ID：pageResultId 唯一；causedByResultId 必须引用更早页结果
    result_owner = {}
    for i, p in enumerate(plans):
        if not isinstance(p, dict):
            continue
        rid = str(p.get("pageResultId") or "").strip()
        if not rid:
            continue
        if rid in result_owner:
            errors.append("pageResultId 重复：%s" % rid)
        result_owner[rid] = i
    for i, p in enumerate(plans):
        if not isinstance(p, dict):
            continue
        cid = str(p.get("causedByResultId") or "").strip()
        if i == 0 and not cid:
            continue
        if not cid:
            continue  # 上面已报缺少
        if cid not in result_owner:
            errors.append("第%d页 causedByResultId 引用了不存在的 %s" % (i + 1, cid))
        elif result_owner[cid] >= i:
            errors.append("第%d页 causedByResultId 不能引用自身或未来页" % (i + 1))
    # core事件 primaryPage 必须写入对应页的 primaryEventIds 与 criticalEventIds
    for ev in crit_events:
        if not isinstance(ev, dict):
            continue
        eid = str(ev.get("eventId") or "").strip()
        if str(ev.get("importance") or "") != "core":
            continue
        pages = _event_primary_pages(ev)
        if not pages:
            continue
        for pn in pages:
            if pn < 1 or pn > len(plans):
                continue
            page = plans[pn - 1]
            if not isinstance(page, dict):
                continue
            if eid not in (page.get("primaryEventIds") or []):
                errors.append("core事件%s的primaryPage第%d页未写入primaryEventIds" %
                              (eid, pn))
            if eid not in (page.get("criticalEventIds") or []):
                errors.append("core事件%s的primaryPage第%d页未写入criticalEventIds" %
                              (eid, pn))
        for idx, page in enumerate(plans, 1):
            if isinstance(page, dict) and \
                    eid in (page.get("primaryEventIds") or []) and \
                    idx not in pages:
                errors.append("core事件%s的primaryEventIds散布在第%d页（应为%s）" %
                              (eid, idx, pages))
    for w in warnings:
        log("⚠ 页面任务因果链警告：" + w)
    return errors


def build_page_narrative_plans(narrative, target_pages=11,
                               scene_setting="", char_sheet="",
                               previous_context=""):
    """第一轮：按本话故事计划拆出每页叙事任务，校验失败只重试本步骤。"""
    set_auto_job(stage="story", progress=0.06,
                 message="正在规划每页叙事任务…")
    continuation = (
        "\n连载承接资料（位置、伤势、装备、关系、秘密必须原样承接）：\n" +
        str(previous_context or "").strip()[:6000]
    ) if str(previous_context or "").strip() else ""
    sysmsg = (
        "你是商业连载漫画的页级叙事规划师。根据已经确认的“本话故事计划”，"
        "把整话拆成%d页的叙事任务。不写逐页具体内容、不分格、不写对白正文、不写生图提示词。\n\n"
        "每页必须满足：\n"
        "1. pagePurpose 明确这一页在故事里负责什么；\n"
        "2. readerTakeaway 明确读者看完这一页必须知道或感受到什么；\n"
        "3. 每页至少推进剧情、人物认知、人物关系、冲突或伏笔中的一项；\n"
        "4. stateChange 写清这一页结束时谁/什么发生了什么看得见的变化"
        "（允许个别页面为空，但不能长期为空）；\n"
        "5. keyMoment 必须是能画出来的具体瞬间（谁做了什么、看到了什么、说了什么）；\n"
        "6. mustIncludeEvents 列出这页必须出现的具体故事事件，供逐页扩写严格落实；"
        "每条必须是故事层面的“谁做了什么/发现了什么/说了什么”，不超过20字，"
        "不得使用镜头、景别、构图、光线对比等画面术语；\n"
        "7. 删除该页后故事应受到明显影响，禁止连续多页只写走路、观察、转头或站立对白；\n"
        "8. 一页只推进一件主要事情，但可以有铺垫、动作和结果；\n"
        "9. 最后一页必须达到 hardFinalState。\n"
        "10. 全部用大白话，禁止空泛词；不得改变故事计划里的目标、阻碍、转折、代价和结果。\n"
        "11. pagePurpose、readerTakeaway、stateChange、keyMoment、mustIncludeEvents 全部禁止"
        "“特写、全景、中景、近景、远景、镜头、画面、展示、对比、光线、视角”等画面术语；"
        "这些内容属于后面的调度与分镜阶段。\n"
        "12. causedBy 写清这一页为什么会发生，必须承接上一页 pageResult 的具体结果；"
        "第1页可以写本话开始时人物/地点/问题本身，不强制套用上一话。\n"
        "13. pageResult 写清这一页结束时人物、信息、关系、位置、装备或危险发生的实际变化；"
        "leadsTo 写清这个结果为什么引出下一页。\n"
        "14. criticalEventIds 列出本页负责落实的 criticalEvents（来自故事计划的关键事件清单）；"
        "所有 core 事件必须至少绑定一页，页数不足时只能合并 support 事件，不能删除 core 事件；"
        "一个 core 事件可以跨两页表现，但不能完全遗漏。\n"
        "15. 页面之间必须形成连续因果链：人物移动必须有行动或过渡；新人物出现必须有出场动作、"
        "声音、遮挡或场景依据；获得/丢失物品或受伤后，后续页面必须承接；"
        "关系变化必须由具体动作、台词或信息触发；不能出现上一页还在观察镜子、"
        "下一页无过程直接进入地下室。\n"
        "16. 不要使用固定开场模板：根据大意和题材自行选择环境开场、人物开场、动作开场、"
        "异常开场或直接对话；不强制第一页是场景、不强制使用旁白、不强制慢节奏。"
        "但开场必须让读者在前30%%页面内理解主要人物、当前地点、人物正在做什么、"
        "以及本话首先需要解决的问题；核心事件前要有足够的行动或信息铺垫，"
        "核心事件发生后要有反应和实际后果，不能把所有概要事件连续快速罗列。\n"
        "17. 本话必须包含：一个明确目标或当前需求、一个具体阻碍、一次人物主动选择、"
        "一次信息/关系/危险/目标变化、一个实际结果或阶段性结果。"
        "不要求大战、反派、受伤或惊天反转；信任变怀疑、安全变危险、不知道变知道、"
        "得到物品又失去、目标完成但出现代价等都可以。"
        "不要添加每页 tensionLevel 之类的固定模板字段。\n"
        "18. 每页必须写清三个事件职责：primaryEventIds=本页真正完成的事件；"
        "setupEventIds=只做铺垫；aftermathEventIds=只表现人物反应或后果。"
        "同一事件的primaryEventIds不能散布在大量页面；core事件只能在它声明的primaryPage页出现为primary。\n"
        "19. 因果链使用显式ID：第1页causedByResultId可以为空；每页pageResultId必须唯一；"
        "第N+1页的causedByResultId必须引用上一页或更早页面的pageResultId；"
        "插入并行情节时允许引用更早结果。\n"
        "20. 每页必须形成“承接→新信息→决定→推向下一页”的完整递进："
        "causedBy 写明承接了上一页哪个具体结果；pageResult 必须包含本页新增的一个明确信息或变化；"
        "leadsTo 必须写明主角因本页结果做了什么决定、这个决定把下一页推向哪里。"
        "禁止整页只做状态描写或原地总结。\n"
        "21. 节奏硬限制：一页最多完成一件主要事件，"
        "禁止一页同时完成“发现名单+捡到门禁卡+进入档案室”这类连续压缩；"
        "核心真相（本话最关键的信息或发现）不能全部在前30%%页面抛完，"
        "关键道具、关键证据和最终真相必须分布在中后段；"
        "最后一页必须出现新的威胁、疑问或决定作为钩子，"
        "不能只是人物站在场景里总结现状。\n\n"
        "只输出一个JSON数组，长度必须正好%d项，不要Markdown、解释或JSON以外的文字：\n"
        '[{"pageNumber":1,"pagePurpose":"","readerTakeaway":"","stateChange":"",'
        '"keyMoment":"","pageEnding":"","mustIncludeEvents":[""],'
        '"location":"","characters":[""],"causedBy":"","pageResult":"","leadsTo":"",'
        '"criticalEventIds":["E1"],"primaryEventIds":["E1"],"setupEventIds":[],'
        '"aftermathEventIds":[],"causedByResultId":"","pageResultId":"R01"}]'
        % (target_pages, target_pages)
    )
    usermsg = (
        "本话故事计划（含 criticalEvents 关键事件清单，必须逐条分配到页面）：\n%s\n\n"
        "固定主要场景设定：\n%s\n\n固定人物视觉卡：\n%s%s"
        % (json.dumps(narrative, ensure_ascii=False)[:8000],
           str(scene_setting or "").strip()[:6500],
           str(char_sheet or "").strip()[:5000], continuation)
    )

    def parse_plans(raw):
        val = _extract_json_value(raw)
        if isinstance(val, dict):
            for k in ("pages", "pagePlans", "plans"):
                if isinstance(val.get(k), list):
                    return val[k]
        return val

    def generate_with_note(note=""):
        user = usermsg
        if note:
            user = usermsg + "\n\n上一版失败：" + note + \
                "\n只输出JSON数组本身：开头是[，结尾是]，不要用对象包裹，不要Markdown。"
        raw = chat_stream(
            [{"role": "system", "content": sysmsg},
             {"role": "user", "content": user}],
            0.4, None, max(4200, target_pages * 650)).strip()
        plans = parse_plans(raw)
        if not isinstance(plans, list):
            raise RuntimeError("每页叙事任务不是JSON数组；原始输出前200字：" +
                               str(raw)[:200])
        # 模型偶发漏写 pageEnding：用 pageResult/keyMoment 回填，避免整轮报废
        for p in plans:
            if isinstance(p, dict) and \
                    not str(p.get("pageEnding") or "").strip():
                fallback = str(p.get("pageResult") or p.get("keyMoment") or "").strip()
                if fallback:
                    p["pageEnding"] = fallback
                    log("⚠ 第%s页缺pageEnding，已用pageResult补全" %
                        (p.get("pageNumber") or "?"))
        errors = validate_page_narrative_plans(plans, target_pages, narrative)
        if errors:
            log("⚠ 每页叙事任务校验失败：" + "；".join(errors[:5]))
            raise RuntimeError("每页叙事任务不合格：" + "；".join(errors[:5]))
        return plans, raw, errors

    plans = raw = errors = None
    last_err = ""
    for attempt in range(1, 6):
        _auto_check_stop()
        try:
            plans, raw, errors = generate_with_note(last_err)
            break
        except Exception as e:
            last_err = str(e)
            log("⚠ 每页叙事任务失败：%s" % last_err)
            if attempt < 3:
                set_auto_job(message="每页叙事任务失败，正在第 %d 次重试…" % (attempt + 1))
                for _ in range(max(1, 2 * attempt * 2)):
                    _auto_check_stop()
                    time.sleep(0.5)
    if plans is None:
        raise RuntimeError(last_err or "每页叙事任务失败")
    set_auto_job(stage="story", progress=0.08,
                 message="✅ 每页叙事任务已规划")
    return {"pagePlans": plans, "raw": str(raw)[:20000], "errors": errors}


def _hit_text(text):
    import re as _re
    return _re.sub(r"\s+", "", str(text or ""))


_SHOT_TERMS = ("特写", "全景", "中景", "近景", "远景", "俯视", "仰视",
               "镜头", "画面", "展示", "对比", "光线", "视角")


def _event_clauses(event):
    """把必须事件拆成可匹配的短句，并去掉镜头术语前缀，用于容错核对。"""
    norm = _hit_text(event)
    parts = re.split(r"[；;、，。]", norm)
    out = []
    for part in parts:
        for term in _SHOT_TERMS:
            if part.startswith(term):
                part = part[len(term):]
                break
        if len(part) >= 4:
            out.append(part)
    if not out and len(norm) >= 4:
        out.append(norm)
    return out


def _event_clause_hit(clause, page_norm):
    """事件短句在页面里命中：优先整句；允许5字滑动窗口匹配同义表达。"""
    if clause in page_norm:
        return True
    if len(clause) >= 5:
        for i in range(len(clause) - 4):
            if clause[i:i + 5] in page_norm:
                return True
    return False


_CRIT_VERBS = (
    "发现", "看见", "看到", "进入", "打开", "取出", "拿走", "摸到", "试探",
    "阻止", "警告", "开口", "说话", "划伤", "流血", "捡起", "放下", "推开",
    "拉开", "抓住", "握住", "跪下", "站住", "离开", "转身", "回头", "低头",
    "抬头", "伸手", "掏出", "插入", "转动", "穿过", "寻找", "继承", "入住",
    "躲避", "翻看", "刻下", "写下", "熄灭", "点亮", "靠近", "退开", "摘下",
    "取下", "偷走", "夺走", "掉落", "碎裂", "摔碎", "触碰", "点击", "按下",
)


def _critical_event_light_hit(event, page_norm, char_names):
    """criticalEvent 在页面里的轻量落实：人物/动作/结果三类中至少命中两类。"""
    ev_norm = _hit_text(event.get("event") or "")
    res_norm = _hit_text(event.get("requiredResult") or "")
    names = [str(n) for n in (char_names or [])
             if str(n).strip() and _hit_text(n) in ev_norm]
    person_hit = any(n in page_norm for n in names)
    action_hit = any(v in ev_norm and v in page_norm for v in _CRIT_VERBS)
    result_hit = bool(res_norm) and any(
        _event_clause_hit(c, page_norm) for c in _event_clauses(res_norm))
    return int(person_hit) + int(action_hit) + int(result_hit)


_GRAM_STOP = set("的了在把从向对给被是就都将也很只")


def _anyof_hit(expr, page_norm):
    """anyOf 单项命中：整句→5字窗口→3字片段→2字片段(≥2处)。用于容纳同义表达。"""
    e = _hit_text(expr)
    if not e:
        return False
    if e in page_norm:
        return True
    if len(e) >= 5:
        for i in range(len(e) - 4):
            if e[i:i + 5] in page_norm:
                return True
    if len(e) >= 3:
        for i in range(len(e) - 2):
            tri = e[i:i + 3]
            if tri in page_norm and not all(c in _GRAM_STOP for c in tri):
                return True
    if len(e) >= 2:
        grams = [e[i:i + 2] for i in range(len(e) - 1)
                 if e[i] not in _GRAM_STOP and e[i + 1] not in _GRAM_STOP]
        if sum(1 for g in grams if g in page_norm) >= 2:
            return True
        # 同义表达的最后一级：组内任一表达命中一个内容2字片段即可。
        # 各组（人物/对象/结果）联合校验仍能把事件钉在准确页。
        if any(g in page_norm for g in grams):
            return True
    return False


def _page_hits_facts(page_norm, facts):
    """requiredFacts 按组校验：每组 anyOf 至少命中一项才通过。返回None表示无组可验。"""
    if not isinstance(facts, list) or not facts:
        return None
    for g in facts:
        if not isinstance(g, dict):
            return False
        anyof = [str(x) for x in (g.get("anyOf") or []) if str(x).strip()]
        if not anyof:
            return False
        if not any(_anyof_hit(x, page_norm) for x in anyof):
            return False
    return True


def validate_pages_against_narrative_plan(page_texts, page_plans, narrative=None,
                                          lenient=False):
    """逐页扩写完成后核对：必须事件不丢、没有纯走路页、最后一页达到 hardFinalState。
    lenient=True 时（仅一句话自动入口使用）core事件requiredFacts只警告不阻断，
    hardFinalEvent与结构性问题仍硬校验。"""
    errors = []
    if len(page_texts) != len(page_plans):
        return ["逐页内容%d页与页面任务%d页不一致" %
                (len(page_texts), len(page_plans))]
    crit_map = {}
    for ev in ((narrative or {}).get("criticalEvents") or []):
        if isinstance(ev, dict):
            crit_map[str(ev.get("eventId") or "").strip()] = ev
    for i, (text, plan) in enumerate(zip(page_texts, page_plans), 1):
        norm = _hit_text(text)
        for ev in (plan.get("mustIncludeEvents") or []):
            ev_text = str(ev or "").strip()
            if not ev_text:
                continue
            clauses = _event_clauses(ev_text)
            if not clauses:
                continue  # 事件太短无法有效核对，不误杀
            if not any(_event_clause_hit(c, norm) for c in clauses):
                # 模型常用同义表达改写事件，字符串匹配无法可靠判定“丢失”。
                # 这里只记录警告，交给报告人工核对；硬校验只保留结构性问题。
                log("⚠ 第%d页事件疑似未逐字落实（警告，需语义核对）：%s" %
                    (i, ev_text[:40]))
        if not any(w in norm for w in _PAGE_PROGRESS_WORDS) and "对白" not in norm:
            errors.append("第%d页没有可见推进动作或事件" % i)
        for eid in ((plan.get("criticalEventIds") or []) if isinstance(plan, dict) else []):
            ev = crit_map.get(str(eid or "").strip())
            if not ev:
                continue
            if str(ev.get("importance") or "") == "core":
                primary = _event_primary_pages(ev)
                if i in primary:
                    facts_ok = _page_hits_facts(norm, ev.get("requiredFacts"))
                    if facts_ok is False:
                        groups = []
                        for g in (ev.get("requiredFacts") or []):
                            if isinstance(g, dict):
                                groups.append("%s[%s]" % (
                                    str(g.get("label") or "组"),
                                    "/".join(str(x) for x in (g.get("anyOf") or []))))
                        msg = ("第%d页 core事件 %s 未同时落实requiredFacts"
                               "（%s；需命中：%s）" %
                               (i, eid, str(ev.get("event") or "")[:30],
                                "；".join(groups)[:160]))
                        if lenient:
                            log("⚠ [lenient] " + msg)
                        else:
                            errors.append(msg)
            else:
                hits = _critical_event_light_hit(
                    ev, norm,
                    (plan.get("characters") or []) if isinstance(plan, dict) else [])
                if hits < 2:
                    log("⚠ 第%d页 criticalEvent %s 落实度低（命中%d/3类，需语义核对）：%s" %
                        (i, eid, hits, str(ev.get("event") or "")[:30]))
    # hardFinalEvent 必须在其 primaryPage 落实（汇总校验）
    for eid, ev in crit_map.items():
        if str(ev.get("hardFinalEvent") or "").lower() not in ("true", "1"):
            continue
        pages = _event_primary_pages(ev)
        if not pages or pages[0] < 1 or pages[0] > len(page_texts):
            continue
        norm = _hit_text(page_texts[pages[0] - 1])
        if _page_hits_facts(norm, ev.get("requiredFacts")) is not True:
            errors.append("hardFinalEvent %s 在primaryPage第%d页未落实requiredFacts" %
                          (eid, pages[0]))
    hfs = ((narrative or {}).get("hardFinalState")) or {}
    last_norm = _hit_text(page_texts[-1]) if page_texts else ""
    last_text = page_texts[-1] if page_texts else ""

    def hfs_keywords(items):
        """把 hardFinalState 的键和值拆成关键词（键名优先，值按顿号逗号拆）。"""
        out = []
        if not isinstance(items, dict):
            return out
        for k, v in items.items():
            key = str(k or "").strip()
            if key and key not in out:
                out.append(key)
            for part in re.split(r"[、；;，,\s]+", str(v or "")):
                part = part.strip()
                if len(part) >= 2 and part not in out:
                    out.append(part)
        return out

    locs = hfs_keywords(hfs.get("locations"))
    injs = hfs_keywords(hfs.get("injuries"))
    eqs = hfs_keywords(hfs.get("equipment"))
    if locs and not any(_hit_text(x) in last_norm for x in locs):
        log("⚠ 最后一页位置疑似未逐字落实（警告，需语义核对）：%s" %
            "、".join(locs[:4]))
    if injs and not any(_hit_text(x) in last_norm for x in injs):
        log("⚠ 最后一页伤势状态疑似未落实（警告，需语义核对）：%s" %
            "、".join(injs[:4]))
    if eqs and not any(_hit_text(x) in last_norm for x in eqs):
        log("⚠ 最后一页装备去向疑似未落实（警告，需语义核对）：%s" %
            "、".join(eqs[:4]))
    eq_text = " ".join(str(v) for v in (hfs.get("equipment") or {}).values())
    empty_hands = any(w in eq_text for w in
                      ("空手", "未携带", "不在手中", "没有带", "双手空空", "无任何"))
    if empty_hands and re.search(
            r"[握拿持抓提夹捏][^。；]{0,8}(钥匙|法杖|铜钥|剑|刀|杖|物品)", last_text):
        msg = "最后一页与空手状态矛盾：人物手里仍拿着物品"
        if lenient:
            log("⚠ [lenient] " + msg)
        else:
            errors.append(msg)
    return errors


def build_comic_anchor(name, card_text, art=""):
    """生成一次固定 comicAnchor：只保留跨页稳定外观，供每一页原样复用。"""
    sysmsg = (
        "你是漫画人物固定外观锚点设计师。根据人物卡输出一行不超过100字的中文外观锚点，"
        "用于同一人物在整部漫画的每一页保持外观一致。只保留：姓名；性别和年龄感；"
        "身材轮廓；发型发色；1至2个脸部识别点；固定服装主轮廓和主色；1至2个永久标志物。"
        "不要写精确身高数字、完整服装结构、性格、剧情、情绪、背景、能力或武器动作。"
        "严格照人物卡提取，不得编造；服装按题材和身份提取，不强制珠宝刺绣；"
        "人物卡里没有写的武器、珠宝、挂件、特殊装备不得补充，固定标志物只能来自人物卡原文。"
        "只输出一行锚点文本本身，不加标题、不加解释、不加JSON。"
    )
    raw = chat_stream(
        [{"role": "system", "content": sysmsg},
         {"role": "user", "content":
          "人物：%s\n人物卡：%s" % (name, str(card_text or "")[:1800])}],
        0.2, None, 300).strip()
    raw = raw.splitlines()[0].strip() if raw else ""
    raw = re.sub(r"^【[^】]*】\s*", "", raw)
    return _short_visual(raw, 110)


def ensure_comic_anchors(char_sheet, design_direction="", art="", previous=None):
    """确认后的人物固定锚点：卡片内容没变就原样复用，变了才重新生成并升版本。"""
    prev = previous if isinstance(previous, dict) else {}
    cards = parse_char_sheet(char_sheet or "")
    out = {}
    for name, card in cards.items():
        base = re.sub(r"\s*[（(][^）)]*[）)]\s*$", "", str(name)).strip()
        card_hash = hashlib.sha256(
            (str(card) + "|" + str(design_direction or "")).encode("utf-8")
        ).hexdigest()[:12]
        old = prev.get(name) or prev.get(base)
        if old and isinstance(old, dict) and \
                old.get("cardHash") == card_hash and \
                str(old.get("comicAnchor") or "").strip():
            out[name] = dict(old)
            continue
        log("🧷 生成漫画锚点：%s" % name)
        anchor = build_comic_anchor(name, card, art)
        if not anchor:
            log("⚠ 漫画锚点生成失败，保留旧锚点：%s" % name)
            if old and isinstance(old, dict) and \
                    str(old.get("comicAnchor") or "").strip():
                out[name] = dict(old)
            continue
        version = 1
        if old and isinstance(old, dict):
            try:
                version = int(old.get("comicAnchorVersion") or 1) + 1
            except Exception:
                version = 2
        out[name] = {
            "comicAnchor": anchor,
            "comicAnchorVersion": version,
            "cardHash": card_hash,
        }
    return out


