                data = self._read_json()
                state = load_creative_state()
                if data.get("key") and data.get("key") == state.get("key"):
                    completed = data.get("completed")
                    if not isinstance(completed, list):
                        completed = state.get("completed") or []
                    state = save_creative_state(
                        stage="images", completed=completed,
                        dir=str(data.get("dir") or state.get("dir") or ""),
                    )
                self._send(200, "application/json", json.dumps(
                    {"ok": True, "state": state}, ensure_ascii=False))

