                data = self._read_json()
                dparts = [safe_name(x) for x in
                          str(data.get("dir", "")).replace("\\", "/").split("/") if x]
                base = os.path.join(COMIC_DIR, *dparts) if dparts else COMIC_DIR
                entries = []
