                data = self._read_json()
                prompt = str(data.get("prompt") or "").strip()
                if not prompt:
                    raise RuntimeError("提示词为空，无法保存")
                images = data.get("images") or []
                if isinstance(images, str):
                    images = [images]
                images = [x for x in images
                          if isinstance(x, str) and x.startswith("data:image/")][:6]
                folder, num = video_save_next_dir()
                saved_images = []
                for i, img in enumerate(images):
                    try:
                        head, _, b64data = img.partition(",")
                        mime = head.split(";")[0].split(":", 1)[-1] if ":" in head else "image/jpeg"
                        ext = ".png" if "png" in mime else ".jpg"
                        raw = base64.b64decode(b64data)
                        fname = "%02d%s" % (i + 1, ext)
                        with open(os.path.join(folder, fname), "wb") as f:
                            f.write(raw)
                        saved_images.append(fname)
                    except Exception:
                        pass
                with open(os.path.join(folder, "prompt.txt"), "w", encoding="utf-8") as f:
                    f.write(prompt)
                self._send(200, "application/json", json.dumps({
                    "ok": True, "num": num, "folder": os.path.basename(folder),
                    "dir": os.path.basename(VIDEO_SAVE_ROOT) + "/" + os.path.basename(folder),
                    "images": saved_images, "promptFile": "prompt.txt"}, ensure_ascii=False))

