def _vc_paths():
    os.makedirs(VC_DIR, exist_ok=True)
    os.makedirs(VC_CHATS_DIR, exist_ok=True)
    os.makedirs(VC_IMG_DIR, exist_ok=True)


def _vc_msg_id():
    return "m_%s_%d" % (time.strftime("%Y%m%d%H%M%S"), int(time.time_ns() % 100000))


def _extract_json_obj(raw):
    t = str(raw or "").strip()
    m = re.search(r"```(?:json)?\s*(.+?)```", t, re.S)
    if m:
        t = m.group(1).strip()
    i, j = t.find("{"), t.rfind("}")
    if i >= 0 and j > i:
        t = t[i:j + 1]
    try:
        obj = json.loads(t)
        return obj if isinstance(obj, dict) else None
    except Exception:
        try:
            obj = json.loads(re.sub(r",\s*([}\]])", r"\1", t))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None


def _vc_repair_json(raw):
    """对模型输出的 JSON 做一次本地修复，失败返回 None。"""
    t = str(raw or "").strip()
    m = re.search(r"```(?:json)?\s*(.+?)```", t, re.S)
    if m:
        t = m.group(1).strip()
    t = t.replace("“", '"').replace("”", '"').replace("‘", "'").replace("’", "'")
    t = t.replace("True", "true").replace("False", "false").replace("None", "null")
    t = re.sub(r",\s*([}\]])", r"\1", t)
    i, j = t.find("{"), t.rfind("}")
    if i >= 0 and j > i:
        t = t[i:j + 1]
    try:
        obj = json.loads(t)
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass
    # 单引号键/值兜底：把最外层单引号替换为双引号
    try:
        t2 = re.sub(r"(?<![\\'])'(?=[^']*')", '"', t)
        obj = json.loads(t2)
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


def vchar_fresh_identity_anchor():
    return {"ageText": "", "bodyBuild": "", "faceShape": "", "eyes": "",
            "hair": "", "skin": "", "signatureFeature": ""}


def vchar_fresh_default_appearance():
    return {"clothing": "", "hairState": "", "accessories": "", "makeup": ""}


def vchar_fresh_default_scene():
    return {"scene": "", "lighting": "", "time": ""}


def vchar_fresh_current_state():
    return {"clothing": "", "hairState": "", "accessories": "", "makeup": "",
            "action": "自然放松地待着", "expression": "自然平静",
            "bodyPose": "自然姿态", "scene": "", "lighting": "", "time": "",
            "viewContext": ""}


def vchar_fresh_memory():
    return {"relationshipProgress": "", "recentFacts": []}


def vchar_ensure_appearance(char):
    """锚点为空时从人设/视觉卡按规则提取补全（只补空字段，不覆盖已有值）。"""
    char = dict(char or {})
    ia = char.get("identityAnchor") or {}
    da = char.get("defaultAppearance") or {}
    if (any(str(v or "").strip() for v in ia.values())
            and any(str(v or "").strip() for v in da.values())):
        return char
    src = str(char.get("visualCard") or "") + "\n" + str(char.get("persona") or "")
    if not any(str(v or "").strip() for v in ia.values()):
        char["identityAnchor"] = vchar_extract_identity_anchor(src)
    if not any(str(v or "").strip() for v in da.values()):
        char["defaultAppearance"] = vchar_extract_default_appearance(src)
    return char


def _vc_write_appearance(char):
    """把补全后的外貌锚点写回角色数据，让聊天出图也使用。"""
    try:
        chars = vchar_list()
        for c in chars:
            if c.get("id") == char.get("id"):
                c["identityAnchor"] = char.get("identityAnchor") or c.get("identityAnchor")
                c["defaultAppearance"] = char.get("defaultAppearance") or c.get("defaultAppearance")
        with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
            json.dump(chars, f, ensure_ascii=False, indent=1)
    except Exception:
        pass


def _vc_pick(text, patterns):
    for pat in patterns:
        m = re.search(pat, str(text or ""))
        if m:
            v = (m.group(1) if m.lastindex else m.group(0)).strip()
            if v:
                return v
    return ""


def vchar_extract_identity_anchor(text):
    """从旧视觉卡/人设文字里按规则提取固定视觉锚点，找不到就留空。"""
    t = str(text or "")
    a = vchar_fresh_identity_anchor()
    a["ageText"] = _vc_pick(t, [r"(\d{1,3})\s*岁"])
    a["bodyBuild"] = _vc_pick(t, [r"(身高[^，。；,;]{0,18})",
                                  r"((?:极度|非常|很|略显|过于|身材)?(?:瘦弱|单薄|孱弱|纤细|修长|丰满|高挑|娇小|匀称|曼妙|健美|清瘦|瘦))"])
    a["faceShape"] = _vc_pick(t, [r"([^，。；,;]{0,8}(?:鹅蛋脸|瓜子脸|圆脸|方脸|长脸|小脸|娃娃脸))"])
    a["eyes"] = _vc_pick(t, [r"([^，。；,;]{0,12}(?:眼[^，。；,;]{0,8}|瞳色[^，。；,;]{0,8}))"])
    a["hair"] = _vc_pick(t, [r"([^，。；,;]{0,14}(?:发|头发|刘海|马尾|盘发)[^，。；,;]{0,10})"])
    a["skin"] = _vc_pick(t, [r"([^，。；,;]{0,10}(?:皮肤|肤色)[^，。；,;]{0,8})"])
    a["signatureFeature"] = _vc_pick(t, [r"(标志物[为是：:]*[^，。；,;]{0,14})",
                                         r"([^，。；,;]{1,12}(?:痣|疤痕|胎记|耳坠|手串|团扇|折扇|簪子|发卡|眼镜|项链))"])
    for k in a:
        a[k] = re.sub(r"^(身高|体型|脸型|眼睛|发型|皮肤|肤色|标志物)[为是：:]*", "", a[k]).strip()
    return a


def vchar_extract_default_appearance(text):
    t = str(text or "")
    d = vchar_fresh_default_appearance()
    segs = [s.strip().strip("，。；;、\n") for s in re.split(r"[，。；;、\n]", t) if s.strip()]
    for s in segs:
        if re.search(r"连衣裙|长裙|短裙|半身裙|百褶裙|旗袍|衬衫|T恤|卫衣|西装|汉服|和服|吊带|睡衣|校服|外套|大衣|风衣|短裤|长裤|牛仔裤|裙子|裙", s):
            s2 = s
            pres = ("喜欢", "最爱", "常穿", "平时", "总是", "穿着一件", "穿着",
                    "身穿", "身着", "穿", "着一件", "着")
            while True:
                hit = next((p for p in pres if s2.startswith(p)), "")
                if not hit:
                    break
                s2 = s2[len(hit):]
            d["clothing"] = s2.strip()
            break
    for s in segs:
        if re.search(r"长发|短发|中长发|齐肩|及腰|卷发|直发|双马尾|单马尾|盘发|丸子头|刘海|寸头|中分|披肩", s):
            d["hairState"] = re.sub(r"^(留着|留|一头|有着|是|扎着)", "", s).strip()
            break
    d["accessories"] = _vc_pick(t, [r"([^。；,;]{1,12}(?:耳环|项链|手串|戒指|簪子|发卡|发带|团扇|折扇|眼镜|手表))"])
    d["makeup"] = _vc_pick(t, [r"([^。；,;]{0,10}(?:淡妆|浓妆|妆容|口红|眼影))"])
    return d


def vchar_extract_default_scene(text):
    t = str(text or "")
    s = vchar_fresh_default_scene()
    s["scene"] = t.strip()
    s["time"] = _vc_pick(t, [r"(清晨|早上|白天|午后|傍晚|黄昏|夜晚|深夜|晚上|夜里|凌晨)"])
    s["lighting"] = _vc_pick(t, [r"([^，。；,;]{0,10}(?:灯光|光线|灯光|暖光|柔光|日光|月光|台灯|床头灯|烛光)[^，。；,;]{0,6})"])
    return s


def vchar_migrate(rec):
    """旧角色静默迁移到 v2 结构；不删除任何旧字段，失败也不影响原数据。"""
    if not isinstance(rec, dict):
        return {}, False
    changed = False
    persona = str(rec.get("persona") or "")
    if "originalPersona" not in rec:
        changed = True
        for sep in ("\n\n（AI补充，只扩写原文已有内容）\n", "\n\n（AI补充，只扩写不改动）\n"):
            if sep in persona:
                a, b = persona.split(sep, 1)
                rec["originalPersona"] = a.strip("\n")
                rec["expandedPersona"] = b.strip("\n")
                break
        else:
            rec["originalPersona"] = persona
            rec["expandedPersona"] = ""
    if "expandedPersona" not in rec:
        rec["expandedPersona"] = ""
        changed = True
    if "relationship" not in rec:
        rec["relationship"] = ""
        changed = True
    if not isinstance(rec.get("identityAnchor"), dict):
        rec["identityAnchor"] = vchar_extract_identity_anchor(
            str(rec.get("visualCard") or "") + "\n" + str(rec.get("originalPersona") or ""))
        changed = True
    if not isinstance(rec.get("defaultAppearance"), dict):
        rec["defaultAppearance"] = vchar_extract_default_appearance(
            str(rec.get("visualCard") or ""))
        changed = True
    if not isinstance(rec.get("defaultScene"), dict):
        rec["defaultScene"] = vchar_extract_default_scene(str(rec.get("defaultScene") or ""))
        changed = True
    if not isinstance(rec.get("styleProfile"), dict):
        style = str(rec.get("style") or "").strip()
        gp = str(rec.get("genPrompt") or "").strip()
        if not style and gp and len(gp) <= 60:
            style = gp
        rec["styleProfile"] = {"renderStyle": style or "超仿真",
                               "cameraStyle": "真实自然的生活照片感"}
        changed = True
    if not isinstance(rec.get("currentState"), dict):
        rec["currentState"] = vchar_fresh_current_state()
        da = rec.get("defaultAppearance") or {}
        ds = rec.get("defaultScene") or {}
        cs = rec["currentState"]
        for k in ("clothing", "hairState", "accessories", "makeup"):
            if str(da.get(k) or "").strip():
                cs[k] = str(da[k]).strip()
        for k in ("scene", "lighting", "time"):
            if str(ds.get(k) or "").strip():
                cs[k] = str(ds[k]).strip()
        changed = True
    if not isinstance(rec.get("memorySummary"), dict):
        rec["memorySummary"] = vchar_fresh_memory()
        changed = True
    else:
        if "recentFacts" not in rec["memorySummary"] or not isinstance(rec["memorySummary"]["recentFacts"], list):
            rec["memorySummary"]["recentFacts"] = []
            changed = True
        if "relationshipProgress" not in rec["memorySummary"]:
            rec["memorySummary"]["relationshipProgress"] = ""
            changed = True
    if "persona" not in rec:
        rec["persona"] = persona
        changed = True
    sp = rec.get("styleProfile")
    if isinstance(sp, dict):
        rs = str(sp.get("renderStyle") or "")
        if "高端电影摄影机拍摄的剧照" in rs:
            sp["renderStyle"] = ("极致电影级剧照：像顶级大片官方发布的电影剧照，强烈的电影调色滤镜，"
                                 "胶片质感，光影层次丰富，构图讲究有张力，画面有故事感和氛围感，"
                                 "质感高级，画面中只呈现人物与场景本身")
            rec["styleProfile"] = sp
            changed = True
        elif "手机摄像头的噪点" in rs:
            sp["renderStyle"] = rs.replace("自然带手机摄像头的噪点", "自然带随手拍摄的噪点")
            rec["styleProfile"] = sp
            changed = True
    return rec, changed


def vchar_list():
    _vc_paths()
    p = os.path.join(VC_DIR, "characters.json")
    try:
        with open(p, encoding="utf-8") as f:
            chars = json.load(f)
    except Exception:
        return []
    if not isinstance(chars, list):
        return []
    dirty = False
    for i, c in enumerate(chars):
        nc, ch = vchar_migrate(c)
        if ch:
            chars[i] = nc
            dirty = True
    if dirty:
        try:
            with open(p, "w", encoding="utf-8") as f:
                json.dump(chars, f, ensure_ascii=False, indent=1)
        except Exception as e:
            log("⚠️ 虚拟人物数据迁移写回失败：" + str(e)[:120])
    return chars


def vchar_save(data):
    _vc_paths()
    chars = vchar_list()
    cid = str(data.get("id") or "").strip()
    if not cid:
        cid = "vc_" + time.strftime("%Y%m%d_%H%M%S") + "_%03d" % int(time.time_ns() % 1000)
    old = next((c for c in chars if c.get("id") == cid), None)
    if old:
        old, _ = vchar_migrate(old)
    rec = dict(old) if old else {}
    rec["id"] = cid
    if data.get("name") is not None:
        rec["name"] = str(data.get("name") or "未命名")[:40]
    if data.get("age") is not None:
        rec["age"] = str(data.get("age") or "")
    if data.get("relationship") is not None:
        rec["relationship"] = str(data.get("relationship") or "")
    if data.get("persona") is not None:
        p = str(data.get("persona") or "")
        rec["persona"] = p
        if "（AI补充，只扩写原文已有内容）" in p:
            a, b = p.split("（AI补充，只扩写原文已有内容）", 1)
            rec["originalPersona"] = a.strip("\n")
            rec["expandedPersona"] = b.strip("\n").lstrip()
        elif "（AI补充，只扩写不改动）" in p:
            a, b = p.split("（AI补充，只扩写不改动）", 1)
            rec["originalPersona"] = a.strip("\n")
            rec["expandedPersona"] = b.strip("\n").lstrip()
        elif p:
            rec["originalPersona"] = p
            rec["expandedPersona"] = ""
    if data.get("visualCard") is not None:
        rec["visualCard"] = str(data.get("visualCard") or "")
    if data.get("defaultScene") is not None:
        ds = data.get("defaultScene")
        if isinstance(ds, dict):
            rec["defaultScene"] = {k: str(ds.get(k) or "") for k in vchar_fresh_default_scene()}
        else:
            rec["defaultScene"] = vchar_extract_default_scene(str(ds or ""))
    if data.get("genPrompt") is not None:
        gp = str(data.get("genPrompt") or "").strip()
        rec["genPrompt"] = gp
        if gp and len(gp) <= 60 and not isinstance(data.get("styleProfile"), dict):
            rec.setdefault("styleProfile", {})["renderStyle"] = gp
    if isinstance(data.get("identityAnchor"), dict):
        ia = vchar_fresh_identity_anchor()
        ia.update({k: str(data["identityAnchor"].get(k) or "") for k in ia})
        rec["identityAnchor"] = ia
    if isinstance(data.get("defaultAppearance"), dict):
        da = vchar_fresh_default_appearance()
        da.update({k: str(data["defaultAppearance"].get(k) or "") for k in da})
        rec["defaultAppearance"] = da
    if isinstance(data.get("styleProfile"), dict):
        rec["styleProfile"] = {
            "renderStyle": str(data["styleProfile"].get("renderStyle") or "超仿真"),
            "cameraStyle": str(data["styleProfile"].get("cameraStyle") or "真实自然的生活照片感")}
    rec.setdefault("name", "未命名")
    rec.setdefault("originalPersona", rec.get("persona", ""))
    rec.setdefault("expandedPersona", "")
    rec.setdefault("relationship", "")
    rec.setdefault("identityAnchor", vchar_fresh_identity_anchor())
    rec.setdefault("defaultAppearance", vchar_fresh_default_appearance())
    if not any(str(v or "").strip() for v in (rec.get("identityAnchor") or {}).values()):
        src = str(rec.get("visualCard") or "") + "\n" + str(rec.get("persona") or "")
        rec["identityAnchor"] = vchar_extract_identity_anchor(src)
    if not any(str(v or "").strip() for v in (rec.get("defaultAppearance") or {}).values()):
        src = str(rec.get("visualCard") or "") + "\n" + str(rec.get("persona") or "")
        rec["defaultAppearance"] = vchar_extract_default_appearance(src)
    rec.setdefault("defaultScene", vchar_fresh_default_scene())
    rec.setdefault("styleProfile", {"renderStyle": "超仿真",
                                    "cameraStyle": "真实自然的生活照片感"})
    if "currentState" not in rec:
        cs = vchar_fresh_current_state()
        da = rec.get("defaultAppearance") or {}
        ds = rec.get("defaultScene") or {}
        for k in ("clothing", "hairState", "accessories", "makeup"):
            if str(da.get(k) or "").strip():
                cs[k] = str(da[k]).strip()
        for k in ("scene", "lighting", "time"):
            if str(ds.get(k) or "").strip():
                cs[k] = str(ds[k]).strip()
        rec["currentState"] = cs
    rec.setdefault("memorySummary", vchar_fresh_memory())
    rec.setdefault("avatar", "")
    rec.setdefault("sheetImage", "")
    rec.setdefault("sheetPrompt", "")
    rec.setdefault("avatarPrompt", "")
    rec.setdefault("genPrompt", "")
    rec.setdefault("style", "")
    rec.setdefault("created", time.time())
    rec["updated"] = time.time()
    idx = next((i for i, c in enumerate(chars) if c.get("id") == cid), None)
    if idx is None:
        chars.append(rec)
    else:
        chars[idx] = rec
    with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
        json.dump(chars, f, ensure_ascii=False, indent=1)
    return rec


def vchar_delete(cid):
    _vc_paths()
    chars = [c for c in vchar_list() if c.get("id") != cid]
    with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
        json.dump(chars, f, ensure_ascii=False, indent=1)
    try:
        os.remove(os.path.join(VC_CHATS_DIR, cid + ".json"))
    except Exception:
        pass
    d = os.path.join(VC_IMG_DIR, safe_name(cid))
    if os.path.isdir(d):
        shutil.rmtree(d, ignore_errors=True)
    return True


def vchar_history(cid):
    _vc_paths()
    p = os.path.join(VC_CHATS_DIR, cid + ".json")
    try:
        with open(p, encoding="utf-8") as f:
            h = json.load(f)
    except Exception:
        return {"id": cid, "messages": []}
    if not isinstance(h, dict):
        return {"id": cid, "messages": []}
    changed = False
    for m in h.get("messages", []):
        if not isinstance(m, dict):
            continue
        jid = m.get("jobId")
        if (m.get("role") == "assistant" and jid and jid != "failed"
                and jid != "pending" and jid not in VC_JOBS
                and not m.get("image") and not m.get("images")):
            m["jobId"] = "failed"
            changed = True
    if changed:
        try:
            with open(p, "w", encoding="utf-8") as f:
                json.dump(h, f, ensure_ascii=False, indent=1)
        except Exception:
            pass
    return h


def vchar_save_history(cid, history):
    _vc_paths()
    with open(os.path.join(VC_CHATS_DIR, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(history, f, ensure_ascii=False, indent=1)


def _vc_preserved_terms_check(original, result):
    """检查扩写结果是否保留原文的关键含义；返回缺失项列表（空=通过）。"""
    o = str(original or "")
    r = str(result or "")
    missing = []
    for c in re.findall(r"(?:奶白|米白|酒红|深蓝|浅蓝|鹅黄|墨绿|银白|亚麻|栗色|蜜糖|黑白|"
                        r"粉|白|黑|金|棕|银|蓝|紫|灰|青|红|黄|墨)(?:色)?", o):
        if c and c not in r:
            missing.append(c)
    if re.search(r"长发|及腰|中长发", o) and not re.search(r"长", r):
        missing.append("长发")
    if re.search(r"短发", o) and not re.search(r"短", r):
        missing.append("短发")
    for w in re.findall(r"卷发|直发|碎发|波波头|双马尾|单马尾|盘发|丸子头|刘海|寸头|齐肩|"
                        r"鹅蛋脸|瓜子脸|圆脸|方脸|丹凤眼|杏眼|桃花眼|双眼皮|单眼皮|高鼻梁|"
                        r"薄唇|厚唇|剑眉|柳叶眉|高挑|娇小|纤细|丰满|修长|匀称|微胖|魁梧|健美|"
                        r"哥哥|姐姐|老公|老婆|主人|少爷|小姐|妹妹|弟弟|女友|妻子|青梅竹马|"
                        r"同学|同事|闺蜜|\d{1,3}\s*岁", o):
        if w and w not in r:
            missing.append(w)
    return sorted(set(missing))


def vchar_auto_card(persona, name="", age=""):
    sys = """你是虚拟人物设定扩写助手。

用户输入的角色设定是“含义不可变”的原文：你可以润色、改写、扩写，但必须完整保留原文中已有的全部含义，不得改变、删除、削弱任何原有设定。

规则：

1. 原文里的外貌、性格、关系、称呼、年龄、身份等信息必须原样保留其含义。例如用户写“白色短发”，只能扩写成“白色干净利落的短碎发”这类，绝不能改成“黑色长发”，也不能删掉“白色”或“短发”的含义。
2. 可以在保留含义的前提下使表达更自然、更具体。例如“白色短发”可以扩写成“白色短发，剪得干净利落，微微露出耳尖”。
3. 不得新增原文没有提供或无法直接推导的新性格、新身份、新关系、新经历、新爱好、新习惯、新口头禅、新服装、新配饰、新标志物或特殊背景。
4. 用户没有提供的名字、年龄、关系和身份必须保持空字符串。
5. 视觉锚点只能从原文明确存在的线索中提取；没有依据的字段保持空字符串，不得编造。
6. 扩写必须用大白话，像平时聊天一样直接自然，禁止文艺腔、华丽辞藻、抒情比喻和书面腔（例如“外壳之下藏着一颗……的心”“仿佛对周遭事物漠不关心”这类都不要），把意思说清楚就行。

只输出合法JSON，不要输出解释、标题或代码块标记。

输出格式：

{
  "persona": "扩写后的完整人设，自然连贯的一段文本，必须包含原文全部含义",
  "originalPersona": "用户原文，必须一字不差，用于核对",
  "name": "只使用用户填写的名字，没有则为空",
  "age": "只使用用户填写的年龄，没有则为空",
  "relationship": "只使用用户明确提供的关系，没有则为空",
  "identityAnchor": {
    "ageText": "只使用用户明确年龄，没有则为空",
    "bodyBuild": "只使用明确描述或能够直接推导的体型信息，没有则为空",
    "faceShape": "没有依据则为空",
    "eyes": "没有依据则为空",
    "hair": "没有依据则为空",
    "skin": "没有依据则为空",
    "signatureFeature": "没有依据则为空"
  },
  "defaultAppearance": {
    "clothing": "只使用用户明确服装，没有依据则为空",
    "hairState": "只使用用户明确内容，没有依据则为空",
    "accessories": "只使用用户明确内容，没有则为空",
    "makeup": "只使用用户明确内容，没有则为空"
  },
  "defaultScene": {
    "scene": "只使用用户明确场景，没有则为空",
    "lighting": "只使用用户明确光线，没有则为空",
    "time": "只使用用户明确时间，没有则为空"
  },
  "styleProfile": {
    "renderStyle": "只使用用户选择的画风",
    "cameraStyle": "符合所选画风的简短镜头说明"
  }
}"""
    user_input = "用户原始设定（含义不可变，可润色扩写）：\n" + str(persona).strip()[:2000]
    if str(name or "").strip():
        user_input += "\n名字：" + str(name).strip()
    if str(age or "").strip():
        user_input += "\n年龄：" + str(age).strip() + "岁"
    raw = chat_stream([{"role": "system", "content": sys},
                       {"role": "user", "content": user_input}],
                      temperature=0.3, num_predict=1500)
    obj = _extract_json_obj(raw) or {}
    original = str(persona).strip()
    expanded_full = str(obj.get("persona") or "").strip()
    missing = _vc_preserved_terms_check(original, expanded_full)
    if expanded_full and expanded_full != original and not missing:
        persona_out = expanded_full
        expanded = expanded_full
    else:
        expanded = str(obj.get("expandedPersona") or "").strip()
        if expanded and expanded != original:
            persona_out = original + "\n\n（AI补充，只扩写原文已有内容）\n" + expanded
        else:
            persona_out = original
            expanded = ""
    name_out = str(name or "").strip()
    age_out = str(age or "").strip()
    rel_out = str(obj.get("relationship") or "").strip()
    ia = obj.get("identityAnchor") if isinstance(obj.get("identityAnchor"), dict) else {}
    da = obj.get("defaultAppearance") if isinstance(obj.get("defaultAppearance"), dict) else {}
    dsc = obj.get("defaultScene") if isinstance(obj.get("defaultScene"), dict) else {}
    sp = obj.get("styleProfile") if isinstance(obj.get("styleProfile"), dict) else {}
    ia = {k: str(ia.get(k) or "") for k in vchar_fresh_identity_anchor()}
    da = {k: str(da.get(k) or "") for k in vchar_fresh_default_appearance()}
    dsc = {k: str(dsc.get(k) or "") for k in vchar_fresh_default_scene()}
    sp = {"renderStyle": str(sp.get("renderStyle") or "超仿真"),
          "cameraStyle": str(sp.get("cameraStyle") or "真实自然的生活照片感")}
    visual_display = vchar_build_visual_display({
        "identityAnchor": ia, "defaultAppearance": da, "age": age_out})
    return {
        "name": name_out,
        "age": age_out,
        "relationship": rel_out,
        "originalPersona": original,
        "expandedPersona": expanded,
        "persona": persona_out,
        "visualCard": visual_display,
        "identityAnchor": ia,
        "defaultAppearance": da,
        "defaultScene": dsc,
        "styleProfile": sp,
    }


VC_CHAT_SYSTEM = """你正在扮演一个长期存在的虚拟人物，与用户进行自然的第一人称聊天。

你需要同时完成：

1. 根据角色人设自然回复用户。
2. 提取角色本轮发生变化的状态。
3. 判断用户是否想看图片。
4. 用户想看图片时，提取用户真正想看的具体画面。
5. 提取本轮值得长期记住的少量事实。

只输出一个合法JSON对象，不要输出解释、前后缀、标题或代码块标记。

输出格式：

{
  "reply": "显示给用户的自然口语回复，不包含括号动作，不提系统、提示词、JSON或图片生成过程",
  "stateDelta": {
    "clothing": "", "hairState": "", "accessories": "", "makeup": "",
    "action": "", "expression": "", "bodyPose": "", "scene": "",
    "lighting": "", "time": "", "viewContext": ""
  },
  "imageIntent": {
    "wantImage": false, "intentType": "pure_chat", "imageMode": "none",
    "focus": "character", "priority": "low", "targetDescription": "", "mustKeep": []
  },
  "memoryUpdate": {
    "relationshipProgress": "", "newFacts": []
  }
}

stateDelta规则：

1. 只填写本轮发生变化的字段。
2. 没有变化的字段输出空字符串。
3. 不要每轮重新编造完整服装、场景、发型和光线。
4. 用户明确要求改变的内容必须准确填写。
5. 角色自然执行的必要变化可以填写，例如准备睡觉时换成睡衣。
6. 不得改变已经冻结的人物身份和固定外貌。

imageIntent规则：

1. 用户明确表达“我想看、让我看看、给我看看、发张、拍张、给我一张”等视觉请求时，wantImage必须为true。
2. 用户没有使用“图片”一词，但明确想看角色的动作、状态、穿着、表情、姿势或所在环境时，wantImage也必须为true。
3. targetDescription描述的是用户真正想看到的最终画面，不是机械复制角色的回复。
4. 允许reply和targetDescription不同。
5. 用户说“我想看你睡觉”，reply可以是“晚安呀，我先睡了”，targetDescription必须描述她已经睡着的画面。
6. 用户说“我想看你在做饭”，targetDescription必须描述她正在做饭的画面。
7. 用户想看纯环境时，focus使用scene。
8. 用户想看人物处于较大场景中时，focus使用character_in_scene。
9. targetDescription只描述画面核心，保持简洁具体，必须使用简体中文，不得混入英文。
10. 用户没有视觉意图时，wantImage为false，imageMode为none，targetDescription为空。
11. 用户明确说出的动作、姿势、服装、场景词语必须原样保留在targetDescription中，不得改写（例如用户说“闭着眼”就写“闭着眼”，不要写成“闭着双眼”）。
12. 画面涉及两人互动时，targetDescription必须写清她的朝向（面对/侧对/背对）和我的肢体动作（例如“我伸手轻触她的脸颊”“她背对我，我的手搭在她肩上”），画面中要有我的手自然入镜。
13. 画面中永远只出现她一个完整人物。互动时只用“我的手/一只手/我的手指”描述我的肢体，禁止写“我站在她面前、我在她身边、我们、两个人”等会让画面出现第二个人的表述。

imageMode只能使用：none / observer_pov / selfie / mirror_selfie / scene_share / character_in_scene / portrait

各模式含义：

observer_pov：用户像在现场一样看着角色。
selfie：角色拿手机直接自拍。
mirror_selfie：角色对着镜子拍摄穿搭或全身。
scene_share：角色向用户分享环境照片，人物可以不入镜。
character_in_scene：人物处于较大的环境中。
portrait：普通正面或半身人物照片。

reply规则：

1. 符合角色人设和两人的关系。
2. 使用自然口语。
3. 不输出括号动作。
4. 不在回复中解释她正在生成图片。
5. 用户要求看图时，角色可以自然回应，但不能因为角色回复方式而改变用户真正想看的画面。
6. 回复要简短自然，一般控制在80—150字，不要长篇大论，不要把一件事翻来覆去说。

memoryUpdate规则：

1. 只记录以后有价值的关系变化和事实。
2. 普通寒暄不记录。
3. 不重复已有记忆。
4. 每轮最多增加3条新事实。"""


def vchar_build_visual_display(rec):
    """把固定视觉锚点拼成一段展示用文本（不参与聊天出图）。"""
    ia = rec.get("identityAnchor") or {}
    da = rec.get("defaultAppearance") or {}
    age = str(rec.get("age") or ia.get("ageText") or "").strip()
    parts = []
    if age:
        parts.append(age + "岁")
    for k in ("bodyBuild", "faceShape", "eyes", "skin", "hair"):
        v = str(ia.get(k) or "").strip()
        if v:
            parts.append(v)
    if str(da.get("hairState") or "").strip():
        parts.append(str(da["hairState"]))
    if str(da.get("clothing") or "").strip():
        parts.append("常穿" + str(da["clothing"]))
    if str(da.get("accessories") or "").strip():
        parts.append("配饰" + str(da["accessories"]))
    if str(ia.get("signatureFeature") or "").strip():
        parts.append("标志物" + str(ia["signatureFeature"]))
    return "，".join(parts)


def merge_character_state(current_state, state_delta):
    """stateDelta 非空字段覆盖；空字段保持原值。"""
    current = dict(current_state or {})
    if not isinstance(state_delta, dict):
        return current
    for k, v in state_delta.items():
        if str(v or "").strip():
            current[str(k)] = str(v).strip()
    return current


def resolve_image_state(current_state, state_delta, image_intent):
    """本轮图片使用的状态：先合并连续状态，再叠加用户明确画面。"""
    merged = merge_character_state(current_state, state_delta)
    resolved = dict(merged)
    intent = image_intent if isinstance(image_intent, dict) else {}
    target = str(intent.get("targetDescription") or "").strip()
    resolved["targetDescription"] = target
    return resolved


def build_krea2_prompt(character, resolved_state, image_intent, purpose="chat",
                       max_len=220, person_lock=False):
    """纯代码拼接 Krea2 最终提示词，不再调用大模型。"""
    char = character or {}
    state = resolved_state or {}
    intent = image_intent or {}
    focus = str(intent.get("focus") or "").strip()
    is_scene = purpose == "chat" and focus == "scene"
    mode = str(intent.get("imageMode") or "").strip()
    if purpose == "avatar":
        mode = "portrait"
    elif purpose == "sheet":
        mode = "character_in_scene"
    sp = char.get("styleProfile") or {}
    style = str(sp.get("renderStyle") or "").strip()
    if not style:
        style = str(char.get("style") or "").strip()
    if not style:
        gp = str(char.get("genPrompt") or "").strip()
        if gp and len(gp) <= 60:
            style = gp
    if not style:
        style = "超仿真"
    target = str(state.get("targetDescription") or "").strip()
    back_view = bool(re.search(r"背影|背对|背身|背过身|转过身|从背后|后背|背向", target))
    multi_hint = bool(re.search(r"另一个人|其他人|朋友|闺蜜|人群|路人|两个|两人|双人|几个人", target))
    if is_scene and target:
        target = "，".join([
            s.strip() for s in target.split("，") if s.strip()
            and not re.search(r"穿着|背影|肩膀|长发|头发|她的脸|她正|她坐|她站|她穿", s)])
    ia = char.get("identityAnchor") or {}
    id_parts = []
    if not is_scene:
        for k in ("ageText", "bodyBuild", "faceShape", "eyes", "hair", "skin", "signatureFeature"):
            v = str(ia.get(k) or "").strip()
            if back_view and k in ("faceShape", "eyes"):
                continue
            if v:
                if k == "ageText" and re.fullmatch(r"\d{1,3}", v):
                    v += "岁"
                elif k == "bodyBuild" and re.fullmatch(r"\d{2,3}\s*cm", v):
                    v = "身高" + v
            if v and v not in id_parts:
                id_parts.append(v)
    if id_parts and target:
        id_parts = [p for p in id_parts if p not in target]
    da = char.get("defaultAppearance") or {}
    dsc = char.get("defaultScene") or {}
    action = target
    if not is_scene and not action:
        action = "，".join([str(x) for x in (
            state.get("action"), state.get("bodyPose"), state.get("expression"))
            if str(x or "").strip()])
    clothing = str(state.get("clothing") or "").strip() or str(da.get("clothing") or "").strip()
    if clothing and target and clothing in target:
        clothing = ""
    hair = str(state.get("hairState") or "").strip() or str(da.get("hairState") or "").strip()
    acc = str(state.get("accessories") or "").strip() or str(da.get("accessories") or "").strip()
    makeup = str(state.get("makeup") or "").strip() or str(da.get("makeup") or "").strip()
    scene = str(state.get("scene") or "").strip() or str(dsc.get("scene") or "").strip()
    lighting = str(state.get("lighting") or "").strip() or str(dsc.get("lighting") or "").strip()
    time_ = str(state.get("time") or "").strip() or str(dsc.get("time") or "").strip()
    cam = str(sp.get("cameraStyle") or "").strip()
    if purpose == "avatar":
        shot = "正方形头像构图，人物面部清晰居中，简洁背景"
    elif purpose == "sheet":
        shot = "横版全身三视图，正面、侧面、背面三个全身像并排，三个形象不重叠，同一套服装，简洁纯色背景"
    else:
        mode_map = {
            "selfie": "手机自拍视角，人物自然看向手机镜头",
            "mirror_selfie": "对镜自拍视角，镜中展示半身或全身穿搭",
            "scene_share": "真实生活随手拍视角，以环境为画面主体",
            "character_in_scene": "人物位于环境中，场景占较大比例，空间关系清楚",
            "portrait": "自然人像视角，人物面部清晰",
        }
        shot = mode_map.get(mode)
        if not shot:
            shot = ("第一人称从她身后观察视角，只看到她的背影"
                    if back_view else
                    "第一人称观察视角，像我就在她面前，中景或中近景")
    segs_meta = [(style, 99)]
    if id_parts:
        segs_meta.append(("，".join(id_parts), 88))
    app = []
    if not is_scene:
        if hair and hair not in "，".join(id_parts):
            app.append(hair)
        if clothing:
            c = clothing
            for pre in ("上身穿着", "身穿", "身着", "穿着"):
                if c.startswith(pre):
                    c = c[len(pre):]
                    break
            app.append("穿着" + c)
        if acc:
            app.append("戴着" + acc)
        if purpose == "avatar" or mode in ("selfie", "mirror_selfie", "portrait"):
            if makeup:
                app.append("妆容" + makeup)
    if app:
        segs_meta.append(("，".join(app), 92))
    hand_int = (not is_scene and target
                and any(w in target for w in ("伸手", "摸", "抚摸", "轻触", "捏",
                                              "拍", "搭在", "搂", "抱", "牵", "亲")))
    if action:
        segs_meta.append((action, 60))
    if hand_int:
        segs_meta.append(("第一人称互动视角，画面底部前景只有一只手（我的手）自然入镜，手部近景", 50))
    if scene:
        segs_meta.append((scene, 40))
    if lighting:
        segs_meta.append((lighting, 25))
    if time_ and time_ not in scene:
        segs_meta.append((time_, 30))
    if shot:
        if hand_int and shot.startswith("第一人称观察视角，像我就在她面前，"):
            shot = "中景或中近景"
        segs_meta.append((shot, 35))
    if cam and cam != "真实自然的生活照片感":
        segs_meta.append((cam, 20))
    if person_lock and id_parts:
        segs_meta.append(("保持同一人物，只更换衣服", 65))
    if purpose == "chat" and not is_scene and not multi_hint:
        segs_meta.append(("画面中仅她一个完整人物，单人画面", 10))
    complex_mode = mode in ("scene_share", "character_in_scene") or len(target) > 80
    limit = 420 if person_lock else (
        300 if (purpose == "sheet" or complex_mode) else max_len)
    parts = [s for s, _p in segs_meta if str(s or "").strip()]
    prompt = "，".join(parts)
    if len(prompt) > limit:
        for seg, _p in sorted(segs_meta, key=lambda x: x[1]):
            if len(prompt) <= limit:
                break
            if seg in parts:
                parts.remove(seg)
                prompt = "，".join(parts)
        if len(prompt) > limit:
            prompt = prompt[:limit]
    return prompt


def vchar_context_block(rec, history, recent=8, exclude_last=True):
    """组装每轮聊天发给模型的上下文：人设、视觉锚点、连续状态、记忆、最近对话。"""
    lines = []
    name = str(rec.get("name") or "").strip()
    if name:
        lines.append("角色名字：" + name)
    age = str(rec.get("age") or "").strip()
    if age:
        lines.append("角色年龄：" + age + "岁")
    rel = str(rec.get("relationship") or "").strip()
    if rel:
        lines.append("角色关系：" + rel)
    persona_txt = str(rec.get("persona") or "").strip()
    if persona_txt:
        lines.append("人物人设（保留原文含义，可含扩写）：\n" + persona_txt)
    ia = rec.get("identityAnchor") or {}
    ia_txt = "，".join([str(ia.get(k) or "").strip() for k in (
        "ageText", "bodyBuild", "faceShape", "eyes", "hair", "skin", "signatureFeature")
        if str(ia.get(k) or "").strip()])
    if ia_txt:
        lines.append("固定人物视觉锚点：" + ia_txt)
    cs = rec.get("currentState") or {}
    cs_txt = "，".join([str(cs.get(k) or "").strip() for k in (
        "clothing", "hairState", "accessories", "makeup", "action", "expression",
        "bodyPose", "scene", "lighting", "time", "viewContext")
        if str(cs.get(k) or "").strip()])
    if cs_txt:
        lines.append("角色当前连续状态：" + cs_txt)
    mem = rec.get("memorySummary") or {}
    if str(mem.get("relationshipProgress") or "").strip():
        lines.append("关系进展：" + str(mem["relationshipProgress"]).strip())
    facts = mem.get("recentFacts") or []
    if facts:
        lines.append("长期记忆：" + "；".join([str(f) for f in facts[-10:]]))
    msgs = [m for m in (history.get("messages") or []) if isinstance(m, dict)
            and m.get("role") in ("user", "assistant")]
    if exclude_last and msgs:
        msgs = msgs[:-1]
    recent_msgs = msgs[-max(2, int(recent)) * 2:]
    if recent_msgs:
        trans = []
        for m in recent_msgs:
            role = "用户" if m.get("role") == "user" else "角色"
            txt = str(m.get("content") or "").strip()
            if txt:
                trans.append(role + "：" + txt)
        if trans:
            lines.append("最近对话（按真实顺序）：\n" + "\n".join(trans))
    return "\n\n".join(lines)


def vchar_update_memory(mem, update):
    mem = dict(mem or {})
    if not isinstance(mem.get("recentFacts"), list):
        mem["recentFacts"] = []
    if "relationshipProgress" not in mem:
        mem["relationshipProgress"] = ""
    upd = update if isinstance(update, dict) else {}
    rel = str(upd.get("relationshipProgress") or "").strip()
    if rel:
        mem["relationshipProgress"] = rel
    facts = [str(x).strip() for x in (mem["recentFacts"] or []) if str(x or "").strip()]
    new_facts = [str(x).strip() for x in (upd.get("newFacts") or []) if str(x or "").strip()][:3]
    for f in new_facts:
        if f and f not in facts:
            facts.append(f)
    if len(facts) > VC_MEMORY_MAX_FACTS:
        facts = ["此前事项：" + "；".join(facts[:10])] + facts[-10:]
    mem["recentFacts"] = facts
    return mem

def vchar_start_image_job(char, msg_id, prompt, append=True, replace_idx=None, seed=None):
    _vc_paths()
    VC_JOB_SEQ[0] += 1
    job_id = "vj_%d_%d" % (int(time.time() * 1000), VC_JOB_SEQ[0])
    VC_JOBS[job_id] = {"id": job_id, "charId": char.get("id"), "msgId": msg_id,
                       "status": "pending", "prompt": prompt, "image": "",
                       "error": "", "start": time.time(),
                       "append": append, "replace_idx": replace_idx, "seed": seed}
    with VC_QUEUE_LOCK:
        VC_QUEUE.append(job_id)
    _vchar_worker_kick()
    return job_id


def _vchar_worker_kick():
    global VC_WORKER_ON
    with VC_QUEUE_LOCK:
        if VC_WORKER_ON:
            return
        VC_WORKER_ON = True
    threading.Thread(target=_vchar_worker_loop, daemon=True).start()


def _vchar_worker_loop():
    global VC_WORKER_ON
    try:
        while True:
            job_id = None
            with VC_QUEUE_LOCK:
                for jid in list(VC_QUEUE):
                    if VC_JOBS.get(jid, {}).get("status") == "pending":
                        job_id = jid
                        break
                if not job_id:
                    VC_WORKER_ON = False
                    return
            job = VC_JOBS.get(job_id)
            if not job:
                continue
            if not VC_PROGRESS["active"]:
                VC_PROGRESS.update({"active": True, "total": 0, "done": 0,
                                    "current": "正在生成配图", "start": time.time(),
                                    "itemStart": 0})
                op_ensure("vchar", "虚拟人物配图", total=0, detail="正在生成配图",
                          kind="krea2_896x1600")
            VC_PROGRESS["total"] += 1
            VC_PROGRESS.update({
                "current": "正在生成配图",
                "itemStart": time.time(),
            })
            op_update("vchar", done=VC_PROGRESS["done"], total=VC_PROGRESS["total"],
                      detail="第 %d/%d 张 正在生成配图" % (
                          min(VC_PROGRESS["done"] + 1, VC_PROGRESS["total"]),
                          VC_PROGRESS["total"]),
                      kind="krea2_896x1600")
            job["status"] = "generating"
            try:
                ts = time.strftime("%Y%m%d_%H%M%S")
                archive = panel_archive_file(
                    os.path.join("虚拟人物", safe_name(job.get("charId"))),
                    ts + "_" + str(VC_JOB_SEQ[0]))
                set_activity("🎭 虚拟人物配图",
                             "第 %d/%d 张" % (min(VC_PROGRESS["done"] + 1, VC_PROGRESS["total"]),
                                              VC_PROGRESS["total"]))
                comfy_generate(job.get("prompt"), seed=job.get("seed"),
                               archive=archive, wh=(896, 1600))
                rel = os.path.relpath(archive, COMIC_DIR).replace("\\", "/")
                job["image"] = rel
                job["status"] = "completed"
                h = vchar_history(job.get("charId"))
                for m in h.get("messages", []):
                    if m.get("id") == job.get("msgId"):
                        if job.get("replace_idx") is not None:
                            imgs = m.setdefault("images", [])
                            prs = m.setdefault("prompts", [])
                            while len(imgs) <= job["replace_idx"]:
                                imgs.append(""); prs.append("")
                            imgs[job["replace_idx"]] = rel
                            prs[job["replace_idx"]] = job.get("prompt")
                            m["image"] = imgs[0]
                        elif job.get("append"):
                            m.setdefault("images", []).append(rel)
                            m.setdefault("prompts", []).append(job.get("prompt"))
                            m.setdefault("jobIds", []).append(job_id)
                            m["image"] = (m.get("images") or [None])[0] or rel
                        else:
                            m["image"] = rel
                            m["prompt"] = job.get("prompt")
                            m["jobId"] = job_id
                vchar_save_history(job.get("charId"), h)
            except Exception as e:
                job["status"] = "failed"
                job["error"] = str(e)[:300]
                log("❌ 虚拟人物出图失败：" + str(e)[:200])
                h = vchar_history(job.get("charId"))
                for m in h.get("messages", []):
                    if m.get("id") == job.get("msgId"):
                        m["jobId"] = "failed"
                vchar_save_history(job.get("charId"), h)
            finally:
                try:
                    comfy_free()
                except Exception:
                    pass
                with VC_QUEUE_LOCK:
                    if job_id in VC_QUEUE:
                        VC_QUEUE.remove(job_id)
                VC_PROGRESS["done"] += 1
                VC_PROGRESS["itemStart"] = 0
                VC_PROGRESS["current"] = ""
                op_update("vchar", done=VC_PROGRESS["done"], total=VC_PROGRESS["total"],
                          detail="已完成 %d/%d 张" % (
                              VC_PROGRESS["done"], VC_PROGRESS["total"]),
                          kind="krea2_896x1600")
                if VC_PROGRESS["done"] >= VC_PROGRESS["total"]:
                    VC_PROGRESS.update({"active": False, "total": 0, "done": 0,
                                        "current": "", "start": 0, "itemStart": 0})
                    op_end("vchar", "complete", "虚拟人物配图已完成")
                    clear_activity()
    except Exception as e:
        log("❌ 虚拟人物出图队列异常：" + str(e)[:200])
        with VC_QUEUE_LOCK:
            VC_WORKER_ON = False


def vchar_generate_avatar(char):
    """用本地 Krea2 生成人物头像（512x512），存为 漫画/虚拟人物/<id>/avatar.png。"""
    _vc_paths()
    char = vchar_ensure_appearance(char)
    _vc_write_appearance(char)
    prompt = build_krea2_prompt(char, {}, {"imageMode": "portrait"},
                                purpose="avatar", max_len=160)
    log("📝 头像提示词：" + str(prompt)[:300])
    archive = panel_archive_file(
        os.path.join("虚拟人物", safe_name(char.get("id"))), "avatar")
    comfy_generate(prompt, seed=None, archive=archive, wh=(512, 512))
    rel = os.path.relpath(archive, COMIC_DIR).replace("\\", "/")
    chars = vchar_list()
    for c in chars:
        if c.get("id") == char.get("id"):
            c["avatar"] = rel
            c["avatarPrompt"] = prompt
    with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
        json.dump(chars, f, ensure_ascii=False, indent=1)
    return rel


def vchar_generate_sheet(char):
    """生成人设图：横版全身三视图（正面/侧面/背面），三个全身像保持间距。"""
    _vc_paths()
    char = vchar_ensure_appearance(char)
    _vc_write_appearance(char)
    prompt = build_krea2_prompt(char, {}, {"imageMode": "character_in_scene"},
                                purpose="sheet", max_len=220)
    log("📝 人设图提示词：" + str(prompt)[:300])
    archive = panel_archive_file(
        os.path.join("虚拟人物", safe_name(char.get("id"))), "sheet")
    comfy_generate(prompt, seed=None, archive=archive, wh=(1536, 864))
    rel = os.path.relpath(archive, COMIC_DIR).replace("\\", "/")
    chars = vchar_list()
    for c in chars:
        if c.get("id") == char.get("id"):
            c["sheetImage"] = rel
            c["sheetPrompt"] = prompt
    with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
        json.dump(chars, f, ensure_ascii=False, indent=1)
    return rel


