def vchar_save_upload(char, image_data):
    """把用户上传的图片存为 漫画/虚拟人物/<id>/uploads/<时间>.png，返回相对路径。"""
    _vc_paths()
    ts = time.strftime("%Y%m%d_%H%M%S")
    archive = panel_archive_file(
        os.path.join("虚拟人物", safe_name(char.get("id")), "uploads"),
        ts + "_" + str(int(time.time_ns() % 100000)))
    try:
        from PIL import Image
        import io as _io
        import base64 as _b64
        b64 = image_data.split(",", 1)[1] if "," in image_data else image_data
        im = Image.open(_io.BytesIO(_b64.b64decode(b64))).convert("RGB")
        im.thumbnail((1280, 1280), Image.LANCZOS)
        os.makedirs(os.path.dirname(archive), exist_ok=True)
        im.save(archive, "PNG")
    except Exception:
        raise RuntimeError("图片无法读取，请换一张")
    return os.path.relpath(archive, COMIC_DIR).replace("\\", "/")


def vchar_msg_delete(cid, msg_id):
    h = vchar_history(cid)
    msgs = h.get("messages", [])
    for m in msgs:
        if m.get("id") != msg_id:
            continue
        rels = list(m.get("images") or [])
        if m.get("image"):
            rels.append(m["image"])
        for rel in rels:
            try:
                os.remove(os.path.join(COMIC_DIR, *str(rel).replace("\\", "/").split("/")))
            except Exception:
                pass
    h["messages"] = [m for m in msgs if m.get("id") != msg_id]
    vchar_save_history(cid, h)
    return True


def vchar_regen_image(char, msg_id, idx=None):
    h = vchar_history(char.get("id"))
    for m in h.get("messages", []):
        if m.get("id") != msg_id:
            continue
        if idx is not None and m.get("prompts") and 0 <= idx < len(m["prompts"]):
            job = vchar_start_image_job(char, msg_id, m["prompts"][idx],
                                        append=False, replace_idx=idx)
        elif m.get("prompt"):
            job = vchar_start_image_job(char, msg_id, m["prompt"], append=False)
        else:
            raise RuntimeError("找不到可重新生成的消息")
        m["jobId"] = job
        vchar_save_history(char.get("id"), h)
        return job
    raise RuntimeError("找不到可重新生成的消息")


def vchar_chat_process(char, text, image_data=""):
    """虚拟人物聊天完整处理：保存消息、调模型、解析JSON、更新连续状态、队列出图。"""
    char = vchar_ensure_appearance(char)
    _vc_write_appearance(char)
    cid = str(char.get("id") or "")
    text = str(text or "").strip()
    image_rel = ""
    image_desc = ""
    cloth_desc = ""
    if image_data.startswith("data:image/"):
        image_rel = vchar_save_upload(char, image_data)
        image_desc = qwen36_vision(
            image_data,
            "请先客观描述图片中人物的动作、姿势、表情和画面场景（光线、构图，120字以内），"
            "不要描述图片中人物的五官、发型、体型、肤色等外貌特征，"
            "然后单独详细分析图片中人物的整套服装：款式、颜色、材质、领口、袖型、长度、图案、装饰、鞋包等搭配，"
            "尽量精准详细。只描述图片中实际存在的内容，不推测图片之外的信息。"
            "输出格式：【人物】<人物与画面描述>\n【服装】<服装详细描述>")
        if "【服装】" in str(image_desc):
            cloth_desc = str(image_desc).split("【服装】", 1)[1].strip()
    hist = vchar_history(cid)
    uid = _vc_msg_id()
    hist.setdefault("messages", []).append(
        {"id": uid, "role": "user", "content": text,
         "image": image_rel, "created": time.time()})
    vchar_save_history(cid, hist)
    ctx = vchar_context_block(char, hist, recent=VC_RECENT_ROUNDS)
    if image_desc:
        user_msg = ctx + "\n\n用户本轮发来一张图片，图片内容：\n" + image_desc
        if text:
            user_msg += "\n用户的话：" + text
    else:
        user_msg = ctx + "\n\n本轮用户消息：" + text
    raw = chat_stream(
        [{"role": "system", "content": VC_CHAT_SYSTEM},
         {"role": "user", "content": user_msg}],
        temperature=0.9, num_predict=1000)
    obj = _extract_json_obj(raw)
    if not isinstance(obj, dict):
        obj = _vc_repair_json(raw)
    if not isinstance(obj, dict):
        reply = re.sub(r"[（(][^（()）]{1,120}[）)]", "", str(raw or "")).strip() or "……"
        state_delta = {}
        intent_raw = {}
        memory_update = {}
    else:
        reply = str(obj.get("reply") or raw).strip()
        reply = re.sub(r"[（(][^（()）]{1,120}[）)]", "", reply).strip() or "……"
        state_delta = obj.get("stateDelta") if isinstance(obj.get("stateDelta"), dict) else {}
        intent_raw = obj.get("imageIntent") if isinstance(obj.get("imageIntent"), dict) else {}
        memory_update = obj.get("memoryUpdate") if isinstance(obj.get("memoryUpdate"), dict) else {}
    want = bool(intent_raw.get("wantImage"))
    mode = str(intent_raw.get("imageMode") or "").strip()
    if mode not in ("none", "observer_pov", "selfie", "mirror_selfie",
                    "scene_share", "character_in_scene", "portrait"):
        mode = "observer_pov" if want else "none"
    focus = str(intent_raw.get("focus") or "character").strip()
    if focus not in ("character", "scene", "character_in_scene"):
        focus = "character"
    intent = {
        "wantImage": want,
        "intentType": str(intent_raw.get("intentType") or ("visual_request" if want else "pure_chat")),
        "imageMode": mode,
        "focus": focus,
        "priority": str(intent_raw.get("priority") or ("high" if want else "low")),
        "targetDescription": str(intent_raw.get("targetDescription") or "").strip(),
        "mustKeep": [str(x) for x in (intent_raw.get("mustKeep") or []) if str(x or "").strip()],
    }
    outfit_change = bool(cloth_desc) and any(w in text for w in VC_OUTFIT_HINTS)
    if outfit_change:
        state_delta["clothing"] = cloth_desc
        intent["wantImage"] = True
        if intent["imageMode"] in ("", "none"):
            intent["imageMode"] = "observer_pov"
        t = "她展示全身服装效果"
        if str(state_delta.get("action") or "").strip():
            t += "，" + str(state_delta["action"]).strip()
        intent["targetDescription"] = t
        log("🧥 换装请求：已识别图片服装描述（%d字），只换服装不改人物" % len(cloth_desc))
    if not intent["wantImage"] and any(w in text for w in VC_VISUAL_HINTS):
        intent["wantImage"] = True
        if intent["imageMode"] in ("", "none"):
            intent["imageMode"] = "observer_pov"
        log("👀 检测到明确看图请求，已强制生成配图")
    if "自拍" in text and "镜子" not in text and intent["imageMode"] == "mirror_selfie":
        intent["imageMode"] = "selfie"
    if (any(w in text for w in ("窗外", "夜景", "风景", "景色"))
            and any(w in text for w in ("看看", "给我看", "拍"))
            and not any(w in text for w in ("站在", "你的样子", "全身", "自拍"))):
        intent["focus"] = "scene"
        intent["imageMode"] = "scene_share"
    if intent["wantImage"] and not intent["targetDescription"]:
        chunks = []
        if str(state_delta.get("action") or "").strip():
            chunks.append("她正在" + str(state_delta["action"]).strip())
        if str(state_delta.get("clothing") or "").strip():
            chunks.append("穿着" + str(state_delta["clothing"]).strip())
        if str(state_delta.get("expression") or "").strip():
            chunks.append("表情" + str(state_delta["expression"]).strip())
        if str(state_delta.get("scene") or "").strip():
            chunks.append("在" + str(state_delta["scene"]).strip())
        if chunks:
            intent["targetDescription"] = "，".join(chunks)
    assume = any(w in text for w in VC_ASSUME_HINTS)
    if state_delta and not assume:
        char["currentState"] = merge_character_state(
            char.get("currentState") or {}, state_delta)
        char["memorySummary"] = vchar_update_memory(
            char.get("memorySummary") or {}, memory_update)
        chars = vchar_list()
        for c in chars:
            if c.get("id") == cid:
                c["currentState"] = char["currentState"]
                c["memorySummary"] = char["memorySummary"]
                c["updated"] = time.time()
        with open(os.path.join(VC_DIR, "characters.json"), "w", encoding="utf-8") as f:
            json.dump(chars, f, ensure_ascii=False, indent=1)
    resolved = resolve_image_state(
        char.get("currentState") or {}, state_delta, intent)
    mid = _vc_msg_id()
    prompt = ""
    if intent["wantImage"] and intent["targetDescription"]:
        prompt = build_krea2_prompt(char, resolved, intent, person_lock=outfit_change)
        log("🖼 虚拟人物配图提示词：" + str(prompt)[:240])
    hist = vchar_history(cid)
    hist.setdefault("messages", []).append({
        "id": mid, "role": "assistant", "content": reply,
        "image": "", "prompt": prompt,
        "jobId": "pending" if (intent["wantImage"] and intent["targetDescription"] and prompt) else "",
        "imageIntent": intent, "stateDelta": state_delta,
        "resolvedState": resolved, "created": time.time()})
    vchar_save_history(cid, hist)
    if intent["wantImage"] and intent["targetDescription"] and prompt:
        job_id = vchar_start_image_job(char, mid, prompt, append=False)
        h2 = vchar_history(cid)
        for m in h2.get("messages", []):
            if m.get("id") == mid:
                m["jobId"] = job_id
        vchar_save_history(cid, h2)
    return {"ok": True, "reply": reply, "msgId": mid, "wantImage": bool(intent["wantImage"])}


def main():
    url = f"http://localhost:{PORT}/"
    try:
        srv = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    except OSError:
        # 端口已被占用：说明写作台已经开着，直接打开网页即可
        print("="*46)
        print("  写作台已经在运行了，正在为你打开网页...")
        print("  网址： " + url)
        print("="*46)
        webbrowser.open(url)
        return
    print("="*46)
    print("  本地模型工作台已启动")
    print("  请在浏览器打开： " + url)
    print("  关闭此黑窗口即可停止。")
    print("PRODUCTION_MODE=stable_fullpage_core_v1")
    print("DEPLOYMENT_SOURCE=blind_winner_A_20260814")
    print("="*46)
    if not os.environ.get("MKZT_NO_BROWSER"):
        threading.Timer(1.0, lambda: webbrowser.open(url)).start()
    def _preload_vision():
        time.sleep(6)
        try:
            q = json.load(urllib.request.urlopen(COMFY + "/queue", timeout=3))
            if q.get("queue_running") or q.get("queue_pending"):
                return
        except Exception:
            pass
        try:
            if load_vision_engine() == "q25":
                qwen25_start()
            else:
                qwen36_start()
        except Exception:
            pass
    threading.Thread(target=_preload_vision, daemon=True).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
